CREATE FUNCTION zapp.auto_add_deleted_contact_to_graveyard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
BEGIN
  -- Fire when deleted_at transitions from NULL to a value (soft delete)
  IF OLD.deleted_at IS NULL AND NEW.deleted_at IS NOT NULL THEN
    PERFORM add_to_contact_id_graveyard(
      NEW.id,
      NULL::UUID,
      'soft_deleted'
    );
  END IF;
  RETURN NEW;
END;
$$;


