--
-- Name: auto_assign_contact(); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.auto_assign_contact() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  assigned_agent_id UUID;
BEGIN
  -- Find the first matching active rule for the connection
  SELECT agent_id INTO assigned_agent_id
  FROM zapp.client_wallet_rules
  WHERE is_active = true
    AND (whatsapp_connection_id IS NULL OR whatsapp_connection_id = NEW.whatsapp_connection_id)
  ORDER BY priority DESC, created_at ASC
  LIMIT 1;
  
  -- If a rule matches and contact has no assignment, assign it
  IF assigned_agent_id IS NOT NULL AND NEW.assigned_to IS NULL THEN
    NEW.assigned_to := assigned_agent_id;
  END IF;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION zapp.auto_assign_contact() OWNER TO supabase_admin;

--
-- Name: auto_assign_contact_sh(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.auto_assign_contact_sh() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_agent uuid;
  v_conn  uuid;
BEGIN
  -- Já atribuído: não sobrescrever
  IF NEW.assigned_to IS NOT NULL THEN
    RETURN NEW;
  END IF;

  -- 1. Wallet rules: regra explícita por conexão (maior prioridade)
  SELECT id INTO v_conn
  FROM zapp.whatsapp_connections
  WHERE instance_name = NEW.instance_name AND is_active = true
  ORDER BY created_at LIMIT 1;

  SELECT agent_id INTO v_agent
  FROM zapp.client_wallet_rules
  WHERE is_active = true
    AND (whatsapp_connection_id IS NULL OR whatsapp_connection_id = v_conn)
  ORDER BY priority DESC, created_at ASC
  LIMIT 1;

  IF v_agent IS NOT NULL THEN
    NEW.assigned_to := v_agent::text;
    RETURN NEW;
  END IF;

  -- 2. Fallback: enfileirar em "Atendimento Geral" — o trigger on_contact_queue_auto_assign
  --    dispara a seguir (BEFORE INSERT, ordem alfa) e escolhe o agente menos carregado.
  --    Apenas seta queue_id se ainda nulo para não sobrescrever atribuição manual de fila.
  IF NEW.queue_id IS NULL THEN
    NEW.queue_id := 'a256e34a-1d95-4efe-b257-36a27d010492'::uuid;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION zapp.auto_assign_contact_sh() OWNER TO postgres;

--
-- Name: auto_assign_to_queue_agent(); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.auto_assign_to_queue_agent() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  assigned_agent_id UUID;
BEGIN
  -- If contact has a queue but no assigned agent, find least busy agent
  IF NEW.queue_id IS NOT NULL AND NEW.assigned_to IS NULL THEN
    SELECT qm.profile_id INTO assigned_agent_id
    FROM zapp.queue_members qm
    JOIN zapp.profiles p ON p.id = qm.profile_id
    WHERE qm.queue_id = NEW.queue_id
      AND qm.is_active = true
      AND p.is_active = true
    ORDER BY (
      SELECT COUNT(*) FROM zapp.contacts c 
      WHERE c.assigned_to = qm.profile_id
    ) ASC
    LIMIT 1;
    
    IF assigned_agent_id IS NOT NULL THEN
      NEW.assigned_to := assigned_agent_id;
    END IF;
  END IF;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION zapp.auto_assign_to_queue_agent() OWNER TO supabase_admin;

--
-- Name: auto_assign_to_queue_agent_sh(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.auto_assign_to_queue_agent_sh() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_agent uuid;
BEGIN
  IF NEW.queue_id IS NOT NULL AND NEW.assigned_to IS NULL THEN
    SELECT qm.profile_id INTO v_agent
    FROM zapp.queue_members qm
    JOIN zapp.profiles p ON p.id = qm.profile_id
    WHERE qm.queue_id = NEW.queue_id
      AND (qm.is_active IS NULL OR qm.is_active = true)
      AND p.is_active = true
    ORDER BY (
      SELECT count(*) FROM zapp.evolution_contacts c2
      WHERE c2.assigned_to = qm.profile_id::text
    ) ASC
    LIMIT 1;
    IF v_agent IS NOT NULL THEN
      NEW.assigned_to := v_agent::text;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION zapp.auto_assign_to_queue_agent_sh() OWNER TO postgres;

--
-- Name: auto_pause_instance_on_auth_spike(text, text, integer, integer); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.auto_pause_instance_on_auth_spike(p_instance text, p_reason text, p_trigger_count integer, p_minutes integer DEFAULT 15) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_id           uuid;
  v_existing     uuid;
  v_clamped_tc   integer;
  v_clamped_min  integer;
BEGIN
  IF p_minutes <= 0 OR p_minutes > 1440 THEN
    v_clamped_min := 15;
  ELSE
    v_clamped_min := p_minutes;
  END IF;

  v_clamped_tc := GREATEST(0, COALESCE(p_trigger_count, 0));

  SELECT id INTO v_existing
    FROM zapp.instance_processing_pauses
   WHERE instance_name = p_instance
     AND paused_until > now()
   ORDER BY paused_until DESC
   LIMIT 1;

  IF v_existing IS NOT NULL THEN
    UPDATE zapp.instance_processing_pauses
       SET paused_until  = GREATEST(paused_until, now() + (v_clamped_min || ' minutes')::interval),
           trigger_count = trigger_count + v_clamped_tc,
           reason        = p_reason,
           updated_at    = now()
     WHERE id = v_existing;
    RETURN v_existing;
  END IF;

  INSERT INTO zapp.instance_processing_pauses (
    instance_name, paused_until, reason, trigger_count, auto_paused
  )
  VALUES (
    p_instance,
    now() + (v_clamped_min || ' minutes')::interval,
    p_reason,
    v_clamped_tc,
    true
  )
  RETURNING id INTO v_id;

  INSERT INTO zapp.audit_logs (user_id, action, entity_type, entity_id, details)
  VALUES (
    NULL,
    'instance_auto_paused',
    'instance_processing_pauses',
    v_id,
    jsonb_build_object(
      'instance',      p_instance,
      'minutes',       v_clamped_min,
      'reason',        p_reason,
      'trigger_count', v_clamped_tc,
      'raw_trigger_count', p_trigger_count
    )
  );

  RETURN v_id;
END;
$$;


ALTER FUNCTION zapp.auto_pause_instance_on_auth_spike(p_instance text, p_reason text, p_trigger_count integer, p_minutes integer) OWNER TO supabase_admin;

--
-- Name: backup_campaign_contacts(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.backup_campaign_contacts() RETURNS TABLE(backed_up integer, deleted_old_partitions integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog', 'auth'
    AS $$
DECLARE
  v_backed_up INT;
  v_deleted INT := 0;
BEGIN
  -- Create today's partition if not exists
  BEGIN
    EXECUTE format(
      'CREATE TABLE IF NOT EXISTS _backups.campaign_contacts_pre_dedup_%s '
      'PARTITION OF _backups.campaign_contacts_pre_dedup '
      'FOR VALUES FROM (%L) TO (%L)',
      TO_CHAR(CURRENT_DATE, 'YYYY_MM_DD'),
      CURRENT_DATE,
      CURRENT_DATE + INTERVAL '1 day'
    );
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;
  
  -- Clear yesterday data
  DELETE FROM _backups.campaign_contacts_pre_dedup
  WHERE backup_date < CURRENT_DATE;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  
  -- Insert today snapshot
  INSERT INTO _backups.campaign_contacts_pre_dedup (id, campaign_id, contact_id, created_at, backup_date)
  SELECT id, campaign_id, contact_id, created_at, CURRENT_DATE
  FROM campaign_contacts;
  GET DIAGNOSTICS v_backed_up = ROW_COUNT;
  
  -- Record metadata
  INSERT INTO _backups.backup_metadata (table_name, backup_date, row_count)
  VALUES ('campaign_contacts', CURRENT_DATE, v_backed_up)
  ON CONFLICT (table_name, backup_date) DO UPDATE
  SET row_count = v_backed_up;
  
  RETURN QUERY SELECT v_backed_up, v_deleted;
END;
$$;


ALTER FUNCTION zapp.backup_campaign_contacts() OWNER TO postgres;

