--
-- Name: bpm_create_card(uuid, text, jsonb, uuid, timestamp with time zone, text, integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.bpm_create_card(p_flow_id uuid, p_title text, p_values jsonb DEFAULT '{}'::jsonb, p_assignee_id uuid DEFAULT NULL::uuid, p_due_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_origin text DEFAULT 'manual'::text, p_priority integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE v_ws uuid; v_step uuid; v_card uuid;
BEGIN
  SELECT workspace_id INTO v_ws FROM bpm_flows WHERE id=p_flow_id AND deleted_at IS NULL;
  IF v_ws IS NULL THEN RAISE EXCEPTION 'Flow not found'; END IF;
  SELECT id INTO v_step FROM bpm_flow_steps WHERE flow_id=p_flow_id AND is_initial=TRUE AND deleted_at IS NULL ORDER BY step_order LIMIT 1;
  IF v_step IS NULL THEN SELECT id INTO v_step FROM bpm_flow_steps WHERE flow_id=p_flow_id AND deleted_at IS NULL ORDER BY step_order LIMIT 1; END IF;
  INSERT INTO bpm_cards (flow_id,current_step_id,workspace_id,title,assignee_id,due_date,origin,priority,created_by) VALUES (p_flow_id,v_step,v_ws,p_title,p_assignee_id,p_due_date,p_origin,p_priority,auth.uid()) RETURNING id INTO v_card;
  RETURN jsonb_build_object('card_id',v_card,'step_id',v_step,'flow_id',p_flow_id,'workspace_id',v_ws);
END; $$;


ALTER FUNCTION zapp.bpm_create_card(p_flow_id uuid, p_title text, p_values jsonb, p_assignee_id uuid, p_due_date timestamp with time zone, p_origin text, p_priority integer) OWNER TO postgres;

