-- Name: bpm_duplicate_card(uuid); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.bpm_duplicate_card(p_card_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE v_old RECORD; v_new uuid;
BEGIN
  SELECT * INTO v_old FROM bpm_cards WHERE id=p_card_id AND deleted_at IS NULL;
  IF v_old IS NULL THEN RAISE EXCEPTION 'Card not found'; END IF;
  INSERT INTO bpm_cards (flow_id,current_step_id,workspace_id,title,priority,assignee_id,due_date,origin,created_by) VALUES (v_old.flow_id,v_old.current_step_id,v_old.workspace_id,v_old.title||' (copia)',v_old.priority,v_old.assignee_id,v_old.due_date,'duplicate',auth.uid()) RETURNING id INTO v_new;
  INSERT INTO bpm_card_subtasks (card_id,title,sort_order,created_by) SELECT v_new,title,sort_order,auth.uid() FROM bpm_card_subtasks WHERE card_id=p_card_id;
  INSERT INTO bpm_card_labels (card_id,label_id) SELECT v_new,label_id FROM bpm_card_labels WHERE card_id=p_card_id;
  RETURN v_new;
END; $$;


ALTER FUNCTION zapp.bpm_duplicate_card(p_card_id uuid) OWNER TO postgres;

--
-- Name: bpm_duplicate_card(uuid, boolean, boolean, boolean); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.bpm_duplicate_card(p_card_id uuid, p_include_answers boolean DEFAULT true, p_include_subtasks boolean DEFAULT true, p_include_checklists boolean DEFAULT true) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE v_old RECORD; v_new uuid; v_ans RECORD; v_new_ans uuid; v_cl RECORD; v_new_cl uuid;
BEGIN
  SELECT * INTO v_old FROM bpm_cards WHERE id=p_card_id AND deleted_at IS NULL;
  IF v_old IS NULL THEN RAISE EXCEPTION 'Card not found'; END IF;
  INSERT INTO bpm_cards (flow_id,current_step_id,workspace_id,title,priority,assignee_id,due_date,origin,created_by)
  VALUES (v_old.flow_id,v_old.current_step_id,v_old.workspace_id,v_old.title||' (copia)',v_old.priority,v_old.assignee_id,v_old.due_date,'duplicate',NULL)
  RETURNING id INTO v_new;
  IF p_include_subtasks THEN INSERT INTO bpm_card_subtasks (card_id,title,sort_order,assignee_id,due_date,created_by) SELECT v_new,title,sort_order,assignee_id,due_date,NULL FROM bpm_card_subtasks WHERE card_id=p_card_id; END IF;
  IF p_include_checklists THEN FOR v_cl IN SELECT * FROM bpm_card_checklists WHERE card_id=p_card_id LOOP INSERT INTO bpm_card_checklists (card_id,title,sort_order,created_by) VALUES (v_new,v_cl.title,v_cl.sort_order,NULL) RETURNING id INTO v_new_cl; INSERT INTO bpm_card_checklist_items (checklist_id,title,sort_order) SELECT v_new_cl,title,sort_order FROM bpm_card_checklist_items WHERE checklist_id=v_cl.id; END LOOP; END IF;
  INSERT INTO bpm_card_labels (card_id,label_id) SELECT v_new,label_id FROM bpm_card_labels WHERE card_id=p_card_id;
  RETURN v_new;
END;
$$;


ALTER FUNCTION zapp.bpm_duplicate_card(p_card_id uuid, p_include_answers boolean, p_include_subtasks boolean, p_include_checklists boolean) OWNER TO postgres;

