--
-- Name: bpm_flow_stats(uuid); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.bpm_flow_stats(p_flow_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE v jsonb;
BEGIN SELECT jsonb_build_object('flow_id',p_flow_id,'total_cards',(SELECT count(*) FROM bpm_cards WHERE flow_id=p_flow_id AND deleted_at IS NULL),'active_cards',(SELECT count(*) FROM bpm_cards WHERE flow_id=p_flow_id AND status='active' AND deleted_at IS NULL),'completed_cards',(SELECT count(*) FROM bpm_cards WHERE flow_id=p_flow_id AND status='completed' AND deleted_at IS NULL),'overdue_cards',(SELECT count(*) FROM bpm_cards WHERE flow_id=p_flow_id AND status='active' AND due_date<NOW() AND deleted_at IS NULL),'cards_by_step',(SELECT jsonb_agg(jsonb_build_object('step',s.name,'count',COALESCE(c.cnt,0),'color',s.color)) FROM bpm_flow_steps s LEFT JOIN (SELECT current_step_id,count(*) cnt FROM bpm_cards WHERE flow_id=p_flow_id AND status='active' AND deleted_at IS NULL GROUP BY current_step_id) c ON c.current_step_id=s.id WHERE s.flow_id=p_flow_id AND s.deleted_at IS NULL ORDER BY s.step_order)) INTO v; RETURN v;
END; $$;


ALTER FUNCTION zapp.bpm_flow_stats(p_flow_id uuid) OWNER TO postgres;

--
-- Name: bpm_install_template(uuid, uuid, text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.bpm_install_template(p_template_id uuid, p_workspace_id uuid, p_flow_name text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE v_tmpl RECORD; v_flow uuid; v_step jsonb; v_step_id uuid; v_order int:=0;
BEGIN
  SELECT * INTO v_tmpl FROM bpm_flow_templates WHERE id=p_template_id;
  IF v_tmpl IS NULL THEN RAISE EXCEPTION 'Template not found'; END IF;
  INSERT INTO bpm_flows (workspace_id,name,description,icon,color,created_by) VALUES (p_workspace_id,COALESCE(p_flow_name,v_tmpl.name),v_tmpl.description,v_tmpl.icon,v_tmpl.color,auth.uid()) RETURNING id INTO v_flow;
  FOR v_step IN SELECT * FROM jsonb_array_elements(v_tmpl.definition->'steps') LOOP
    INSERT INTO bpm_flow_steps (flow_id,name,step_order,color,is_initial,is_final) VALUES (v_flow,v_step->>'name',v_order,COALESCE(v_step->>'color','#85B7EB'),v_order=0,COALESCE((v_step->>'is_final')::boolean,false)) RETURNING id INTO v_step_id;
    v_order:=v_order+1;
  END LOOP;
  UPDATE bpm_flow_templates SET install_count=install_count+1 WHERE id=p_template_id;
  RETURN jsonb_build_object('success',true,'flow_id',v_flow,'steps_created',v_order);
END; $$;


ALTER FUNCTION zapp.bpm_install_template(p_template_id uuid, p_workspace_id uuid, p_flow_name text) OWNER TO postgres;

