--
-- Name: bpm_move_card(uuid, uuid, text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.bpm_move_card(p_card_id uuid, p_to_step_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE v_card RECORD; v_step RECORD;
BEGIN
  SELECT * INTO v_card FROM bpm_cards WHERE id=p_card_id AND deleted_at IS NULL;
  IF v_card IS NULL THEN RAISE EXCEPTION 'Card not found'; END IF;
  SELECT * INTO v_step FROM bpm_flow_steps WHERE id=p_to_step_id AND flow_id=v_card.flow_id AND deleted_at IS NULL;
  IF v_step IS NULL THEN RAISE EXCEPTION 'Step not found'; END IF;
  UPDATE bpm_cards SET current_step_id=p_to_step_id,updated_at=NOW(),completed_at=CASE WHEN v_step.is_final THEN NOW() ELSE NULL END,status=CASE WHEN v_step.is_final THEN 'completed'::bpm_card_status ELSE status END WHERE id=p_card_id;
  RETURN jsonb_build_object('success',true,'card_id',p_card_id,'from_step',v_card.current_step_id,'to_step',p_to_step_id,'is_final',v_step.is_final);
END; $$;


ALTER FUNCTION zapp.bpm_move_card(p_card_id uuid, p_to_step_id uuid, p_reason text) OWNER TO postgres;

--
-- Name: bpm_my_tasks(uuid, text, integer, integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.bpm_my_tasks(p_workspace_id uuid DEFAULT NULL::uuid, p_status text DEFAULT 'active'::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE v jsonb;
BEGIN
  SELECT jsonb_build_object(
    'total', (SELECT count(*) FROM bpm_cards c WHERE c.assignee_id=auth.uid() AND c.status=p_status::bpm_card_status AND c.deleted_at IS NULL AND (p_workspace_id IS NULL OR c.workspace_id=p_workspace_id)),
    'cards', (SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb) FROM (
      SELECT c.id, c.title, c.card_number, c.status, c.priority, c.due_date,
        f.name as flow_name, s.name as step_name, c.due_date < NOW() as is_overdue
      FROM bpm_cards c
      JOIN bpm_flows f ON c.flow_id=f.id
      JOIN bpm_flow_steps s ON c.current_step_id=s.id
      WHERE c.assignee_id=auth.uid() AND c.status=p_status::bpm_card_status AND c.deleted_at IS NULL AND (p_workspace_id IS NULL OR c.workspace_id=p_workspace_id)
      ORDER BY c.priority DESC, c.due_date ASC NULLS LAST
      LIMIT p_limit OFFSET p_offset
    ) t)
  ) INTO v;
  RETURN v;
END;
$$;


ALTER FUNCTION zapp.bpm_my_tasks(p_workspace_id uuid, p_status text, p_limit integer, p_offset integer) OWNER TO postgres;

