--
-- Name: can_supervise_profile(uuid, uuid); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.can_supervise_profile(_user_id uuid, _target_profile_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$ SELECT zapp.is_manager_or_above(_user_id) OR ( zapp.has_role(_user_id, 'supervisor') AND zapp.get_user_department(_user_id) IS NOT NULL AND zapp.get_user_department(_user_id) = ( SELECT department_id FROM zapp.profiles WHERE id = _target_profile_id LIMIT 1 ) ) OR EXISTS ( SELECT 1 FROM zapp.profiles WHERE id = _target_profile_id AND user_id = _user_id ); $$;


