--
-- Name: cleanup_failed_messages(); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.cleanup_failed_messages() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  v_cutoff timestamptz := now() - interval '30 days';
  v_deleted_count integer := 0;
BEGIN
  -- Apenas service_role (cron) ou admin pode executar
  IF auth.role() <> 'service_role' AND NOT zapp.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Access denied: admin role or service_role required';
  END IF;

  WITH deleted AS (
    DELETE FROM zapp.failed_messages
    WHERE status IN ('succeeded', 'abandoned')
      AND COALESCE(succeeded_at, last_attempt_at, created_at) < v_cutoff
    RETURNING id
  )
  SELECT count(*) INTO v_deleted_count FROM deleted;

  RETURN jsonb_build_object(
    'deleted_count', v_deleted_count,
    'cutoff', v_cutoff,
    'executed_at', now()
  );
END;
$$;


ALTER FUNCTION zapp.cleanup_failed_messages() OWNER TO supabase_admin;

--
-- Name: cleanup_old_data(); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.cleanup_old_data() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  deleted_errors int := 0;
  deleted_webhooks int := 0;
  deleted_dlq int := 0;
  deleted_audit int := 0;
BEGIN
  -- 1. Cleanup error logs > 30 days
  DELETE FROM zapp.app_error_logs WHERE created_at < now() - interval '30 days';
  GET DIAGNOSTICS deleted_errors = ROW_COUNT;

  -- 2. Cleanup webhook events > 14 days
  DELETE FROM zapp.evolution_webhook_events WHERE created_at < now() - interval '14 days';
  GET DIAGNOSTICS deleted_webhooks = ROW_COUNT;

  -- 3. Cleanup dead letter queue > 30 days
  DELETE FROM zapp.dead_letter_queue WHERE created_at < now() - interval '30 days';
  GET DIAGNOSTICS deleted_dlq = ROW_COUNT;

  -- 4. Cleanup audit log > 90 days
  DELETE FROM zapp.audit_log WHERE created_at < now() - interval '90 days';
  GET DIAGNOSTICS deleted_audit = ROW_COUNT;

  RETURN jsonb_build_object(
    'timestamp', now(),
    'deleted_errors', deleted_errors,
    'deleted_webhooks', deleted_webhooks,
    'deleted_dlq', deleted_dlq,
    'deleted_audit', deleted_audit
  );
END;
$$;


ALTER FUNCTION zapp.cleanup_old_data() OWNER TO supabase_admin;

