CREATE FUNCTION zapp.clear_login_attempts(p_email text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
BEGIN
  -- Guard: apenas authenticated ou service_role pode limpar tentativas
  -- anon nao tem mais EXECUTE, mas guard duplo por segurança
  IF auth.role() NOT IN ('authenticated', 'service_role', 'postgres') THEN
    RAISE EXCEPTION 'permission denied: apenas usuarios autenticados podem limpar tentativas de login'
      USING ERRCODE = '42501';
  END IF;
  DELETE FROM zapp.login_attempts WHERE email = LOWER(p_email);
END;
$$;


