-- Name: debug_lid_case(jsonb); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.debug_lid_case(p_json jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $_$ DECLARE v_out text; BEGIN SELECT CASE WHEN COALESCE(c->>'id', c->>'remoteJid') LIKE '%@lid' THEN (SELECT ci.phone_number FROM evo.contact_identity ci WHERE ci.lid_jid = COALESCE(c->>'id', c->>'remoteJid') AND ci.phone_number ~ '^[0-9]{10,14}$' ORDER BY ci.last_seen DESC LIMIT 1) ELSE 'no-lid' END INTO v_out FROM jsonb_array_elements(p_json) AS c LIMIT 1; RETURN v_out; END; $_$;


ALTER FUNCTION zapp.debug_lid_case(p_json jsonb) OWNER TO postgres;

