-- Name: debug_lid_flow(jsonb); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.debug_lid_flow(p_json jsonb) RETURNS TABLE(jid text, case_phone text, resolved text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $_$ DECLARE v_jid text; v_phone text; BEGIN FOR v_jid IN SELECT COALESCE(c->>'id', c->>'remoteJid') FROM jsonb_array_elements(p_json) AS c LOOP v_phone := CASE WHEN v_jid LIKE '%@lid' THEN (SELECT ci.phone_number FROM evo.contact_identity ci WHERE ci.lid_jid = v_jid AND ci.phone_number ~ '^[0-9]{10,14}$' ORDER BY ci.last_seen DESC LIMIT 1) ELSE 'not-lid' END; RETURN QUERY SELECT v_jid, v_phone, (SELECT ci.phone_number FROM evo.contact_identity ci WHERE ci.lid_jid = v_jid LIMIT 1); END LOOP; END; $_$;


ALTER FUNCTION zapp.debug_lid_flow(p_json jsonb) OWNER TO postgres;

