--
-- Name: find_duplicate_contacts(text, integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.find_duplicate_contacts(p_workspace_id text DEFAULT NULL::text, p_limit integer DEFAULT 100) RETURNS TABLE(phone text, contact_ids uuid[], instance_names text[], total integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp, pg_temp'
    AS $$
BEGIN
  IF NOT zapp.is_admin_or_supervisor() THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
  SELECT ec.phone_number, array_agg(ec.id)::uuid[], array_agg(ec.instance_name)::text[], count(*)::integer
  FROM zapp.evolution_contacts ec
  WHERE ec.phone_number IS NOT NULL AND ec.phone_number <> ''
    AND (p_workspace_id IS NULL OR ec.instance_name = p_workspace_id)
  GROUP BY ec.phone_number HAVING count(*) > 1 ORDER BY count(*) DESC LIMIT p_limit;
END;
$$;


ALTER FUNCTION zapp.find_duplicate_contacts(p_workspace_id text, p_limit integer) OWNER TO postgres;

--
-- Name: fn_accept_transfer(uuid, text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_accept_transfer(p_transfer_id uuid, p_operator text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
BEGIN
    UPDATE zapp.conversation_transfers SET status = 'accepted', target_operator = p_operator, accepted_at = NOW()
    WHERE id = p_transfer_id AND status = 'pending';
    RETURN FOUND;
END;
$$;


ALTER FUNCTION zapp.fn_accept_transfer(p_transfer_id uuid, p_operator text) OWNER TO postgres;

--
-- Name: fn_accept_transfer(uuid, uuid); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_accept_transfer(p_transfer_id uuid, p_agent_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
    v_conversation_id UUID;
BEGIN
    -- Update the transfer record
    UPDATE zapp.conversation_transfers
    SET 
        status = 'accepted',
        to_agent_id = p_agent_id,
        accepted_at = NOW()
    WHERE 
        id = p_transfer_id AND status = 'pending'
    RETURNING conversation_id INTO v_conversation_id;
    
    IF FOUND THEN
        -- Assign the contact to the new agent
        UPDATE zapp.contacts
        SET assigned_to = p_agent_id
        WHERE id = v_conversation_id;
        
        RETURN TRUE;
    END IF;
    
    RETURN FALSE;
END;
$$;


ALTER FUNCTION zapp.fn_accept_transfer(p_transfer_id uuid, p_agent_id uuid) OWNER TO postgres;

