-- Name: fn_add_audio_meme(text, text, text, numeric, text, text[], text, text, integer); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.fn_add_audio_meme(p_name text, p_audio_url text, p_category text DEFAULT 'outros'::text, p_duration_seconds numeric DEFAULT NULL::numeric, p_uploaded_by text DEFAULT NULL::text, p_tags text[] DEFAULT '{}'::text[], p_file_hash text DEFAULT NULL::text, p_mime_type text DEFAULT 'audio/mpeg'::text, p_file_size integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$
DECLARE
  v_id uuid;
  v_dup jsonb;
BEGIN
  v_dup := rpc_check_audio_meme_duplicate(p_audio_url, p_file_hash);
  IF (v_dup->>'is_duplicate')::boolean THEN
    RETURN jsonb_build_object('ok', false, 'error', 'duplicata', 'existing_id', v_dup->>'existing_id');
  END IF;

  INSERT INTO audio_memes (
    name, audio_url, category, duration_seconds, uploaded_by,
    tags, file_hash, mime_type, file_size,
    use_count, is_favorite, is_active
  ) VALUES (
    p_name, p_audio_url, p_category, p_duration_seconds, p_uploaded_by,
    p_tags, p_file_hash, p_mime_type, p_file_size,
    0, false, true
  ) RETURNING id INTO v_id;

  RETURN jsonb_build_object('ok', true, 'id', v_id, 'name', p_name, 'category', p_category);
END;
$$;


