--
-- Name: fn_add_tag(character varying, uuid, character varying, character varying); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_add_tag(p_entity_type character varying, p_entity_id uuid, p_tag_name character varying, p_assigned_by character varying DEFAULT 'system'::character varying) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$
DECLARE v_tag_id UUID;
BEGIN
    INSERT INTO evolution_tags (name) VALUES (LOWER(TRIM(p_tag_name))) ON CONFLICT (name) DO UPDATE SET use_count = evolution_tags.use_count + 1 RETURNING id INTO v_tag_id;
    INSERT INTO evolution_tag_assignments (tag_id, entity_type, entity_id, assigned_by) VALUES (v_tag_id, p_entity_type, p_entity_id, p_assigned_by) ON CONFLICT DO NOTHING;
    IF p_entity_type = 'contact' THEN
        UPDATE evolution_contacts SET tags = ARRAY(SELECT DISTINCT t.name FROM evolution_tag_assignments ta JOIN evolution_tags t ON ta.tag_id = t.id WHERE ta.entity_type = 'contact' AND ta.entity_id = p_entity_id) WHERE id = p_entity_id;
    END IF;
    RETURN TRUE;
END;
$$;


ALTER FUNCTION zapp.fn_add_tag(p_entity_type character varying, p_entity_id uuid, p_tag_name character varying, p_assigned_by character varying) OWNER TO postgres;

--
-- Name: fn_add_to_dlq(text, text, text, jsonb, text, text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_add_to_dlq(p_event_type text, p_instance_name text, p_remote_jid text, p_payload jsonb, p_error_message text, p_error_stack text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$ DECLARE v_dlq_id UUID; BEGIN INSERT INTO evolution_webhook_dlq(event_type,instance_name,remote_jid,payload,error_message,error_stack,next_retry_at) VALUES(p_event_type,p_instance_name,p_remote_jid,p_payload,p_error_message,p_error_stack,NOW()+INTERVAL '5 minutes') RETURNING id INTO v_dlq_id; RETURN v_dlq_id; END; $$;


ALTER FUNCTION zapp.fn_add_to_dlq(p_event_type text, p_instance_name text, p_remote_jid text, p_payload jsonb, p_error_message text, p_error_stack text) OWNER TO postgres;

--
-- Name: fn_add_to_dlq(text, text, text, jsonb, text, text, text, text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_add_to_dlq(p_event_type text, p_instance_name text, p_remote_jid text DEFAULT NULL::text, p_payload jsonb DEFAULT NULL::jsonb, p_error_message text DEFAULT ''::text, p_error_stack text DEFAULT NULL::text, p_raw_payload text DEFAULT NULL::text, p_queue_name text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'public'
    AS $$
DECLARE
  v_dlq_id UUID;
  v_resolved_payload JSONB;
BEGIN
  -- Tentar parsear raw_payload como JSONB se payload não foi fornecido
  IF p_payload IS NULL AND p_raw_payload IS NOT NULL THEN
    BEGIN
      v_resolved_payload := p_raw_payload::jsonb;
    EXCEPTION WHEN OTHERS THEN
      v_resolved_payload := NULL; -- BAD JSON: guarda no raw_payload
    END;
  ELSE
    v_resolved_payload := p_payload;
  END IF;

  INSERT INTO zapp.evolution_webhook_dlq (
    event_type, instance_name, remote_jid,
    payload, raw_payload, queue_name,
    error_message, error_stack,
    next_retry_at, status, created_at
  )
  VALUES (
    p_event_type, p_instance_name, p_remote_jid,
    v_resolved_payload, p_raw_payload, p_queue_name,
    p_error_message, p_error_stack,
    now() + INTERVAL '5 minutes', 'pending', now()
  )
  RETURNING id INTO v_dlq_id;

  RETURN v_dlq_id;
END;
$$;


ALTER FUNCTION zapp.fn_add_to_dlq(p_event_type text, p_instance_name text, p_remote_jid text, p_payload jsonb, p_error_message text, p_error_stack text, p_raw_payload text, p_queue_name text) OWNER TO postgres;

