--
-- Name: fn_agent_presence_status(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_agent_presence_status() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$
BEGIN
  NEW.updated_at = now();
  NEW.last_activity_at = now();
  IF NEW.status = 'online' AND (OLD.status IS NULL OR OLD.status != 'online') THEN
    NEW.went_online_at = now();
  END IF;
  IF NEW.status = 'offline' AND OLD.status = 'online' THEN
    NEW.went_offline_at = now();
  END IF;
  RETURN NEW;
END;
$$;


