--
-- Name: fn_alert_connection_drift(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_alert_connection_drift() RETURNS TABLE(alerted_users integer, problematic_count integer, classifications text[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog', 'monitoring', 'auth'
    AS $$
DECLARE
  v_summary record; v_user_count int := 0; v_dedup_window interval := interval '15 minutes';
BEGIN
  SELECT * INTO v_summary FROM zapp.fn_connection_drift_summary();
  problematic_count := v_summary.degraded + v_summary.unhealthy + v_summary.stale + v_summary.never_checked;
  IF problematic_count = 0 THEN classifications := ARRAY[]::text[]; alerted_users := 0; RETURN NEXT; RETURN; END IF;
  IF EXISTS (SELECT 1 FROM zapp.app_notifications n WHERE n.entity_type='whatsapp_connection_drift' AND n.created_at > now()-v_dedup_window AND (n.metadata->>'problematic_count')::int = problematic_count) THEN
    classifications := ARRAY['skipped_dedup']; alerted_users := 0; RETURN NEXT; RETURN;
  END IF;
  classifications := ARRAY[]::text[];
  IF v_summary.degraded     > 0 THEN classifications := array_append(classifications, 'degraded'); END IF;
  IF v_summary.unhealthy    > 0 THEN classifications := array_append(classifications, 'unhealthy'); END IF;
  IF v_summary.stale        > 0 THEN classifications := array_append(classifications, 'stale'); END IF;
  IF v_summary.never_checked> 0 THEN classifications := array_append(classifications, 'never_checked'); END IF;
  WITH inserted AS (
    INSERT INTO zapp.app_notifications (user_id, title, body, type, entity_type, action_url, metadata)
    SELECT u.id, format('Conexao WhatsApp instavel (%s/%s)',problematic_count,v_summary.total_connections),
      format('Drift: %s. Ultima reconciliacao ha %ss.',array_to_string(classifications,', '),v_summary.reconcile_age_seconds),
      'warning','whatsapp_connection_drift','/#connections',
      jsonb_build_object('problematic_count',problematic_count,'total_connections',v_summary.total_connections,'classifications',classifications,'reconcile_age_seconds',v_summary.reconcile_age_seconds,'detected_at',now())
    FROM auth.users u WHERE u.email_confirmed_at IS NOT NULL RETURNING 1
  ) SELECT count(*) INTO v_user_count FROM inserted;
  alerted_users := v_user_count; RETURN NEXT;
END;
$$;


ALTER FUNCTION zapp.fn_alert_connection_drift() OWNER TO postgres;

--
-- Name: FUNCTION fn_alert_connection_drift(); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.fn_alert_connection_drift() IS 'Detecta drift de conexões WhatsApp e cria notificações em app_notifications. Tem dedup de 15min para evitar spam. Disparado pelo cron whatsapp_connection_drift_alert (a cada 5min).';


--
-- Name: fn_alert_connection_lost(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_alert_connection_lost() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$
BEGIN
    IF NEW.event_type = 'CONNECTION_UPDATE' THEN
        IF (NEW.payload->>'state') IN ('close','connecting') OR (NEW.payload->'data'->>'state') IN ('close','connecting') THEN
            INSERT INTO evolution_alerts (alert_type,severity,message,payload) VALUES ('connection_lost','critical','WhatsApp desconectado! Estado: '||COALESCE(NEW.payload->>'state',NEW.payload->'data'->>'state','unknown'),NEW.payload);
        ELSIF (NEW.payload->>'state') = 'open' OR (NEW.payload->'data'->>'state') = 'open' THEN
            INSERT INTO evolution_alerts (alert_type,severity,message,payload) VALUES ('connection_restored','info','WhatsApp reconectado com sucesso!',NEW.payload);
        END IF;
    END IF;
    IF NEW.event_type = 'LOGOUT_INSTANCE' THEN
        INSERT INTO evolution_alerts (alert_type,severity,message,payload) VALUES ('logout_detected','critical','ALERTA: Logout detectado na instancia!',NEW.payload);
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION zapp.fn_alert_connection_lost() OWNER TO postgres;

