BEGIN
  INSERT INTO evolution_alerts (alert_type, title, message, description, severity, payload)
  VALUES (p_type, p_title, p_message, p_message, p_severity, jsonb_build_object('source', p_source, 'metadata', p_metadata))
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


