--
-- Name: fn_alert_ghost_conversations(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_alert_ghost_conversations() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'ops', 'pg_catalog'
    AS $$ DECLARE v_count int; v_threshold int:=500; v_payload jsonb; BEGIN SELECT count(*) INTO v_count FROM zapp.evolution_conversations cv WHERE cv.contact_id IS NULL AND cv.remote_jid LIKE '%@s.whatsapp.net' AND cv.last_message_at > now()-interval'30 days'; IF EXISTS (SELECT 1 FROM zapp.evolution_alerts WHERE alert_type='ghost_conversations' AND created_at > now()-interval'24 hours' AND resolved_at IS NULL) THEN RETURN 0; END IF; IF v_count < v_threshold THEN UPDATE zapp.evolution_alerts SET resolved_at=now(), resolved_by='cron-auto-ghost' WHERE alert_type='ghost_conversations' AND resolved_at IS NULL; RETURN 0; END IF; v_payload:=jsonb_build_object('ghost_count',v_count,'threshold',v_threshold,'check_at',now(),'root_cause','Contatos sem registro no CRM (pre-importacao ou deletados)','instruction','Ver public.evo_ghost_conversations. Importar via UI Zapp Webb ou aguardar Baileys.','trend','Decrescente: mai=178 JIDs, jun=159, jul=90, ago=12 (normal)'); INSERT INTO zapp.evolution_alerts (alert_type,severity,title,message,payload) VALUES ('ghost_conversations','warning',format('%s conversas sem contato (limite: %s)',v_count,v_threshold),format('v_ghost_conversations retornou %s conversas (30d) sem contact_id. Acima de %s. Importar contatos via UI.',v_count,v_threshold),v_payload); RETURN v_count; END; $$;


