CREATE FUNCTION zapp.fn_alert_ghost_message_events() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$ DECLARE v_ghosts jsonb; v_n int; BEGIN SELECT jsonb_agg(jsonb_build_object('instance', g.instance, 'eventos', g.n, 'ultimo', g.ultimo)), count(*) INTO v_ghosts, v_n FROM ( SELECT w.instance, count(*) AS n, max(w.created_at) AS ultimo FROM zapp.webhook_audit_log w WHERE w.error_message = 'unknown_instance' AND w.event_type IN ('messages.upsert','MESSAGES_UPSERT') AND w.created_at > now() - interval '15 minutes' AND NOT EXISTS (SELECT 1 FROM zapp.instance_registry ir WHERE ir.instance_name = w.instance AND ir.status = 'test') AND NOT EXISTS (SELECT 1 FROM zapp.whatsapp_connections wc WHERE wc.instance_name = w.instance OR wc.evo_instance_id = w.instance) GROUP BY w.instance ) g; IF v_n IS NULL OR v_n = 0 THEN RETURN 0; END IF; IF EXISTS (SELECT 1 FROM zapp.evolution_alerts WHERE alert_type = 'ghost_message_events' AND created_at > now() - interval '60 minutes') THEN RETURN 0; END IF; INSERT INTO zapp.evolution_alerts (alert_type, severity, title, message, payload) VALUES ('ghost_message_events', 'critical', 'Mensagens de instancia DESCONHECIDA rejeitadas (possivel instancia fantasma)', 'messages.upsert rejeitados como unknown_instance nos ultimos 15 min. Verificar instancias na Evolution.', v_ghosts); RETURN v_n; END; $$;


