--
-- Name: fn_alert_health_score_degraded(integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_alert_health_score_degraded(p_threshold integer) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$
DECLARE
  v_hs JSONB; v_score NUMERIC; v_grade TEXT; v_already BOOLEAN;
BEGIN
  v_hs    := zapp.fn_system_health_score_cached(30, FALSE);
  v_score := (v_hs->>'score')::NUMERIC;
  v_grade := v_hs->>'grade';

  IF v_score >= p_threshold THEN
    RETURN jsonb_build_object('status','ok','score',v_score,'grade',v_grade,'_cached',(v_hs->>'_cached')::BOOL);
  END IF;

  SELECT EXISTS(
    SELECT 1 FROM zapp.evolution_alerts
    WHERE alert_type='health_score_degraded'
      AND created_at > NOW()-INTERVAL '2 hours'
      AND resolved_at IS NULL
  ) INTO v_already;

  IF v_already THEN
    RETURN jsonb_build_object('status','already_alerted','score',v_score,'_cached',(v_hs->>'_cached')::BOOL);
  END IF;

  INSERT INTO zapp.evolution_alerts(alert_type, severity, title, message, payload)
  VALUES(
    'health_score_degraded',
    CASE WHEN v_score<50 THEN 'critical' WHEN v_score<65 THEN 'high' ELSE 'medium' END,
    'Health Score DEGRADADO: '||ROUND(v_score,1)||'% (Grade '||v_grade||')',
    'Score '||ROUND(v_score,1)||'% abaixo do threshold '||p_threshold||'%. Grade: '||v_grade||'. Verifique o breakdown.',
    jsonb_build_object('score',v_score,'grade',v_grade,'threshold',p_threshold,'breakdown',v_hs->'breakdown')
  );

  RETURN jsonb_build_object(
    'status','alert_created','score',v_score,'grade',v_grade,
    'severity',CASE WHEN v_score<50 THEN 'critical' WHEN v_score<65 THEN 'high' ELSE 'medium' END
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('error',SQLERRM);
END;
$$;


ALTER FUNCTION zapp.fn_alert_health_score_degraded(p_threshold integer) OWNER TO postgres;

--
-- Name: fn_alert_health_score_degraded(numeric); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_alert_health_score_degraded(p_threshold numeric DEFAULT 70) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_hs JSONB; v_score NUMERIC; v_grade TEXT; v_already BOOLEAN;
BEGIN
  -- CACHE: usa fn_system_health_score_cached (TTL=5min) em vez de fn_system_health_score()
  -- Reducao: ~1256ms -> <5ms em cache hit (220x mais rapido)
  v_hs    := zapp.fn_system_health_score_cached(5, FALSE);
  v_score := (v_hs->>'score')::NUMERIC;
  v_grade := v_hs->>'grade';

  IF v_score >= p_threshold THEN
    RETURN jsonb_build_object('status','ok','score',v_score,'grade',v_grade,'_cached',(v_hs->>'_cached')::BOOL);
  END IF;

  SELECT EXISTS(
    SELECT 1 FROM zapp.evolution_alerts
    WHERE alert_type='health_score_degraded'
      AND created_at > NOW()-INTERVAL '2 hours'
      AND resolved_at IS NULL
  ) INTO v_already;

  IF v_already THEN
    RETURN jsonb_build_object('status','already_alerted','score',v_score,'_cached',(v_hs->>'_cached')::BOOL);
  END IF;

  INSERT INTO zapp.evolution_alerts(alert_type, severity, title, message, payload)
  VALUES(
    'health_score_degraded',
    CASE WHEN v_score<50 THEN 'critical' WHEN v_score<65 THEN 'high' ELSE 'medium' END,
    'Health Score DEGRADADO: '||ROUND(v_score,1)||'% (Grade '||v_grade||')',
    'Score '||ROUND(v_score,1)||'% abaixo do threshold '||p_threshold||'%. Grade: '||v_grade||'. Verifique o breakdown.',
    jsonb_build_object('score',v_score,'grade',v_grade,'threshold',p_threshold,'breakdown',v_hs->'breakdown')
  );

  RETURN jsonb_build_object(
    'status','alert_created','score',v_score,'grade',v_grade,
    'severity',CASE WHEN v_score<50 THEN 'critical' WHEN v_score<65 THEN 'high' ELSE 'medium' END
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('error',SQLERRM);
END;
$$;


ALTER FUNCTION zapp.fn_alert_health_score_degraded(p_threshold numeric) OWNER TO postgres;

--
-- Name: FUNCTION fn_alert_health_score_degraded(p_threshold numeric); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.fn_alert_health_score_degraded(p_threshold numeric) IS 'Verifica health score e cria alerta se abaixo do threshold. v2: usa fn_system_health_score_cached(5,FALSE) em vez de fn_system_health_score() direto. Reducao: ~1256ms -> <5ms em cache hit. Retorna _cached flag para diagnostico.';


--
-- Name: fn_alert_message_pipeline_stalled(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_alert_message_pipeline_stalled() RETURNS TABLE(alerted_users integer, pipeline_health text, msgs_5min integer, age_seconds integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog', 'monitoring', 'auth'
    AS $$
DECLARE
  v_rate record; v_user_count int := 0; v_dedup_window interval := interval '15 minutes';
BEGIN
  SELECT * INTO v_rate FROM zapp.fn_message_rate_5min();
  pipeline_health := v_rate.pipeline_health; msgs_5min := v_rate.msgs_5min; age_seconds := v_rate.age_seconds;
  IF v_rate.pipeline_health <> 'critical_business_hours' THEN alerted_users := 0; RETURN NEXT; RETURN; END IF;
  -- FIX 2026-07-04: zapp.app_notifications
  IF EXISTS (SELECT 1 FROM zapp.app_notifications n WHERE n.entity_type='message_pipeline_stalled' AND n.created_at > now()-v_dedup_window) THEN
    alerted_users := 0; RETURN NEXT; RETURN;
  END IF;
  WITH inserted AS (
    INSERT INTO zapp.app_notifications (user_id, title, body, type, entity_type, action_url, metadata)
    SELECT u.id, 'Pipeline de mensagens parado',
      format('0 mensagens recebidas em 5min durante horario comercial. Ultima ha %ss.',v_rate.age_seconds),
      'error','message_pipeline_stalled','/#dashboard',
      jsonb_build_object('msgs_5min',v_rate.msgs_5min,'age_seconds',v_rate.age_seconds,'last_msg_at',v_rate.last_msg_at,'detected_at',now())
    FROM auth.users u WHERE u.email_confirmed_at IS NOT NULL RETURNING 1
  ) SELECT count(*) INTO v_user_count FROM inserted;
  alerted_users := v_user_count; RETURN NEXT;
END;
$$;


ALTER FUNCTION zapp.fn_alert_message_pipeline_stalled() OWNER TO postgres;

