-- Name: FUNCTION fn_alert_message_pipeline_stalled(); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.fn_alert_message_pipeline_stalled() IS 'Detecta pipeline de mensagens parado durante horário comercial (Bateria #8 pós-incidente 2026-05-04). Alerta com type=error e dedup 15min.';


--
-- Name: fn_alert_table_bloat(numeric); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_alert_table_bloat(p_threshold_pct numeric DEFAULT 15) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_bloated jsonb := '[]'::jsonb;
  v_count int := 0;
  v_row record;
BEGIN
  FOR v_row IN
    SELECT schemaname, relname,
      n_dead_tup, n_live_tup,
      round(100.0*n_dead_tup/NULLIF(n_live_tup+n_dead_tup,0),2) as dead_pct,
      pg_size_pretty(pg_total_relation_size(schemaname||'.'||relname)) as total_size
    FROM pg_stat_user_tables
    WHERE schemaname IN ('public','zapp','evo')
      AND (n_live_tup + n_dead_tup) >= 500
      AND round(100.0*n_dead_tup/NULLIF(n_live_tup+n_dead_tup,0),2) > p_threshold_pct
    ORDER BY dead_pct DESC LIMIT 10
  LOOP
    v_bloated := v_bloated || jsonb_build_array(
      jsonb_build_object(
        'schema', v_row.schemaname,
        'table', v_row.relname,
        'dead_pct', v_row.dead_pct,
        'dead_tuples', v_row.n_dead_tup,
        'size', v_row.total_size
      )
    );
    v_count := v_count + 1;
  END LOOP;

  IF v_count > 0 THEN
    -- Alertar admins via app_notifications
    INSERT INTO zapp.app_notifications(user_id, title, body, type, metadata)
    SELECT u.id,
      'Table Bloat Alert ('||v_count||' tabelas)',
      'Tabelas com dead_pct > '||p_threshold_pct||'%% detectadas. VACUUM necessario.',
      'warning',
      jsonb_build_object('bloated_tables', v_bloated, 'threshold_pct', p_threshold_pct, 'count', v_count)
    FROM auth.users u
    JOIN zapp.profiles p ON p.id = u.id
    WHERE p.role = 'admin'
    LIMIT 1
    ON CONFLICT DO NOTHING;
  END IF;

  RETURN jsonb_build_object(
    'checked_at', now(),
    'threshold_pct', p_threshold_pct,
    'bloated_count', v_count,
    'tables', v_bloated,
    'action', CASE WHEN v_count > 0 THEN 'alert_sent' ELSE 'ok' END
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('error', SQLERRM, 'checked_at', now());
END;
$$;


ALTER FUNCTION zapp.fn_alert_table_bloat(p_threshold_pct numeric) OWNER TO postgres;

--
-- Name: FUNCTION fn_alert_table_bloat(p_threshold_pct numeric); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.fn_alert_table_bloat(p_threshold_pct numeric) IS 'Alerta quando dead_pct > threshold (default 15%) em tabelas public/zapp/evo. Insere notificacao para admins. Criado auditoria 2026-07-04.';


--
-- Name: fn_alert_wpp2_disconnection(text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_alert_wpp2_disconnection(p_instance_name text DEFAULT 'wpp2'::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$
DECLARE
  v_conn record;
  v_min_disconnected numeric;
  v_already_alerted boolean;
  v_alert_type text;
BEGIN
  SELECT status, phone_number, last_connected_at, disconnected_at, instance_name, is_active
  INTO v_conn
  FROM zapp.whatsapp_connections
  WHERE instance_name = p_instance_name
  LIMIT 1;

  IF v_conn IS NULL OR v_conn.status = 'connected' THEN
    RETURN jsonb_build_object('status','ok','instance_name',p_instance_name,'instance_status', COALESCE(v_conn.status,'not_found'));
  END IF;

  v_min_disconnected := COALESCE(
    EXTRACT(EPOCH FROM (now() - GREATEST(v_conn.last_connected_at, v_conn.disconnected_at))) / 60,
    9999
  );

  IF v_min_disconnected < 30 THEN
    RETURN jsonb_build_object('status','grace_period','disconnected_min',round(v_min_disconnected::numeric,1));
  END IF;

  v_alert_type := p_instance_name || '_disconnection';

  SELECT EXISTS(
    SELECT 1 FROM zapp.evolution_alerts
    WHERE alert_type = v_alert_type
      AND created_at > now() - INTERVAL '60 minutes'
      AND resolved_at IS NULL
  ) INTO v_already_alerted;

  IF v_already_alerted THEN
    RETURN jsonb_build_object('status','already_alerted','disconnected_min',round(v_min_disconnected::numeric,1));
  END IF;

  INSERT INTO zapp.evolution_alerts(alert_type, severity, title, message, payload)
  VALUES (
    v_alert_type,
    CASE WHEN v_min_disconnected > 120 THEN 'critical' ELSE 'high' END,
    format('%s DESCONECTADO — Rescan QR necessario', p_instance_name),
    format('Instancia %s (%s) desconectada ha %s minutos. Acesse o manager para reconectar.',
           p_instance_name, v_conn.phone_number, round(v_min_disconnected)::text),
    jsonb_build_object('instance',p_instance_name,'phone',v_conn.phone_number,
                       'disconnected_min',round(v_min_disconnected::numeric,1),
                       'action_required','QR_SCAN','url','https://evolution.atomicabr.com.br/manager')
  );

  RETURN jsonb_build_object('status','alert_created',
    'severity',CASE WHEN v_min_disconnected>120 THEN 'critical' ELSE 'high' END,
    'disconnected_min',round(v_min_disconnected::numeric,1));
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('error',SQLERRM,'ts',now());
END;
$$;


ALTER FUNCTION zapp.fn_alert_wpp2_disconnection(p_instance_name text) OWNER TO postgres;

--
-- Name: fn_analytics_wal_watchdog(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_analytics_wal_watchdog() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog'
    AS $$ DECLARE v_slot TEXT; v_lag_mb NUMERIC; v_flush_lag_mb NUMERIC; v_effective_mb NUMERIC; v_active BOOLEAN; v_trigger_mb CONSTANT NUMERIC := 150; v_frozen_trigger_mb CONSTANT NUMERIC := 150; v_high_trigger CONSTANT NUMERIC := 400; v_cooldown CONSTANT INTERVAL := '45 minutes'; v_last_open TIMESTAMPTZ; v_alert_exists BOOLEAN; v_flush_lsn pg_lsn; v_last_flush_lsn_str TEXT; v_frozen_minutes NUMERIC; BEGIN /* FIX-SLOT-ROTATION-2026-08-12: fecha alertas orfaos de slots dropados */ UPDATE zapp.evolution_alerts ea SET resolved_at=now(), resolved_by='fn_analytics_wal_watchdog:slot_dropped' WHERE ea.alert_type='wal_slot_analytics_restart' AND ea.resolved_at IS NULL AND (ea.payload->>'slot') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM pg_replication_slots prs WHERE prs.slot_name=(ea.payload->>'slot')); SELECT slot_name, round(pg_wal_lsn_diff(pg_current_wal_lsn(),restart_lsn)/1024.0/1024,1), round(pg_wal_lsn_diff(pg_current_wal_lsn(),confirmed_flush_lsn)/1024.0/1024,1), active, confirmed_flush_lsn INTO v_slot, v_lag_mb, v_flush_lag_mb, v_active, v_flush_lsn FROM pg_replication_slots WHERE slot_name LIKE 'cainophile%' ORDER BY pg_wal_lsn_diff(pg_current_wal_lsn(),restart_lsn) DESC LIMIT 1; IF v_slot IS NULL THEN RETURN jsonb_build_object('ok',true,'msg','sem slot cainophile'); END IF; v_effective_mb := GREATEST(v_lag_mb, v_flush_lag_mb); IF v_effective_mb <= v_trigger_mb THEN UPDATE zapp.evolution_alerts SET resolved_at=now(), resolved_by='fn_analytics_wal_watchdog:recovered' WHERE alert_type IN ('wal_slot_analytics_restart','wal_slot_high_lag') AND resolved_at IS NULL; RETURN jsonb_build_object('ok',true,'slot',v_slot,'effective_mb',v_effective_mb,'msg','abaixo do trigger — OK, alertas resolvidos'); END IF; SELECT MAX(created_at) INTO v_last_open FROM zapp.evolution_alerts WHERE alert_type='wal_slot_analytics_restart' AND resolved_at IS NULL AND created_at > NOW()-v_cooldown; IF v_last_open IS NOT NULL THEN RETURN jsonb_build_object('ok',true,'slot',v_slot,'effective_mb',v_effective_mb,'msg','cooldown ativo (alerta aberto desde '||v_last_open::text||')'); END IF; SELECT EXISTS(SELECT 1 FROM zapp.evolution_alerts WHERE alert_type='wal_slot_analytics_restart' AND resolved_at IS NULL) INTO v_alert_exists; IF NOT v_alert_exists THEN INSERT INTO zapp.evolution_alerts (alert_type,severity,title,message,payload) VALUES ('wal_slot_analytics_restart', CASE WHEN v_effective_mb >= v_high_trigger THEN 'high' ELSE 'medium' END,'[WAL-WATCHDOG] Slot '||v_slot||' com '||v_effective_mb||'MB','Slot '||v_slot||' atingiu '||v_effective_mb||'MB. restart_lag='||v_lag_mb||'MB flush_lag='||v_flush_lag_mb||'MB',jsonb_build_object('slot',v_slot,'restart_mb',v_lag_mb,'flush_mb',v_flush_lag_mb,'effective_mb',v_effective_mb,'active',v_active,'checked_at',now(),'fix','NB7-s17: cooldown baseado em alertas ABERTOS','frozen_detection','NB8-audit-s15: flush_lag>150MB trigger added')); END IF; RETURN jsonb_build_object('ok',true,'action','alert_created_or_existing','slot',v_slot,'effective_mb',v_effective_mb,'msg','alerta criado/mantido — wal-slot-guard container deve agir'); END $$;


