-- Name: fn_audio_meme_stats(); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.fn_audio_meme_stats() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$
BEGIN
  RETURN (
    SELECT jsonb_build_object(
      'ok', true,
      'total_memes', (SELECT count(*) FROM audio_memes WHERE is_active),
      'total_inactive', (SELECT count(*) FROM audio_memes WHERE NOT is_active),
      'total_categories', (SELECT count(*) FROM audio_meme_categories WHERE is_active),
      'categories_with_memes', (SELECT count(DISTINCT category) FROM audio_memes WHERE is_active),
      'total_favorites_by_users', (SELECT count(*) FROM audio_meme_favorites),
      'total_use_count', (SELECT COALESCE(sum(use_count),0) FROM audio_memes),
      'total_with_tags', (SELECT count(*) FROM audio_memes WHERE array_length(tags,1) > 0),
      'total_with_hash', (SELECT count(*) FROM audio_memes WHERE file_hash IS NOT NULL),
      'avg_duration_seconds', (SELECT round(avg(duration_seconds)::numeric,1) FROM audio_memes WHERE duration_seconds IS NOT NULL),
      'mime_types', (
        SELECT jsonb_agg(jsonb_build_object('mime', COALESCE(mime_type,'null'), 'count', cnt))
        FROM (SELECT mime_type, count(*) AS cnt FROM audio_memes GROUP BY mime_type ORDER BY cnt DESC) sub
      ),
      'top_categories', (
        SELECT jsonb_agg(jsonb_build_object(
          'slug', slug, 'label', label_pt, 'emoji', emoji, 'count', meme_count, 'uses', total_uses
        ) ORDER BY meme_count DESC)
        FROM audio_meme_categories WHERE meme_count > 0
      ),
      'storage_status', 'URLs no Supabase Cloud antigo - migracao R2 pendente'
    )
  );
END;
$$;


