--
-- Name: fn_audit_storage_orphans(text, integer, integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_audit_storage_orphans(p_bucket text DEFAULT 'whatsapp-media'::text, p_days_old integer DEFAULT 30, p_limit integer DEFAULT 100) RETURNS TABLE(bucket_id text, object_name text, object_size bigint, created_at timestamp with time zone, motivo text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'storage', 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    o.bucket_id::text,
    o.name::text,
    (o.metadata->>'size')::bigint,
    o.created_at,
    'sem_referencia_db'::text
  FROM storage.objects o
  WHERE o.bucket_id = p_bucket
    AND o.created_at < now() - (p_days_old || ' days')::interval
    -- Não referenciado em evolution_media
    AND NOT EXISTS (
      SELECT 1 FROM zapp.evolution_media em
      WHERE em.storage_path = o.name AND em.storage_bucket = o.bucket_id
    )
    -- Não referenciado em evolution_messages
    AND NOT EXISTS (
      SELECT 1 FROM zapp.evolution_messages m WHERE m.media_path = o.name
    )
    -- Não referenciado em stickers (adicionado)
    AND NOT EXISTS (
      SELECT 1 FROM zapp.stickers s
      WHERE s.image_url LIKE '%' || o.name
         OR s.image_url LIKE '%' || split_part(o.name, '/', 2)
    )
    -- Não referenciado em audio_memes (adicionado)
    AND NOT EXISTS (
      SELECT 1 FROM zapp.audio_memes am
      WHERE am.audio_url LIKE '%' || o.name
         OR am.audio_url LIKE '%' || split_part(o.name, '/', 2)
    )
  ORDER BY o.created_at
  LIMIT p_limit;
END $$;


ALTER FUNCTION zapp.fn_audit_storage_orphans(p_bucket text, p_days_old integer, p_limit integer) OWNER TO postgres;

--
-- Name: fn_audit_trigger(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_audit_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$ BEGIN IF TG_OP = 'DELETE' THEN INSERT INTO evolution_audit_log (action, entity_type, entity_id, old_values, performed_by) VALUES ('delete', TG_TABLE_NAME, OLD.id, to_jsonb(OLD), 'system'); RETURN OLD; ELSIF TG_OP = 'UPDATE' THEN INSERT INTO evolution_audit_log (action, entity_type, entity_id, old_values, new_values, performed_by) VALUES ('update', TG_TABLE_NAME, NEW.id, to_jsonb(OLD), to_jsonb(NEW), 'system'); RETURN NEW; ELSIF TG_OP = 'INSERT' THEN INSERT INTO evolution_audit_log (action, entity_type, entity_id, new_values, performed_by) VALUES ('create', TG_TABLE_NAME, NEW.id, to_jsonb(NEW), 'system'); RETURN NEW; END IF; RETURN NULL; END; $$;


ALTER FUNCTION zapp.fn_audit_trigger() OWNER TO postgres;

--
-- Name: fn_audit_trigger_v2(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_audit_trigger_v2() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE v_row_id TEXT; v_changed JSONB;
BEGIN
  IF TG_OP = 'DELETE' THEN
    BEGIN v_row_id := OLD.id::text; EXCEPTION WHEN OTHERS THEN v_row_id := NULL; END;
    INSERT INTO audit_log_tables(tbl_name,operation,row_id,old_values,changed_by) VALUES(TG_TABLE_NAME,'DELETE',v_row_id,to_jsonb(OLD),current_user); RETURN OLD;
  ELSIF TG_OP = 'UPDATE' THEN
    BEGIN v_row_id := NEW.id::text; EXCEPTION WHEN OTHERS THEN v_row_id := NULL; END;
    SELECT jsonb_object_agg(key,value) INTO v_changed FROM jsonb_each(to_jsonb(NEW)) WHERE to_jsonb(OLD)->key IS DISTINCT FROM value;
    IF v_changed IS NOT NULL AND v_changed != '{}'::jsonb THEN
      INSERT INTO audit_log_tables(tbl_name,operation,row_id,changed_fields,old_values,new_values,changed_by) VALUES(TG_TABLE_NAME,'UPDATE',v_row_id,v_changed,to_jsonb(OLD),to_jsonb(NEW),current_user);
    END IF; RETURN NEW;
  ELSIF TG_OP = 'INSERT' THEN
    BEGIN v_row_id := NEW.id::text; EXCEPTION WHEN OTHERS THEN v_row_id := NULL; END;
    INSERT INTO audit_log_tables(tbl_name,operation,row_id,new_values,changed_by) VALUES(TG_TABLE_NAME,'INSERT',v_row_id,to_jsonb(NEW),current_user); RETURN NEW;
  END IF; RETURN NULL;
END; $$;


ALTER FUNCTION zapp.fn_audit_trigger_v2() OWNER TO postgres;

--
-- Name: fn_audit_vocabulary_check_alert(); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.fn_audit_vocabulary_check_alert() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE 
  v_divergencias INT;
  v_amostra jsonb;
BEGIN
  SELECT COUNT(*) INTO v_divergencias
  FROM fn_validate_audit_vocabulary()
  WHERE permitida = false;
  
  IF v_divergencias > 0 THEN
    SELECT jsonb_agg(jsonb_build_object('rpc', rpc_name, 'action', action_literal))
    INTO v_amostra
    FROM fn_validate_audit_vocabulary() WHERE permitida = false LIMIT 10;
    
    INSERT INTO webhook_health_alerts (alert_type, severity, title, details)
    SELECT 'audit_vocabulary_drift', 'WARNING',
      format('🟡 %s RPCs usam actions fora do vocabulário', v_divergencias),
      jsonb_build_object('divergencias_encontradas', v_divergencias, 'amostra', v_amostra,
        'acao_recomendada', 'Adicionar actions ao constraint evolution_audit_log_action_check OU renomear action no RPC')
    WHERE NOT EXISTS (
      SELECT 1 FROM webhook_health_alerts 
      WHERE alert_type = 'audit_vocabulary_drift' AND resolved_at IS NULL
    );
  ELSE
    UPDATE webhook_health_alerts 
    SET resolved_at = now(),
        details = details || jsonb_build_object('auto_resolved', true, 'reason', 'Divergências eliminadas')
    WHERE alert_type = 'audit_vocabulary_drift' AND resolved_at IS NULL;
  END IF;
END;
$$;


ALTER FUNCTION zapp.fn_audit_vocabulary_check_alert() OWNER TO supabase_admin;

--
-- Name: fn_auto_archive_inactive_conversations(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_auto_archive_inactive_conversations() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE v_count integer;
BEGIN
  WITH archived AS (UPDATE evolution_conversations SET status='arquivada',updated_at=NOW() WHERE status IN ('aberta','open','active') AND updated_at < NOW()-INTERVAL '30 days' AND id NOT IN (SELECT DISTINCT conversation_id FROM evolution_messages WHERE created_at > NOW()-INTERVAL '30 days' AND conversation_id IS NOT NULL) RETURNING 1)
  SELECT COUNT(*) INTO v_count FROM archived;
  IF v_count > 0 THEN INSERT INTO evolution_realtime_events (event_type,entity_type,title,body,priority) VALUES ('conversations_archived','conversation','Conversas Arquivadas',v_count||' conversas inativas foram arquivadas','low'); END IF;
  RETURN v_count;
END; $$;


ALTER FUNCTION zapp.fn_auto_archive_inactive_conversations() OWNER TO postgres;

--
-- Name: fn_auto_assign_contact(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_auto_assign_contact() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE v_connection_id uuid; v_agent uuid;
BEGIN
  BEGIN
    SELECT wc.id INTO v_connection_id FROM public.whatsapp_connections wc
    WHERE wc.instance_name = NEW.instance_name::text AND wc.is_active = true
    ORDER BY wc.last_connected_at DESC NULLS LAST LIMIT 1;
    SELECT r.agent_id INTO v_agent FROM public.client_wallet_rules r
    WHERE r.is_active = true AND (r.whatsapp_connection_id IS NULL OR r.whatsapp_connection_id = v_connection_id)
    ORDER BY r.priority DESC, r.created_at ASC LIMIT 1;
    IF v_agent IS NOT NULL THEN NEW.assigned_to := v_agent::text; END IF;
  EXCEPTION WHEN OTHERS THEN NULL;
  END;
  RETURN NEW;
END $$;


ALTER FUNCTION zapp.fn_auto_assign_contact() OWNER TO postgres;

--
-- Name: FUNCTION fn_auto_assign_contact(); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.fn_auto_assign_contact() IS 'Paridade Lovable (auto_assign_contact) adaptada: resolve conexão via instance_name; carteira de clientes (client_wallet_rules). Exception-safe: nunca bloqueia ingestão.';


--
-- Name: fn_auto_categorize_group(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_auto_categorize_group() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$
BEGIN
  IF NEW.name ILIKE '%venda%' OR NEW.name ILIKE '%comercial%' THEN NEW.category := 'vendas';
  ELSIF NEW.name ILIKE '%suporte%' OR NEW.name ILIKE '%atendimento%' THEN NEW.category := 'suporte';
  ELSIF NEW.name ILIKE '%interno%' OR NEW.name ILIKE '%equipe%' OR NEW.name ILIKE '%time%' THEN NEW.category := 'interno';
  ELSIF NEW.name ILIKE '%fornecedor%' THEN NEW.category := 'fornecedores';
  ELSIF NEW.name ILIKE '%cliente%' THEN NEW.category := 'clientes';
  ELSE NEW.category := COALESCE(NEW.category, 'outros'); END IF;
  RETURN NEW;
END; $$;


ALTER FUNCTION zapp.fn_auto_categorize_group() OWNER TO postgres;

--
-- Name: fn_auto_cleanup_stale_alerts(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_auto_cleanup_stale_alerts() RETURNS TABLE(acknowledged_count integer, resolved_dup_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE v_ack_count int := 0; v_dup_count int := 0;
BEGIN
  UPDATE evolution_alerts SET acknowledged=true, acknowledged_at=NOW(), acknowledged_by='fn_auto_cleanup_stale_alerts'
  WHERE acknowledged=false AND created_at < NOW()-INTERVAL '24 hours' AND alert_type LIKE ANY (ARRAY['cron_failing%','audit:%','test:%','high_value_deal','logout_detected']);
  GET DIAGNOSTICS v_ack_count = ROW_COUNT;
  WITH dups AS (SELECT id, ROW_NUMBER() OVER (PARTITION BY alert_type, COALESCE(remote_jid,'__null__') ORDER BY created_at DESC) AS rn
    FROM evolution_alerts WHERE acknowledged=false AND resolved_at IS NULL)
  UPDATE evolution_alerts e SET resolved_at=NOW(), resolved_by='fn_auto_cleanup_stale_alerts (dedup)'
  FROM dups d WHERE e.id=d.id AND d.rn > 1;
  GET DIAGNOSTICS v_dup_count = ROW_COUNT;
  RETURN QUERY SELECT v_ack_count, v_dup_count;
END $$;


ALTER FUNCTION zapp.fn_auto_cleanup_stale_alerts() OWNER TO postgres;

--
-- Name: fn_auto_enqueue_media_download(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_auto_enqueue_media_download() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog'
    AS $$
DECLARE v_media_key text; v_direct_path text; v_mimetype text; v_msg_subkey text; v_needs_download boolean;
BEGIN
  v_msg_subkey := CASE WHEN NEW.message_type IN ('image','imageMessage') THEN 'imageMessage'
    WHEN NEW.message_type IN ('video','videoMessage') THEN 'videoMessage'
    WHEN NEW.message_type IN ('ptvMessage') THEN 'ptvMessage'
    WHEN NEW.message_type IN ('audio','ptt','audioMessage') THEN 'audioMessage'
    WHEN NEW.message_type IN ('document','documentMessage') THEN 'documentMessage'
    WHEN NEW.message_type IN ('sticker','stickerMessage') THEN 'stickerMessage'
    ELSE NULL END;
  IF v_msg_subkey IS NULL THEN RETURN NEW; END IF;
  v_needs_download := (NEW.media_url IS NULL OR NEW.media_url='' OR NEW.media_url LIKE '%kong%' OR NEW.media_url LIKE '%mmg.whatsapp.net%' OR NEW.media_url LIKE '%.enc%');
  IF NOT v_needs_download THEN RETURN NEW; END IF;
  IF NEW.media_meta IS NOT NULL AND NEW.media_meta->>'mediaKey' IS NOT NULL THEN
    v_media_key := NEW.media_meta->>'mediaKey'; v_direct_path := NEW.media_meta->>'directPath'; v_mimetype := NEW.media_meta->>'mimetype';
  ELSIF NEW.ingest_meta IS NOT NULL AND NEW.ingest_meta->>'mediaKey' IS NOT NULL THEN
    v_media_key := NEW.ingest_meta->>'mediaKey'; v_direct_path := NEW.ingest_meta->>'directPath'; v_mimetype := NEW.ingest_meta->>'mimetype';
  ELSIF NEW.raw_data IS NOT NULL AND NEW.raw_data::text LIKE '%mediaKey%' THEN
    v_media_key := NEW.raw_data->'message'->v_msg_subkey->>'mediaKey'; v_direct_path := NEW.raw_data->'message'->v_msg_subkey->>'directPath'; v_mimetype := NEW.raw_data->'message'->v_msg_subkey->>'mimetype';
  END IF;
  IF NEW.message_id IS NOT NULL THEN
    PERFORM evo.rpc_boundary_enqueue_media_download(
      NEW.message_id, NEW.id, NEW.remote_jid, NEW.instance_name, NEW.message_type,
      v_media_key, v_direct_path, v_mimetype,
      CASE WHEN v_media_key IS NOT NULL THEN 10 ELSE 5 END);
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION zapp.fn_auto_enqueue_media_download() OWNER TO postgres;

--
-- Name: FUNCTION fn_auto_enqueue_media_download(); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.fn_auto_enqueue_media_download() IS 'Enfileira automaticamente os downloads de mídia pendentes detectados nas mensagens recebidas.';


