-- Name: fn_auto_offline_agents(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_auto_offline_agents() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  updated_count integer;
BEGIN
  UPDATE zapp.agent_presence 
  SET status = 'away'
  WHERE status = 'online' AND last_activity_at < now() - interval '30 minutes';
  GET DIAGNOSTICS updated_count = ROW_COUNT;
  RETURN updated_count;
END;
$$;


