--
-- Name: fn_auto_resolve_alerts(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_auto_resolve_alerts() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$
BEGIN
  -- Auto-resolver alertas de saturação de conexão se abaixou
  UPDATE zapp.evolution_alerts
  SET resolved_at = now(), resolved_by = 'auto_resolve_cron'
  WHERE alert_type = 'connection_saturation'
    AND resolved IS NOT TRUE
    AND NOT EXISTS (
      SELECT 1 FROM pg_stat_activity 
      WHERE backend_type='client backend' 
      HAVING count(*) > 0.8 * current_setting('max_connections')::int
    );

  -- Auto-resolver alertas de 401 se taxa caiu
  UPDATE zapp.evolution_alerts
  SET resolved_at = now(), resolved_by = 'auto_resolve_cron'
  WHERE alert_type = 'high_401_rate'
    AND resolved IS NOT TRUE
    AND created_at < now() - interval '1 hour'
    AND NOT EXISTS (
      SELECT 1 FROM public.evo_traefik_401_stats
      WHERE collected_at > now()-interval '1 hour'
      HAVING sum("count") > 500
    );

  -- Auto-resolver alertas de DDL churn se passou 2h sem novo
  UPDATE zapp.evolution_alerts
  SET resolved_at = now(), resolved_by = 'auto_resolve_cron'
  WHERE alert_type = 'ddl_policy_churn'
    AND resolved IS NOT TRUE
    AND created_at < now() - interval '2 hours';
END;
$$;


ALTER FUNCTION zapp.fn_auto_resolve_alerts() OWNER TO postgres;

--
-- Name: fn_auto_resolve_baileys_alerts(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_auto_resolve_baileys_alerts() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v integer;
BEGIN
  -- FIX 2026-07-05 (sessao 6): esta funcao acknowledgeava alertas 'baileys' apos 6h
  -- independente da severidade, diferente da politica da funcao irma
  -- fn_auto_resolve_alerts (que exclui severity='critical'). Um alerta critico de
  -- conexao (ex.: tipo contem 'baileys_disconnected') podia ser silenciado sem
  -- confirmacao — mesma classe de risco do S6-4 (alertas criticos fechados sem
  -- verificar o estado real). Agora tambem exclui 'critical'.
  UPDATE evolution_alerts SET acknowledged=true, acknowledged_at=now()
  WHERE acknowledged=false AND alert_type ILIKE '%baileys%' AND created_at < now()-interval '6 hours'
    AND severity NOT IN ('critical');
  GET DIAGNOSTICS v = ROW_COUNT;
  RETURN v;
END;
$$;


ALTER FUNCTION zapp.fn_auto_resolve_baileys_alerts() OWNER TO postgres;

--
-- Name: fn_auto_save_received_audio_meme(text, text, text, text, numeric); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.fn_auto_save_received_audio_meme(p_audio_url text, p_name text DEFAULT NULL::text, p_mime_type text DEFAULT 'audio/mpeg'::text, p_file_hash text DEFAULT NULL::text, p_duration_seconds numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$
DECLARE
  v_id uuid;
  v_dup jsonb;
  v_final_name text;
BEGIN
  -- Checar duplicata
  v_dup := rpc_check_audio_meme_duplicate(p_audio_url, p_file_hash);
  IF (v_dup->>'is_duplicate')::boolean THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'duplicate', 'existing_id', v_dup->>'existing_id');
  END IF;

  v_final_name := COALESCE(p_name, 'Recebido ' || to_char(now(), 'DD/MM/YYYY'));

  INSERT INTO audio_memes (name, audio_url, category, mime_type, file_hash, duration_seconds, uploaded_by, use_count, is_favorite, is_active)
  VALUES (v_final_name, p_audio_url, 'recebidos', p_mime_type, p_file_hash, p_duration_seconds, 'auto_save', 0, false, true)
  RETURNING id INTO v_id;

  RETURN jsonb_build_object('ok', true, 'id', v_id, 'name', v_final_name, 'category', 'recebidos');
END;
$$;


ALTER FUNCTION zapp.fn_auto_save_received_audio_meme(p_audio_url text, p_name text, p_mime_type text, p_file_hash text, p_duration_seconds numeric) OWNER TO supabase_admin;

