--
-- Name: fn_auto_save_received_sticker(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_auto_save_received_sticker() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$
DECLARE
  v_sticker_id uuid;
BEGIN
  IF NEW.message_type = 'sticker'
     AND NEW.media_url IS NOT NULL AND NEW.media_url != ''
     AND (NEW.from_me IS NULL OR NEW.from_me = false) THEN
    -- Dedup por URL (evita duplicar figurinhas recebidas)
    SELECT id INTO v_sticker_id FROM zapp.stickers WHERE image_url = NEW.media_url LIMIT 1;
    IF v_sticker_id IS NULL THEN
      INSERT INTO zapp.stickers (name, image_url, category, is_animated, use_count)
      VALUES ('Recebida ' || to_char(COALESCE(NEW.created_at, now()), 'DD/MM/YYYY'), NEW.media_url, 'recebidas', false, 0)
      RETURNING id INTO v_sticker_id;
    END IF;
    -- Vincula sticker_id na mensagem (UPDATE explicito funciona em AFTER INSERT)
    IF v_sticker_id IS NOT NULL THEN
      UPDATE zapp.evolution_messages_wpp2 SET sticker_id = v_sticker_id
      WHERE id = NEW.id AND sticker_id IS NULL;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION zapp.fn_auto_save_received_sticker() OWNER TO postgres;

--
-- Name: fn_auto_task_on_deal(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_auto_task_on_deal() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'public'
    AS $$
BEGIN
  IF NEW.stage = 'orcamento_enviado' AND OLD.stage != 'orcamento_enviado' THEN
    INSERT INTO zapp.evolution_tasks (title, deal_id, contact_id, task_type, due_date, priority, created_at)
    VALUES ('Follow-up do orçamento: ' || NEW.title, NEW.id, NEW.contact_id, 'follow_up', CURRENT_DATE + 2, 'alta', now());
  END IF;
  IF NEW.stage = 'pagamento_pendente' AND OLD.stage != 'pagamento_pendente' THEN
    INSERT INTO zapp.evolution_tasks (title, deal_id, contact_id, task_type, due_date, priority, created_at)
    VALUES ('Confirmar pagamento: ' || NEW.title, NEW.id, NEW.contact_id, 'task', CURRENT_DATE + 1, 'alta', now());
  END IF;
  RETURN NEW;
END; $$;


