--
-- Name: fn_auto_update_connection_status(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_auto_update_connection_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_instance TEXT;
  v_key      TEXT;
BEGIN
  IF NEW.event_type = 'connection.update' THEN
    v_instance := COALESCE(NEW.instance_name, 'wpp2');
    v_key      := 'connection_status_' || v_instance;

    INSERT INTO zapp.evolution_settings (id, key, value, description, category, is_secret, created_at, updated_at)
    VALUES (
      gen_random_uuid(),
      v_key,
      jsonb_build_object(
        'event',      NEW.event_type,
        'state',      NEW.payload->>'state',
        'instance',   v_instance,
        'updated_at', now()::text
      ),
      'Status de conexão da instância ' || v_instance || ' — atualizado automaticamente',
      'general',
      false,
      now(),
      now()
    )
    ON CONFLICT (key) DO UPDATE
      SET value      = EXCLUDED.value,
          updated_at = now();
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION zapp.fn_auto_update_connection_status() OWNER TO postgres;

