--

CREATE FUNCTION zapp.fn_baileys_logout_metrics(p_days integer DEFAULT 7) RETURNS TABLE(metric_name text, metric_value numeric, detail jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
BEGIN
  RETURN QUERY SELECT 'logouts_total'::text, COUNT(*)::numeric, jsonb_build_object('period_days',p_days)
  FROM evolution_webhook_events WHERE event_type IN ('CONNECTION_UPDATE','connection.update') AND payload->>'state'='close' AND created_at >= NOW()-(p_days||' days')::interval;
  RETURN QUERY SELECT 'logouts_by_reason'::text, NULL::numeric, jsonb_object_agg(reason,cnt)
  FROM (SELECT COALESCE(payload->>'statusReason','unknown') AS reason, COUNT(*) AS cnt FROM evolution_webhook_events WHERE event_type IN ('CONNECTION_UPDATE','connection.update') AND payload->>'state'='close' AND created_at >= NOW()-(p_days||' days')::interval GROUP BY 1) sub;
END; $$;


