CREATE FUNCTION zapp.fn_baileys_recovery_cascade() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE v_resolved integer; v_health record;
BEGIN
  SELECT * INTO v_health FROM fn_check_baileys_zombie() LIMIT 1;
  IF v_health.severity_score>1 THEN RETURN jsonb_build_object('recovery',false,'reason','not_healthy','severity',v_health.severity_score); END IF;
  SELECT fn_auto_resolve_baileys_alerts() INTO v_resolved;
  RETURN jsonb_build_object('recovery',true,'alerts_resolved',v_resolved,'health',v_health.health_status);
END; $$;


