--
-- Name: fn_batch_normalize_status(integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_batch_normalize_status(p_batch integer DEFAULT 50000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$ DECLARE v_updated integer := 0; v_started timestamptz := clock_timestamp(); BEGIN WITH targets AS (SELECT id FROM evolution_messages WHERE status IN ('PENDING','DELIVERY_ACK','SENT','RECEIVED','FAILED','ERROR','READ','PLAYED','SERVER_ACK','READ_RECEIPT') LIMIT p_batch) UPDATE evolution_messages m SET status = CASE WHEN m.status IN ('0','ERROR','FAILED') THEN 'failed' WHEN m.status IN ('1','PENDING') THEN 'pending' WHEN m.status IN ('2','SENT','SERVER_ACK') THEN 'sent' WHEN m.status IN ('3','DELIVERED','DELIVERY_ACK','RECEIVED') THEN 'delivered' WHEN m.status IN ('4','READ','READ_RECEIPT') THEN 'read' WHEN m.status IN ('5','PLAYED') THEN 'read' ELSE LOWER(m.status) END FROM targets t WHERE m.id = t.id; GET DIAGNOSTICS v_updated = ROW_COUNT; RETURN jsonb_build_object('updated', v_updated, 'duration_ms', round((extract(epoch from (clock_timestamp() - v_started))*1000)::numeric, 1)); END; $$;


ALTER FUNCTION zapp.fn_batch_normalize_status(p_batch integer) OWNER TO postgres;

--
-- Name: fn_block_internal_media_url(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_block_internal_media_url() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'zapp', 'pg_catalog'
    AS $$
DECLARE
  v_url    text;
  v_pattern text;
  -- APENAS padrões que o fn_rewrite_media_url NÃO consegue corrigir:
  -- localhost, 127.0.0.1, 0.0.0.0 = hostnames arbitrários de máquina local
  -- Não inclui 'kong:' porque fn_rewrite_media_url converte kong → public URL
  v_irrecoverable_patterns text[] := ARRAY[
    'http://localhost',
    'http://127.0.0.1',
    'http://0.0.0.0',
    '://localhost:',
    '://127.0.0.1:',
    '://0.0.0.0:'
  ];
BEGIN
  -- Determinar a URL a verificar baseado na tabela
  IF TG_TABLE_NAME LIKE 'evolution_messages%' THEN
    v_url := NEW.media_url;
  ELSIF TG_TABLE_NAME = 'evolution_media' THEN
    v_url := NEW.storage_url;
  ELSIF TG_TABLE_NAME = 'evolution_contacts' THEN
    v_url := NEW.profile_picture_url;
  END IF;

  IF v_url IS NOT NULL AND v_url <> '' THEN
    FOREACH v_pattern IN ARRAY v_irrecoverable_patterns LOOP
      IF v_url ILIKE ('%' || v_pattern || '%') THEN
        RAISE EXCEPTION '[ZAPP-SECURITY] URL localhost/loopback irrecuperável em %.%: "%" (padrão: "%")',
          TG_TABLE_SCHEMA, TG_TABLE_NAME, v_url, v_pattern
          USING ERRCODE = 'check_violation';
      END IF;
    END LOOP;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION zapp.fn_block_internal_media_url() OWNER TO postgres;

