--
-- Name: fn_cache_warmup_after_vacuum(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_cache_warmup_after_vacuum() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_start timestamptz := now();
  v_counts jsonb := '{}';
  v_n bigint;
BEGIN
  -- Warm up the five key evo tables vacuumed nightly (02:01-02:21)
  SELECT COUNT(*) INTO v_n FROM zapp.evolution_messages_wpp2;
  v_counts := v_counts || jsonb_build_object('evolution_messages_wpp2', v_n);

  SELECT COUNT(*) INTO v_n FROM zapp.evolution_alerts WHERE resolved = false;
  v_counts := v_counts || jsonb_build_object('evolution_alerts_open', v_n);

  SELECT COUNT(*) INTO v_n FROM zapp.evolution_contacts WHERE deleted_at IS NULL;
  v_counts := v_counts || jsonb_build_object('evolution_contacts_active', v_n);

  SELECT COUNT(*) INTO v_n FROM public.evo_bootstrap_log;
  v_counts := v_counts || jsonb_build_object('evolution_bootstrap_log', v_n);

  SELECT COUNT(*) INTO v_n FROM public.evo_connection_history;
  v_counts := v_counts || jsonb_build_object('evolution_connection_history', v_n);

  -- Also warm up zapp.evolution_messages (partitioned parent — forces partition map into cache)
  SELECT COUNT(*) INTO v_n FROM zapp.evolution_messages WHERE created_at > now() - interval '7 days';
  v_counts := v_counts || jsonb_build_object('evolution_messages_7d', v_n);

  RETURN jsonb_build_object(
    'warmed_at', v_start,
    'duration_ms', EXTRACT(EPOCH FROM (now() - v_start)) * 1000,
    'counts', v_counts
  );
END;
$$;


ALTER FUNCTION zapp.fn_cache_warmup_after_vacuum() OWNER TO postgres;

--
-- Name: fn_calculate_daily_kpis(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_calculate_daily_kpis() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'public', 'extensions'
    AS $$
DECLARE
  v_day_start timestamptz := date_trunc('day', now());
  v_new_contacts int; v_active_contacts int; v_total_contacts int;
  v_msgs_received int; v_msgs_sent int; v_avg_response int;
  v_convs_opened int; v_convs_resolved int; v_avg_resolution int;
  v_deals_created int; v_deals_won int; v_deals_lost int;
  v_revenue numeric; v_pipeline numeric;
  v_automations int; v_followups int;
  v_lead_to_deal numeric; v_deal_win numeric; v_avg_msgs_per_contact numeric;
BEGIN
  SELECT count(*) INTO v_new_contacts FROM evolution_contacts WHERE created_at >= v_day_start AND deleted_at IS NULL;
  SELECT count(*) INTO v_active_contacts FROM evolution_contacts WHERE deleted_at IS NULL AND last_message_at >= v_day_start;
  SELECT count(*) INTO v_total_contacts FROM evolution_contacts WHERE deleted_at IS NULL;
  SELECT count(*) INTO v_msgs_received FROM evolution_messages WHERE direction = 'inbound' AND created_at >= v_day_start AND deleted_at IS NULL;
  SELECT count(*) INTO v_msgs_sent FROM evolution_messages WHERE direction = 'outbound' AND created_at >= v_day_start AND deleted_at IS NULL;
  SELECT COALESCE(avg(first_response_seconds), 0)::int INTO v_avg_response FROM evolution_conversations WHERE first_response_at >= v_day_start AND first_response_seconds IS NOT NULL;
  SELECT count(*) INTO v_convs_opened FROM evolution_conversations WHERE created_at >= v_day_start;
  SELECT count(*) INTO v_convs_resolved FROM evolution_conversations WHERE resolution_at >= v_day_start;
  SELECT COALESCE(avg(resolution_seconds), 0)::int INTO v_avg_resolution FROM evolution_conversations WHERE resolution_at >= v_day_start AND resolution_seconds IS NOT NULL;
  SELECT count(*) INTO v_deals_created FROM evolution_deals WHERE created_at >= v_day_start AND deleted_at IS NULL;
  SELECT count(*) INTO v_deals_won FROM evolution_deals WHERE won = true AND closed_at >= v_day_start AND deleted_at IS NULL;
  SELECT count(*) INTO v_deals_lost FROM evolution_deals WHERE lost = true AND closed_at >= v_day_start AND deleted_at IS NULL;
  SELECT COALESCE(sum(value), 0) INTO v_revenue FROM evolution_deals WHERE won = true AND closed_at >= v_day_start AND deleted_at IS NULL;
  SELECT COALESCE(sum(weighted_value), 0) INTO v_pipeline FROM evolution_deals WHERE won = false AND lost = false AND deleted_at IS NULL;
  SELECT count(*) INTO v_automations FROM evolution_automation_logs WHERE executed_at >= v_day_start;
  SELECT count(*) INTO v_followups FROM evolution_followups WHERE sent_at >= v_day_start;
  v_lead_to_deal := CASE WHEN v_new_contacts > 0 THEN v_deals_created::numeric / v_new_contacts ELSE 0 END;
  v_deal_win := CASE WHEN (v_deals_won + v_deals_lost) > 0 THEN v_deals_won::numeric / (v_deals_won + v_deals_lost) ELSE 0 END;
  v_avg_msgs_per_contact := CASE WHEN v_total_contacts > 0 THEN (v_msgs_received + v_msgs_sent)::numeric / v_total_contacts ELSE 0 END;
  RETURN jsonb_build_object(
    'metric_date', current_date, 'new_contacts', v_new_contacts, 'active_contacts', v_active_contacts,
    'total_contacts', v_total_contacts, 'messages_received', v_msgs_received, 'messages_sent', v_msgs_sent,
    'avg_response_time_seconds', v_avg_response, 'conversations_opened', v_convs_opened,
    'conversations_resolved', v_convs_resolved, 'avg_resolution_time_seconds', v_avg_resolution,
    'deals_created', v_deals_created, 'deals_won', v_deals_won, 'deals_lost', v_deals_lost,
    'revenue', v_revenue, 'pipeline_value', v_pipeline, 'lead_to_deal_rate', v_lead_to_deal,
    'deal_win_rate', v_deal_win, 'avg_messages_per_contact', v_avg_msgs_per_contact,
    'automations_triggered', v_automations, 'followups_sent', v_followups
  );
END; $$;


ALTER FUNCTION zapp.fn_calculate_daily_kpis() OWNER TO postgres;

--
-- Name: fn_calculate_daily_metrics(date); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_calculate_daily_metrics(p_date date DEFAULT (CURRENT_DATE - 1)) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$ BEGIN INSERT INTO evolution_daily_metrics (metric_date, new_contacts, active_contacts, total_contacts, messages_received, messages_sent, conversations_opened, conversations_resolved, deals_created, deals_won, deals_lost, revenue, pipeline_value) SELECT p_date, (SELECT COUNT(*) FROM evolution_contacts WHERE DATE(created_at) = p_date), (SELECT COUNT(*) FROM evolution_contacts WHERE DATE(last_message_at) = p_date), (SELECT COUNT(*) FROM evolution_contacts WHERE DATE(created_at) <= p_date), (SELECT COUNT(*) FROM evolution_webhook_events WHERE event_type = 'MESSAGES_UPSERT' AND DATE(created_at) = p_date), (SELECT COUNT(*) FROM evolution_webhook_events WHERE event_type = 'SEND_MESSAGE' AND DATE(created_at) = p_date), (SELECT COUNT(*) FROM evolution_conversations WHERE DATE(created_at) = p_date), (SELECT COUNT(*) FROM evolution_conversations WHERE DATE(resolution_at) = p_date), (SELECT COUNT(*) FROM evolution_deals WHERE DATE(created_at) = p_date), (SELECT COUNT(*) FROM evolution_deals WHERE stage = 'pago' AND DATE(actual_close_date) = p_date), (SELECT COUNT(*) FROM evolution_deals WHERE stage = 'perdido' AND DATE(actual_close_date) = p_date), (SELECT COALESCE(SUM(value), 0) FROM evolution_deals WHERE stage = 'pago' AND DATE(actual_close_date) = p_date), (SELECT COALESCE(SUM(value), 0) FROM evolution_deals WHERE stage NOT IN ('perdido','pedido_finalizado')) ON CONFLICT (metric_date) DO UPDATE SET new_contacts = EXCLUDED.new_contacts, messages_received = EXCLUDED.messages_received, messages_sent = EXCLUDED.messages_sent, calculated_at = NOW(); END; $$;


ALTER FUNCTION zapp.fn_calculate_daily_metrics(p_date date) OWNER TO postgres;

--
-- Name: fn_calculate_first_response(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_calculate_first_response() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$
BEGIN
  IF OLD.first_response_at IS NULL AND NEW.last_outbound_at IS NOT NULL AND NEW.first_message_at IS NOT NULL THEN
    NEW.first_response_at = NEW.last_outbound_at;
    NEW.first_response_seconds = EXTRACT(EPOCH FROM (NEW.last_outbound_at - NEW.first_message_at))::integer;
  END IF;
  RETURN NEW;
END; $$;


ALTER FUNCTION zapp.fn_calculate_first_response() OWNER TO postgres;

--
-- Name: fn_calculate_next_send(text, timestamp with time zone); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_calculate_next_send(p_schedule text, p_from timestamp with time zone DEFAULT now()) RETURNS timestamp with time zone
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
  v_sched text := lower(btrim(COALESCE(p_schedule, 'daily')));
  v_base  timestamptz := COALESCE(p_from, now());
  v_next  timestamptz;
BEGIN
  IF v_sched = 'weekly' THEN
    v_next := date_trunc('week', v_base) + interval '8 days 8 hours';
  ELSIF v_sched = 'monthly' THEN
    v_next := date_trunc('month', v_base) + interval '1 month 8 hours';
  ELSE
    v_next := date_trunc('day', v_base) + interval '1 day 8 hours';
  END IF;

  IF v_next <= v_base THEN
    v_next := v_next + interval '1 day';
  END IF;

  RETURN v_next;
END
$$;


ALTER FUNCTION zapp.fn_calculate_next_send(p_schedule text, p_from timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION fn_calculate_next_send(p_schedule text, p_from timestamp with time zone); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.fn_calculate_next_send(p_schedule text, p_from timestamp with time zone) IS 'Calcula next_send_at: daily=amanhã 08:00, weekly=próxima segunda 08:00, monthly=dia 1 08:00, cron=fallback daily.';


--
-- Name: fn_calculate_resolution_time(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_calculate_resolution_time() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$
BEGIN
  IF OLD.status NOT IN ('resolvida','resolved','closed') AND NEW.status IN ('resolvida','resolved','closed') THEN
    NEW.resolution_at = NOW();
    IF NEW.first_message_at IS NOT NULL THEN
      NEW.resolution_seconds = EXTRACT(EPOCH FROM (NOW() - NEW.first_message_at))::integer;
    END IF;
  END IF;
  RETURN NEW;
END; $$;


ALTER FUNCTION zapp.fn_calculate_resolution_time() OWNER TO postgres;

--
-- Name: fn_call_stats(integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_call_stats(p_days integer DEFAULT 7) RETURNS TABLE(total_calls bigint, missed_calls bigint, answered_calls bigint, callback_pending bigint, avg_duration_seconds numeric, busiest_hour integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$ BEGIN RETURN QUERY SELECT COUNT(*), COUNT(*) FILTER (WHERE call_status = 'missed'), COUNT(*) FILTER (WHERE call_status IN ('accepted','ended')), COUNT(*) FILTER (WHERE call_status = 'missed' AND missed_callback_sent = false), AVG(duration_seconds) FILTER (WHERE duration_seconds IS NOT NULL), (SELECT EXTRACT(HOUR FROM created_at)::INTEGER FROM evolution_calls WHERE created_at > NOW() - (p_days || ' days')::INTERVAL GROUP BY EXTRACT(HOUR FROM created_at) ORDER BY COUNT(*) DESC LIMIT 1) FROM evolution_calls WHERE created_at > NOW() - (p_days || ' days')::INTERVAL; END; $$;


