--
-- Name: fn_capture_csat_replies(integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_capture_csat_replies(p_limit integer DEFAULT 50) RETURNS TABLE(captured integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'public'
    AS $_$
DECLARE
  v_limit   integer := GREATEST(1, LEAST(COALESCE(p_limit, 50), 200));
  v_captured integer := 0;
  v_msg     record;
  v_survey  record;
  v_rating  integer;
  v_rt_secs integer;
BEGIN
  FOR v_msg IN
    SELECT m.message_id, m.remote_jid, m.content, m.created_at,
           m.contact_id, m.conversation_id, m.instance_name
      FROM zapp.evolution_messages m
     WHERE m.from_me = false
       AND m.content ~ '^[[:space:]]*[1-5][[:space:]]*$'
       AND m.created_at >= now() - interval '72 hours'
       AND NOT EXISTS (
         SELECT 1 FROM zapp.csat_responses r
          WHERE r.message_id = m.message_id
       )
     ORDER BY m.created_at DESC
     LIMIT v_limit
  LOOP
    SELECT s.id, s.agent_id, s.conversation_id, s.send_at
      INTO v_survey
      FROM zapp.csat_surveys s
     WHERE s.contact_id = v_msg.contact_id
       AND s.status = 'sent'
       AND s.rating IS NULL
       AND s.responded_at IS NULL
       AND v_msg.created_at BETWEEN s.send_at AND s.send_at + interval '72 hours'
       AND (s.conversation_id IS NULL OR v_msg.conversation_id IS NULL
            OR s.conversation_id = v_msg.conversation_id)
     ORDER BY s.send_at DESC
     LIMIT 1;

    IF NOT FOUND THEN
      CONTINUE;
    END IF;

    v_rating  := btrim(v_msg.content)::integer;
    v_rt_secs := GREATEST(0, EXTRACT(EPOCH FROM (v_msg.created_at - v_survey.send_at))::integer);

    UPDATE zapp.csat_surveys s
       SET rating              = v_rating,
           responded_at        = v_msg.created_at,
           updated_at          = now()
     WHERE s.id = v_survey.id
       AND s.responded_at IS NULL
       AND s.rating IS NULL;

    IF FOUND THEN
      INSERT INTO zapp.csat_responses
        (contact_id, conversation_id, agent_id, instance_name,
         rating, comment, response_time_seconds, message_id, created_at)
      VALUES
        (v_msg.contact_id, v_survey.conversation_id, v_survey.agent_id,
         v_msg.instance_name, v_rating, NULL, v_rt_secs, v_msg.message_id,
         v_msg.created_at)
      ON CONFLICT DO NOTHING;

      v_captured := v_captured + 1;
    END IF;
  END LOOP;

  RETURN QUERY SELECT v_captured;
END;
$_$;


ALTER FUNCTION zapp.fn_capture_csat_replies(p_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_capture_csat_replies(p_limit integer); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.fn_capture_csat_replies(p_limit integer) IS 'Captura respostas CSAT "1"-"5" de zapp.evolution_messages e preenche csat_surveys.rating/responded_at + csat_responses (cron 2min, SIM-CSAT E3).';


--
-- Name: fn_categorize_sticker(uuid, text, text, text[]); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.fn_categorize_sticker(p_sticker_id uuid, p_new_category text, p_new_name text DEFAULT NULL::text, p_tags text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$
DECLARE
  v_old_cat text;
  v_exists boolean;
BEGIN
  -- Verificar se categoria existe
  SELECT EXISTS(SELECT 1 FROM sticker_categories WHERE slug = p_new_category AND is_active) INTO v_exists;
  IF NOT v_exists THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Categoria ' || p_new_category || ' nao encontrada');
  END IF;
  
  SELECT category INTO v_old_cat FROM stickers WHERE id = p_sticker_id;
  IF v_old_cat IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Sticker nao encontrado');
  END IF;
  
  UPDATE stickers SET
    category = p_new_category,
    name = COALESCE(p_new_name, name),
    tags = COALESCE(p_tags, tags)
  WHERE id = p_sticker_id;
  
  -- trigger trg_sticker_category_count ja atualiza automaticamente
  
  RETURN jsonb_build_object(
    'ok', true,
    'sticker_id', p_sticker_id,
    'old_category', v_old_cat,
    'new_category', p_new_category,
    'name', COALESCE(p_new_name, (SELECT name FROM stickers WHERE id = p_sticker_id))
  );
END;
$$;


ALTER FUNCTION zapp.fn_categorize_sticker(p_sticker_id uuid, p_new_category text, p_new_name text, p_tags text[]) OWNER TO supabase_admin;

--
-- Name: FUNCTION fn_categorize_sticker(p_sticker_id uuid, p_new_category text, p_new_name text, p_tags text[]); Type: COMMENT; Schema: zapp; Owner: supabase_admin
--

COMMENT ON FUNCTION zapp.fn_categorize_sticker(p_sticker_id uuid, p_new_category text, p_new_name text, p_tags text[]) IS 'Move figurinha entre categorias. Opcionalmente renomeia e adiciona tags.';


--
-- Name: fn_checar_inbound_zerado(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_checar_inbound_zerado() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog'
    AS $$
DECLARE
  v_upserts  bigint;
  v_janela   interval := '1 hour';
  v_cooldown interval := '6 hours';
  v_ja_alertou boolean := false;
  v_hora_local int;
  v_silencio   boolean := false;
BEGIN
  SELECT count(*) INTO v_upserts
  FROM zapp.webhook_events_processed
  WHERE event_type = 'messages.upsert'
    AND processed_at > now() - v_janela;

  -- Janela de silêncio comercial (19:00-07:59 BRT):
  -- Tráfego cai para < 30 msgs/h após 18h BRT (padrão histórico confirmado).
  -- Antes era 23:00-06:59; ampliado em 2026-08-13 após auditoria de falsos positivos.
  SELECT extract(hour FROM now() AT TIME ZONE 'America/Sao_Paulo')::int INTO v_hora_local;
  IF v_hora_local >= 19 OR v_hora_local < 8 THEN
    v_silencio := true;
  END IF;

  IF v_upserts = 0 AND NOT v_silencio THEN
    SELECT EXISTS (
      SELECT 1 FROM zapp.evolution_alerts
      WHERE alert_type = 'ingestion_zero_inbound'
        AND created_at > now() - v_cooldown
    ) INTO v_ja_alertou;

    IF NOT v_ja_alertou THEN
      INSERT INTO zapp.evolution_alerts (alert_type, severity, title, message, payload)
      VALUES (
        'ingestion_zero_inbound',
        'high',
        'Inbound zerado ha mais de 1h — pipeline pode estar parado',
        format(
          'Nenhum evento messages.upsert registrado em zapp.webhook_events_processed na ultima hora (janela %s). '
          'Horario comercial: verificar pipeline inbound: consumer, edge evolution-webhook, view public.evolution_messages.',
          v_janela::text
        ),
        jsonb_build_object(
          'upserts_ultima_hora', v_upserts,
          'janela', v_janela::text,
          'fonte', 'zapp.webhook_events_processed',
          'cooldown', v_cooldown::text,
          'silencio_comercial', v_silencio,
          'hora_brt', v_hora_local,
          'janela_silencio', '19:00-07:59 BRT',
          'detectado_em', now()
        )
      );
    END IF;
  ELSIF v_upserts > 0 THEN
    -- Tráfego voltou: auto-resolve alertas abertos deste tipo
    UPDATE zapp.evolution_alerts
    SET resolved_at = now(), resolved_by = 'fn_checar_inbound_zerado'
    WHERE alert_type = 'ingestion_zero_inbound'
      AND resolved_at IS NULL;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'upserts_ultima_hora', v_upserts,
    'silencio_comercial', v_silencio,
    'hora_brt', v_hora_local,
    'alerta_emitido', (v_upserts = 0 AND NOT v_ja_alertou AND NOT v_silencio)
  );
END
$$;


ALTER FUNCTION zapp.fn_checar_inbound_zerado() OWNER TO postgres;

--
-- Name: fn_check_401_rate(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_check_401_rate() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog'
    AS $$
DECLARE
  v_rate_1h  BIGINT;
  v_threshold CONSTANT INT := 500;
BEGIN
  SELECT COALESCE(SUM("count"),0) INTO v_rate_1h
  FROM public.evo_traefik_401_stats
  WHERE collected_at > now() - interval '1 hour';

  IF v_rate_1h > v_threshold THEN
    INSERT INTO zapp.evolution_alerts
      (alert_type, severity, title, message, payload)
    VALUES
      ('high_401_rate', 'high', '401 rate elevada na Evolution API',
       format('Detectados %s hits 401 na ultima hora', v_rate_1h),
       jsonb_build_object('hits_1h', v_rate_1h, 'threshold', v_threshold))
    ON CONFLICT DO NOTHING;
  ELSE
    UPDATE zapp.evolution_alerts
    SET resolved_at = now(), resolved_by = 'fn_check_401_rate: rate normalizada'
    WHERE alert_type = 'high_401_rate'
      AND resolved_at IS NULL
      AND created_at < now() - interval '1 hour';
  END IF;
END;
$$;


ALTER FUNCTION zapp.fn_check_401_rate() OWNER TO postgres;

--
-- Name: fn_check_ack_stall(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_check_ack_stall() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog'
    AS $$
DECLARE
  v_recent_total BIGINT;
  v_recent_stuck BIGINT;
  v_stall_mins   INT;
BEGIN
  SELECT count(*), count(*) FILTER (WHERE status='sent')
  INTO v_recent_total, v_recent_stuck
  FROM zapp.evolution_messages_wpp2
  WHERE from_me AND created_at > now()-interval '2 hours';

  v_stall_mins := EXTRACT(EPOCH FROM (
    now() - COALESCE(
      (SELECT MAX(updated_at) FROM zapp.evolution_messages_wpp2
       WHERE from_me AND status='sent' AND created_at > now()-interval '2 hours'),
      now()
    )
  ))/60;

  -- [100PLAN S20] threshold revertido 120→30 min após T21 confirmado em prod
  -- (banner T1-T28,T21 ativo, container 9c07f9fcbd2f healthy)
  IF v_recent_total >= 10
     AND v_recent_stuck::numeric / NULLIF(v_recent_total,0) > 0.5
     AND v_stall_mins > 30 THEN
    INSERT INTO zapp.evolution_alerts (alert_type, severity, title, message, payload)
    VALUES ('ack_stall','high','ACK stall detectado',
            format('%s/%s sends recentes (2h) travados em sent ha %s min',
                   v_recent_stuck, v_recent_total, ROUND(v_stall_mins)),
            jsonb_build_object('recent_total',v_recent_total,'recent_stuck',v_recent_stuck,'stall_min',v_stall_mins))
    ON CONFLICT DO NOTHING;
  ELSE
    UPDATE zapp.evolution_alerts
    SET resolved_at=now(), resolved_by='fn_check_ack_stall: sem stall recente'
    WHERE alert_type='ack_stall' AND resolved_at IS NULL
      AND created_at < now()-interval '30 minutes';
  END IF;
END;
$$;


ALTER FUNCTION zapp.fn_check_ack_stall() OWNER TO postgres;

