--
-- Name: fn_check_evolution_jid_health(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_check_evolution_jid_health() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$
DECLARE
  v_window_min int:=15; v_volume_min int:=50; v_alert_key text:='evo_jid_completeness';
  v_total int; v_sem_jid int; v_pct numeric; v_severity text;
  v_was_alerting boolean:=false; v_last_severity text;
  v_title text; v_message text; v_kpi_data jsonb; v_dispatch jsonb; v_status text;
  v_now timestamptz:=now();
BEGIN
  SELECT count(*), count(*) FILTER(WHERE remote_jid IS NULL OR remote_jid='')
    INTO v_total, v_sem_jid
    FROM zapp.evolution_messages
    WHERE created_at >= v_now - make_interval(mins=>v_window_min)
      AND message_id NOT LIKE 'smoke-%' AND message_id NOT LIKE 'TEST-%'
      AND message_id NOT LIKE 'hotfix-test-%' AND message_id NOT LIKE 'e2e-%';
  v_pct := CASE WHEN v_total=0 THEN 0 ELSE round(100.0*v_sem_jid/v_total,2) END;
  v_severity := CASE WHEN v_total<v_volume_min THEN 'info' WHEN v_pct>=20 THEN 'critical' WHEN v_pct>=5 THEN 'error' WHEN v_pct>=1 THEN 'warning' ELSE 'info' END;
  v_last_severity := evo.rpc_boundary_cooldown_get(v_alert_key);
  v_was_alerting := v_last_severity IS NOT NULL AND zapp.fn_severity_rank(v_last_severity)>=1;
  v_kpi_data := jsonb_build_object('window_min',v_window_min,'total_msgs',v_total,'msgs_sem_jid',v_sem_jid,'pct_sem_jid',v_pct,'volume_min',v_volume_min,'volume_ok',v_total>=v_volume_min,'checked_at',v_now,'previous_severity',v_last_severity,'source_table','zapp.evolution_messages');
  v_status := CASE WHEN v_total<v_volume_min THEN 'low_volume_skip' WHEN v_severity='info' AND v_was_alerting THEN 'recovered' WHEN v_severity='info' THEN 'healthy' ELSE 'alerting' END;
  IF v_status='low_volume_skip' THEN RETURN jsonb_build_object('action','skip','reason','low_volume','kpi',v_kpi_data); END IF;
  IF v_status='healthy' THEN RETURN jsonb_build_object('action','noop','reason','healthy','kpi',v_kpi_data); END IF;
  IF v_status='recovered' THEN
    v_title:='OK Pipeline JID recuperado';
    v_message:=format(E'JID completeness voltou ao normal.\n- Total msgs: %s\n- Sem JID: %s\n- Pct: %s%%',v_total,v_sem_jid,v_pct);
    PERFORM evo.rpc_boundary_cooldown_clear(v_alert_key);
    v_dispatch:=zapp.fn_send_bitrix_alert(p_alert_key:=v_alert_key||'_recovery',p_severity:='info',p_title:=v_title,p_message:=v_message,p_payload:=v_kpi_data,p_force_send:=true);
    RETURN jsonb_build_object('action','recovery_sent','kpi',v_kpi_data,'dispatch',v_dispatch);
  END IF;
  v_title:=format('Pipeline JID: %s',upper(v_severity));
  v_message:=format(E'Degradacao no JID.\n- Janela: %s min\n- Total msgs: %s\n- Sem JID: %s\n- Pct: %s%%',v_window_min,v_total,v_sem_jid,v_pct);
  v_dispatch:=zapp.fn_send_bitrix_alert(p_alert_key:=v_alert_key,p_severity:=v_severity,p_title:=v_title,p_message:=v_message,p_payload:=v_kpi_data);
  RETURN jsonb_build_object('action','alerted','kpi',v_kpi_data,'dispatch',v_dispatch);
END $$;


ALTER FUNCTION zapp.fn_check_evolution_jid_health() OWNER TO postgres;

--
-- Name: fn_check_evolution_pipeline_health(); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.fn_check_evolution_pipeline_health() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_msgs_5min int; v_msgs_1h int; v_audit_5min int; v_audit_rejected int;
  v_last_msg timestamptz; v_last_audit_ok timestamptz;
  v_status text := 'healthy'; v_alerts jsonb := '[]'::jsonb;
  v_result jsonb; v_recent_alert bigint;
  v_conn_open boolean := false;
BEGIN
  SELECT lower(coalesce(status,'')) = 'open' INTO v_conn_open
    FROM zapp.whatsapp_connections WHERE instance_name = 'wpp2';
  SELECT count(*), max(created_at) INTO v_msgs_5min, v_last_msg
    FROM zapp.evolution_messages WHERE created_at > NOW()-INTERVAL '5 minutes';
  SELECT count(*) INTO v_msgs_1h
    FROM zapp.evolution_messages WHERE created_at > NOW()-INTERVAL '1 hour';
  -- FIX 2026-07-04: zapp.webhook_audit_log
  SELECT count(*) FILTER(WHERE status='processed'), count(*) FILTER(WHERE status='rejected'),
         max(created_at) FILTER(WHERE status='processed')
    INTO v_audit_5min, v_audit_rejected, v_last_audit_ok
    FROM zapp.webhook_audit_log WHERE created_at > NOW()-INTERVAL '5 minutes';
  IF NOT coalesce(v_conn_open, false) THEN
    UPDATE zapp.evolution_alerts
      SET resolved_at = NOW(), resolved_by = 'fn_check_pipeline_health:wpp2_disconnected_expected'
      WHERE alert_type = 'pipeline_health' AND resolved_at IS NULL;
    RETURN jsonb_build_object('status', 'skip_disconnected', 'reason', 'wpp2 esta desconectada: silencio esperado', 'msgs_5min', v_msgs_5min, 'checked_at', NOW());
  END IF;
  IF v_msgs_5min=0 AND v_msgs_1h>10 THEN v_status:='degraded'; v_alerts:=v_alerts||'[{"level":"warn","msg":"No messages in last 5min"}]'::jsonb; END IF;
  IF v_msgs_1h=0 THEN v_status:='critical'; v_alerts:=v_alerts||'[{"level":"crit","msg":"No messages in last 1 hour"}]'::jsonb; END IF;
  IF v_audit_rejected>100 THEN v_alerts:=v_alerts||jsonb_build_array(jsonb_build_object('level','warn','msg','High rejection rate: '||v_audit_rejected)); END IF;
  v_result:=jsonb_build_object('status',v_status,'checked_at',NOW(),'msgs_5min',v_msgs_5min,'msgs_1h',v_msgs_1h,'last_message_at',v_last_msg,'audit_processed_5min',v_audit_5min,'audit_rejected_5min',v_audit_rejected,'last_audit_ok',v_last_audit_ok,'alerts',v_alerts);
  IF v_status!='healthy' AND jsonb_array_length(v_alerts)>0 THEN
    SELECT COUNT(*) INTO v_recent_alert FROM zapp.evolution_alerts WHERE alert_type='pipeline_health' AND resolved_at IS NULL AND created_at>NOW()-INTERVAL '30 minutes';
    IF v_recent_alert=0 THEN
      UPDATE zapp.evolution_alerts SET resolved_at=NOW(), resolved_by='superseded: novo alerta pipeline_health criado' WHERE alert_type='pipeline_health' AND resolved_at IS NULL;
      INSERT INTO zapp.evolution_alerts(alert_type,severity,title,message,payload) VALUES('pipeline_health',CASE WHEN v_status='critical' THEN 'high' ELSE 'medium' END,'Evolution pipeline '||v_status, v_alerts->>0, v_result);
    END IF;
  ELSE
    UPDATE zapp.evolution_alerts SET resolved_at=NOW(), resolved_by='fn_check_pipeline_health:recovered' WHERE alert_type='pipeline_health' AND resolved_at IS NULL;
  END IF;
  RETURN v_result;
END;
$$;


