--
-- Name: fn_circuit_allow(text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_circuit_allow(p_service text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v RECORD;
BEGIN
  SELECT * INTO v FROM zapp.api_circuit_breaker WHERE service = p_service;
  IF NOT FOUND THEN RETURN TRUE; END IF;  -- serviço desconhecido: libera

  IF v.state = 'closed' THEN
    RETURN TRUE;

  ELSIF v.state = 'open' THEN
    -- cooldown expirou? transiciona para half_open e libera o teste
    IF clock_timestamp() >= v.next_attempt_at THEN
      UPDATE zapp.api_circuit_breaker
        SET state = 'half_open', success_count_half_open = 0, updated_at = now()
      WHERE service = p_service;
      RETURN TRUE;
    END IF;
    RETURN FALSE;  -- ainda no cooldown: bloquear

  ELSIF v.state = 'half_open' THEN
    RETURN TRUE;  -- permite o call de teste

  END IF;
  RETURN TRUE;  -- fallback seguro
END;
$$;


ALTER FUNCTION zapp.fn_circuit_allow(p_service text) OWNER TO postgres;

--
-- Name: FUNCTION fn_circuit_allow(p_service text); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.fn_circuit_allow(p_service text) IS 'Retorna TRUE se a call ao serviço deve prosseguir. Chamar ANTES de qualquer request à API externa. Se retornar FALSE: não fazer a call, retornar erro imediato ao caller.';


--
-- Name: fn_circuit_record(text, boolean); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_circuit_record(p_service text, p_success boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v RECORD;
BEGIN
  SELECT * INTO v FROM zapp.api_circuit_breaker WHERE service = p_service;
  IF NOT FOUND THEN RETURN; END IF;

  IF p_success THEN
    IF v.state = 'closed' THEN
      -- sucesso normal: zerar falhas acumuladas
      UPDATE zapp.api_circuit_breaker
        SET failure_count = 0, last_success_at = now(), updated_at = now()
      WHERE service = p_service;

    ELSIF v.state = 'half_open' THEN
      -- sucesso no teste: incrementar contador de recuperação
      IF (v.success_count_half_open + 1) >= v.required_successes_to_close THEN
        -- atingiu threshold: fechar circuito (recuperado)
        UPDATE zapp.api_circuit_breaker
          SET state = 'closed', failure_count = 0,
              success_count_half_open = 0, last_success_at = now(),
              opened_at = NULL, next_attempt_at = NULL, updated_at = now()
        WHERE service = p_service;
      ELSE
        UPDATE zapp.api_circuit_breaker
          SET success_count_half_open = success_count_half_open + 1,
              last_success_at = now(), updated_at = now()
        WHERE service = p_service;
      END IF;
    END IF;

  ELSE
    -- falha
    IF v.state = 'closed' THEN
      IF (v.failure_count + 1) >= v.threshold_failures THEN
        -- atingiu threshold: ABRIR circuito
        UPDATE zapp.api_circuit_breaker
          SET state = 'open', failure_count = v.failure_count + 1,
              last_failure_at = now(), opened_at = now(),
              next_attempt_at = now() + (v.cooldown_seconds || ' seconds')::interval,
              updated_at = now()
        WHERE service = p_service;
      ELSE
        UPDATE zapp.api_circuit_breaker
          SET failure_count = failure_count + 1,
              last_failure_at = now(), updated_at = now()
        WHERE service = p_service;
      END IF;

    ELSIF v.state = 'half_open' THEN
      -- falhou no teste: voltar para open com cooldown reset
      UPDATE zapp.api_circuit_breaker
        SET state = 'open', failure_count = failure_count + 1,
            success_count_half_open = 0, last_failure_at = now(),
            opened_at = now(),
            next_attempt_at = now() + (v.cooldown_seconds || ' seconds')::interval,
            updated_at = now()
      WHERE service = p_service;
    END IF;
  END IF;
END;
$$;


ALTER FUNCTION zapp.fn_circuit_record(p_service text, p_success boolean) OWNER TO postgres;

--
-- Name: FUNCTION fn_circuit_record(p_service text, p_success boolean); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.fn_circuit_record(p_service text, p_success boolean) IS 'Registrar resultado de uma call. Chamar DEPOIS de qualquer request à API externa. TRUE = sucesso, FALSE = falha. Transiciona estado da máquina de estados.';


