-- Name: fn_circuit_reset(text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_circuit_reset(p_service text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
