--
-- Name: fn_circuit_status(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_circuit_status() RETURNS TABLE(service text, state text, failure_count integer, success_count_half_open integer, opened_at timestamp with time zone, next_attempt_at timestamp with time zone, last_failure_at timestamp with time zone, last_success_at timestamp with time zone, mins_until_retry numeric)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
  SELECT
    service, state, failure_count, success_count_half_open,
    opened_at, next_attempt_at, last_failure_at, last_success_at,
    CASE WHEN state = 'open' AND next_attempt_at > now()
         THEN round(extract(epoch from next_attempt_at - now()) / 60, 1)
         ELSE 0 END AS mins_until_retry
  FROM zapp.api_circuit_breaker
  ORDER BY service;
$$;


