COMMENT ON FUNCTION zapp.fn_connection_drift_summary() IS 'KPI agregado seguro (sem dados PII) de saúde das conexões WhatsApp. Para uso em dashboards públicos, gates anti-regressão e webhooks.';


--
-- Name: fn_constraints_reference_pipeline(); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.fn_constraints_reference_pipeline() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  v_snapshot jsonb;
  v_is_drift boolean;
  v_alert_id uuid;
BEGIN
  v_snapshot := fn_snapshot_constraints_reference(NULL, 'monthly_cron');
  v_is_drift := (v_snapshot->'drift'->>'is_drift')::boolean;
  
  IF v_is_drift THEN
    INSERT INTO zapp.webhook_health_alerts (alert_type, severity, title, details)
    VALUES ('constraints_reference_drift','WARNING',
      format('🔔 Schema Evolution DB mudou — regenerar EVOLUTION_DB_CONSTRAINTS_REFERENCE.md'),
      jsonb_build_object(
        'acao_recomendada', 'Executar fn_generate_constraints_reference() e subir na project-knowledge',
        'snapshot_id', v_snapshot->>'new_version_id',
        'drift', v_snapshot->'drift',
        'tamanho_kb', ROUND((v_snapshot->>'content_size_bytes')::int / 1024.0, 2),
        'total_linhas', (v_snapshot->>'total_lines')::int,
        'hash_novo', v_snapshot->>'hash'
      )
    ) RETURNING id INTO v_alert_id;
    v_snapshot := v_snapshot || jsonb_build_object('alert_created', v_alert_id);
  END IF;
  
  INSERT INTO zapp.evolution_audit_log (action, entity_type, performed_by, performed_by_type, metadata)
  VALUES ('gc','system_docs','constraints_reference_pipeline','system', v_snapshot);
  
  RETURN v_snapshot;
END;
$$;


ALTER FUNCTION zapp.fn_constraints_reference_pipeline() OWNER TO supabase_admin;

--
-- Name: fn_contact_audit_trigger(); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.fn_contact_audit_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  v_action        text;
  v_old_values    jsonb := NULL;
  v_new_values    jsonb := NULL;
  v_changed_by    uuid;
  v_sensitive_fields text[] := ARRAY['phone', 'email', 'cpf', 'cnpj', 'name', 'notes',
                                      'address', 'company', 'custom_fields', 'tags',
                                      'lgpd_consent_at', 'lgpd_opt_out_at', 'is_blocked'];
BEGIN
  v_action := TG_OP;
  v_changed_by := auth.uid();
  IF TG_OP = 'UPDATE' THEN
    v_old_values := jsonb_object_agg(key, value)
      FROM jsonb_each(to_jsonb(OLD))
      WHERE key = ANY(v_sensitive_fields)
        AND to_jsonb(OLD)->>key IS DISTINCT FROM to_jsonb(NEW)->>key;
    v_new_values := jsonb_object_agg(key, value)
      FROM jsonb_each(to_jsonb(NEW))
      WHERE key = ANY(v_sensitive_fields)
        AND to_jsonb(OLD)->>key IS DISTINCT FROM to_jsonb(NEW)->>key;
    IF v_old_values IS NULL AND v_new_values IS NULL THEN
      RETURN NEW;
    END IF;
  ELSIF TG_OP = 'INSERT' THEN
    v_new_values := to_jsonb(NEW) - 'updated_at' - 'created_at';
  ELSIF TG_OP = 'DELETE' THEN
    v_old_values := to_jsonb(OLD);
  END IF;
  -- FIX 2026-07-04: zapp.contact_audit_log (era public)
  INSERT INTO zapp.contact_audit_log (
    contact_id, action, changed_by, changed_at, old_values, new_values
  ) VALUES (
    COALESCE(NEW.id, OLD.id), v_action, v_changed_by, now(), v_old_values, v_new_values
  );
  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION zapp.fn_contact_audit_trigger() OWNER TO supabase_admin;

