--
-- Name: fn_contacts_view_delete_handler(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_contacts_view_delete_handler() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
BEGIN
  -- Soft delete: marca deleted_at em vez de remover fisicamente
  -- Requisito LGPD: 30 dias de undo antes da exclusao permanente
  -- PITFALL: em trigger INSTEAD OF DELETE, NEW e NULL — nunca acessar NEW.*
  UPDATE zapp.evolution_contacts
  SET deleted_at = NOW(),
      deleted_reason = CASE
        WHEN array_length(TG_ARGV, 1) > 0 THEN TG_ARGV[0]
        ELSE 'user_request'
      END
  WHERE id = OLD.id;
  RETURN OLD;
END;
$$;


