--
-- Name: fn_contacts_view_insert(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_contacts_view_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE v_new_id uuid;
BEGIN
  INSERT INTO zapp.evolution_contacts (    -- schema explícito: BASE TABLE
    id, full_name, phone_number, email, profile_picture_url,
    lead_status, assigned_to, company, role_title, notes,
    lead_source, instance_name, remote_jid, push_name, tags, created_at
  ) VALUES (
    COALESCE(NEW.id, gen_random_uuid()),
    NEW.name, NEW.phone, NEW.email, NEW.avatar_url,
    COALESCE(NEW.status, 'open'), NEW.assigned_to, NEW.company, NEW.position, NEW.notes,
    NEW.source,
    COALESCE(NEW.instance_name, 'wpp2'),  -- R13: default corrigido p/ instância ativa (pink_test removida 2026-07-09)
    COALESCE(NEW.external_id, NEW.remote_jid, NEW.phone || '@s.whatsapp.net'),
    NEW.push_name, NEW.tags,
    COALESCE(NEW.created_at, now())
  ) RETURNING id INTO v_new_id;
  NEW.id := v_new_id;
  RETURN NEW;
END;
$$;


