--
-- Name: FUNCTION fn_contacts_view_insert(); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.fn_contacts_view_insert() IS 'v2 2026-07-02: honra remote_jid/push_name/tags explicitos; fallback external_id->remote_jid->phone@s.whatsapp.net.';


--
-- Name: fn_contacts_view_insert_handler(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_contacts_view_insert_handler() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_id uuid;
  v_instance text;
BEGIN
  -- [2026-07-05 contacts-view-io] zapp.contacts virou view (~21/06) sem INSTEAD OF:
  -- todo INSERT do webhook handler falhava (0A000) => contato/mensagem nao espelhados.
  -- [2026-08-12 FIX lead_status] vocabulario de evolution_contacts.lead_status e PT-BR
  -- (chk_lead_status_vocab: novo/qualificado/negociando/ganho/perdido/inativo); o default
  -- legado 'open' violava o CHECK e derrubava TODO insert de contato novo do webhook
  -- (mensagens inbound de contatos novos descartadas silenciosamente).
  v_instance := NULLIF(NEW.instance_name,'');
  IF v_instance IS NULL AND NEW.whatsapp_connection_id IS NOT NULL THEN
    SELECT wc.instance_name INTO v_instance
    FROM zapp.whatsapp_connections wc WHERE wc.id = NEW.whatsapp_connection_id;
  END IF;

  INSERT INTO zapp.evolution_contacts (
    id, remote_jid, phone_number, push_name, profile_picture_url, full_name,
    email, company, role_title, lead_status, lead_source, lead_score,
    whatsapp_labels, tags, assigned_to, queue_id, notes, instance_name,
    raw_data, total_purchases, last_message_at, created_at, updated_at
  ) VALUES (
    COALESCE(NEW.id, gen_random_uuid()),
    COALESCE(NULLIF(NEW.remote_jid,''), NULLIF(NEW.external_id,''), NEW.phone || '@s.whatsapp.net'),
    NEW.phone,
    COALESCE(NEW.push_name, NEW.nickname),
    NEW.avatar_url,
    NEW.name,
    NEW.email, NEW.company,
    COALESCE(NEW."position", NEW.job_title),
    COALESCE(NEW.status, 'novo'),
    NEW.source,
    COALESCE(NEW.lead_score, 0),
    NEW.whatsapp_labels, NEW.tags, NEW.assigned_to, NEW.queue_id, NEW.notes,
    COALESCE(v_instance, 'wpp2'),
    NEW.metadata,
    COALESCE(NEW.total_purchases, 0),
    NEW.last_message_at,
    COALESCE(NEW.created_at, now()), COALESCE(NEW.updated_at, now())
  ) RETURNING id INTO v_id;

  NEW.id := v_id;
  RETURN NEW;
END $$;


ALTER FUNCTION zapp.fn_contacts_view_insert_handler() OWNER TO postgres;

--
-- Name: fn_contacts_view_update(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_contacts_view_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
BEGIN
  -- Schema explícito: zapp.evolution_contacts (BASE TABLE), não zapp.evolution_contacts (VIEW)
  UPDATE zapp.evolution_contacts
  SET
    full_name           = COALESCE(NEW.name,       full_name),
    phone_number        = COALESCE(NEW.phone,       phone_number),
    email               = COALESCE(NEW.email,       email),
    profile_picture_url = COALESCE(NEW.avatar_url,  profile_picture_url),
    lead_status         = COALESCE(NEW.status,      lead_status),
    assigned_to         = NEW.assigned_to,
    company             = COALESCE(NEW.company,     company),
    role_title          = COALESCE(NEW.position,    role_title),
    notes               = COALESCE(NEW.notes,       notes),
    lead_source         = COALESCE(NEW.source,      lead_source),
    tags                = COALESCE(NEW.tags,        tags),
    deleted_at          = NEW.deleted_at,
    updated_at          = now()
  WHERE id = NEW.id;

  IF NOT FOUND THEN
    RAISE WARNING '[fn_contacts_view_update] Nenhum contato encontrado com id=%', NEW.id;
  END IF;

  RETURN NEW;
END;
$$;


