-- Name: fn_convert_contact_to_deal(uuid, text, numeric); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_convert_contact_to_deal(p_contact_id uuid, p_title text DEFAULT NULL::text, p_value numeric DEFAULT 0) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE v_deal_id uuid; v_name text;
BEGIN
  SELECT COALESCE(full_name,push_name,'Sem nome') INTO v_name FROM evolution_contacts WHERE id=p_contact_id;
  INSERT INTO evolution_deals (title,contact_id,value,stage,source) VALUES (COALESCE(p_title,'Deal - '||v_name),p_contact_id,p_value,'novo_lead','whatsapp') RETURNING id INTO v_deal_id;
  UPDATE evolution_contacts SET lead_status='qualified' WHERE id=p_contact_id;
  RETURN v_deal_id;
END; $$;


