CREATE FUNCTION zapp.fn_count_total_rows(p_schema text, p_table text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_count bigint;
BEGIN
  PERFORM zapp.fn_require_app_user();
