--
-- Name: fn_create_transfer(uuid, uuid, uuid, uuid, text, text, text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_create_transfer(p_conversation_id uuid, p_from_agent_id uuid, p_to_agent_id uuid DEFAULT NULL::uuid, p_to_queue_id uuid DEFAULT NULL::uuid, p_transfer_type text DEFAULT 'direct'::text, p_priority text DEFAULT 'P3'::text, p_context_summary text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
    v_transfer_id UUID;
BEGIN
    INSERT INTO zapp.conversation_transfers (
        conversation_id,
        from_agent_id,
        to_agent_id,
        to_queue_id,
        transfer_type,
        priority,
        context_summary,
        sla_deadline
    ) VALUES (
        p_conversation_id,
        p_from_agent_id,
        p_to_agent_id,
        p_to_queue_id,
        p_transfer_type,
        p_priority,
        p_context_summary,
        CASE 
            WHEN p_priority = 'P1' THEN NOW() + INTERVAL '15 minutes'
            WHEN p_priority = 'P2' THEN NOW() + INTERVAL '1 hour'
            WHEN p_priority = 'P3' THEN NOW() + INTERVAL '4 hours'
            ELSE NOW() + INTERVAL '24 hours'
        END
    ) RETURNING id INTO v_transfer_id;
    
    RETURN v_transfer_id;
END;
$$;


