--
-- Name: fn_create_transfer(text, text, text, text, text, integer, text, text, text, text[]); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.fn_create_transfer(p_source_instance text, p_target_instance text, p_remote_jid text, p_reason text, p_category text DEFAULT 'outro'::text, p_priority integer DEFAULT 2, p_transfer_type text DEFAULT 'internal'::text, p_source_operator text DEFAULT NULL::text, p_context_summary text DEFAULT NULL::text, p_tags text[] DEFAULT '{}'::text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$ DECLARE v_cid uuid; v_cname text; v_convid uuid; v_msgs jsonb; v_tid uuid; v_tk int; BEGIN SELECT id, push_name INTO v_cid, v_cname FROM evolution_contacts WHERE remote_jid=p_remote_jid LIMIT 1; SELECT id INTO v_convid FROM evolution_conversations WHERE remote_jid=p_remote_jid AND instance_name=p_source_instance LIMIT 1; SELECT COALESCE(jsonb_agg(row_to_json(m)),'[]'::jsonb) INTO v_msgs FROM (SELECT message_id, from_me, left(content,200) AS content, message_type, created_at::timestamp(0) AS ts FROM evolution_messages WHERE remote_jid=p_remote_jid AND instance_name=p_source_instance ORDER BY created_at DESC LIMIT 5) m; INSERT INTO conversation_transfers(source_instance,source_conversation_id,source_operator,target_instance,contact_id,remote_jid,contact_name,transfer_type,category,reason,context_summary,context_messages,tags,priority) VALUES(p_source_instance,v_convid,p_source_operator,p_target_instance,v_cid,p_remote_jid,v_cname,p_transfer_type,p_category,p_reason,p_context_summary,v_msgs,p_tags,p_priority) RETURNING id,ticket_number INTO v_tid,v_tk; RETURN jsonb_build_object('ok',true,'transfer_id',v_tid,'ticket_number',v_tk,'contact_name',v_cname,'context_messages_count',jsonb_array_length(v_msgs),'expires_at',(SELECT expires_at FROM conversation_transfers WHERE id=v_tid)); END $$;


ALTER FUNCTION zapp.fn_create_transfer(p_source_instance text, p_target_instance text, p_remote_jid text, p_reason text, p_category text, p_priority integer, p_transfer_type text, p_source_operator text, p_context_summary text, p_tags text[]) OWNER TO supabase_admin;

--
-- Name: fn_cron_guardian(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_cron_guardian() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'cron', 'pg_catalog'
    AS $_$
DECLARE
  v_recreated text[] := '{}';
  v_fixed     text[] := '{}';
  v_count int;
  v_src text;
  v_new text;
  v_before text;   -- snapshot antes de cada patch
BEGIN
  -- === GUARDIAN DE CRONS ===
  SELECT COUNT(*) INTO v_count FROM cron.job WHERE jobname='v2-pipeline-heartbeat' AND active;
  IF v_count = 0 THEN
    PERFORM cron.schedule('v2-pipeline-heartbeat','*/30 * * * *','SELECT zapp.fn_v2_pipeline_heartbeat()');
    v_recreated := array_append(v_recreated, 'v2-pipeline-heartbeat');
  END IF;

  SELECT COUNT(*) INTO v_count FROM cron.job WHERE jobname='vacuum-messages-2h' AND active;
  IF v_count = 0 THEN
    PERFORM cron.schedule('vacuum-messages-2h','25 */2 * * *','VACUUM ANALYZE zapp.evolution_messages');
    v_recreated := array_append(v_recreated, 'vacuum-messages-2h');
  END IF;

  SELECT COUNT(*) INTO v_count FROM cron.job WHERE jobname='vacuum-contacts-2h' AND active;
  IF v_count = 0 THEN
    PERFORM cron.schedule('vacuum-contacts-2h','35 */2 * * *','VACUUM ANALYZE zapp.evolution_contacts');
    v_recreated := array_append(v_recreated, 'vacuum-contacts-2h');
  END IF;

  -- === GUARDIAN DE fn_system_health_score ===
  SELECT prosrc INTO v_src FROM pg_proc WHERE proname='fn_system_health_score';
  IF v_src IS NULL THEN
    RETURN jsonb_build_object('error','fn_system_health_score nao encontrada');
  END IF;
  v_new := v_src;

  -- PROTEÇÃO 1: cron_health sem filtro "does not exist"
  IF v_new NOT ILIKE '%does not exist%' THEN
    v_before := v_new;
    v_new := replace(v_new,
      $O$SELECT COUNT(*) INTO v FROM cron.job_run_details WHERE status='failed' AND start_time IS NOT NULL AND start_time>NOW()-INTERVAL '24 hours';$O$,
      $N$SELECT COUNT(*) INTO v FROM cron.job_run_details WHERE status='failed' AND start_time IS NOT NULL AND start_time>NOW()-INTERVAL '24 hours' AND return_message NOT LIKE '%does not exist%' AND return_message NOT LIKE '%invalid input value for enum webhook_event_status%';$N$
    );
    IF v_new = v_before THEN  -- tentativa 24h falhou, tentar 1h
      v_new := replace(v_new,
        $O$SELECT COUNT(*) INTO v FROM cron.job_run_details WHERE status='failed' AND start_time IS NOT NULL AND start_time>NOW()-INTERVAL '1 hour';$O$,
        $N$SELECT COUNT(*) INTO v FROM cron.job_run_details WHERE status='failed' AND start_time IS NOT NULL AND start_time>NOW()-INTERVAL '1 hour' AND return_message NOT LIKE '%does not exist%' AND return_message NOT LIKE '%invalid input value for enum webhook_event_status%';$N$
      );
    END IF;
    -- FIX: comparar v_new vs v_before (não vs v_src original)
    IF v_new <> v_before THEN
      v_fixed := array_append(v_fixed, 'fn_health:cron_filter');
    ELSE
      v_fixed := array_append(v_fixed, 'fn_health:cron_filter:PATTERN_NOT_FOUND');
    END IF;
  END IF;

  -- PROTEÇÃO 2: partition_indexes com tabela errada
  -- Detectar EXATAMENTE: 'evolution_messages','message_id' (sem _wpp2)
  -- Usar posição para verificar que NÃO é wpp2
  IF position($P$('evolution_messages','message_id_instance_name_key'$P$ IN v_new) > 0
     AND position($P$('evolution_messages_wpp2','message_id_instance_name_key'$P$ IN v_new) = 0
  THEN
    v_before := v_new;
    v_new := replace(v_new,
      $O$('evolution_messages','message_id_instance_name_key','evo'),('evolution_messages','id_idx','evo')$O$,
      $N$('evolution_messages_wpp2','message_id_instance_name_key','evo'),('evolution_messages_wpp2','id_idx','evo')$N$
    );
    -- FIX: comparar v_new vs v_before desta etapa
    IF v_new <> v_before THEN
      v_fixed := array_append(v_fixed, 'fn_health:partition_idx_table');
    ELSE
      v_fixed := array_append(v_fixed, 'fn_health:partition_idx_table:PATTERN_NOT_FOUND');
    END IF;
  END IF;

  -- Aplicar se houve mudanças reais
  IF v_new <> v_src THEN
    EXECUTE format(
      'CREATE OR REPLACE FUNCTION zapp.fn_system_health_score() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,evo,zapp,ops,extensions,pg_catalog AS %L',
      v_new
    );
  END IF;

  RETURN jsonb_build_object(
    'checked', 3,
    'recreated', to_jsonb(v_recreated),
    'fixed', to_jsonb(v_fixed),
    'ts', now()
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('error', SQLERRM, 'ts', now());
END;
$_$;


ALTER FUNCTION zapp.fn_cron_guardian() OWNER TO postgres;

--
-- Name: fn_d30_execute_full_pipeline(boolean); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.fn_d30_execute_full_pipeline(p_dry_run boolean DEFAULT true) RETURNS TABLE(fase text, etapa text, detalhe text, status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  v_backup_schema TEXT;
  v_snapshot_atualizado BOOLEAN := false;
  v_tabelas_drop INT;
BEGIN
  IF NOT p_dry_run AND EXISTS(SELECT 1 FROM pg_namespace WHERE nspname = 'legacy_staging') THEN
    INSERT INTO migration_snapshot_d30 (entidade, qtd_legacy, qtd_evolution, qtd_migrados, qtd_novos_pos_migracao, taxa_migracao_pct, notes)
    VALUES (
      'contatos_final_d30',
      (SELECT COUNT(*)::int FROM legacy_staging.contacts),
      (SELECT COUNT(*)::int FROM evolution_contacts),
      (SELECT COUNT(*)::int FROM evolution_contacts WHERE raw_data ->> 'legacy_id' IS NOT NULL),
      (SELECT COUNT(*)::int FROM evolution_contacts WHERE raw_data ->> 'legacy_id' IS NULL),
      ROUND(100.0 * (SELECT COUNT(*) FROM evolution_contacts WHERE raw_data ->> 'legacy_id' IS NOT NULL) 
            / NULLIF((SELECT COUNT(*) FROM legacy_staging.contacts), 0), 2),
      'Snapshot FINAL no momento do D+30 execution'
    );
    v_snapshot_atualizado := true;
  END IF;
  
  RETURN QUERY SELECT 
    '1_snapshot'::text, 'refresh_numeros_finais'::text,
    CASE WHEN v_snapshot_atualizado THEN 'Snapshot final inserido' ELSE 'Modo dry-run ou schema não existe' END::text,
    CASE WHEN v_snapshot_atualizado THEN 'OK' ELSE 'SKIP' END::text;
  
  IF NOT p_dry_run THEN
    FOR fase, etapa IN SELECT 'backup' as a, b.etapa FROM fn_d30_backup_legacy_staging() b LOOP
      detalhe := etapa; status := 'OK';
      RETURN NEXT;
    END LOOP;
  ELSE
    RETURN QUERY SELECT '2_backup'::text, 'dry_run'::text, 
      'Criaria schema backup_legacy_<timestamp>'::text, 'DRY_RUN'::text;
  END IF;
  
  RETURN QUERY 
    SELECT '3_validation'::text, c.action::text, c.detail::text, 
      CASE WHEN c.action = 'blocked' THEN 'BLOCKED' 
           WHEN c.action = 'dry_run' THEN 'DRY_RUN' 
           ELSE 'OK' END::text
    FROM fn_legacy_staging_cleanup(true) c;
  
  IF NOT p_dry_run THEN
    SELECT COUNT(*)::int INTO v_tabelas_drop 
    FROM information_schema.tables WHERE table_schema = 'legacy_staging';
    RETURN QUERY 
      SELECT '4_drop'::text, c.action::text, c.detail::text,
        CASE WHEN c.action = 'executed' THEN '🏆 DONE' 
             WHEN c.action = 'blocked' THEN 'BLOCKED'
             ELSE 'INFO' END::text
      FROM fn_legacy_staging_cleanup(false) c;
  ELSE
    RETURN QUERY SELECT '4_drop'::text, 'dry_run'::text,
      'DROP SCHEMA legacy_staging CASCADE (aguardando 15/05)'::text, 'DRY_RUN'::text;
  END IF;
  
  RETURN QUERY SELECT '5_done'::text, 'pipeline_finished'::text,
    'Pipeline D+30 finalizado. Checar v_migration_reconciliation.'::text, '🏆'::text;
END;
$$;


ALTER FUNCTION zapp.fn_d30_execute_full_pipeline(p_dry_run boolean) OWNER TO supabase_admin;

--
-- Name: fn_d30_reminder_check(); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.fn_d30_reminder_check() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  v_first_migration TIMESTAMPTZ;
  v_days_since NUMERIC;
  v_legacy_exists BOOLEAN;
  v_existing_alert_id UUID;
BEGIN
  SELECT EXISTS(SELECT 1 FROM pg_namespace WHERE nspname = 'legacy_staging') 
    INTO v_legacy_exists;
  
  IF NOT v_legacy_exists THEN
    UPDATE webhook_health_alerts
    SET resolved_at = now(),
        details = details || jsonb_build_object('auto_resolved', true, 'reason', 'legacy_staging foi dropado')
    WHERE alert_type IN ('d30_approaching', 'd30_ready', 'd30_overdue')
      AND resolved_at IS NULL;
    RETURN;
  END IF;
  
  SELECT MIN(executed_at) INTO v_first_migration FROM zapp.migration_audit;
  v_days_since := EXTRACT(EPOCH FROM (now() - v_first_migration)) / 86400;
  
  IF v_days_since >= 27 AND v_days_since < 30 THEN
    SELECT id INTO v_existing_alert_id FROM webhook_health_alerts 
    WHERE alert_type = 'd30_approaching' AND resolved_at IS NULL LIMIT 1;
    IF v_existing_alert_id IS NULL THEN
      INSERT INTO webhook_health_alerts (alert_type, severity, title, details)
      VALUES ('d30_approaching','WARNING','🟡 D+30 se aproximando - preparar DROP legacy_staging',
        jsonb_build_object('dias_desde_migracao', ROUND(v_days_since, 1),
          'dias_para_d30', ROUND(30 - v_days_since, 1),
          'acao_recomendada', 'Revisar checklist + rodar fn_d30_execute_full_pipeline(true) em dry-run',
          'comando_execucao', 'SELECT * FROM fn_d30_execute_full_pipeline(false);'));
    END IF;
  ELSIF v_days_since >= 30 THEN
    SELECT id INTO v_existing_alert_id FROM webhook_health_alerts 
    WHERE alert_type = 'd30_ready' AND resolved_at IS NULL LIMIT 1;
    IF v_existing_alert_id IS NULL THEN
      INSERT INTO webhook_health_alerts (alert_type, severity, title, details)
      VALUES ('d30_ready','CRITICAL','🔴 D+30 atingido - EXECUTAR DROP legacy_staging',
        jsonb_build_object('dias_desde_migracao', ROUND(v_days_since, 1),
          'dias_apos_d30', ROUND(v_days_since - 30, 1),
          'tabelas_staging', (SELECT COUNT(*)::int FROM information_schema.tables WHERE table_schema = 'legacy_staging'),
          'comando_execucao', 'SELECT * FROM fn_d30_execute_full_pipeline(false);',
          'acao_recomendada', 'Executar pipeline D+30 agora. Backup automático incluído.'));
    END IF;
  ELSIF v_days_since >= 60 THEN
    SELECT id INTO v_existing_alert_id FROM webhook_health_alerts 
    WHERE alert_type = 'd30_overdue' AND resolved_at IS NULL LIMIT 1;
    IF v_existing_alert_id IS NULL THEN
      INSERT INTO webhook_health_alerts (alert_type, severity, title, details)
      VALUES ('d30_overdue','CRITICAL','🚨 D+30 ATRASADO - legacy_staging deveria ter sido dropado',
        jsonb_build_object('dias_desde_migracao', ROUND(v_days_since, 1),
          'dias_de_atraso', ROUND(v_days_since - 30, 1),
          'urgencia', 'ALTA - acumulando dívida técnica + LGPD',
          'comando_execucao', 'SELECT * FROM fn_d30_execute_full_pipeline(false);'));
    END IF;
  END IF;
END;
$$;


