CREATE FUNCTION zapp.fn_dashboard_data() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE v jsonb;
BEGIN SELECT jsonb_build_object('contacts',(SELECT count(*) FROM evolution_contacts WHERE deleted_at IS NULL),'messages_today',(SELECT count(*) FROM evolution_messages WHERE created_at>=date_trunc('day',now())),'messages_7d',(SELECT count(*) FROM evolution_messages WHERE created_at>=now()-interval '7 days'),'open_conversations',(SELECT count(*) FROM evolution_conversations WHERE status IN ('aberta','open','active')),'pipeline_value',(SELECT COALESCE(sum(value),0) FROM evolution_deals WHERE stage NOT IN ('perdido','pedido_finalizado')),'active_deals',(SELECT count(*) FROM evolution_deals WHERE stage NOT IN ('perdido','pedido_finalizado')),'unread_alerts',(SELECT count(*) FROM evolution_alerts WHERE acknowledged=false)) INTO v; RETURN v; END; $$;


