--
-- Name: fn_demand_forecast(integer, integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_demand_forecast(p_days integer DEFAULT 28, p_forecast_days integer DEFAULT 7) RETURNS TABLE(d date, kind text, dow integer, value numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'pg_catalog'
    AS $$
  WITH daily AS (
    SELECT created_at::date AS d, count(*)::numeric AS n
    FROM evo.evolution_messages
    WHERE created_at >= date_trunc('day', now()) - (p_days || ' days')::interval
      AND deleted_at IS NULL
    GROUP BY 1
  ), dow_stats AS (
    SELECT EXTRACT(dow FROM d)::int AS dow, round(avg(n), 2) AS avg_n
    FROM daily GROUP BY 1
  ), trend AS (
    SELECT CASE WHEN count(*) FILTER (WHERE d >= date_trunc('week', now()) - interval '28 days'
                                       AND d < date_trunc('week', now()) - interval '14 days') > 0
                THEN LEAST(1.5, GREATEST(0.5,
                     round(avg(n) FILTER (WHERE d >= date_trunc('week', now()) - interval '14 days'
                                           AND d < date_trunc('week', now())), 2) /
                     NULLIF(avg(n) FILTER (WHERE d >= date_trunc('week', now()) - interval '28 days'
                                           AND d < date_trunc('week', now()) - interval '14 days'), 0)))
           ELSE 1 END AS f
    FROM daily
  )
  SELECT d, 'actual'::text, EXTRACT(dow FROM d)::int, n FROM daily
    WHERE d >= date_trunc('day', now()) - interval '6 days'
  UNION ALL
  SELECT (date_trunc('day', now()) + (g || ' days')::interval)::date, 'forecast'::text,
         EXTRACT(dow FROM date_trunc('day', now()) + (g || ' days')::interval)::int,
         round(ds.avg_n * tr.f, 0)
  FROM generate_series(0, p_forecast_days - 1) g
  CROSS JOIN dow_stats ds
  CROSS JOIN trend tr;
$$;


ALTER FUNCTION zapp.fn_demand_forecast(p_days integer, p_forecast_days integer) OWNER TO postgres;

--
-- Name: fn_detect_401_bursts(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_detect_401_bursts() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_count_log      int := 0;
  v_count_ipwatch  int := 0;
  v_count_health   int := 0;
  v_total          int;
  v_ipwatch_total  bigint := 0;
  v_monitoring_gap boolean := true;
  v_already_burst  boolean;
  v_already_gap    boolean;
  v_already_hunt   boolean;
  v_alert_fired    boolean := false;
  v_gap_detail     text;
BEGIN
  SELECT count(*)::int INTO v_count_log
  FROM zapp.webhook_audit_log
  WHERE status_code = 401 AND created_at > now() - interval '15min';

  SELECT count(*)::int INTO v_count_health
  FROM zapp.webhook_health_alerts
  WHERE alert_type = 'sentry_401_feed' AND created_at > now() - interval '15min';

  v_total := v_count_log + v_count_ipwatch + v_count_health;

  v_gap_detail :=
    'BLIND: evolution_ip_watch removida em 2026-08-06 (fantasma, 0 linhas, sem trigger). ' ||
    'webhook_audit_log captures edge-fn rejections only, not Evolution API 401s. ' ||
    'Burst detection remains DB-blind until log pipeline is wired.';

  SELECT EXISTS(
    SELECT 1 FROM zapp.warroom_alerts
    WHERE source = 'fn_detect_401_bursts' AND alert_type = 'critical'
      AND created_at > now() - interval '30min'
  ) INTO v_already_burst;

  SELECT EXISTS(
    SELECT 1 FROM zapp.warroom_alerts
    WHERE source = 'fn_detect_401_bursts' AND alert_type = 'warning'
      AND created_at > now() - interval '6h'
  ) INTO v_already_gap;

  -- FIX v5: dedup por TITLE (v4 usava message LIKE que nunca batia -> spam a cada 15min)
  SELECT EXISTS(
    SELECT 1 FROM zapp.warroom_alerts
    WHERE source = 'fn_detect_401_bursts' AND alert_type = 'info'
      AND title LIKE '%stale_api_key_hunt%'
      AND created_at > now() - interval '24h'
  ) INTO v_already_hunt;

  IF v_total >= 3 AND NOT v_already_burst THEN
    INSERT INTO zapp.warroom_alerts (alert_type, title, message, source)
    VALUES (
      'critical',
      format('🚨 401 BURST: %s signals em 15min', v_total),
      format(
        'Sources: webhook_audit_log=%s | evolution_ip_watch=%s (removida 2026-08-06) | health_alerts=%s '
        '— Verificar imediatamente. Chave atual: vault evolution_api_key (md5 0d658c199f7945a2b960a0a22ab5efa6).',
        v_count_log, v_count_ipwatch, v_count_health
      ),
      'fn_detect_401_bursts'
    );
    v_alert_fired := true;

  ELSIF v_monitoring_gap AND NOT v_already_gap THEN
    INSERT INTO zapp.warroom_alerts (alert_type, title, message, source)
    VALUES (
      'warning',
      '⚠️ 401 DETECTION BLIND: pipeline VPS→DB inativo',
      'evolution_ip_watch removida em 2026-08-06 (era fantasma: 0 linhas). ' ||
      'Ação: configurar Traefik access log → Supabase API. ' ||
      'Sentry recebe 401s (logpatch T3 corrigido em 2026-07-12).',
      'fn_detect_401_bursts'
    );
    v_alert_fired := true;
  END IF;

  IF NOT v_already_hunt THEN
    INSERT INTO zapp.warroom_alerts (alert_type, title, message, source)
    VALUES (
      'info',
      '🔍 OBS-2 stale_api_key_hunt: encontre o consumer com chave velha',
      'A Evolution API gera ~1 × 401 a cada 5 min de um consumer com apikey obsoleta. ' ||
      'Chave atual: vault evolution_api_key (md5 0d658c199f7945a2b960a0a22ab5efa6). ' ||
      'CHECKLIST: n8n credenciais → docker service env → secrets swarm → Sentry 401s. ' ||
      'Ref: AUDITORIA_EVO_API_2026-07-12.md OBS-2.',
      'fn_detect_401_bursts'
    );
    v_alert_fired := true;
  END IF;

  RETURN jsonb_build_object(
    'ok',             true,
    'count_15min',    v_total,
    'alert_fired',    v_alert_fired,
    'sources', jsonb_build_object(
      'webhook_audit_log_401',  v_count_log,
      'evolution_ip_watch_401', v_count_ipwatch,
      'health_alerts_401',      v_count_health
    ),
    'monitoring_gap',        v_monitoring_gap,
    'monitoring_gap_detail', v_gap_detail,
    'version', 'v5-fix-dedup-title-2026-08-14'
  );
END;
$$;


ALTER FUNCTION zapp.fn_detect_401_bursts() OWNER TO postgres;

--
-- Name: fn_detect_ack_loss_gap(interval, integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_detect_ack_loss_gap(p_window interval DEFAULT '00:30:00'::interval, p_dlq_threshold integer DEFAULT 5) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_total_dlq_msg      bigint := 0;
  v_db_timeout_count   bigint := 0;
  v_db_error_count     bigint := 0;
  v_likely_lost_count  bigint := 0;
  v_retry_exhausted    bigint := 0;
  v_dlq_growth_rate    numeric;
  v_prev_window_count  bigint := 0;
  v_result             jsonb;
  v_status             text;
BEGIN
  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE failure_category = 'db_write_timeout'),
    COUNT(*) FILTER (WHERE failure_category IN ('db_write_timeout', 'db_write_error')),
    COUNT(*) FILTER (WHERE likely_lost),
    COUNT(*) FILTER (WHERE retry_exhausted)
  INTO
    v_total_dlq_msg,
    v_db_timeout_count,
    v_db_error_count,
    v_likely_lost_count,
    v_retry_exhausted
  FROM public.evo_ack_loss_candidates
  WHERE created_at >= now() - p_window;

  SELECT COUNT(*)
  INTO v_prev_window_count
  FROM public.evo_ack_loss_candidates
  WHERE created_at >= now() - (p_window * 2)
    AND created_at <  now() - p_window;

  v_dlq_growth_rate := CASE
    WHEN v_prev_window_count = 0 AND v_total_dlq_msg > 0 THEN 999.0
    WHEN v_prev_window_count = 0 THEN 0.0
    ELSE round(((v_total_dlq_msg::numeric / v_prev_window_count) - 1) * 100, 1)
  END;

  v_status := CASE
    WHEN v_likely_lost_count > 0 OR v_db_timeout_count >= p_dlq_threshold THEN 'CRITICAL'
    WHEN v_db_error_count > 0    OR v_total_dlq_msg > 0                   THEN 'WARN'
    ELSE 'OK'
  END;

  IF v_likely_lost_count > 0 THEN
    BEGIN
      INSERT INTO zapp.webhook_health_alerts
        (alert_type, severity, title, details, created_at)
      VALUES (
        'ack_loss_gap',
        'critical',
        format('E8-06: ACK-loss CRITICAL — %s likely-lost messages (ACKed, DB write failed, no retry)',
          v_likely_lost_count),
        jsonb_build_object(
          'likely_lost_count',    v_likely_lost_count,
          'db_timeout_count',     v_db_timeout_count,
          'db_error_count',       v_db_error_count,
          'retry_exhausted',      v_retry_exhausted,
          'total_dlq_msg',        v_total_dlq_msg,
          'window',               p_window,
          'dlq_growth_rate_pct',  v_dlq_growth_rate,
          'root_cause',           'Consumer ACKs RabbitMQ before Supabase INSERT confirmed',
          'fix_action',           'ACK only after INSERT returns success — consumer code change required'
        ),
        now()
      );
    EXCEPTION WHEN OTHERS THEN NULL; END;

  ELSIF v_db_timeout_count >= p_dlq_threshold THEN
    BEGIN
      INSERT INTO zapp.webhook_health_alerts
        (alert_type, severity, title, details, created_at)
      VALUES (
        'ack_loss_gap',
        'high',
        format('E8-06: ACK-loss WARN — %s DB-timeout DLQ entries in %s (threshold: %s)',
          v_db_timeout_count, p_window, p_dlq_threshold),
        jsonb_build_object(
          'db_timeout_count',     v_db_timeout_count,
          'db_error_count',       v_db_error_count,
          'total_dlq_msg',        v_total_dlq_msg,
          'window',               p_window,
          'dlq_growth_rate_pct',  v_dlq_growth_rate,
          'root_cause',           'Consumer ACKs RabbitMQ before Supabase INSERT confirmed',
          'fix_action',           'ACK only after INSERT returns success — consumer code change required'
        ),
        now()
      );
    EXCEPTION WHEN OTHERS THEN NULL; END;
  END IF;

  v_result := jsonb_build_object(
    'checked_at',           now(),
    'window',               p_window,
    'status',               v_status,
    'total_dlq_msg',        v_total_dlq_msg,
    'db_timeout_count',     v_db_timeout_count,
    'db_error_count',       v_db_error_count,
    'likely_lost_count',    v_likely_lost_count,
    'retry_exhausted',      v_retry_exhausted,
    'dlq_growth_rate_pct',  v_dlq_growth_rate,
    'threshold',            p_dlq_threshold,
    'root_cause',           'Consumer ACKs RabbitMQ before Supabase INSERT confirmed (at-most-once)',
    'fix_action',           'ACK only AFTER INSERT confirmed — consumer code change required'
  );

  RETURN v_result;
END;
$$;


ALTER FUNCTION zapp.fn_detect_ack_loss_gap(p_window interval, p_dlq_threshold integer) OWNER TO postgres;

--
-- Name: fn_detect_dedup_cap_failures(interval); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_detect_dedup_cap_failures(p_window interval DEFAULT '01:00:00'::interval) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog'
    AS $$
DECLARE
  v_dedup_threshold  CONSTANT int := 3;
  v_total_dupes      bigint := 0;
  v_total_dup_rows   bigint := 0;
  v_worst_offenders  jsonb;
  v_result           jsonb;
  v_status           text;
BEGIN
  SELECT
    COUNT(DISTINCT message_id),
    SUM(cnt) - COUNT(DISTINCT message_id)
  INTO v_total_dupes, v_total_dup_rows
  FROM (
    SELECT message_id, COUNT(*) AS cnt
    FROM zapp.evolution_messages
    WHERE message_id IS NOT NULL
      AND created_at >= now() - p_window
    GROUP BY message_id
    HAVING COUNT(*) > 1
  ) t;

  SELECT jsonb_agg(jsonb_build_object(
    'message_id',  message_id,
    'count',       cnt,
    'first_seen',  first_seen,
    'last_seen',   last_seen
  ) ORDER BY cnt DESC)
  INTO v_worst_offenders
  FROM (
    SELECT
      message_id,
      COUNT(*)        AS cnt,
      MIN(created_at) AS first_seen,
      MAX(created_at) AS last_seen
    FROM zapp.evolution_messages
    WHERE message_id IS NOT NULL
      AND created_at >= now() - p_window
    GROUP BY message_id
    HAVING COUNT(*) > 1
    ORDER BY cnt DESC
    LIMIT 5
  ) t;

  v_status := CASE
    WHEN v_total_dupes >= v_dedup_threshold THEN 'CRITICAL'
    WHEN v_total_dupes > 0                  THEN 'WARN'
    ELSE 'OK'
  END;

  IF v_status IN ('CRITICAL', 'WARN') THEN
    BEGIN
      INSERT INTO zapp.webhook_health_alerts
        (alert_type, severity, title, details, created_at)
      VALUES (
        'dedup_cap_failure',
        CASE WHEN v_status = 'CRITICAL' THEN 'critical' ELSE 'high' END,
        format('E8-01: Dedup failure — %s duplicate message_ids (%s extra rows) in %s',
          v_total_dupes, v_total_dup_rows, p_window),
        jsonb_build_object(
          'total_duplicate_ids', v_total_dupes,
          'total_extra_rows',    v_total_dup_rows,
          'window',              p_window,
          'worst_offenders',     COALESCE(v_worst_offenders, '[]'::jsonb),
          'root_cause',          'Consumer v2 Set has no TTL/max-size; grows until OOM or loses state on restart',
          'fix_action',          'Add LRU cap (max 10k entries) + TTL (5min) to consumer dedup Set'
        ),
        now()
      );
    EXCEPTION WHEN OTHERS THEN NULL; END;
  END IF;

  RETURN jsonb_build_object(
    'checked_at',          now(),
    'window',              p_window,
    'status',              v_status,
    'total_duplicate_ids', v_total_dupes,
    'total_extra_rows',    COALESCE(v_total_dup_rows, 0),
    'worst_offenders',     COALESCE(v_worst_offenders, '[]'::jsonb),
    'threshold',           v_dedup_threshold,
    'root_cause',          'Consumer v2 Set has no TTL/max-size cap',
    'fix_action',          'Add LRU cap + TTL to dedup Set, or enforce UNIQUE on evolution_messages.message_id'
  );
END;
$$;


ALTER FUNCTION zapp.fn_detect_dedup_cap_failures(p_window interval) OWNER TO postgres;

--
-- Name: FUNCTION fn_detect_dedup_cap_failures(p_window interval); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.fn_detect_dedup_cap_failures(p_window interval) IS 'E8-01: Detects duplicate message_id entries in evolution_messages — proof that the consumer v2 dedup Set failed (no cap, no TTL, state lost on restart). WARN on first duplicate, CRITICAL when >= 3 duplicate IDs in window.';


--
-- Name: fn_detect_schema_drift(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_detect_schema_drift() RETURNS TABLE(function_name text, suspected_column text, suspected_table text, severity text, hint text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE v_fn RECORD; v_tbl RECORD; v_match RECORD;
BEGIN
  FOR v_fn IN SELECT p.proname, pg_get_functiondef(p.oid) AS src FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.prolang=(SELECT oid FROM pg_language WHERE lanname='plpgsql') AND p.proname NOT LIKE 'fn_detect_schema_drift%' LOOP
    FOR v_tbl IN SELECT t.table_name, array_agg(c.column_name::text) AS real_cols FROM information_schema.tables t JOIN information_schema.columns c ON c.table_name=t.table_name AND c.table_schema=t.table_schema WHERE t.table_schema='public' GROUP BY t.table_name LOOP
      FOR v_match IN SELECT DISTINCT (regexp_matches(v_fn.src,'(?:"'||v_tbl.table_name||'"|\m'||v_tbl.table_name||'\M)\s*\.\s*"?([a-zA-Z_][a-zA-Z0-9_]*)"?','g'))[1] AS col LOOP
        IF v_match.col IS NOT NULL AND v_match.col NOT IN ('*','oid','tableoid') AND NOT (v_match.col=ANY(v_tbl.real_cols)) THEN
          function_name:=v_fn.proname; suspected_column:=v_match.col; suspected_table:=v_tbl.table_name; severity:='high'; hint:='Column not found'; RETURN NEXT;
        END IF;
      END LOOP;
    END LOOP;
  END LOOP;
END; $$;


ALTER FUNCTION zapp.fn_detect_schema_drift() OWNER TO postgres;

--
-- Name: fn_detect_spurious_closes(interval, interval); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_detect_spurious_closes(p_window interval DEFAULT '01:00:00'::interval, p_reconnect_window interval DEFAULT '00:00:30'::interval) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$
DECLARE
  v_spurious_warn_pct     CONSTANT numeric := 70.0;
  v_spurious_critical_pct CONSTANT numeric := 90.0;
  v_min_count             CONSTANT int     := 5;
  v_total_disconnects  bigint := 0;
  v_spurious_count     bigint := 0;
  v_real_count         bigint := 0;
  v_spurious_rate      numeric := 0;
  v_top_offenders      jsonb;
  v_result             jsonb;
  v_status             text;
BEGIN
  WITH disconnects AS (
    SELECT
      instance_name,
      created_at AS disconnected_at,
      LEAD(state)       OVER (PARTITION BY instance_name ORDER BY created_at) AS next_state,
      LEAD(created_at)  OVER (PARTITION BY instance_name ORDER BY created_at) AS next_state_at
    FROM public.evo_connection_history
    WHERE state = 'disconnected'
      AND created_at >= now() - p_window
  )
  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE
      next_state IN ('connecting', 'connected')
      AND (next_state_at - disconnected_at) <= p_reconnect_window
    ),
    COUNT(*) FILTER (WHERE
      next_state IS NULL
      OR next_state NOT IN ('connecting', 'connected')
      OR (next_state_at - disconnected_at) > p_reconnect_window
    )
  INTO v_total_disconnects, v_spurious_count, v_real_count
  FROM disconnects
  WHERE next_state IS NOT NULL;
  IF v_total_disconnects > 0 THEN
    v_spurious_rate := round((v_spurious_count::numeric / v_total_disconnects) * 100, 1);
  END IF;
  WITH disconnects AS (
    SELECT
      instance_name,
      created_at AS disconnected_at,
      LEAD(state)       OVER (PARTITION BY instance_name ORDER BY created_at) AS next_state,
      LEAD(created_at)  OVER (PARTITION BY instance_name ORDER BY created_at) AS next_state_at
    FROM public.evo_connection_history
    WHERE state = 'disconnected'
      AND created_at >= now() - p_window
  ),
  classified AS (
    SELECT
      instance_name,
      CASE WHEN next_state IN ('connecting','connected')
             AND (next_state_at - disconnected_at) <= p_reconnect_window
           THEN true ELSE false END AS is_spurious
    FROM disconnects WHERE next_state IS NOT NULL
  )
  SELECT jsonb_agg(jsonb_build_object(
    'instance_name',   instance_name,
    'spurious_count',  spurious_count,
    'real_count',      real_count,
    'total',           spurious_count + real_count
  ) ORDER BY spurious_count DESC)
  INTO v_top_offenders
  FROM (
    SELECT
      instance_name,
      COUNT(*) FILTER (WHERE is_spurious)     AS spurious_count,
      COUNT(*) FILTER (WHERE NOT is_spurious)  AS real_count
    FROM classified
    GROUP BY instance_name
    HAVING COUNT(*) FILTER (WHERE is_spurious) > 0
    ORDER BY spurious_count DESC
    LIMIT 5
  ) t;
  v_status := CASE
    WHEN v_spurious_count >= v_min_count AND v_spurious_rate >= v_spurious_critical_pct THEN 'CRITICAL'
    WHEN v_spurious_count >= v_min_count AND v_spurious_rate >= v_spurious_warn_pct     THEN 'WARN'
    WHEN v_spurious_count > 0                                                           THEN 'INFO'
    ELSE 'OK'
  END;
  IF v_status = 'CRITICAL' THEN
    BEGIN
      INSERT INTO zapp.webhook_health_alerts
        (alert_type, severity, title, details, created_at)
      VALUES (
        'spurious_close_flood',
        'critical',
        format('E1-12: %s%% of connection closes are spurious (%s/%s) — n8n consumer filter REQUIRED',
          round(v_spurious_rate, 0), v_spurious_count, v_total_disconnects),
        jsonb_build_object(
          'spurious_count',        v_spurious_count,
          'real_count',            v_real_count,
          'total_disconnects',     v_total_disconnects,
          'spurious_rate_pct',     v_spurious_rate,
          'window',                p_window,
          'reconnect_window',      p_reconnect_window,
          'top_offenders',         COALESCE(v_top_offenders, '[]'::jsonb),
          'fix_action',            'Add filter in n8n consumer: skip connection.update type=close when next event is connecting/connected within 30s',
          'threshold_warn_pct',    v_spurious_warn_pct,
          'threshold_crit_pct',    v_spurious_critical_pct
        ),
        now()
      );
    EXCEPTION WHEN OTHERS THEN NULL; END;
  ELSIF v_status = 'WARN' THEN
    BEGIN
      INSERT INTO zapp.webhook_health_alerts
        (alert_type, severity, title, details, created_at)
      VALUES (
        'spurious_close_flood',
        'high',
        format('E1-12: %s%% of connection closes are spurious (%s/%s) — consider n8n consumer filter',
          round(v_spurious_rate, 0), v_spurious_count, v_total_disconnects),
        jsonb_build_object(
          'spurious_count',        v_spurious_count,
          'real_count',            v_real_count,
          'total_disconnects',     v_total_disconnects,
          'spurious_rate_pct',     v_spurious_rate,
          'window',                p_window,
          'reconnect_window',      p_reconnect_window,
          'top_offenders',         COALESCE(v_top_offenders, '[]'::jsonb),
          'fix_action',            'Filter connection.update type=close in n8n when Baileys reconnects within 30s'
        ),
        now()
      );
    EXCEPTION WHEN OTHERS THEN NULL; END;
  END IF;
  v_result := jsonb_build_object(
    'checked_at',          now(),
    'window',              p_window,
    'reconnect_window',    p_reconnect_window,
    'status',              v_status,
    'total_disconnects',   v_total_disconnects,
    'spurious_count',      v_spurious_count,
    'real_count',          v_real_count,
    'spurious_rate_pct',   v_spurious_rate,
    'top_offenders',       COALESCE(v_top_offenders, '[]'::jsonb),
    'thresholds',          jsonb_build_object(
                             'warn_pct',     v_spurious_warn_pct,
                             'critical_pct', v_spurious_critical_pct,
                             'min_count',    v_min_count
                           ),
    'fix_action',          'Filter connection.update type=close in n8n consumer when Baileys reconnects within 30s'
  );
  RETURN v_result;
END $$;


ALTER FUNCTION zapp.fn_detect_spurious_closes(p_window interval, p_reconnect_window interval) OWNER TO postgres;

--
-- Name: FUNCTION fn_detect_spurious_closes(p_window interval, p_reconnect_window interval); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.fn_detect_spurious_closes(p_window interval, p_reconnect_window interval) IS 'E1-12: Detects spurious connection.update close events — disconnections where Baileys auto-reconnects within p_reconnect_window (default 30s). WARN when >70% of closes are spurious, CRITICAL when >90%. Provides per-instance breakdown to calibrate n8n consumer filter. Scheduled every 15 minutes via pg_cron.';


--
-- Name: fn_detect_swarm_task_duplication(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_detect_swarm_task_duplication() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_heartbeat_window   CONSTANT interval := '5 minutes';
  v_heartbeat_max_ok   CONSTANT int      := 2;
  v_open_window        CONSTANT interval := '60 seconds';

  v_burst_count        int := 0;
  v_double_open_count  int := 0;
  r                    record;
BEGIN
  FOR r IN
    SELECT
      service_name,
      COUNT(*) AS hb_count,
      MIN(heartbeat_at) AS first_hb,
      MAX(heartbeat_at) AS last_hb
    FROM public.evo_guardian_heartbeat
    WHERE heartbeat_at >= now() - v_heartbeat_window
    GROUP BY service_name
    HAVING COUNT(*) > v_heartbeat_max_ok
    ORDER BY hb_count DESC
  LOOP
    v_burst_count := v_burst_count + 1;

    BEGIN
      INSERT INTO zapp.webhook_health_alerts
        (alert_type, severity, title, details, created_at)
      VALUES (
        'swarm_task_duplicate',
        'critical',
        format('E1-07: Swarm duplicate suspected — service "%s" sent %s heartbeats in 5min (max_ok=%s)',
          r.service_name, r.hb_count, v_heartbeat_max_ok),
        jsonb_build_object(
          'service_name',   r.service_name,
          'hb_count_5min',  r.hb_count,
          'max_ok',         v_heartbeat_max_ok,
          'first_hb',       r.first_hb,
          'last_hb',        r.last_hb,
          'detection',      'heartbeat_burst'
        ),
        now()
      );
    EXCEPTION WHEN OTHERS THEN NULL; END;
  END LOOP;

  FOR r IN
    WITH opens AS (
      SELECT
        instance_name,
        created_at,
        LAG(created_at) OVER (PARTITION BY instance_name ORDER BY created_at) AS prev_open_at
      FROM public.evo_connection_history
      WHERE state = 'open'
        AND created_at >= now() - interval '10 minutes'
    )
    SELECT
      instance_name,
      prev_open_at,
      created_at AS this_open_at,
      EXTRACT(EPOCH FROM (created_at - prev_open_at))::int AS gap_seconds
    FROM opens
    WHERE prev_open_at IS NOT NULL
      AND (created_at - prev_open_at) <= v_open_window
    ORDER BY gap_seconds ASC
  LOOP
    v_double_open_count := v_double_open_count + 1;

    BEGIN
      INSERT INTO zapp.webhook_health_alerts
        (alert_type, severity, title, details, created_at)
      VALUES (
        'swarm_task_duplicate',
        'critical',
        format('E1-07: Baileys double-open on "%s" — two OPEN events %ss apart (window: %ss)',
          r.instance_name, r.gap_seconds, EXTRACT(EPOCH FROM v_open_window)::int),
        jsonb_build_object(
          'instance_name', r.instance_name,
          'first_open',    r.prev_open_at,
          'second_open',   r.this_open_at,
          'gap_seconds',   r.gap_seconds,
          'detection',     'double_open'
        ),
        now()
      );
    EXCEPTION WHEN OTHERS THEN NULL; END;
  END LOOP;

  RETURN jsonb_build_object(
    'checked_at',             now(),
    'heartbeat_bursts_found', v_burst_count,
    'double_opens_found',     v_double_open_count,
    'total_detections',       v_burst_count + v_double_open_count,
    'status',                 CASE
                                WHEN (v_burst_count + v_double_open_count) > 0 THEN 'CRITICAL'
                                ELSE 'PASS'
                              END
  );
END;
$$;


ALTER FUNCTION zapp.fn_detect_swarm_task_duplication() OWNER TO postgres;

