-- Name: fn_dlq_stats(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_dlq_stats() RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$
DECLARE v jsonb;
BEGIN SELECT jsonb_build_object('total',(SELECT count(*) FROM evolution_webhook_dlq),'pending',(SELECT count(*) FROM evolution_webhook_dlq WHERE status='pending'),'retrying',(SELECT count(*) FROM evolution_webhook_dlq WHERE status='retrying'),'resolved',(SELECT count(*) FROM evolution_webhook_dlq WHERE status='resolved'),'failed',(SELECT count(*) FROM evolution_webhook_dlq WHERE status='failed')) INTO v; RETURN v; END; $$;


