--
-- Name: fn_download_wa_status_media(integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_download_wa_status_media(p_batch_size integer DEFAULT 10) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$
DECLARE
  v_supabase_url text;
  v_service_key text; v_health_secret text;
  v_row RECORD; v_queued int := 0; v_recovered int := 0;
BEGIN
  v_supabase_url := COALESCE(ops.fn_get_vault_secret('supabase_api_url'), 'https://supabase.atomicabr.com.br');
  SELECT decrypted_secret INTO v_service_key FROM vault.decrypted_secrets WHERE name='supabase_service_role_key' LIMIT 1;
  IF v_service_key IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'JWT nao encontrado no vault'); END IF;
  SELECT decrypted_secret INTO v_health_secret FROM vault.decrypted_secrets WHERE name='health_secret' LIMIT 1;
  IF v_health_secret IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'health_secret nao encontrado no vault'); END IF;
  UPDATE zapp.evolution_whatsapp_status SET media_download_status='pending', media_downloaded_at=NULL
  WHERE media_download_status='processing' AND (media_downloaded_at IS NULL OR media_downloaded_at < now() - interval '15 minutes');
  GET DIAGNOSTICS v_recovered = ROW_COUNT;
  FOR v_row IN
    SELECT id, message_id, participant_jid, media_url FROM zapp.evolution_whatsapp_status
    WHERE media_url LIKE '%mmg.whatsapp.net%' AND media_download_status='pending' AND (expires_at IS NULL OR expires_at > now())
    LIMIT p_batch_size
  LOOP
    UPDATE zapp.evolution_whatsapp_status SET media_download_status='processing', media_downloaded_at=now() WHERE id=v_row.id;
    PERFORM net.http_post(
      url := v_supabase_url || '/functions/v1/download-wa-status-media',
      body := jsonb_build_object('statusId', v_row.id, 'messageId', v_row.message_id, 'mediaUrl', v_row.media_url, 'participantJid', v_row.participant_jid),
      headers := jsonb_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer ' || v_service_key, 'x-internal-secret', v_health_secret),
      timeout_milliseconds := 60000
    );
    v_queued := v_queued + 1;
  END LOOP;
  RETURN jsonb_build_object('ok', true, 'queued', v_queued, 'recovered', v_recovered, 'executed_at', now());
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('ok', false, 'error', SQLERRM);
END; $$;


ALTER FUNCTION zapp.fn_download_wa_status_media(p_batch_size integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_download_wa_status_media(p_batch_size integer); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.fn_download_wa_status_media(p_batch_size integer) IS 'Baixa em lotes as mídias de status (stories) do WhatsApp que ainda não foram armazenadas localmente.';


--
-- Name: fn_drop_logflare_slot(); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.fn_drop_logflare_slot() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp, pg_temp'
    AS $$
DECLARE
  v_pid int;
  v_lag_mb numeric;
  v_slot_active boolean;
  v_attempts int := 0;
BEGIN
  -- Verificar lag
  SELECT pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn)/1048576, active
  INTO v_lag_mb, v_slot_active
  FROM pg_replication_slots 
  WHERE slot_name = 'cainophile_nwl2ry0m';
  
  IF v_lag_mb IS NULL THEN
    RETURN 'Slot já foi dropado';
  END IF;
  
  -- Encontrar PID
  SELECT pa.pid INTO v_pid
  FROM pg_stat_activity pa
  WHERE pa.query LIKE '%cainophile%' AND pa.pid != pg_backend_pid()
  LIMIT 1;
  
  -- Terminar backend (SECURITY DEFINER como postgres)
  IF v_pid IS NOT NULL THEN
    PERFORM pg_terminate_backend(v_pid);
    -- Polling: esperar slot ficar inativo
    LOOP
      PERFORM pg_sleep(0.5);
      v_attempts := v_attempts + 1;
      SELECT active INTO v_slot_active FROM pg_replication_slots WHERE slot_name = 'cainophile_nwl2ry0m';
      EXIT WHEN v_slot_active = false OR v_attempts > 10;
    END LOOP;
  END IF;
  
  -- Tentar dropar
  SELECT active INTO v_slot_active FROM pg_replication_slots WHERE slot_name = 'cainophile_nwl2ry0m';
  IF v_slot_active THEN
    RETURN format('FALHA: slot ainda ativo após %s tentativas (lag: %s MB)', v_attempts, round(v_lag_mb,1));
  END IF;
  
  PERFORM pg_drop_replication_slot('cainophile_nwl2ry0m');
  RETURN format('SUCESSO: Slot dropado. WAL liberado: %s MB', round(v_lag_mb, 1));
EXCEPTION
  WHEN OTHERS THEN
    RETURN format('ERRO: %s', SQLERRM);
END;
$$;


ALTER FUNCTION zapp.fn_drop_logflare_slot() OWNER TO supabase_admin;

--
-- Name: fn_edge_delete_evolution_credentials(uuid); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_edge_delete_evolution_credentials(p_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'permission denied' USING ERRCODE = '42501';
  END IF;

  DELETE FROM zapp.evolution_instance_credentials WHERE id = p_id;
  RETURN FOUND;
END;
$$;


ALTER FUNCTION zapp.fn_edge_delete_evolution_credentials(p_id uuid) OWNER TO postgres;

--
-- Name: fn_edge_get_evolution_credentials(text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_edge_get_evolution_credentials(p_instance text DEFAULT 'wpp2'::text) RETURNS TABLE(instance_name text, api_url text, api_key text, health_status text, last_health_check timestamp with time zone, is_active boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ DECLARE v_claims_role text := coalesce((NULLIF(current_setting('request.jwt.claims',true),''))::jsonb->>'role',''); BEGIN IF v_claims_role<>'service_role' AND session_user NOT IN ('postgres','supabase_admin') THEN RAISE EXCEPTION 'forbidden: service_role required' USING ERRCODE='42501'; END IF; RETURN QUERY SELECT c.instance_name::text, c.api_url::text, COALESCE(ds.decrypted_secret, c.api_key)::text AS api_key, c.health_status::text, c.last_health_check, c.is_active FROM zapp.evolution_instance_credentials c LEFT JOIN LATERAL (SELECT ds2.decrypted_secret FROM vault.decrypted_secrets ds2 WHERE ds2.id=c.vault_secret_id LIMIT 1) ds ON true WHERE c.instance_name=p_instance; END; $$;


ALTER FUNCTION zapp.fn_edge_get_evolution_credentials(p_instance text) OWNER TO postgres;

