-- Name: fn_edge_get_n8n_config(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_edge_get_n8n_config() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog'
    AS $$
DECLARE
  v_row zapp.n8n_config%ROWTYPE;
BEGIN
  SELECT * INTO v_row FROM zapp.n8n_config WHERE id = 1;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;
  RETURN jsonb_build_object(
    'id',         v_row.id,
    'base_url',   v_row.base_url,
    'enabled',    v_row.enabled,
    'created_at', v_row.created_at,
    'updated_at', v_row.updated_at
  );
END;
$$;


