--
-- Name: fn_edge_upsert_evolution_credentials(text, text, text, text, text, boolean); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_edge_upsert_evolution_credentials(p_instance_name text, p_api_url text, p_api_key text, p_display_name text, p_department text, p_is_active boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_id uuid;
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'permission denied' USING ERRCODE = '42501';
  END IF;

  INSERT INTO zapp.evolution_instance_credentials (
    instance_name, api_url, api_key, display_name, department, is_active, updated_at
  )
  VALUES (
    p_instance_name, p_api_url, p_api_key, p_display_name, p_department,
    COALESCE(p_is_active, true), now()
  )
  ON CONFLICT (instance_name) DO UPDATE SET
    api_url      = EXCLUDED.api_url,
    api_key      = EXCLUDED.api_key,
    display_name = EXCLUDED.display_name,
    department   = EXCLUDED.department,
    is_active    = EXCLUDED.is_active,
    updated_at   = now()
  RETURNING id INTO v_id;

  RETURN jsonb_build_object('id', v_id::text);
END;
$$;


ALTER FUNCTION zapp.fn_edge_upsert_evolution_credentials(p_instance_name text, p_api_url text, p_api_key text, p_display_name text, p_department text, p_is_active boolean) OWNER TO postgres;

--
-- Name: fn_edge_upsert_n8n_config(text, boolean); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_edge_upsert_n8n_config(p_base_url text, p_enabled boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog'
    AS $$
DECLARE
  v_row zapp.n8n_config%ROWTYPE;
BEGIN
  INSERT INTO zapp.n8n_config (id, base_url, enabled, updated_by)
  VALUES (1, p_base_url, p_enabled, auth.uid())
  ON CONFLICT (id) DO UPDATE
     SET base_url   = EXCLUDED.base_url,
         enabled    = EXCLUDED.enabled,
         updated_by = EXCLUDED.updated_by
  RETURNING * INTO v_row;
  RETURN jsonb_build_object(
    'id',         v_row.id,
    'base_url',   v_row.base_url,
    'enabled',    v_row.enabled,
    'created_at', v_row.created_at,
    'updated_at', v_row.updated_at
  );
END;
$$;


