--

COMMENT ON FUNCTION zapp.fn_enforce_direction() IS 'Garante a direção correta (inbound ou outbound) das mensagens conforme remetente e destinatário.';


--
-- Name: fn_enqueue_message_dispatch(uuid, text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_enqueue_message_dispatch(p_message_id uuid, p_instance text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp, pg_temp'
    AS $$
DECLARE
  v_msg      record;
  v_queue_id uuid;
  v_type     text;
  v_meta     jsonb;
BEGIN
  -- ------------------------------------------------------------------
  -- 1) Validação de entrada + existência da mensagem
  --    Retorna NULL (idempotente) quando não há nada a fazer — o caller
  --    (fn_retry_stuck_messages, cron 10/10min) trata NULL como skip.
  -- ------------------------------------------------------------------
  IF p_message_id IS NULL OR p_instance IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT em.id, em.contact_id, em.remote_jid, em.instance_name,
         em.message_type, em.content, em.media_url, em.media_mimetype,
         em.caption, em.payload, em.direction, em.from_me,
         em.audio_meme_id, em.sticker_id
    INTO v_msg
    FROM zapp.evolution_messages em
   WHERE em.id = p_message_id;

  IF v_msg.id IS NULL THEN
    RETURN NULL;  -- mensagem inexistente (ou apagada) → nada a re-enfileirar
  END IF;

  -- Guard defensivo: nunca re-enfileirar mensagem inbound
  IF v_msg.direction IS DISTINCT FROM 'outbound' OR v_msg.from_me IS NOT TRUE THEN
    RETURN NULL;
  END IF;

  -- ------------------------------------------------------------------
  -- 2) Guard anti-duplicata: já existe linha na fila para esta mensagem
  --    em pending/sending → não inserir de novo.
  -- ------------------------------------------------------------------
  IF EXISTS (
    SELECT 1
      FROM zapp.outbound_message_queue
     WHERE metadata ->> 'source_message_id' = p_message_id::text
       AND status IN ('pending', 'sending')
  ) THEN
    RETURN NULL;
  END IF;

  -- ------------------------------------------------------------------
  -- 3) Normalização de message_type para o CHECK da fila
  --    (evo guarda tipos da Evolution como 'extendedTextMessage'/'ptt';
  --     a fila só aceita os 9 tipos do CHECK + o dispatch só sabe enviar
  --     'text' via sendText e 'audio' via sendMedia(mediatype=audio, ptt)).
  -- ------------------------------------------------------------------
  v_type := CASE
    WHEN v_msg.message_type IN ('text', 'conversation', 'extendedTextMessage') THEN 'text'
    WHEN v_msg.message_type IN ('audio', 'ptt')                              THEN 'audio'
    WHEN v_msg.message_type IN ('image','video','document','sticker',
                                'location','contact','template')              THEN v_msg.message_type
    WHEN COALESCE(v_msg.media_url, '') <> ''                                  THEN 'document'
    ELSE 'text'
  END;

  -- ------------------------------------------------------------------
  -- 4) metadata: payload original preservado + marcadores de origem
  --    (fn_outbound_dispatch lê metadata->>'fileName' para mídia).
  --    payload || marcadores: operando da DIREITA vence no jsonb ||,
  --    garantindo que source_message_id/re_enqueued_at nunca sejam
  --    sobrescritos por chaves homônimas do payload.
  -- ------------------------------------------------------------------
  v_meta := CASE WHEN jsonb_typeof(v_msg.payload) = 'object' THEN v_msg.payload ELSE '{}'::jsonb END
         || jsonb_build_object(
              'source_message_id', p_message_id,
              're_enqueued_at',    now()
            );

  -- ------------------------------------------------------------------
  -- 5) INSERT na fila — formato canônico (mesmas colunas/valores de
  --    send_message_v2 e rpc_send_sticker: pending/0/3; sticker_id e
  --    audio_meme_id só se o registro de origem ainda existir — FKs).
  -- ------------------------------------------------------------------
  INSERT INTO zapp.outbound_message_queue (
    contact_id, remote_jid, instance_name, message_type, content,
    media_url, media_mime_type, caption, metadata, status,
    retry_count, max_retries, created_by, ptt,
    audio_meme_id, sticker_id
  ) VALUES (
    v_msg.contact_id,
    v_msg.remote_jid,
    p_instance,
    v_type,
    v_msg.content,
    v_msg.media_url,
    v_msg.media_mimetype,
    v_msg.caption,
    v_meta,
    'pending',
    0, 3,
    NULL,               -- cron context: sem auth.uid(); padrão rpc_send_sticker usa p_created_by
    TRUE,               -- ptt default canônico (dispatch faz coalesce(ptt,true))
    (SELECT id FROM zapp.audio_memes WHERE id = v_msg.audio_meme_id),  -- NULL se órfão (FK)
    (SELECT id FROM zapp.stickers   WHERE id = v_msg.sticker_id)       -- NULL se órfão (FK)
  )
  RETURNING id INTO v_queue_id;

  RETURN v_queue_id;
END;
$$;


ALTER FUNCTION zapp.fn_enqueue_message_dispatch(p_message_id uuid, p_instance text) OWNER TO postgres;

--
-- Name: fn_ensure_critical_crons_active(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_ensure_critical_crons_active() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'cron', 'pg_catalog'
    AS $$
DECLARE
  v_results jsonb := '[]'::jsonb;
  v_issues  int   := 0;
  v_rec     record;
  
  -- Crons críticos: (jobid, nome, max_silence_minutes)
  -- silence = max tempo sem execução bem-sucedida antes de alertar
  v_critical_crons int[][] := ARRAY[
    [328, 65],    -- lid-passive-accumulator (*/30min, alertar se > 65min)
    [429, 6],     -- pipeline-canary-keep-alive (*/3min, alertar se > 6min)  
    [466, 70],    -- lid-convergence-snapshot-hourly (0 * * * *, alertar se > 70min)
    [467, 370],   -- lid-normalizer-test-suite-6h (0 */6, alertar se > 370min)
    [468, 130]    -- lid-regression-suite-2h (0 */2, alertar se > 130min)
  ];
  v_pair int[];
BEGIN
  FOREACH v_pair SLICE 1 IN ARRAY v_critical_crons
  LOOP
    SELECT
      j.jobid,
      j.jobname,
      j.active,
      d.status AS last_status,
      d.start_time AS last_run,
      EXTRACT(EPOCH FROM (now() - d.start_time))/60 AS silence_min
    INTO v_rec
    FROM cron.job j
    LEFT JOIN (
      SELECT jobid, status, start_time,
             ROW_NUMBER() OVER (PARTITION BY jobid ORDER BY runid DESC) AS rn
      FROM cron.job_run_details
    ) d ON d.jobid = j.jobid AND d.rn = 1
    WHERE j.jobid = v_pair[1];

    IF v_rec.jobid IS NULL THEN
      -- Cron não encontrado → CRITICAL
      v_issues := v_issues + 1;
      v_results := v_results || jsonb_build_object(
        'jobid', v_pair[1], 'status', 'MISSING',
        'severity', 'critical', 'message', 'Cron job não encontrado'
      );
      -- Criar alerta
      INSERT INTO zapp.evolution_alerts (alert_type, severity, message, payload)
      VALUES (
        'cron_critical_missing', 'critical',
        format('Cron crítico jobid=%s não existe', v_pair[1]),
        jsonb_build_object('jobid', v_pair[1], 'check', 'fn_ensure_critical_crons_active')
      ) ON CONFLICT DO NOTHING;

    ELSIF NOT v_rec.active THEN
      -- Cron desativado → HIGH
      v_issues := v_issues + 1;
      v_results := v_results || jsonb_build_object(
        'jobid', v_rec.jobid, 'jobname', v_rec.jobname,
        'status', 'INACTIVE', 'severity', 'high',
        'message', 'Cron desativado'
      );
      INSERT INTO zapp.evolution_alerts (alert_type, severity, message, payload)
      VALUES (
        'cron_critical_inactive', 'high',
        format('Cron crítico "%s" (jobid=%s) está DESATIVADO', v_rec.jobname, v_rec.jobid),
        jsonb_build_object('jobid', v_rec.jobid, 'jobname', v_rec.jobname)
      ) ON CONFLICT DO NOTHING;

    ELSIF v_rec.last_run IS NULL OR v_rec.silence_min > v_pair[2] THEN
      -- Cron ativo mas não rodou a tempo → WARN
      v_issues := v_issues + 1;
      v_results := v_results || jsonb_build_object(
        'jobid', v_rec.jobid, 'jobname', v_rec.jobname,
        'status', 'STALE', 'severity', 'medium',
        'silence_min', round(v_rec.silence_min::numeric, 1),
        'max_silence_min', v_pair[2],
        'last_run', v_rec.last_run,
        'last_status', v_rec.last_status
      );

    ELSIF v_rec.last_status != 'succeeded' THEN
      -- Último run falhou → WARN
      v_results := v_results || jsonb_build_object(
        'jobid', v_rec.jobid, 'jobname', v_rec.jobname,
        'status', 'LAST_FAILED', 'severity', 'medium',
        'last_run', v_rec.last_run,
        'last_status', v_rec.last_status
      );

    ELSE
      -- OK
      v_results := v_results || jsonb_build_object(
        'jobid', v_rec.jobid, 'jobname', v_rec.jobname,
        'status', 'OK', 'severity', 'none',
        'last_run', v_rec.last_run,
        'silence_min', round(v_rec.silence_min::numeric, 1)
      );
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'status', CASE WHEN v_issues = 0 THEN 'ALL_OK' ELSE 'ISSUES_FOUND' END,
    'issues', v_issues,
    'crons_checked', array_length(v_critical_crons, 1),
    'results', v_results,
    'ts', now()
  );
END;
$$;


ALTER FUNCTION zapp.fn_ensure_critical_crons_active() OWNER TO postgres;

--
-- Name: FUNCTION fn_ensure_critical_crons_active(); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.fn_ensure_critical_crons_active() IS 'Monitor dos 5 crons LID críticos: passive-accumulator(328), canary(429), convergence(466), normalizer(467), regression(468). Cria alertas em evo.evolution_alerts se algum estiver inativo ou atrasado.';


--
-- Name: fn_escalate_critical_alerts(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_escalate_critical_alerts() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'vault'
    AS $$
DECLARE v_url text; v_alerts jsonb; v_count int; v_req bigint;
BEGIN
  SELECT count(*), jsonb_agg(jsonb_build_object('tipo',alert_type,'sev',severity,'msg',message,'quando',created_at) ORDER BY created_at DESC)
    INTO v_count, v_alerts
  FROM zapp.evolution_alerts
  WHERE coalesce(acknowledged,false)=false AND escalated_at IS NULL AND severity='critical';

  IF v_count = 0 THEN
    RETURN jsonb_build_object('escalated',0,'reason','sem alertas criticos novos');
  END IF;

  BEGIN
    SELECT decrypted_secret INTO v_url FROM vault.decrypted_secrets WHERE name='alerts_webhook_url';
  EXCEPTION WHEN OTHERS THEN v_url := NULL; END;

  IF v_url IS NULL OR v_url = '' THEN
    UPDATE zapp.evolution_alerts SET escalated_at=now()
      WHERE coalesce(acknowledged,false)=false AND escalated_at IS NULL AND severity='critical';
    RETURN jsonb_build_object('escalated',v_count,'delivered',false,'reason','configure vault.alerts_webhook_url para entregar');
  END IF;

  v_req := net.http_post(
    url := v_url,
    headers := jsonb_build_object('Content-Type','application/json'),
    body := jsonb_build_object('source','supabase-evolution-watchdog','severity','critical','count',v_count,'alerts',v_alerts,'at',now()),
    timeout_milliseconds := 8000);

  UPDATE zapp.evolution_alerts SET escalated_at=now()
    WHERE coalesce(acknowledged,false)=false AND escalated_at IS NULL AND severity='critical';

  RETURN jsonb_build_object('escalated',v_count,'delivered',true,'net_request_id',v_req);
END; $$;


ALTER FUNCTION zapp.fn_escalate_critical_alerts() OWNER TO postgres;

