--
-- Name: fn_evo_outbox_claim(integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_evo_outbox_claim(p_limit integer DEFAULT 20) RETURNS TABLE(id bigint, notification_id uuid, channel text, payload jsonb, status text, created_at timestamp with time zone, attempt_count integer, last_error text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'public'
    AS $$
DECLARE v_limit int;
BEGIN
  v_limit := COALESCE(p_limit, 20);
  IF v_limit <= 0 THEN v_limit := 20; END IF;

  -- Reset sending → pending se travado há mais de 30min
  UPDATE zapp.evolution_notification_outbox o
  SET status = 'pending'
  WHERE o.status = 'sending'
    AND o.last_attempt_at < now() - interval '30 minutes';

  RETURN QUERY
  UPDATE zapp.evolution_notification_outbox o
  SET status = 'sending',
      attempt_count = o.attempt_count + 1,
      last_attempt_at = now()
  WHERE o.id IN (
    SELECT o2.id FROM zapp.evolution_notification_outbox o2
    WHERE o2.status = 'pending'
    ORDER BY o2.id
    LIMIT v_limit
    FOR UPDATE SKIP LOCKED
  )
  RETURNING o.id, o.notification_id, o.channel, o.payload,
            o.status, o.created_at, o.attempt_count, o.last_error;
END;
$$;


ALTER FUNCTION zapp.fn_evo_outbox_claim(p_limit integer) OWNER TO postgres;

--
-- Name: fn_evo_outbox_mark(bigint, text, text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_evo_outbox_mark(p_id bigint, p_status text, p_last_error text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'public'
    AS $$
BEGIN
  IF p_status NOT IN ('sent', 'failed') THEN RETURN false; END IF;
  UPDATE zapp.evolution_notification_outbox
  SET status = p_status, last_error = left(COALESCE(p_last_error, ''), 2000)
  WHERE id = p_id AND status = 'sending';
  RETURN FOUND;
END;
$$;


