--
-- Name: fn_evolution_webhook_events_retention(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_evolution_webhook_events_retention() RETURNS TABLE(bucket text, deleted_rows bigint)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE v_heavy bigint:=0; v_noise bigint:=0; v_normal bigint:=0; v_batch int; v_batch_size int:=10000;
BEGIN
  SET LOCAL statement_timeout='30min';
  LOOP WITH v AS (SELECT id FROM evolution_webhook_events WHERE event_type IN ('MESSAGES_UPSERT','messages.upsert') AND created_at<now()-interval '7 days' LIMIT v_batch_size) DELETE FROM evolution_webhook_events e USING v WHERE e.id=v.id; GET DIAGNOSTICS v_batch=ROW_COUNT; v_heavy:=v_heavy+v_batch; EXIT WHEN v_batch=0; PERFORM pg_sleep(0.1); END LOOP;
  LOOP WITH v AS (SELECT id FROM evolution_webhook_events WHERE event_type IN ('CHATS_UPDATE','chats.update','CONTACTS_UPDATE','contacts.update') AND created_at<now()-interval '3 days' LIMIT v_batch_size) DELETE FROM evolution_webhook_events e USING v WHERE e.id=v.id; GET DIAGNOSTICS v_batch=ROW_COUNT; v_noise:=v_noise+v_batch; EXIT WHEN v_batch=0; PERFORM pg_sleep(0.1); END LOOP;
  LOOP WITH v AS (SELECT id FROM evolution_webhook_events WHERE created_at<now()-interval '30 days' LIMIT v_batch_size) DELETE FROM evolution_webhook_events e USING v WHERE e.id=v.id; GET DIAGNOSTICS v_batch=ROW_COUNT; v_normal:=v_normal+v_batch; EXIT WHEN v_batch=0; PERFORM pg_sleep(0.1); END LOOP;
  RETURN QUERY SELECT 'heavy_7d'::text,v_heavy UNION ALL SELECT 'noise_3d',v_noise UNION ALL SELECT 'normal_30d',v_normal;
END; $$;


ALTER FUNCTION zapp.fn_evolution_webhook_events_retention() OWNER TO postgres;

--
-- Name: fn_executive_dashboard(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_executive_dashboard() RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$
DECLARE v jsonb;
BEGIN SELECT jsonb_build_object('kpis',fn_dashboard_data(),'pipeline',fn_pipeline_analytics(),'sentiment',(SELECT jsonb_build_object('positive',(SELECT count(*) FROM evolution_sentiment_analysis WHERE sentiment='positive' AND analyzed_at>=now()-interval '7 days'),'negative',(SELECT count(*) FROM evolution_sentiment_analysis WHERE sentiment='negative' AND analyzed_at>=now()-interval '7 days')))) INTO v; RETURN v; END; $$;


ALTER FUNCTION zapp.fn_executive_dashboard() OWNER TO postgres;

--
-- Name: fn_executive_summary(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_executive_summary() RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$ BEGIN RETURN fn_executive_dashboard(); END; $$;


ALTER FUNCTION zapp.fn_executive_summary() OWNER TO postgres;

--
-- Name: fn_expire_whatsapp_media_urls(integer, integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_expire_whatsapp_media_urls(p_days_old integer DEFAULT 7, p_batch_limit integer DEFAULT 500) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'zapp', 'pg_catalog'
    AS $$ DECLARE v_updated integer; v_still_pending integer; BEGIN WITH to_expire AS (SELECT id FROM zapp.evolution_messages_wpp2 WHERE (media_url LIKE '%mmg.whatsapp.net%' OR media_url LIKE '%cdn.whatsapp.net%' OR media_url LIKE '%mmg.whatsapp.com%' OR media_url LIKE '%media.whatsapp.net%') AND (media_status IS NULL OR media_status NOT IN ('expired','ready')) AND created_at < NOW()-(p_days_old||' days')::interval LIMIT p_batch_limit) UPDATE zapp.evolution_messages_wpp2 em SET media_status='expired', updated_at=NOW() FROM to_expire t WHERE em.id=t.id; GET DIAGNOSTICS v_updated=ROW_COUNT; SELECT COUNT(*) INTO v_still_pending FROM zapp.evolution_messages_wpp2 WHERE (media_url LIKE '%mmg.whatsapp.net%' OR media_url LIKE '%cdn.whatsapp.net%' OR media_url LIKE '%mmg.whatsapp.com%') AND (media_status IS NULL OR media_status NOT IN ('expired','ready')) AND created_at < NOW()-(p_days_old||' days')::interval; RETURN jsonb_build_object('updated',v_updated,'still_pending',v_still_pending,'days_threshold',p_days_old,'executed_at',NOW()); END; $$;


ALTER FUNCTION zapp.fn_expire_whatsapp_media_urls(p_days_old integer, p_batch_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_expire_whatsapp_media_urls(p_days_old integer, p_batch_limit integer); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.fn_expire_whatsapp_media_urls(p_days_old integer, p_batch_limit integer) IS 'Expira URLs de mídia do WhatsApp com mais de N dias, em lotes limitados, forçando re-download quando necessário.';


--
-- Name: fn_export_messages(text, text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_export_messages(p_jid text, p_instance text DEFAULT 'wpp2'::text, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(data timestamp with time zone, remetente text, tipo text, conteudo text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
  SELECT created_at, CASE WHEN from_me THEN 'Eu' ELSE COALESCE(push_name,'Cliente') END, message_type, COALESCE(content,'[midia]') FROM evolution_messages WHERE remote_jid=p_jid AND instance_name=p_instance AND (p_from IS NULL OR created_at>=p_from) AND (p_to IS NULL OR created_at<=p_to) ORDER BY created_at;
$$;


ALTER FUNCTION zapp.fn_export_messages(p_jid text, p_instance text, p_from timestamp with time zone, p_to timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_extract_phone_from_jid(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_extract_phone_from_jid() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog'
    AS $_$ DECLARE v_local text; BEGIN
  IF NEW.remote_jid IS NOT NULL AND (NEW.remote_jid LIKE '%@g.us' OR NEW.remote_jid LIKE '%@broadcast' OR NEW.remote_jid LIKE '%@newsletter') THEN
    NEW.phone_number := NULL;
  ELSIF NEW.remote_jid IS NOT NULL AND NEW.remote_jid LIKE '%@lid' THEN
    IF NEW.phone_number ~ '^[0-9]{10,14}$' AND NEW.phone_number <> regexp_replace(NEW.remote_jid, '@.+$', '') THEN
      NULL;
    ELSE
      NEW.phone_number := NULL;
    END IF;
  ELSIF NEW.remote_jid IS NOT NULL AND NEW.phone_number IS NULL THEN
    v_local := LEFT(split_part(NEW.remote_jid, '@', 1), 20);
    IF length(v_local) >= 14 AND v_local ~ '^[0-9]{14,}$' THEN NULL;
    ELSE NEW.phone_number := v_local;
    END IF;
  END IF;
  RETURN NEW;
END $_$;


ALTER FUNCTION zapp.fn_extract_phone_from_jid() OWNER TO postgres;

--
-- Name: fn_f008_col_comment(oid, text, text, boolean, text, boolean); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_f008_col_comment(p_rel oid, p_att text, p_typ text, p_notnull boolean, p_fk text, p_pk boolean) RETURNS text
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v text;
  v_check text;
  v_base text;
BEGIN
  SELECT ' Valores: ' || regexp_replace(substring(pg_get_constraintdef(cc.oid) from 'ARRAY\[(.+?)\]'), '(::character varying)|(::text)|''', '', 'g') || '.'
    INTO v_check
  FROM pg_constraint cc
  WHERE cc.conrelid = p_rel AND cc.contype = 'c'
    AND (pg_get_constraintdef(cc.oid) LIKE '%(' || p_att || ')::text = ANY%'
      OR pg_get_constraintdef(cc.oid) LIKE '%' || p_att || ' = ANY%')
  LIMIT 1;
  v_check := coalesce(v_check, '');

  v := CASE
    WHEN p_pk AND p_att IN ('id','key_id') THEN format('PK (%s).', p_typ)
    WHEN p_fk <> '' THEN format('FK -> %s.%s', p_fk, CASE WHEN p_notnull THEN ' Obrigatoria.' ELSE '' END)
    WHEN p_att IN ('created_at','criado_em','inserted_at') THEN 'Timestamp de criacao do registro.'
    WHEN p_att IN ('updated_at','atualizado_em') THEN 'Timestamp da ultima atualizacao do registro.'
    WHEN p_att = 'deleted_at' THEN 'Soft delete: quando preenchido, o registro esta excluido logicamente.'
    WHEN p_att = 'resolved_at' THEN 'Quando o item foi resolvido (NULL = em aberto).'
    WHEN p_att IN ('expires_at','expire_at','token_expires_at') THEN 'Timestamp de expiracao/validade.'
    WHEN p_att = 'processed_at' THEN 'Quando o item foi processado pelo pipeline.'
    WHEN p_att = 'checked_at' THEN 'Timestamp da ultima verificacao.'
    WHEN p_att = 'connected_at' THEN 'Quando a conexao foi estabelecida.'
    WHEN p_att IN ('started_at','iniciado_em') THEN 'Timestamp de inicio da execucao.'
    WHEN p_att IN ('finished_at','completed_at','ended_at','concluido_em') THEN 'Timestamp de conclusao.'
    WHEN p_att = 'status' THEN 'Status do registro.' || v_check
    WHEN p_att IN ('name','nome') THEN 'Nome de exibicao.'
    WHEN p_att IN ('title','titulo') THEN 'Titulo de exibicao.'
    WHEN p_att IN ('description','descricao') THEN 'Descricao livre.'
    WHEN p_att = 'message' THEN 'Texto da mensagem.'
    WHEN p_att = 'content' THEN 'Conteudo textual.'
    WHEN p_att = 'metadata' THEN 'JSONB de metadados adicionais (estrutura livre por modulo).'
    WHEN p_att = 'payload' THEN 'JSONB com o payload bruto do evento/requisicao.'
    WHEN p_att IN ('details','detail') THEN 'Detalhes adicionais do evento.'
    WHEN p_att = 'config' THEN 'JSONB de configuracao do modulo.'
    WHEN p_att = 'settings' THEN 'JSONB de configuracoes.'
    WHEN p_att IN ('is_active','ativo') THEN 'Flag: registro ativo?'
    WHEN p_att = 'enabled' THEN 'Flag: recurso habilitado?'
    WHEN p_att = 'is_read' THEN 'Flag: item lido pelo usuario?'
    WHEN p_att = 'email' THEN 'Endereco de e-mail.'
    WHEN p_att IN ('phone','telefone','phone_number') THEN 'Numero de telefone.'
    WHEN p_att = 'remote_jid' THEN 'JID WhatsApp (ex.: 5511...@s.whatsapp.net; @g.us para grupos).'
    WHEN p_att = 'instance_name' THEN 'Instancia Evolution API dona do registro (ex.: wpp2).'
    WHEN p_att = 'message_id' THEN 'ID da mensagem WhatsApp (WAMID) na Evolution.'
    WHEN p_att = 'user_id' THEN 'ID do usuario (auth.users).'
    WHEN p_att = 'profile_id' THEN 'ID do perfil (zapp.profiles).'
    WHEN p_att = 'workspace_id' THEN 'ID do workspace/tenant (zapp.workspaces).'
    WHEN p_att = 'contact_id' THEN 'ID do contato relacionado.'
    WHEN p_att = 'conversation_id' THEN 'ID da conversa relacionada.'
    WHEN p_att = 'ip_address' THEN 'Endereco IP de origem.'
    WHEN p_att = 'user_agent' THEN 'User-Agent do cliente HTTP.'
    WHEN p_att = 'error_message' THEN 'Mensagem de erro (NULL = sem erro).'
    WHEN p_att IN ('error_code','error_type','error_msg') THEN 'Codigo/tipo do erro.'
    WHEN p_att IN ('http_status','http_code','status_code') THEN 'Codigo de status HTTP.'
    WHEN p_att = 'duration_ms' THEN 'Duracao em milissegundos.'
    WHEN p_att = 'duration_seconds' THEN 'Duracao em segundos.'
    WHEN p_att IN ('retry_count','attempts','tentativas') THEN 'Numero de tentativas realizadas.'
    WHEN p_att = 'attempt_number' THEN 'Numero da tentativa atual.'
    WHEN p_att = 'max_retries' THEN 'Limite maximo de tentativas.'
    WHEN p_att IN ('table_name','tbl_name') THEN 'Nome da tabela referenciada.'
    WHEN p_att = 'event_type' THEN 'Tipo do evento.' || v_check
    WHEN p_att = 'alert_type' THEN 'Tipo do alerta.' || v_check
    WHEN p_att = 'severity' THEN 'Severidade.' || v_check
    WHEN p_att IN ('category','categoria') THEN 'Categoria.' || v_check
    WHEN p_att IN ('type','tipo','kind') THEN 'Tipo do registro.' || v_check
