    WHEN p_att IN ('delta_abs','delta_pct') THEN 'Delta medido (absoluto/percentual).'
    WHEN p_att IN ('inactivity_timeout','cooldown_seconds','reconnect_interval_seconds') THEN 'Intervalo/timeout em segundos.'
    WHEN p_att IN ('archive_days') THEN 'Dias ate arquivamento (retencao).'
    WHEN p_att IN ('src_contacts','mir_contacts') THEN 'Contador de contatos (origem/espelho) na migracao.'
    WHEN p_att IN ('postgres_cdc_default','broadcast_adapter') THEN 'Configuracao interna do servico Supabase Realtime.'
    WHEN p_att IN ('alerts','breakdown','full_result','recent_errors','detected_signals','inbox_filters','n8n_workflows','bitrix_integration','permissions') THEN format('JSONB: %s.', replace(p_att,'_',' '))
    WHEN p_att LIKE 'bitrix%' OR p_att LIKE '%bitrix%' THEN format('Integracao Bitrix24: %s.', replace(p_att,'_',' '))
    WHEN p_att LIKE 'tts_%' THEN format('Configuracao TTS (texto-para-voz): %s.', replace(substr(p_att,5),'_',' '))
    WHEN p_att LIKE '%_sound_type' THEN format('Som de notificacao para "%s".', replace(left(p_att, length(p_att)-11),'_',' '))
    WHEN p_att LIKE 'sla_%' THEN format('Parametro de SLA: %s.', replace(substr(p_att,5),'_',' ')) || v_check
    WHEN p_att LIKE 'probe_%' THEN format('Dado do probe de monitoramento: %s.', replace(substr(p_att,7),'_',' '))
    WHEN p_att LIKE 'test_%' THEN format('Identificacao do teste: %s.', replace(substr(p_att,6),'_',' '))
    WHEN p_att LIKE 'max_%' THEN format('Limite maximo: %s.', replace(substr(p_att,5),'_',' '))
    WHEN p_att LIKE 'min_%' THEN format('Limite minimo: %s.', replace(substr(p_att,5),'_',' '))
    WHEN p_att LIKE '%_threshold%' THEN format('Limiar configurado: %s.', replace(p_att,'_',' '))
    WHEN p_att = 'threshold' THEN 'Limiar configurado.'
    WHEN p_att LIKE 'is\_%' THEN format('Flag booleana: %s?', replace(substr(p_att,4), '_', ' '))
    WHEN p_att LIKE 'has\_%' THEN format('Flag booleana: possui %s?', replace(substr(p_att,5), '_', ' '))
    WHEN p_att LIKE '%\_url' THEN format('URL de %s.', replace(left(p_att, length(p_att)-4), '_', ' '))
    WHEN p_att LIKE '%\_ms' THEN format('%s em milissegundos.', initcap(replace(left(p_att, length(p_att)-3), '_', ' ')))
    WHEN p_att LIKE '%\_seconds' THEN format('%s em segundos.', initcap(replace(left(p_att, length(p_att)-8), '_', ' ')))
    WHEN p_att LIKE '%\_minutes' THEN format('%s em minutos.', initcap(replace(left(p_att, length(p_att)-8), '_', ' ')))
    WHEN p_att LIKE '%\_hours' THEN format('%s em horas.', initcap(replace(left(p_att, length(p_att)-6), '_', ' ')))
    WHEN p_att LIKE '%\_days' THEN format('%s em dias.', initcap(replace(left(p_att, length(p_att)-5), '_', ' ')))
    WHEN p_att LIKE '%\_count' THEN format('Contador de %s.', replace(left(p_att, length(p_att)-6), '_', ' '))
    WHEN p_att LIKE '%\_at' AND p_typ LIKE 'timestamp%' THEN format('Timestamp do evento "%s".', replace(left(p_att, length(p_att)-3), '_', ' '))
    WHEN p_att LIKE '%\_em' AND p_typ LIKE 'timestamp%' THEN format('Timestamp do evento "%s".', replace(left(p_att, length(p_att)-3), '_', ' '))
    WHEN p_att LIKE '%\_date' THEN format('Data de %s.', replace(left(p_att, length(p_att)-5), '_', ' '))
    WHEN p_att LIKE '%\_jid' THEN format('JID WhatsApp (%s).', replace(left(p_att, length(p_att)-4), '_', ' '))
    WHEN p_att LIKE '%\_name' THEN format('Nome de %s.', replace(left(p_att, length(p_att)-5), '_', ' '))
    WHEN p_att LIKE '%\_hash' THEN format('Hash de %s.', replace(left(p_att, length(p_att)-5), '_', ' '))
    WHEN p_att LIKE '%\_key' THEN format('Chave: %s.', replace(left(p_att, length(p_att)-4), '_', ' '))
    WHEN p_att LIKE '%\_type' THEN format('Tipo de %s.', replace(left(p_att, length(p_att)-5), '_', ' ')) || v_check
    WHEN p_att LIKE '%\_status' THEN format('Status de %s.', replace(left(p_att, length(p_att)-7), '_', ' ')) || v_check
    WHEN p_att LIKE '%\_reason' THEN format('Motivo de %s.', replace(left(p_att, length(p_att)-7), '_', ' '))
    WHEN p_att LIKE '%\_notes' THEN format('Anotacoes de %s.', replace(left(p_att, length(p_att)-6), '_', ' '))
    WHEN p_att LIKE '%\_message' THEN format('Texto: %s.', replace(p_att, '_', ' '))
    WHEN p_att LIKE '%\_by' THEN format('Autor da acao "%s".', replace(left(p_att, length(p_att)-3), '_', ' '))
    WHEN p_att LIKE '%\_ids' AND p_typ LIKE '%[]' THEN format('Lista de IDs: %s.', replace(left(p_att, length(p_att)-4), '_', ' '))
    WHEN p_att LIKE '%\_id' AND p_fk = '' THEN format('ID de %s relacionado.', replace(left(p_att, length(p_att)-3), '_', ' '))
    WHEN p_typ = 'boolean' THEN format('Flag booleana "%s".', replace(p_att, '_', ' '))
    WHEN p_typ = 'inet' THEN 'Endereco IP.'
    WHEN p_typ = 'jsonb' THEN format('JSONB: %s.', replace(p_att, '_', ' '))
    ELSE NULL
  END;
  RETURN v;
END;
$$;


ALTER FUNCTION zapp.fn_f008_col_comment(p_rel oid, p_att text, p_typ text, p_notnull boolean, p_fk text, p_pk boolean) OWNER TO postgres;

--
-- Name: fn_feed_401_disconnect_alerts(integer, integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_feed_401_disconnect_alerts(p_minutes integer DEFAULT 15, p_threshold integer DEFAULT 3) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$
DECLARE
  v_count       bigint := 0;
  v_last_event  timestamptz;
  v_events      jsonb;
  v_open_alert  boolean;
  v_alerted     boolean := false;
  v_since       timestamptz;
BEGIN
  v_since := now() - make_interval(mins => p_minutes);

  SELECT count(*), max(created_at)
  INTO v_count, v_last_event
  FROM public.evo_connection_history
  WHERE instance_name = 'wpp2'
    AND state IN ('logged_out', 'disconnected')
    AND created_at >= v_since;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'at', created_at, 'state', state, 'previous_state', previous_state,
           'source', COALESCE(metadata->>'source', 'unknown')
         ) ORDER BY created_at DESC), '[]'::jsonb)
  INTO v_events
  FROM (
    SELECT created_at, state, previous_state, metadata
    FROM public.evo_connection_history
    WHERE instance_name = 'wpp2'
      AND state IN ('logged_out', 'disconnected')
      AND created_at >= v_since
    ORDER BY created_at DESC
    LIMIT 10
  ) e;

  SELECT EXISTS(
    SELECT 1 FROM zapp.webhook_health_alerts
    WHERE alert_type = 'sentry_401_feed' AND resolved_at IS NULL
      AND created_at > now() - interval '30 minutes'
  ) INTO v_open_alert;

  IF v_count >= p_threshold AND NOT v_open_alert THEN
    INSERT INTO zapp.webhook_health_alerts
      (alert_type, severity, title, details, created_at)
    VALUES (
      'sentry_401_feed',
      'warning',
      format('E3-10: 401/desconexão — %s evento(s) em %smin (fonte: evolution_connection_history)', v_count, p_minutes),
      jsonb_build_object(
        'generated_at', now(), 'window_minutes', p_minutes, 'since', v_since,
        'event_count', v_count, 'events', v_events,
        'last_event_at', v_last_event,
        'source_table', 'public.evo_connection_history',
        'threshold', p_threshold,
        'auto_reconnect', false,
        'action_required', 'QR_SCAN',
        'runbook', 'logout -> connect -> qrcode (skill evolution-runtime-diagnostics; AG-EX-05)',
        'decisao', 'auto-reconnect NAO implementado: enforcement do WhatsApp (Baileys 7.0.0-rc.9, issue #2248) -> restart/redeploy nao resolve; acao = alerta + re-pareamento manual (QR scan)'
      ),
      now()
    );
    INSERT INTO zapp.evolution_alerts (alert_type, severity, title, message, payload)
    VALUES (
      'wpp2_disconnect_burst',
      'critical',
      format('wpp2: %s desconexões em %s min', v_count, p_minutes),
      format('Instancia wpp2 registrou %s eventos de desconexao em %s min (threshold %s) na fonte evolution_connection_history. Sem auto-reconnect (enforcement #2248). Acao: verificar QR/re-pareamento via manager.',
        v_count, p_minutes, p_threshold),
      jsonb_build_object(
        'instance', 'wpp2', 'window_minutes', p_minutes, 'threshold', p_threshold,
        'event_count', v_count, 'source_table', 'public.evo_connection_history',
        'auto_reconnect', false, 'action_required', 'QR_SCAN'
      )
    );
    v_alerted := true;
  END IF;

  RETURN jsonb_build_object(
    'ok', true, 'checked_at', now(),
    'window_minutes', p_minutes, 'threshold', p_threshold,
    'event_count', v_count, 'alerted', v_alerted,
    'last_event_at', v_last_event, 'auto_reconnect', false
  );
END $$;


ALTER FUNCTION zapp.fn_feed_401_disconnect_alerts(p_minutes integer, p_threshold integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_feed_401_disconnect_alerts(p_minutes integer, p_threshold integer); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.fn_feed_401_disconnect_alerts(p_minutes integer, p_threshold integer) IS 'Alimenta alertas de desconexão por 401 quando a taxa de erros supera o threshold na janela de minutos informada.';


--
-- Name: fn_filter_canary_messages(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_filter_canary_messages() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'pg_catalog'
    AS $_$
BEGIN
  -- [ORIGINAL] Padrão exato: "wd-canary " seguido de 1+ dígitos (epoch unix do watchdog-canary v1)
  IF NEW.content ~ '^wd-canary [0-9]+$' THEN
    BEGIN
      INSERT INTO zapp.evolution_audit_log (
        action, entity_type, entity_id, new_values, metadata, performed_by, created_at
      ) VALUES (
        'canary_filtered', 'evolution_messages_wpp2', gen_random_uuid(),
        jsonb_build_object('message_id', NEW.message_id, 'content', NEW.content,
                           'from_me', NEW.from_me, 'remote_jid', NEW.remote_jid),
        jsonb_build_object('filtered_at', now(), 'push_name', NEW.push_name),
        'watchdog-canary', now()
      );
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    RETURN NULL;
  END IF;

  -- [100PLAN A4] pg-cron canary: @localhost JID = mensagem sintética de health check
  -- Redireciona para evo.pipeline_canary_log em vez de contaminar evolution_messages_wpp2
  IF NEW.remote_jid LIKE '%@localhost' THEN
    BEGIN
      INSERT INTO evo.pipeline_canary_log (message_id, remote_jid, content, created_at)
      VALUES (
        COALESCE(NEW.message_id, 'unknown-' || extract(epoch from now())::text),
        NEW.remote_jid,
        left(COALESCE(NEW.content, ''), 500),
        COALESCE(NEW.created_at, now())
      );
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    RETURN NULL;  -- bloqueia INSERT na tabela de produção
  END IF;

  RETURN NEW;
END;
$_$;


ALTER FUNCTION zapp.fn_filter_canary_messages() OWNER TO postgres;

--
-- Name: FUNCTION fn_filter_canary_messages(); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.fn_filter_canary_messages() IS 'Filtra mensagens canary (teste) para que não poluam métricas, relatórios ou filas de produção.';


--
-- Name: fn_flag_poison_messages(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_flag_poison_messages() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog'
    AS $$
DECLARE
  v_flagged    bigint := 0;
  v_total_dlq  bigint;
  v_result     jsonb;
BEGIN
  UPDATE zapp.evolution_webhook_dlq
  SET status = 'poison'
  WHERE status = 'pending'
    AND retry_count >= max_retries;

  GET DIAGNOSTICS v_flagged = ROW_COUNT;

  SELECT COUNT(*) INTO v_total_dlq FROM zapp.evolution_webhook_dlq;

  v_result := jsonb_build_object(
    'checked_at',      now(),
    'newly_flagged',   v_flagged,
    'total_dlq_rows',  v_total_dlq
  );

  IF v_flagged > 0 THEN
    BEGIN
      INSERT INTO zapp.webhook_health_alerts
        (alert_type, severity, title, details, created_at)
      VALUES (
        'dlq_poison_messages',
        'high',
        format('E8-03: %s poison message(s) flagged in evolution_webhook_dlq — consumer restart loop prevented', v_flagged),
        v_result,
        now()
      );
    EXCEPTION WHEN OTHERS THEN NULL; END;
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION zapp.fn_flag_poison_messages() OWNER TO postgres;

--
-- Name: FUNCTION fn_flag_poison_messages(); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.fn_flag_poison_messages() IS 'Marca mensagens poison (impossíveis de processar) para quarentena, evitando loops de reprocessamento.';


--
-- Name: fn_force_autovacuum(text, text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_force_autovacuum(p_schema text, p_table text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_relid oid; v_dead int; v_live int; v_relkind char;
BEGIN
  IF p_schema NOT IN ('public','zapp','evo') THEN
    RETURN jsonb_build_object('error','schema_not_allowed','schema',p_schema);
  END IF;
  SELECT c.oid, c.relkind INTO v_relid, v_relkind
  FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
  WHERE n.nspname=p_schema AND c.relname=p_table;
  IF v_relid IS NULL THEN
    RETURN jsonb_build_object('error','table_not_found','table',p_schema||'.'||p_table);
  END IF;
  IF v_relkind != 'r' THEN
    RETURN jsonb_build_object('error','not_a_table','relkind',v_relkind,'table',p_schema||'.'||p_table);
  END IF;
  SELECT n_dead_tup, n_live_tup INTO v_dead, v_live FROM pg_stat_user_tables WHERE relid=v_relid;
  EXECUTE 'ANALYZE '||p_schema||'.'||quote_ident(p_table);
  IF v_dead > 0 THEN
    EXECUTE format('ALTER TABLE %I.%I SET (autovacuum_vacuum_scale_factor=0.0001, autovacuum_vacuum_threshold=0, autovacuum_vacuum_cost_delay=2)', p_schema, p_table);
    PERFORM cron.schedule(
      'restore_av_'||p_schema||'_'||p_table,
      to_char(now()+INTERVAL '2 minutes','MI HH24')||' * * *',
      format('ALTER TABLE %I.%I RESET (autovacuum_vacuum_scale_factor, autovacuum_vacuum_threshold, autovacuum_vacuum_cost_delay); SELECT cron.unschedule(''restore_av_%s_%s'');', p_schema, p_table, p_schema, p_table)
    );
  END IF;
  RETURN jsonb_build_object(
    'analyzed',true,'table',p_schema||'.'||p_table,
    'dead_tuples_before',v_dead,'live_tuples',v_live,
    'autovacuum_triggered',v_dead>0,'restore_scheduled',v_dead>0,
    'note',CASE WHEN v_dead>0 THEN 'ANALYZE + scale_factor=0.0001 + threshold=0. Restaurado em 2min.' ELSE 'ANALYZE feito. Sem dead tuples.' END
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('error',SQLERRM,'table',p_schema||'.'||p_table);
END;
$$;


ALTER FUNCTION zapp.fn_force_autovacuum(p_schema text, p_table text) OWNER TO postgres;

