CREATE FUNCTION zapp.fn_gc_audit(p_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE v_audit integer; v_cutoff timestamptz:=now()-(p_days||' days')::interval;
BEGIN DELETE FROM evolution_audit_log WHERE created_at<v_cutoff; GET DIAGNOSTICS v_audit=ROW_COUNT;
  RETURN jsonb_build_object('success',true,'cutoff',v_cutoff,'deleted_audit',v_audit);
END; $$;


