--
-- Name: fn_gc_webhook_events(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_gc_webhook_events() RETURNS TABLE(removidos integer, arquivados integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE v_removidos INT; v_arquivados INT;
BEGIN
  WITH deleted AS (DELETE FROM evolution_webhook_events WHERE event_type IN ('CONNECTION_UPDATE','PRESENCE_UPDATE','CHATS_UPDATE','MESSAGES_UPDATE') AND created_at < now() - interval '7 days' RETURNING 1) SELECT COUNT(*) INTO v_removidos FROM deleted;
  WITH deleted AS (DELETE FROM evolution_webhook_events WHERE event_type IN ('MESSAGES_UPSERT','SEND_MESSAGE') AND created_at < now() - interval '90 days' RETURNING 1) SELECT COUNT(*) INTO v_arquivados FROM deleted;
  RETURN QUERY SELECT v_removidos, v_arquivados;
END;
$$;


