-- Name: fn_get_contact_summary(uuid); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_get_contact_summary(p_contact_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE v jsonb;
BEGIN
  SELECT jsonb_build_object('contact',row_to_json(c),'total_messages',c.total_messages,'last_message',c.last_message_at,
    'deals',(SELECT jsonb_agg(row_to_json(d)) FROM evolution_deals d WHERE d.contact_id=c.id),
    'conversations',(SELECT count(*) FROM evolution_conversations cv WHERE cv.contact_id=c.id),
    'instances',(SELECT json_agg(DISTINCT m.instance_name) FROM evolution_messages m WHERE m.contact_id=c.id)
  ) INTO v FROM evolution_contacts c WHERE c.id=p_contact_id;
  RETURN v;
END; $$;


