-- Name: fn_get_deleted_messages(text, text, integer); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.fn_get_deleted_messages(p_instance text, p_jid text DEFAULT NULL::text, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$ SELECT jsonb_build_object('ok', true, 'total', count(*), 'messages', COALESCE(jsonb_agg(jsonb_build_object('message_id', message_id, 'remote_jid', remote_jid, 'content', content, 'from_me', from_me, 'deleted_at', deleted_at, 'created_at', created_at) ORDER BY deleted_at DESC), '[]'::jsonb)) FROM (SELECT message_id, remote_jid, content, from_me, deleted_at, created_at FROM evolution_messages WHERE instance_name = p_instance AND deleted_at IS NOT NULL AND (p_jid IS NULL OR remote_jid = p_jid) ORDER BY deleted_at DESC LIMIT p_limit) sub; $$;


