--
-- Name: fn_gmail_mark_first_reply(); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.fn_gmail_mark_first_reply() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$
BEGIN
  -- Quando uma mensagem enviada é inserida, verifica se a thread ainda não teve resposta
  IF NEW.is_sent = true THEN
    UPDATE zapp.gmail_threads t
    SET
      first_reply_at = NEW.internal_date,
      frt_minutes    = EXTRACT(EPOCH FROM (NEW.internal_date - t.last_message_at)) / 60,
      sla_status     = 'ok'
    WHERE t.id = NEW.thread_id_ref
      AND t.first_reply_at IS NULL
      AND t.unread_count > 0;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION zapp.fn_gmail_mark_first_reply() OWNER TO supabase_admin;

--
-- Name: fn_guard_qa_instances(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_guard_qa_instances() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog'
    AS $$
BEGIN
  IF NEW.instance_name ILIKE 'qa%'
     OR NEW.instance_name ILIKE 'q'
     OR NEW.instance_name ILIKE '%fantasma%'
     OR NEW.instance_name ILIKE '%test%bench%'
     OR NEW.display_name ILIKE '%sintet%'
     OR NEW.display_name ILIKE '%QA -%'
  THEN
    RAISE EXCEPTION 'BLOQUEADO: instância QA/sintética não permitida em produção: % (%)',
      NEW.instance_name, NEW.display_name
      USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION zapp.fn_guard_qa_instances() OWNER TO postgres;

