--

CREATE FUNCTION zapp.fn_handle_expired_r2_media() RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'zapp', 'pg_catalog'
    AS $$ DECLARE expired_count integer; BEGIN UPDATE zapp.evolution_messages_wpp2 SET media_url=NULL, media_status='expired', updated_at=now() WHERE media_url LIKE 'https://zapp-media-proxy%' AND message_type::text IN ('image','audio','ptt','video') AND created_at < now()-interval '180 days' AND deleted_at IS NULL; GET DIAGNOSTICS expired_count=ROW_COUNT; UPDATE zapp.evolution_messages_wpp2 SET media_url=NULL, media_status='expired', updated_at=now() WHERE media_url LIKE 'https://zapp-media-proxy%' AND message_type::text='document' AND created_at < now()-interval '365 days' AND deleted_at IS NULL; RETURN expired_count; END; $$;


