--
-- Name: fn_ingest_restore_logs_from_text(text); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.fn_ingest_restore_logs_from_text(p_logs text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  v_line text; v_json jsonb; v_inserted int := 0; v_skipped int := 0;
  v_errors int := 0; v_prefix text := '@@RESTORE_STEP@@';
  v_raw text; v_cleaned text; v_brace_count int; v_end_pos int; v_char text;
BEGIN
  IF p_logs IS NULL OR length(p_logs) = 0 THEN
    RETURN jsonb_build_object('status','empty');
  END IF;

  FOR v_line IN SELECT unnest(regexp_split_to_array(p_logs, E'\n'))
  LOOP
    IF position(v_prefix IN v_line) > 0 THEN
      v_raw := substring(v_line FROM position(v_prefix IN v_line) + length(v_prefix));
      BEGIN v_json := v_raw::jsonb; EXCEPTION WHEN OTHERS THEN v_json := NULL; END;

      IF v_json IS NULL THEN
        v_brace_count := 0; v_end_pos := 0;
        FOR i IN 1..length(v_raw) LOOP
          v_char := substring(v_raw FROM i FOR 1);
          IF v_char = '{' THEN v_brace_count := v_brace_count + 1; END IF;
          IF v_char = '}' THEN
            v_brace_count := v_brace_count - 1;
            IF v_brace_count = 0 THEN v_end_pos := i; EXIT; END IF;
          END IF;
        END LOOP;
        IF v_end_pos > 0 THEN
          v_cleaned := substring(v_raw FROM 1 FOR v_end_pos);
          BEGIN v_json := v_cleaned::jsonb;
          EXCEPTION WHEN OTHERS THEN v_errors := v_errors + 1; CONTINUE; END;
        ELSE v_errors := v_errors + 1; CONTINUE;
        END IF;
      END IF;

      BEGIN
        IF NOT EXISTS (
          SELECT 1 FROM zapp.restore_test_log
          WHERE run_id = (v_json->>'run_id')::uuid AND step = v_json->>'step'
        ) THEN
          INSERT INTO zapp.restore_test_log(run_id, step, status, detail, metrics, dump_file)
          VALUES (
            (v_json->>'run_id')::uuid, v_json->>'step', v_json->>'status',
            v_json->>'detail', COALESCE(v_json->'metrics','{}'::jsonb), v_json->>'dump_file'
          );
          v_inserted := v_inserted + 1;
          IF v_json->>'status' = 'failed' THEN
            PERFORM zapp.fn_alert_dispatch(
              p_alert_key  => 'restore_test_failed_' || (v_json->>'step'),
              p_severity   => 'critical',
              p_title      => format('Restore test FAILED: %s', v_json->>'step'),
              p_message    => COALESCE(v_json->>'detail','sem detalhes'),
              p_details    => jsonb_build_object('run_id', v_json->>'run_id', 'metrics', v_json->'metrics')
            );
          END IF;
        ELSE v_skipped := v_skipped + 1;
        END IF;
      EXCEPTION WHEN OTHERS THEN v_errors := v_errors + 1;
      END;
    END IF;
  END LOOP;

  RETURN jsonb_build_object('status','ok','inserted', v_inserted,'skipped', v_skipped,'errors', v_errors);
END;
$$;


ALTER FUNCTION zapp.fn_ingest_restore_logs_from_text(p_logs text) OWNER TO supabase_admin;

--
-- Name: fn_insert_idempotency_failure_audit(text, text, text, text, text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_insert_idempotency_failure_audit(p_event_id text, p_instance text DEFAULT NULL::text, p_event_type text DEFAULT NULL::text, p_error_code text DEFAULT NULL::text, p_error_message text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp, pg_temp'
    AS $$
BEGIN
  INSERT INTO zapp.audit_logs (action, entity_type, event_type, resource, status, details)
  VALUES (
    'idempotency_rollback_failure',
    'webhook_event',
    coalesce(p_event_type, 'unknown'),
    'evolution-webhook',
    'error',
    jsonb_build_object(
      'event_id', p_event_id,
      'instance', p_instance,
      'event_type', p_event_type,
      'error_code', p_error_code,
      'error_message', p_error_message
    )
  );
EXCEPTION WHEN OTHERS THEN
  BEGIN
    INSERT INTO ops.maintenance_log (job, details, ran_at)
    VALUES ('fn_insert_idempotency_failure_audit', jsonb_build_object('event_id', p_event_id, 'error', SQLERRM), now());
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;
END;
$$;


