--
-- Name: fn_list_shared_links(text, boolean, text, integer); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.fn_list_shared_links(p_instance text DEFAULT NULL::text, p_from_me boolean DEFAULT NULL::boolean, p_search text DEFAULT NULL::text, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$
BEGIN
  RETURN (
    SELECT jsonb_build_object(
      'ok', true,
      'total', count(*),
      'links', COALESCE(jsonb_agg(
        jsonb_build_object(
          'message_id', message_id,
          'content', left(content, 200),
          'url', link_preview->>'url',
          'title', link_preview->>'title',
          'description', link_preview->>'description',
          'preview_type', link_preview->>'previewType',
          'has_thumbnail', (link_preview->>'hasThumbnail')::boolean,
          'instance', instance_name,
          'from_me', from_me,
          'created_at', created_at
        ) ORDER BY created_at DESC
      ), '[]'::jsonb)
    )
    FROM (
      SELECT * FROM evolution_messages
      WHERE link_preview IS NOT NULL
        AND (p_instance IS NULL OR instance_name = p_instance)
        AND (p_from_me IS NULL OR from_me = p_from_me)
        AND (p_search IS NULL OR content ILIKE '%' || p_search || '%' OR link_preview->>'title' ILIKE '%' || p_search || '%')
      ORDER BY created_at DESC
      LIMIT p_limit
    ) sub
  );
END;
$$;


