--
-- Name: fn_list_stickers_for_user(uuid, text, boolean, text, boolean, integer); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.fn_list_stickers_for_user(p_user_id uuid, p_category text DEFAULT NULL::text, p_favorites_only boolean DEFAULT false, p_search text DEFAULT NULL::text, p_animated_only boolean DEFAULT false, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'ok', true,
    'user_id', p_user_id,
    'total', count(*),
    'memes', COALESCE(jsonb_agg(
      jsonb_build_object(
        'id', sub.id,
        'name', sub.name,
        'image_url', sub.image_url,
        'category', sub.category,
        'is_animated', sub.is_animated,
        'is_favorite', sub.is_user_fav,
        'use_count', sub.use_count,
        'tags', sub.tags,
        'mime_type', sub.mime_type
      ) ORDER BY sub.is_user_fav DESC, sub.use_count DESC, sub.name
    ), '[]'::jsonb)
  ) INTO v_result
  FROM (
    SELECT s.*, (sf.id IS NOT NULL) AS is_user_fav
    FROM stickers s
    LEFT JOIN sticker_favorites sf ON sf.sticker_id = s.id AND sf.user_id = p_user_id
    WHERE s.is_active = true
      AND (p_category IS NULL OR s.category = p_category)
      AND (NOT p_favorites_only OR sf.id IS NOT NULL)
      AND (p_search IS NULL OR s.name ILIKE '%' || p_search || '%' OR p_search = ANY(s.tags))
      AND (NOT p_animated_only OR s.is_animated = true)
    ORDER BY (sf.id IS NOT NULL) DESC, s.use_count DESC, s.name
    LIMIT p_limit
  ) sub;
  RETURN COALESCE(v_result, jsonb_build_object('ok', true, 'user_id', p_user_id, 'total', 0, 'memes', '[]'::jsonb));
END;
$$;


ALTER FUNCTION zapp.fn_list_stickers_for_user(p_user_id uuid, p_category text, p_favorites_only boolean, p_search text, p_animated_only boolean, p_limit integer) OWNER TO supabase_admin;

