COMMENT ON FUNCTION zapp.fn_list_stickers_for_user(p_user_id uuid, p_category text, p_favorites_only boolean, p_search text, p_animated_only boolean, p_limit integer) IS 'Lista figurinhas com is_favorite personalizado POR USUARIO. Suporta filtro por categoria, animados, busca textual e tags.';


--
-- Name: fn_log_assignment_change(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_log_assignment_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
BEGIN
  BEGIN
    PERFORM zapp.rpc_log_assignment_change(
      NEW.id,
      zapp.fn_uuid_safe(OLD.assigned_to),
      zapp.fn_uuid_safe(NEW.assigned_to),
      CASE WHEN OLD.assigned_to IS NULL THEN 'assign'
           WHEN NEW.assigned_to IS NULL THEN 'unassign'
           ELSE 'transfer' END,
      COALESCE(zapp.fn_uuid_safe(NEW.assigned_to), zapp.fn_uuid_safe(OLD.assigned_to))
    );
  EXCEPTION WHEN OTHERS THEN NULL;
  END;
  RETURN NEW;
END $$;


ALTER FUNCTION zapp.fn_log_assignment_change() OWNER TO postgres;

--
-- Name: FUNCTION fn_log_assignment_change(); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.fn_log_assignment_change() IS 'Paridade Lovable (log_assignment_change) adaptada: audita mudanças de assigned_to em zapp.conversation_events. Exception-safe.';


--
-- Name: fn_log_dispatch_error(); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.fn_log_dispatch_error() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  v_agent_email TEXT;
BEGIN
  v_agent_email := COALESCE(
    NEW.payload->>'agent_email',
    NEW.payload->>'agentEmail',
    NEW.payload->>'assigned_to',
    NEW.payload->>'user_email'
  );

  INSERT INTO zapp.dispatch_error_logs (
    failed_message_id, instance_name, remote_jid,
    agent_email, error_code, error_message, http_status,
    retry_count, payload, occurred_at
  ) VALUES (
    NEW.id, NEW.instance_name, NEW.remote_jid,
    v_agent_email, NEW.error_code, NEW.error_message, NEW.http_status,
    COALESCE(NEW.retry_count, 0), NEW.payload, COALESCE(NEW.created_at, now())
  );

  RETURN NEW;
END;
$$;


ALTER FUNCTION zapp.fn_log_dispatch_error() OWNER TO supabase_admin;

--
-- Name: fn_log_evo_license_health(text, integer, integer, jsonb, boolean); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_log_evo_license_health(p_status text, p_http_status integer, p_response_time_ms integer, p_raw jsonb DEFAULT NULL::jsonb, p_alert boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'evo,zapp'
    AS $$ DECLARE v_last timestamptz; BEGIN INSERT INTO zapp.evolution_license_health_log (status, http_status, response_time_ms, raw, alert_sent) VALUES (p_status, p_http_status, p_response_time_ms, p_raw, p_alert); IF p_alert THEN INSERT INTO zapp.warroom_alerts (source, alert_type, severity, title, entity, message) VALUES ('evo-license-watchdog', 'critical', 'critical', 'EVOLUTION API — LICENÇA NÃO ATIVA', 'evolution', 'license=' || COALESCE(p_status,'unknown') || ' http=' || COALESCE(p_http_status::text,'0') || ' rt=' || COALESCE(p_response_time_ms::text,'?') || 'ms checked_at=' || now()); END IF; END $$;


