-- Name: fn_log_reconnection_attempt(uuid, text, text, text, integer, boolean, jsonb); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_log_reconnection_attempt(p_connection_id uuid DEFAULT NULL::uuid, p_instance_name text DEFAULT NULL::text, p_status text DEFAULT 'attempting'::text, p_error_message text DEFAULT NULL::text, p_attempt_number integer DEFAULT 1, p_qr_generated boolean DEFAULT false, p_metadata jsonb DEFAULT NULL::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$
DECLARE v_id uuid;
BEGIN
  -- CRITICAL FIX: inserir em zapp.reconnection_logs (BASE TABLE), não em
  -- zapp.reconnection_logs que é uma VIEW sem INSTEAD OF trigger.
  INSERT INTO zapp.reconnection_logs
    (connection_id, instance_name, status, error_message,
     attempt_number, qr_generated, metadata)
  VALUES
    (p_connection_id, p_instance_name, p_status, p_error_message,
     p_attempt_number, p_qr_generated, p_metadata)
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


