--
-- Name: fn_log_route_switchover(); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.fn_log_route_switchover() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
BEGIN
  IF OLD.current_provider_id IS DISTINCT FROM NEW.current_provider_id
     AND NEW.current_provider_id IS NOT NULL THEN
    INSERT INTO zapp.provider_session_logs (provider_id, level, event, message, payload)
    VALUES (
      NEW.current_provider_id,
      'warn',
      'switchover',
      COALESCE(NEW.switched_reason, 'route changed'),
      jsonb_build_object(
        'from_provider', OLD.current_provider_id,
        'to_provider', NEW.current_provider_id,
        'channel_connection_id', NEW.channel_connection_id,
        'whatsapp_connection_id', NEW.whatsapp_connection_id
      )
    );
    NEW.switched_at := now();
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION zapp.fn_log_route_switchover() OWNER TO supabase_admin;

--
-- Name: fn_log_whatsapp_connection_state_change(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_log_whatsapp_connection_state_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'zapp', 'evo', 'public', 'pg_catalog'
    AS $$
DECLARE
  v_source text;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.status IS DISTINCT FROM OLD.status THEN
    -- current_setting retorna '' (string vazia) quando não existe.
    -- NULLIF transforma '' em NULL, e COALESCE finalmente cai no default 'app'.
    v_source := COALESCE(NULLIF(current_setting('app.reconcile_source', true), ''), 'app');

    INSERT INTO zapp.evolution_connection_history
      (instance_name, state, previous_state, duration_seconds, metadata, created_at)
    VALUES (
      NEW.instance_name,
      NEW.status,
      OLD.status,
      EXTRACT(EPOCH FROM (now() - COALESCE(OLD.updated_at, now())))::int,
      jsonb_build_object(
        'phone_number', NEW.phone_number,
        'owner_jid', NEW.owner_jid,
        'health_status', NEW.health_status,
        'health_reason', NEW.health_reason,
        'source', v_source
      ),
      now()
    );
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION zapp.fn_log_whatsapp_connection_state_change() OWNER TO postgres;

--
-- Name: FUNCTION fn_log_whatsapp_connection_state_change(); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.fn_log_whatsapp_connection_state_change() IS 'Trigger AFTER UPDATE OF status em whatsapp_connections. Insere registro em evolution_connection_history com state, previous_state e metadata jsonb (phone_number, owner_jid, health_*, source). Source = ''cron_reconcile'' quando vem do cron, ''app'' caso contrário.';


--
-- Name: fn_login_attempt_record_failed(text, text, text, boolean); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.fn_login_attempt_record_failed(p_email text, p_ip_address text, p_user_agent text, p_success boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_attempt_count integer;
  v_locked_until timestamptz;
BEGIN
  INSERT INTO zapp.login_attempts (
    email, ip_address, user_agent, success, attempt_count, last_attempt_at, locked_until, updated_at
  )
  VALUES (
    p_email, NULLIF(p_ip_address, 'unknown'), p_user_agent, COALESCE(p_success, false),
    1, now(), NULL, now()
  )
  ON CONFLICT (email) DO UPDATE SET
    attempt_count    = login_attempts.attempt_count + 1,
    ip_address       = EXCLUDED.ip_address,
    user_agent       = EXCLUDED.user_agent,
    last_attempt_at  = now(),
    locked_until     = CASE
      WHEN login_attempts.attempt_count + 1 >= 5
        THEN now() + (pow(2, LEAST(login_attempts.attempt_count + 1 - 5, 10)) * interval '1 minute')
      ELSE NULL
    END,
    updated_at       = now()
  RETURNING attempt_count, locked_until
  INTO v_attempt_count, v_locked_until;

  RETURN jsonb_build_object(
    'attempt_count',    v_attempt_count,
    'locked_until',     to_jsonb(v_locked_until),
    'last_attempt_at',  to_jsonb(now()),
    'is_locked',        v_locked_until IS NOT NULL
  );
END;
$$;


ALTER FUNCTION zapp.fn_login_attempt_record_failed(p_email text, p_ip_address text, p_user_agent text, p_success boolean) OWNER TO supabase_admin;

--
-- Name: fn_lux_alert_check(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_lux_alert_check() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'net'
    AS $$
DECLARE
  v_alerts   JSONB    := '[]'::jsonb;
  v_open_ct  INT      := 0;
  v_stale_ct INT      := 0;
  v_days_v2  INT      := 0;
  v_v2_eol   TIMESTAMPTZ := '2026-11-18 00:00:00+00'::TIMESTAMPTZ;
  v_sev      TEXT;
  v_row      RECORD;
BEGIN
  -- 1: Credenciais expirando (usa expires_at + alerta_dias_antes nativos da tabela)
  FOR v_row IN
    SELECT servico, expires_at, alerta_dias_antes,
           round(extract(epoch FROM (expires_at - now()))/86400)::int AS days_left
    FROM zapp.cookies_config
    WHERE expires_at IS NOT NULL AND is_healthy = true
      AND expires_at < now() + (coalesce(alerta_dias_antes, 14) || ' days')::interval
    ORDER BY expires_at
  LOOP
    v_sev := CASE WHEN v_row.days_left <= 3 THEN 'critical' ELSE 'warning' END;
    INSERT INTO zapp.lux_system_alerts (alert_type, severity, service, message, data)
    SELECT 'credential_expiring', v_sev, v_row.servico,
      format('[%s] Credencial "%s" expira em %s dias (%s) — renovar AGORA',
        upper(v_sev), v_row.servico, v_row.days_left, v_row.expires_at::date),
      jsonb_build_object('expires_at', v_row.expires_at, 'days_left', v_row.days_left,
        'alerta_threshold_days', coalesce(v_row.alerta_dias_antes,14))
    WHERE NOT EXISTS (
      SELECT 1 FROM zapp.lux_system_alerts
      WHERE alert_type = 'credential_expiring' AND service = v_row.servico
        AND resolved_at IS NULL AND created_at > now() - interval '12 hours'
    );
    v_alerts := v_alerts || jsonb_build_object(
      'type','credential_expiring','service',v_row.servico,
      'severity',v_sev,'days_left',v_row.days_left);
  END LOOP;

  -- 2: Lusha V2 EOL countdown (deadline fixo: 18/nov/2026)
  v_days_v2 := round(extract(epoch FROM (v_v2_eol - now()))/86400)::int;
  IF v_days_v2 <= 90 THEN
    v_sev := CASE WHEN v_days_v2 <= 30 THEN 'critical' ELSE 'warning' END;
    INSERT INTO zapp.lux_system_alerts (alert_type, severity, service, message, data)
    SELECT 'api_v2_eol', v_sev, 'lusha',
      format('[%s] Lusha API V2 encerra em %s dias (18/nov/2026) — migrar para V3 URGENTE', upper(v_sev), v_days_v2),
      jsonb_build_object('eol_date', v_v2_eol, 'days_left', v_days_v2)
    WHERE NOT EXISTS (
      SELECT 1 FROM zapp.lux_system_alerts
      WHERE alert_type = 'api_v2_eol' AND resolved_at IS NULL AND created_at > now() - interval '24 hours'
    );
    v_alerts := v_alerts || jsonb_build_object('type','api_v2_eol','severity',v_sev,'days_left',v_days_v2);
  END IF;

  -- 3: Circuits abertos (>=2 = degradado, 3 = paralisado)
  SELECT count(*) INTO v_open_ct FROM zapp.fn_circuit_status() WHERE state = 'open';
  IF v_open_ct >= 2 THEN
    v_sev := CASE WHEN v_open_ct >= 3 THEN 'critical' ELSE 'warning' END;
    INSERT INTO zapp.lux_system_alerts (alert_type, severity, message, data)
    SELECT 'circuits_open', v_sev,
      format('[%s] %s/3 circuits abertos — enrichment %s',
        upper(v_sev), v_open_ct, CASE WHEN v_open_ct >= 3 THEN 'PARALISADO' ELSE 'DEGRADADO' END),
      (SELECT jsonb_agg(jsonb_build_object('service',service,'state',state,'failures',failure_count))
       FROM zapp.fn_circuit_status() WHERE state='open')
    WHERE NOT EXISTS (
      SELECT 1 FROM zapp.lux_system_alerts
      WHERE alert_type = 'circuits_open' AND resolved_at IS NULL AND created_at > now() - interval '2 hours'
    );
    v_alerts := v_alerts || jsonb_build_object('type','circuits_open','severity',v_sev,'open_count',v_open_ct);
  END IF;

  -- 4: LeadContact sem Bearer token (SESSION-only = frágil)
  IF EXISTS (SELECT 1 FROM zapp.cookies_config WHERE servico = 'leadcontact' AND coalesce(token,'') = '') THEN
    INSERT INTO zapp.lux_system_alerts (alert_type, severity, service, message, data)
    SELECT 'no_bearer_token', 'info', 'leadcontact',
      '[INFO] LeadContact usa apenas SESSION cookie — configure Bearer token (painel → API Key) para fallback automático',
      jsonb_build_object('action','Painel LeadContact → Settings → API Key → copiar Bearer token')
    WHERE NOT EXISTS (
      SELECT 1 FROM zapp.lux_system_alerts
      WHERE alert_type = 'no_bearer_token' AND service = 'leadcontact' AND resolved_at IS NULL
    );
    v_alerts := v_alerts || jsonb_build_object('type','no_bearer_token','severity','info','service','leadcontact');
  END IF;

  -- 5: Pending órfãos (probe cycle pode estar falhando)
  SELECT count(*) INTO v_stale_ct FROM zapp.cookie_probe_pending WHERE dispatched_at < now() - interval '2 hours';
  IF v_stale_ct > 0 THEN
    INSERT INTO zapp.lux_system_alerts (alert_type, severity, message, data)
    SELECT 'stale_pending', 'warning',
      format('[WARNING] %s linhas órfãs em cookie_probe_pending (>2h) — fn_cookie_probe_cycle pode estar falhando', v_stale_ct),
      jsonb_build_object('count', v_stale_ct)
    WHERE NOT EXISTS (
      SELECT 1 FROM zapp.lux_system_alerts
      WHERE alert_type = 'stale_pending' AND resolved_at IS NULL AND created_at > now() - interval '2 hours'
    );
    v_alerts := v_alerts || jsonb_build_object('type','stale_pending','severity','warning','count',v_stale_ct);
  END IF;

  RETURN jsonb_build_object('alerts_fired', jsonb_array_length(v_alerts), 'alerts', v_alerts);
END;
$$;


ALTER FUNCTION zapp.fn_lux_alert_check() OWNER TO postgres;

--
-- Name: fn_lux_maintenance(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_lux_maintenance() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'net'
    AS $$
DECLARE
  v_probe_deleted  INT := 0;
  v_pending_purged INT := 0;
  v_alerts_archived INT := 0;
BEGIN
  -- 1: Purge probe logs > 30 dias
  DELETE FROM zapp.cookie_probe_log WHERE probed_at < now() - interval '30 days';
  GET DIAGNOSTICS v_probe_deleted = ROW_COUNT;
  -- 2: Purge pending órfãos > 2 horas (devem ter sido coletados pelo cycle)
  DELETE FROM zapp.cookie_probe_pending WHERE dispatched_at < now() - interval '2 hours';
  GET DIAGNOSTICS v_pending_purged = ROW_COUNT;
  -- 3: Arquivar alertas resolvidos > 7 dias
  DELETE FROM zapp.lux_system_alerts WHERE resolved_at IS NOT NULL AND resolved_at < now() - interval '7 days';
  GET DIAGNOSTICS v_alerts_archived = ROW_COUNT;
  RETURN jsonb_build_object(
    'probe_logs_deleted', v_probe_deleted,
    'pending_purged',     v_pending_purged,
    'alerts_archived',    v_alerts_archived,
    'ran_at',             now());
END;
$$;


ALTER FUNCTION zapp.fn_lux_maintenance() OWNER TO postgres;

