-- Name: fn_move_audio_meme_category(uuid, text); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.fn_move_audio_meme_category(p_meme_id uuid, p_new_category text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$
DECLARE
  v_old text;
BEGIN
  SELECT category INTO v_old FROM audio_memes WHERE id = p_meme_id;
  IF v_old IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'meme_id nao encontrado');
  END IF;
  UPDATE audio_memes SET category = p_new_category WHERE id = p_meme_id;
  RETURN jsonb_build_object('ok', true, 'id', p_meme_id, 'old_category', v_old, 'new_category', p_new_category);
END;
$$;


