--
-- Name: fn_normalize_br_phone(text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_normalize_br_phone(raw_phone text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$
DECLARE
  cleaned text;
  len integer;
BEGIN
  -- Remove tudo que não é dígito
  cleaned := regexp_replace(raw_phone, '[^0-9]', '', 'g');
  len := length(cleaned);
  
  -- Remove prefixo 55 se presente
  IF len >= 12 AND left(cleaned, 2) = '55' THEN
    cleaned := substring(cleaned FROM 3);
    len := length(cleaned);
  END IF;
  
  -- Se tem 10 dígitos (sem 9o dígito), adiciona o 9 para celulares
  IF len = 10 THEN
    -- Celulares começam com 9,8,7,6 após DDD
    IF substring(cleaned FROM 3 FOR 1) IN ('9','8','7','6') THEN
      cleaned := left(cleaned, 2) || '9' || substring(cleaned FROM 3);
    END IF;
  END IF;
  
  RETURN cleaned;
END;
$$;


ALTER FUNCTION zapp.fn_normalize_br_phone(raw_phone text) OWNER TO postgres;

--
-- Name: fn_normalize_conversation_jid(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_normalize_conversation_jid() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog'
    AS $_$
  DECLARE v_phone text; v_lid_local text;
  BEGIN
    NEW.remote_jid := regexp_replace(lower(NEW.remote_jid), ':([0-9]+)@', '@', 'g');
    IF lower(NEW.remote_jid) ~ '^[0-9]+@lid$' THEN
      v_lid_local := split_part(lower(NEW.remote_jid), '@', 1);
      SELECT ci.phone_number INTO v_phone
      FROM public.evo_contact_identity ci
      WHERE ci.lid_jid = lower(NEW.remote_jid)
        AND ci.instance_name = COALESCE(NEW.instance_name, 'wpp2')
        AND ci.phone_number IS NOT NULL
        AND ci.phone_number <> v_lid_local
        AND length(ci.phone_number) <= 13
      LIMIT 1;
      IF v_phone IS NULL THEN
        SELECT ec.phone_number INTO v_phone
        FROM zapp.evolution_contacts ec
        WHERE lower(ec.remote_jid) = lower(NEW.remote_jid)
          AND ec.phone_number ~ '^[0-9]+$'
          AND length(ec.phone_number) <= 13
          AND ec.phone_number <> v_lid_local
          AND ec.deleted_at IS NULL
        ORDER BY ec.updated_at DESC
        LIMIT 1;
      END IF;
      IF v_phone IS NOT NULL THEN
        NEW.remote_jid := v_phone || '@s.whatsapp.net';
      END IF;
    END IF;
    RETURN NEW;
  END $_$;


ALTER FUNCTION zapp.fn_normalize_conversation_jid() OWNER TO postgres;

--
-- Name: fn_normalize_message_types(integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_normalize_message_types(p_batch_size integer DEFAULT 5000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET statement_timeout TO '240s'
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE v_started timestamptz:=clock_timestamp(); v_updated int:=0; v_batch int; v_from text; v_to text; v_froms text[]:=ARRAY['imageMessage','audioMessage','videoMessage','documentMessage','stickerMessage']; v_tos text[]:=ARRAY['image','audio','video','document','sticker']; i int;
BEGIN
  FOR i IN 1..array_length(v_froms,1) LOOP v_from:=v_froms[i]; v_to:=v_tos[i];
    LOOP WITH batch AS (SELECT id FROM evolution_messages WHERE message_type=v_from LIMIT p_batch_size) UPDATE evolution_messages em SET message_type=v_to FROM batch WHERE em.id=batch.id; GET DIAGNOSTICS v_batch=ROW_COUNT; v_updated:=v_updated+v_batch; EXIT WHEN v_batch=0; END LOOP;
  END LOOP;
  RETURN jsonb_build_object('status','ok','total_updated',v_updated);
END; $$;


ALTER FUNCTION zapp.fn_normalize_message_types(p_batch_size integer) OWNER TO postgres;

--
-- Name: fn_normalize_phone(text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_normalize_phone(p_phone text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$
DECLARE
  v_digits text;
  v_len    int;
BEGIN
  -- Extrair apenas digitos
  v_digits := regexp_replace(COALESCE(p_phone, ''), '[^0-9]', '', 'g');

  IF v_digits = '' THEN
    RETURN NULL;
  END IF;

  -- Remover zero lider: DDD pode ser escrito como '021', '011', etc.
  -- Ex: '02199998888' (11d) -> remove '0' -> '2199998888' (10d)
  IF left(v_digits, 1) = '0' THEN
    v_digits := substring(v_digits, 2);
  END IF;

  v_len := length(v_digits);

  -- 10-11 digitos: numero sem DDI -> adicionar '55' (Brasil)
  IF v_len BETWEEN 10 AND 11 THEN
    RETURN '55' || v_digits;
  END IF;

  -- 12-13 digitos: deve comecar com '55' (DDI Brasil) para ser valido
  IF v_len BETWEEN 12 AND 13 THEN
    IF left(v_digits, 2) = '55' THEN
      RETURN v_digits;
    END IF;
    -- DDI diferente de 55: nao e numero brasileiro -> NULL
    RETURN NULL;
  END IF;

  -- Fora de range (< 10 ou > 13 digitos): invalido
  RETURN NULL;
END;
$$;


ALTER FUNCTION zapp.fn_normalize_phone(p_phone text) OWNER TO postgres;

--
-- Name: fn_normalize_remote_jid(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_normalize_remote_jid() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog'
    AS $_$
  DECLARE v_phone text; v_lid_local text;
  BEGIN
    IF TG_OP = 'INSERT' AND NEW.remote_jid IS NOT NULL AND NEW.remote_jid_original IS NULL THEN
      NEW.remote_jid_original := NEW.remote_jid;
    END IF;
    IF NEW.remote_jid IS NOT NULL AND NEW.remote_jid LIKE '%:%@%' THEN
      NEW.remote_jid := regexp_replace(lower(NEW.remote_jid), ':([0-9]+)@', '@', 'g');
    END IF;
    IF NEW.remote_jid IS NULL OR NEW.remote_jid = '' THEN
      IF NEW.status = 'deleted' OR NEW.content = '[Mensagem apagada]' THEN
        NEW.remote_jid := 'unknown@deleted';
      ELSIF NEW.message_id LIKE 'smoke-%' OR NEW.message_id LIKE 'test-%'
         OR NEW.message_id LIKE 'pg-cron-canary-%' OR NEW.message_id LIKE 'sentinel-%' THEN
        NEW.remote_jid := 'smoke-test@localhost';
      ELSE
        NEW.remote_jid := 'unknown@s.whatsapp.net';
      END IF;
      RETURN NEW;
    END IF;
    IF NEW.remote_jid LIKE '%@lid' THEN
      v_lid_local := split_part(lower(NEW.remote_jid), '@', 1);
      SELECT lpm.phone_number INTO v_phone
      FROM public.evo_lid_phone_map lpm
      WHERE lower(lpm.lid_jid) = lower(NEW.remote_jid)
        AND lpm.instance_name = COALESCE(NEW.instance_name, 'wpp2')
        AND lpm.phone_number IS NOT NULL
        AND lpm.confidence NOT IN ('none', 'bootstrap_invalid')
        AND lpm.phone_number <> v_lid_local
      LIMIT 1;
      IF v_phone IS NULL THEN
        SELECT ci.phone_number INTO v_phone
        FROM public.evo_contact_identity ci
        WHERE ci.lid_jid = lower(NEW.remote_jid)
          AND ci.instance_name = COALESCE(NEW.instance_name, 'wpp2')
          AND ci.phone_number IS NOT NULL
          AND ci.phone_number <> v_lid_local
          AND length(ci.phone_number) <= 13
        LIMIT 1;
      END IF;
      IF v_phone IS NULL THEN
        SELECT ec.phone_number INTO v_phone
        FROM zapp.evolution_contacts ec
        WHERE lower(ec.remote_jid) = lower(NEW.remote_jid)
          AND ec.phone_number ~ '^[0-9]+$'
          AND length(ec.phone_number) <= 13
          AND ec.phone_number <> v_lid_local
          AND ec.deleted_at IS NULL
        LIMIT 1;
      END IF;
      IF v_phone IS NOT NULL THEN
        NEW.remote_jid := v_phone || '@s.whatsapp.net';
      END IF;
      RETURN NEW;
    END IF;
    RETURN NEW;
  END $_$;


ALTER FUNCTION zapp.fn_normalize_remote_jid() OWNER TO postgres;

--
-- Name: fn_normalize_send_jid(text, text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_normalize_send_jid(p_jid text, p_instance text DEFAULT 'wpp2'::text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $_$
DECLARE
  v_jid    text;
  v_phone  text;
  v_lid_local text;
BEGIN
  v_jid := btrim(coalesce(p_jid,''));
  IF v_jid = '' THEN
    RAISE EXCEPTION 'fn_normalize_send_jid: jid vazio/nulo' USING ERRCODE='22023';
  END IF;

  -- FIX s24a: strip leading + (simples, antes de qualquer outra transformação)
  v_jid := ltrim(v_jid, '+');

  -- FIX s24b: strip device suffix :N (5511999999999:42@s.whatsapp.net → 5511999999999@s.whatsapp.net)
  IF v_jid ~ '^[0-9]+:[0-9]+@' THEN
    v_jid := regexp_replace(v_jid, ':[0-9]+@', '@');
  END IF;

  -- Case 1: @lid — tentar resolver para PN real
  IF lower(v_jid) ~ '^[0-9]+@lid$' THEN
    v_lid_local := split_part(lower(v_jid), '@', 1);

    -- 1a. Checar contact_identity (fonte de verdade pós-Evolution 2.4.x)
    SELECT ci.phone_number INTO v_phone
    FROM public.evo_contact_identity ci
    WHERE ci.lid_jid = lower(v_jid)
      AND ci.instance_name = p_instance
      AND ci.phone_number IS NOT NULL
      AND ci.phone_number <> v_lid_local
      AND length(ci.phone_number) <= 15
    LIMIT 1;

    -- 1b. Fallback: lid_phone_map (mapeamentos de alta confiança acumulados)
    IF v_phone IS NULL THEN
      SELECT lm.phone_number INTO v_phone
      FROM public.evo_lid_phone_map lm
      WHERE lm.lid_jid = lower(v_jid)
        AND lm.phone_number IS NOT NULL
        AND lm.phone_number <> v_lid_local
        AND lm.confidence IN ('high','medium')
        AND length(lm.phone_number) <= 15
      ORDER BY lm.confidence DESC, lm.updated_at DESC LIMIT 1;
    END IF;

    -- 1c. Fallback: evolution_contacts com phone REAL
    IF v_phone IS NULL THEN
      SELECT ec.phone_number INTO v_phone
      FROM zapp.evolution_contacts ec
      WHERE lower(ec.remote_jid) = lower(v_jid)
        AND ec.instance_name = p_instance
        AND ec.phone_number ~ '^[0-9]+$'
        AND length(ec.phone_number) <= 13
        AND ec.phone_number <> v_lid_local
        AND ec.deleted_at IS NULL
      ORDER BY ec.updated_at DESC LIMIT 1;
    END IF;

    IF v_phone IS NULL THEN
      RAISE EXCEPTION
        'fn_normalize_send_jid: JID @lid % sem phone_number real mapeado (instância %). Aguarda Evolution >=2.4.x para resolução automática. Use contact_identity após upgrade.',
        v_jid, p_instance
      USING ERRCODE='22023';
    END IF;

    RETURN v_phone || '@s.whatsapp.net';
  END IF;

  -- Case 2: JIDs válidos diretamente
  IF v_jid ~ '^[0-9]+@(s\.whatsapp\.net|g\.us|c\.us)$' OR v_jid = 'status@broadcast' THEN
    RETURN v_jid;
  END IF;

  RAISE EXCEPTION 'fn_normalize_send_jid: JID malformado: %', v_jid USING ERRCODE='22023';
END $_$;


ALTER FUNCTION zapp.fn_normalize_send_jid(p_jid text, p_instance text) OWNER TO postgres;

--
-- Name: FUNCTION fn_normalize_send_jid(p_jid text, p_instance text); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.fn_normalize_send_jid(p_jid text, p_instance text) IS 'Normaliza JID para envio. Fixes s24: (a) strip + prefix via ltrim, (b) strip device suffix :N, (c) fallback lid_phone_map para LID resolution. [2026-08-12]';


--
-- Name: fn_notify_critical_alert(text, text, text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_notify_critical_alert(p_title text, p_message text, p_source text DEFAULT 'system'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
BEGIN
