--
-- Name: fn_process_evolution_notifications(integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_process_evolution_notifications(p_batch integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'public'
    AS $$
DECLARE
  v_claimed int := 0;
  v_delivered int := 0;
  v_external int := 0;
  v_rec record;
  v_ch text;
  v_payload jsonb;
BEGIN
  FOR v_rec IN
    SELECT id, title, message, channels_sent, notification_type,
           contact_id, conversation_id, deal_id, priority, metadata, created_at
    FROM zapp.evolution_notifications
    WHERE status = 'pending'
    ORDER BY created_at ASC
    LIMIT p_batch
    FOR UPDATE SKIP LOCKED
  LOOP
    v_claimed := v_claimed + 1;
    v_payload := jsonb_build_object(
      'notification_id', v_rec.id,
      'notification_type', v_rec.notification_type,
      'title', v_rec.title,
      'message', v_rec.message,
      'contact_id', v_rec.contact_id,
      'conversation_id', v_rec.conversation_id,
      'deal_id', v_rec.deal_id,
      'priority', v_rec.priority,
      'metadata', v_rec.metadata,
      'created_at', v_rec.created_at
    );

    IF v_rec.channels_sent IS NULL OR
       NOT (v_rec.channels_sent && ARRAY['email'::text,'slack'::text,'webhook'::text,'whatsapp_promo'::text])
    THEN
      UPDATE zapp.evolution_notifications
      SET status = 'delivered'
      WHERE id = v_rec.id AND status = 'pending';
      v_delivered := v_delivered + 1;
    ELSE
      FOREACH v_ch IN ARRAY v_rec.channels_sent LOOP
        IF v_ch IN ('email','slack','webhook','whatsapp_promo') THEN
          INSERT INTO zapp.evolution_notification_outbox (notification_id, channel, payload, status)
          VALUES (v_rec.id, v_ch, v_payload, 'pending');
        END IF;
      END LOOP;
      UPDATE zapp.evolution_notifications
      SET status = 'pending_external'
      WHERE id = v_rec.id AND status = 'pending';
      v_external := v_external + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'claimed', v_claimed,
    'delivered_in_app', v_delivered,
    'pending_external', v_external,
    'executado_em', now()
  );
END;
$$;


ALTER FUNCTION zapp.fn_process_evolution_notifications(p_batch integer) OWNER TO postgres;

