--
-- Name: fn_process_webhook_event(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_process_webhook_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE v_contact_id UUID; v_conversation_id UUID; v_remote_jid TEXT; v_push_name TEXT; v_message_id TEXT; v_content TEXT; v_message_type TEXT; v_from_me BOOLEAN; v_payload JSONB; v_key JSONB; v_message JSONB;
BEGIN
  IF NEW.event_type NOT IN ('MESSAGES_UPSERT','SEND_MESSAGE','messages.upsert') THEN RETURN NEW; END IF;
  IF jsonb_typeof(NEW.payload)='array' THEN v_payload:=NEW.payload->0; ELSE v_payload:=NEW.payload; END IF;
  v_key:=COALESCE(v_payload->'key',v_payload->'data'->'key');
  v_message:=COALESCE(v_payload->'message',v_payload->'data'->'message');
  v_remote_jid:=COALESCE(v_key->>'remoteJid',v_payload->>'remoteJid',NEW.remote_jid);
  v_message_id:=COALESCE(v_key->>'id',v_payload->>'keyId',v_payload->>'messageId');
  v_from_me:=COALESCE((v_key->>'fromMe')::boolean,NEW.from_me,false);
  v_push_name:=COALESCE(v_payload->>'pushName',v_key->>'pushName');
  v_content:=COALESCE(v_message->>'conversation',v_message->'extendedTextMessage'->>'text','');
  v_message_type:=CASE WHEN v_message ? 'imageMessage' THEN 'image' WHEN v_message ? 'videoMessage' THEN 'video' WHEN v_message ? 'audioMessage' THEN 'audio' WHEN v_message ? 'documentMessage' THEN 'document' WHEN v_message ? 'stickerMessage' THEN 'sticker' ELSE 'text' END;
  IF v_remote_jid IS NULL OR v_message_id IS NULL THEN NEW.processed:=true; NEW.processed_at:=NOW(); RETURN NEW; END IF;
  IF v_remote_jid NOT LIKE '%@g.us' AND v_remote_jid NOT LIKE '%@broadcast' THEN
    BEGIN v_contact_id:=fn_upsert_contact_from_webhook(v_remote_jid,v_push_name,NEW.instance_name); v_conversation_id:=fn_get_or_create_conversation(v_contact_id,v_remote_jid,NEW.instance_name); EXCEPTION WHEN OTHERS THEN NULL; END;
  END IF;
  INSERT INTO evolution_messages (remote_jid,message_id,contact_id,conversation_id,content,message_type,direction,from_me,instance_name,push_name,raw_data) VALUES (v_remote_jid,v_message_id,v_contact_id,v_conversation_id,v_content,v_message_type,CASE WHEN v_from_me THEN 'outbound' ELSE 'inbound' END,v_from_me,NEW.instance_name,v_push_name,v_payload)
  ON CONFLICT (message_id,instance_name) DO UPDATE SET content=COALESCE(EXCLUDED.content,evolution_messages.content),raw_data=evolution_messages.raw_data||EXCLUDED.raw_data;
  NEW.processed:=true; NEW.processed_at:=NOW(); RETURN NEW;
EXCEPTION WHEN OTHERS THEN NEW.error_message:=SQLERRM; NEW.processed:=false; RETURN NEW;
END; $$;


ALTER FUNCTION zapp.fn_process_webhook_event() OWNER TO postgres;

--
-- Name: fn_process_whatsapp_message(jsonb, text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_process_whatsapp_message(p_payload jsonb, p_instance text DEFAULT 'wpp2'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $_$
DECLARE v_key jsonb; v_remote_jid text; v_message_id text; v_from_me boolean; v_push_name text; v_content text; v_message_type text; v_contact_id uuid; v_conversation_id uuid; v_msg_pk uuid; v_media_type text; v_media_url text; v_media_mimetype text; v_caption text; v_media_meta jsonb; v_link_preview jsonb; v_msg_subkey text; v_is_new boolean; v_media_filename text;
BEGIN
IF (p_payload->>'messageType') = 'reactionMessage' THEN RETURN fn_handle_reaction(p_payload, p_instance); END IF;
IF (p_payload->>'messageType') = 'protocolMessage' THEN RETURN fn_handle_message_delete(p_payload, p_instance); END IF;
IF (p_payload->'key'->>'remoteJid') = 'status@broadcast' THEN RETURN fn_handle_whatsapp_status(p_payload, p_instance); END IF;
-- Validar instance_name
IF NOT EXISTS (
  SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
  WHERE n.nspname='evo' AND c.relname='evolution_messages_'||lower(regexp_replace(p_instance,'[^a-z0-9]','_','g'))
  UNION ALL
  SELECT 1 FROM zapp.whatsapp_connections wc WHERE wc.instance_name=p_instance
) THEN
  RETURN jsonb_build_object('ok',false,'error','Instance not registered','instance',p_instance);
END IF;
v_key := p_payload->'key'; v_remote_jid := v_key->>'remoteJid'; v_message_id := v_key->>'id'; v_from_me := COALESCE((v_key->>'fromMe')::boolean, false); v_push_name := p_payload->>'pushName'; v_message_type := COALESCE(p_payload->>'messageType', 'text');
v_content := COALESCE(p_payload->'message'->>'conversation', p_payload->'message'->'extendedTextMessage'->>'text', '');
v_media_url := COALESCE( p_payload->'message'->>'mediaUrl', p_payload->'message'->'imageMessage'->>'url', p_payload->'message'->'audioMessage'->>'url', p_payload->'message'->'videoMessage'->>'url', p_payload->'message'->'documentMessage'->>'url', p_payload->'message'->'ptvMessage'->>'url', p_payload->'message'->'stickerMessage'->>'url' );
v_media_mimetype := COALESCE( p_payload->'message'->'imageMessage'->>'mimetype', p_payload->'message'->'audioMessage'->>'mimetype', p_payload->'message'->'videoMessage'->>'mimetype', p_payload->'message'->'ptvMessage'->>'mimetype', p_payload->'message'->'stickerMessage'->>'mimetype', p_payload->'message'->'documentMessage'->>'mimetype' );
-- FIXED: media_filename somente de documentMessage.fileName (fonte confiável)
-- Content é texto da mensagem ou ID interno WA — não é filename
v_media_filename := p_payload->'message'->'documentMessage'->>'fileName';
-- Fallback apenas se content parecer filename real (tem extensão válida)
IF v_media_filename IS NULL AND v_message_type = 'document' THEN
  DECLARE v_cf text := COALESCE(p_payload->>'content', v_content);
  BEGIN
    IF v_cf ~ '\.[a-zA-Z0-9]{2,5}$' AND v_cf !~ '^DOC-[0-9]{8}-WA' THEN
      v_media_filename := v_cf;
    END IF;
  END;
END IF;
-- Inferir mimetype pelo filename
IF v_media_mimetype IS NULL AND v_media_filename IS NOT NULL THEN
  v_media_mimetype := CASE
    WHEN lower(v_media_filename) LIKE '%.pdf'  THEN 'application/pdf'
    WHEN lower(v_media_filename) LIKE '%.docx' THEN 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
    WHEN lower(v_media_filename) LIKE '%.doc'  THEN 'application/msword'
    WHEN lower(v_media_filename) LIKE '%.xlsx' THEN 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
    WHEN lower(v_media_filename) LIKE '%.xls'  THEN 'application/vnd.ms-excel'
    WHEN lower(v_media_filename) LIKE '%.pptx' THEN 'application/vnd.openxmlformats-officedocument.presentationml.presentation'
    WHEN lower(v_media_filename) LIKE '%.ppt'  THEN 'application/vnd.ms-powerpoint'
    WHEN lower(v_media_filename) LIKE '%.jpg'  THEN 'image/jpeg'
    WHEN lower(v_media_filename) LIKE '%.jpeg' THEN 'image/jpeg'
    WHEN lower(v_media_filename) LIKE '%.png'  THEN 'image/png'
    WHEN lower(v_media_filename) LIKE '%.mp4'  THEN 'video/mp4'
    WHEN lower(v_media_filename) LIKE '%.mp3'  THEN 'audio/mpeg'
    WHEN lower(v_media_filename) LIKE '%.zip'  THEN 'application/zip'
    WHEN lower(v_media_filename) LIKE '%.txt'  THEN 'text/plain'
    WHEN lower(v_media_filename) LIKE '%.csv'  THEN 'text/csv'
    WHEN lower(v_media_filename) LIKE '%.gif'  THEN 'image/gif'
    WHEN lower(v_media_filename) LIKE '%.xml'  THEN 'application/xml'
    ELSE 'application/octet-stream'
  END;
END IF;
v_media_type := CASE WHEN p_payload->'message'->'imageMessage' IS NOT NULL THEN 'image' WHEN p_payload->'message'->'audioMessage' IS NOT NULL THEN 'audio' WHEN p_payload->'message'->'videoMessage' IS NOT NULL THEN 'video' WHEN p_payload->'message'->'ptvMessage' IS NOT NULL THEN 'video' WHEN p_payload->'message'->'stickerMessage' IS NOT NULL THEN 'sticker' WHEN p_payload->'message'->'documentMessage' IS NOT NULL THEN 'document' ELSE NULL END;
v_caption := COALESCE(p_payload->'message'->'imageMessage'->>'caption', p_payload->'message'->'videoMessage'->>'caption', p_payload->'message'->'documentMessage'->>'caption');
IF p_payload->'message' ? 'extendedTextMessage' THEN
  v_link_preview := jsonb_build_object('url', p_payload->'message'->'extendedTextMessage'->>'matchedText','canonicalUrl', p_payload->'message'->'extendedTextMessage'->>'canonicalUrl','title', p_payload->'message'->'extendedTextMessage'->>'title','description', p_payload->'message'->'extendedTextMessage'->>'description','previewType', p_payload->'message'->'extendedTextMessage'->>'previewType','hasThumbnail', (p_payload->'message'->'extendedTextMessage' ? 'jpegThumbnail'));
  IF v_link_preview->>'url' IS NULL OR v_link_preview->>'url' = '' THEN v_link_preview := NULL; END IF;
END IF;
v_msg_subkey := CASE WHEN p_payload->'message' ? 'imageMessage' THEN 'imageMessage' WHEN p_payload->'message' ? 'audioMessage' THEN 'audioMessage' WHEN p_payload->'message' ? 'videoMessage' THEN 'videoMessage' WHEN p_payload->'message' ? 'ptvMessage' THEN 'ptvMessage' WHEN p_payload->'message' ? 'stickerMessage' THEN 'stickerMessage' WHEN p_payload->'message' ? 'documentMessage' THEN 'documentMessage' ELSE NULL END;
IF v_msg_subkey IS NOT NULL THEN v_media_meta := jsonb_build_object('mediaKey', p_payload->'message'->v_msg_subkey->>'mediaKey', 'directPath', p_payload->'message'->v_msg_subkey->>'directPath', 'mimetype', p_payload->'message'->v_msg_subkey->>'mimetype', 'ptt', p_payload->'message'->v_msg_subkey->>'ptt'); END IF;
INSERT INTO zapp.evolution_contacts (remote_jid, push_name, instance_name, first_contact_at) VALUES (v_remote_jid, CASE WHEN NOT v_from_me THEN v_push_name END, p_instance, now())
ON CONFLICT (remote_jid) DO UPDATE SET push_name=COALESCE(CASE WHEN NOT v_from_me THEN v_push_name END, evolution_contacts.push_name), updated_at=now() RETURNING id INTO v_contact_id;
SELECT NOT EXISTS (SELECT 1 FROM zapp.evolution_messages WHERE message_id = v_message_id AND instance_name = p_instance) INTO v_is_new;
INSERT INTO zapp.evolution_conversations (remote_jid, contact_id, last_message_content, last_message_type, last_message_at, last_inbound_at, last_outbound_at, unread_count, status, instance_name, first_message_at)
VALUES (v_remote_jid, v_contact_id, LEFT(COALESCE(v_content,''),200), v_message_type, now(), CASE WHEN NOT v_from_me THEN now() END, CASE WHEN v_from_me THEN now() END, CASE WHEN NOT v_from_me AND v_is_new THEN 1 ELSE 0 END, 'aberta', p_instance, now())
ON CONFLICT (remote_jid, instance_name) DO UPDATE SET contact_id=COALESCE(evolution_conversations.contact_id, EXCLUDED.contact_id), last_message_content=LEFT(COALESCE(v_content,''),200), last_message_type=v_message_type, last_message_at=now(), last_inbound_at=CASE WHEN NOT v_from_me THEN now() ELSE evolution_conversations.last_inbound_at END, last_outbound_at=CASE WHEN v_from_me THEN now() ELSE evolution_conversations.last_outbound_at END, unread_count=CASE WHEN NOT v_from_me AND v_is_new THEN COALESCE(evolution_conversations.unread_count,0)+1 ELSE evolution_conversations.unread_count END, updated_at=now() RETURNING id INTO v_conversation_id;
INSERT INTO zapp.evolution_messages (message_id, remote_jid, contact_id, conversation_id, from_me, content, message_type, push_name, media_type, media_url, media_mimetype, media_filename, caption, status, direction, instance_name, link_preview, media_meta)
VALUES (v_message_id, v_remote_jid, v_contact_id, v_conversation_id, v_from_me, v_content, v_message_type, v_push_name, v_media_type, v_media_url, v_media_mimetype, v_media_filename, v_caption, CASE WHEN v_from_me THEN 'sent' ELSE 'received' END, CASE WHEN v_from_me THEN 'outbound' ELSE 'inbound' END, p_instance, v_link_preview, v_media_meta)
ON CONFLICT (message_id, instance_name) DO UPDATE SET
  content = CASE
    WHEN NULLIF(EXCLUDED.content,'') IS NULL THEN evolution_messages.content
    WHEN evolution_messages.content IS NULL OR evolution_messages.content = '' THEN EXCLUDED.content
    WHEN evolution_messages.edited_at IS NOT NULL THEN EXCLUDED.content
    ELSE evolution_messages.content
  END,
  media_url = COALESCE(EXCLUDED.media_url, evolution_messages.media_url),
  media_filename = COALESCE(EXCLUDED.media_filename, evolution_messages.media_filename),
  media_mimetype = COALESCE(EXCLUDED.media_mimetype, evolution_messages.media_mimetype),
  status = CASE
    WHEN evolution_messages.status = 'deleted' THEN evolution_messages.status
    WHEN evolution_messages.status = 'read' AND EXCLUDED.status NOT IN ('deleted','failed') THEN evolution_messages.status
    WHEN evolution_messages.status = 'played' AND EXCLUDED.status IN ('received','pending','sent','delivered') THEN evolution_messages.status
    WHEN evolution_messages.status = 'delivered' AND EXCLUDED.status IN ('received','pending','sent') THEN evolution_messages.status
    WHEN evolution_messages.status = 'sent' AND EXCLUDED.status IN ('received','pending') THEN evolution_messages.status
    ELSE EXCLUDED.status
  END,
  link_preview = COALESCE(EXCLUDED.link_preview, evolution_messages.link_preview),
  media_meta = CASE
    WHEN EXCLUDED.media_meta IS NULL THEN evolution_messages.media_meta
    ELSE NULLIF(COALESCE(evolution_messages.media_meta,'{}') || jsonb_strip_nulls(EXCLUDED.media_meta), '{}')
  END,
  updated_at = now()
RETURNING id, (created_at = now()) INTO v_msg_pk, v_is_new;
RETURN jsonb_build_object('ok',true,'remote_jid',v_remote_jid,'message_external_id',v_message_id,'contact_id',v_contact_id,'conversation_id',v_conversation_id,'message_pk',v_msg_pk,'from_me',v_from_me,'message_type',v_message_type,'is_new_message',COALESCE(v_is_new,true),'media_url_extracted',v_media_url IS NOT NULL,'media_filename_extracted',v_media_filename IS NOT NULL,'media_meta_populated',v_media_meta IS NOT NULL,'link_preview_populated',v_link_preview IS NOT NULL);
EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('ok',false,'error',SQLERRM,'error_detail',SQLSTATE,'remote_jid',v_remote_jid,'message_external_id',v_message_id);
END;
$_$;


ALTER FUNCTION zapp.fn_process_whatsapp_message(p_payload jsonb, p_instance text) OWNER TO postgres;

--
-- Name: FUNCTION fn_process_whatsapp_message(p_payload jsonb, p_instance text); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.fn_process_whatsapp_message(p_payload jsonb, p_instance text) IS 'Processa payload messages.upsert da Evolution API.
FIX #3A 2026-07-26: Content replay attack guard — content só atualizado se vazio/editado.
FIX #3B 2026-07-26: Status progression guard — status nunca regride (read não volta a delivered).
FIX #4  2026-07-26: Instance validation — rejeita instâncias sem partição e sem connection.';


--
-- Name: fn_purge_api_key_from_logs(text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_purge_api_key_from_logs(p_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'public'
    AS $$
DECLARE
  v_redacted CONSTANT text := '[REDACTED-E3-04]';
  v_result   jsonb     := '{}';
  v_n        bigint;
BEGIN
  IF p_key IS NULL OR length(p_key) < 16 THEN
    RAISE EXCEPTION 'E3-04: p_key must be >= 16 characters to prevent accidental mass-redaction';
  END IF;

  UPDATE archive._audit_whatsapp_connections_2026_05_04
    SET api_key = v_redacted
    WHERE api_key = p_key;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n > 0 THEN v_result := v_result || jsonb_build_object('archive._audit_connections.api_key', v_n); END IF;

  UPDATE cron.job_run_details
    SET command        = replace(command,        p_key, v_redacted),
        return_message = replace(return_message, p_key, v_redacted)
    WHERE command        LIKE '%' || p_key || '%'
       OR return_message LIKE '%' || p_key || '%';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n > 0 THEN v_result := v_result || jsonb_build_object('cron.job_run_details', v_n); END IF;

  -- tabelas evo via contrato (rpc_boundary_scrub_secret): bootstrap_log + webhook_events_v2
  v_result := v_result || COALESCE((evo.rpc_boundary_scrub_secret(p_key))->'detail', '{}'::jsonb);

  UPDATE zapp.evolution_audit_log
    SET old_values = CASE WHEN old_values::text LIKE '%' || p_key || '%'
                          THEN replace(old_values::text, p_key, v_redacted)::jsonb
                          ELSE old_values END,
        new_values = CASE WHEN new_values::text LIKE '%' || p_key || '%'
                          THEN replace(new_values::text, p_key, v_redacted)::jsonb
                          ELSE new_values END,
        metadata   = CASE WHEN metadata::text LIKE '%' || p_key || '%'
                          THEN replace(metadata::text, p_key, v_redacted)::jsonb
                          ELSE metadata END
    WHERE old_values::text LIKE '%' || p_key || '%'
       OR new_values::text LIKE '%' || p_key || '%'
       OR metadata::text   LIKE '%' || p_key || '%';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n > 0 THEN v_result := v_result || jsonb_build_object('zapp.evolution_audit_log', v_n); END IF;

  UPDATE zapp.evolution_health_logs
    SET error_message = replace(error_message, p_key, v_redacted),
        metadata = CASE WHEN metadata::text LIKE '%' || p_key || '%'
                        THEN replace(metadata::text, p_key, v_redacted)::jsonb
                        ELSE metadata END
    WHERE error_message LIKE '%' || p_key || '%'
       OR metadata::text LIKE '%' || p_key || '%';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n > 0 THEN v_result := v_result || jsonb_build_object('zapp.evolution_health_logs', v_n); END IF;

  UPDATE zapp.evolution_webhook_dlq
    SET payload = CASE WHEN payload::text LIKE '%' || p_key || '%'
                       THEN replace(payload::text, p_key, v_redacted)::jsonb
                       ELSE payload END,
        raw_payload   = replace(raw_payload,   p_key, v_redacted),
        error_message = replace(error_message, p_key, v_redacted)
    WHERE payload::text   LIKE '%' || p_key || '%'
       OR raw_payload     LIKE '%' || p_key || '%'
       OR error_message   LIKE '%' || p_key || '%';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n > 0 THEN v_result := v_result || jsonb_build_object('zapp.evolution_webhook_dlq', v_n); END IF;

  UPDATE ops.ddl_audit
    SET query = replace(query, p_key, v_redacted)
    WHERE query LIKE '%' || p_key || '%';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n > 0 THEN v_result := v_result || jsonb_build_object('ops.ddl_audit', v_n); END IF;

  UPDATE zapp.webhook_audit_log
    SET request_body = CASE WHEN request_body::text LIKE '%' || p_key || '%'
                            THEN replace(request_body::text, p_key, v_redacted)::jsonb
                            ELSE request_body END,
        response_body = CASE WHEN response_body::text LIKE '%' || p_key || '%'
                             THEN replace(response_body::text, p_key, v_redacted)::jsonb
                             ELSE response_body END,
        error_message = replace(error_message, p_key, v_redacted)
    WHERE request_body::text  LIKE '%' || p_key || '%'
       OR response_body::text LIKE '%' || p_key || '%'
       OR error_message       LIKE '%' || p_key || '%';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n > 0 THEN v_result := v_result || jsonb_build_object('zapp.webhook_audit_log', v_n); END IF;

  UPDATE zapp.provider_message_log
    SET request_body = CASE WHEN request_body::text LIKE '%' || p_key || '%'
                            THEN replace(request_body::text, p_key, v_redacted)::jsonb
                            ELSE request_body END,
        response_body = CASE WHEN response_body::text LIKE '%' || p_key || '%'
                             THEN replace(response_body::text, p_key, v_redacted)::jsonb
                             ELSE response_body END,
        payload = CASE WHEN payload::text LIKE '%' || p_key || '%'
                       THEN replace(payload::text, p_key, v_redacted)::jsonb
                       ELSE payload END,
        error_message = replace(error_message, p_key, v_redacted)
    WHERE request_body::text  LIKE '%' || p_key || '%'
       OR response_body::text LIKE '%' || p_key || '%'
       OR payload::text       LIKE '%' || p_key || '%'
       OR error_message       LIKE '%' || p_key || '%';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n > 0 THEN v_result := v_result || jsonb_build_object('zapp.provider_message_log', v_n); END IF;

  UPDATE zapp.system_logs
    SET message  = replace(message, p_key, v_redacted),
        metadata = CASE WHEN metadata::text LIKE '%' || p_key || '%'
                        THEN replace(metadata::text, p_key, v_redacted)::jsonb
                        ELSE metadata END
    WHERE message        LIKE '%' || p_key || '%'
       OR metadata::text LIKE '%' || p_key || '%';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n > 0 THEN v_result := v_result || jsonb_build_object('zapp.system_logs', v_n); END IF;

  RETURN jsonb_build_object(
    'purged_at',      now(),
    'key_prefix',     left(p_key, 4) || repeat('*', GREATEST(0, length(p_key) - 4)),
    'tables_hit',     (SELECT count(*)::int FROM jsonb_object_keys(v_result)),
    'detail',         v_result
  );
END $$;


ALTER FUNCTION zapp.fn_purge_api_key_from_logs(p_key text) OWNER TO postgres;

--
-- Name: FUNCTION fn_purge_api_key_from_logs(p_key text); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.fn_purge_api_key_from_logs(p_key text) IS 'E3-04: Redacts a leaked Evolution API key from all log/audit/webhook tables. Operator must supply the actual key value — never hardcoded in this file. Safe to re-run (idempotent: already-redacted rows are skipped by LIKE filter). Usage: SELECT public.fn_purge_api_key_from_logs(''<actual-key-here'');';


--
-- Name: fn_purge_warroom_alerts(integer, integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_purge_warroom_alerts(p_resolved_days integer DEFAULT 30, p_all_days integer DEFAULT 90) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'public'
    AS $$
DECLARE
  v_resolved bigint := 0;
  v_old      bigint := 0;
BEGIN
  -- 1: resolvidos com mais de p_resolved_days dias
  DELETE FROM zapp.warroom_alerts
  WHERE resolved_at IS NOT NULL
    AND resolved_at < now() - (p_resolved_days || ' days')::interval;
  GET DIAGNOSTICS v_resolved = ROW_COUNT;

  -- 2: qualquer alerta com mais de p_all_days dias (independente de status)
  DELETE FROM zapp.warroom_alerts
  WHERE created_at < now() - (p_all_days || ' days')::interval;
  GET DIAGNOSTICS v_old = ROW_COUNT;

  INSERT INTO ops.maintenance_log (job, details, ran_at)
  VALUES ('fn_purge_warroom_alerts',
    jsonb_build_object('resolvidos_purged', v_resolved, 'antigos_purged', v_old,
                       'total', v_resolved + v_old,
                       'retencoes', jsonb_build_object('resolved_days', p_resolved_days, 'all_days', p_all_days)),
    now())
  ON CONFLICT DO NOTHING;

  RETURN jsonb_build_object('resolvidos_purged', v_resolved, 'antigos_purged', v_old,
                             'total_deleted', v_resolved + v_old);
END $$;


ALTER FUNCTION zapp.fn_purge_warroom_alerts(p_resolved_days integer, p_all_days integer) OWNER TO postgres;

--
-- Name: fn_purge_webhook_logs(interval); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_purge_webhook_logs(older_than interval DEFAULT '90 days'::interval) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog'
    AS $$
DECLARE
  v_total bigint := 0;
  v_batch bigint;
BEGIN
  LOOP
    DELETE FROM zapp.webhook_audit_log
    WHERE id IN (
      SELECT id FROM zapp.webhook_audit_log
      WHERE created_at < now() - older_than
      LIMIT 5000
    );
    GET DIAGNOSTICS v_batch = ROW_COUNT;
    v_total := v_total + v_batch;
    EXIT WHEN v_batch = 0;
    PERFORM pg_sleep(0.2);
  END LOOP;
  LOOP
    DELETE FROM zapp.webhook_events_processed
    WHERE id IN (
      SELECT id FROM zapp.webhook_events_processed
      WHERE processed_at < now() - older_than
      LIMIT 5000
    );
    GET DIAGNOSTICS v_batch = ROW_COUNT;
    v_total := v_total + v_batch;
    EXIT WHEN v_batch = 0;
    PERFORM pg_sleep(0.2);
  END LOOP;
  INSERT INTO ops.maintenance_log (job, details, ran_at)
  VALUES ('fn_purge_webhook_logs',
          jsonb_build_object('older_than', older_than, 'deleted_rows', v_total),
          now())
  ON CONFLICT DO NOTHING;
  RETURN v_total;
END;
$$;


ALTER FUNCTION zapp.fn_purge_webhook_logs(older_than interval) OWNER TO postgres;

--
-- Name: fn_queue_autoassign_tick(integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_queue_autoassign_tick(p_limit integer DEFAULT 300) RETURNS TABLE(assigned integer, enqueued integer)
    LANGUAGE plpgsql
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$
DECLARE r record; v_agent uuid; v_q uuid; v_a int:=0; v_e int:=0;
BEGIN
  FOR r IN
    SELECT ec.id AS contact_id, q.id AS queue_id
    FROM zapp.evolution_contacts ec
    CROSS JOIN LATERAL (
       SELECT id FROM zapp.queues
        WHERE COALESCE(status,'active')='active' AND COALESCE(auto_assign,true) AND COALESCE(is_active,true)
        ORDER BY priority DESC, created_at ASC LIMIT 1
    ) q
    WHERE ec.deleted_at IS NULL AND ec.assigned_to IS NULL
      AND ( ec.id IN (SELECT contact_id FROM zapp.queue_positions)
            OR (ec.last_message_at > now() - interval '15 minutes'
                AND COALESCE(ec.lead_status,'open') NOT IN ('resolved','closed')) )
    LIMIT p_limit
  LOOP
    v_q := r.queue_id;
    SELECT p.user_id INTO v_agent
    FROM zapp.queue_members qm JOIN zapp.profiles p ON p.id=qm.profile_id
    WHERE qm.queue_id=v_q AND COALESCE(qm.is_active,true) AND COALESCE(p.is_active,true) AND COALESCE(p.is_online,false)
      AND ( SELECT count(*) FROM zapp.evolution_contacts a WHERE a.assigned_to=p.user_id::text AND COALESCE(a.lead_status,'open') NOT IN ('resolved','closed') )
          < COALESCE(qm.max_simultaneous, p.max_chats, 10)
    ORDER BY ( SELECT count(*) FROM zapp.evolution_contacts a WHERE a.assigned_to=p.user_id::text AND COALESCE(a.lead_status,'open') NOT IN ('resolved','closed') ) ASC, random()
    LIMIT 1;
    IF v_agent IS NOT NULL THEN
      UPDATE zapp.evolution_contacts SET assigned_to=v_agent::text, queue_id=v_q, updated_at=now() WHERE id=r.contact_id;
      v_a:=v_a+1;
    ELSE
      PERFORM zapp.fn_queue_enqueue(r.contact_id, v_q); v_e:=v_e+1;
    END IF;
    v_agent:=NULL;
  END LOOP;
  RETURN QUERY SELECT v_a, v_e;
END $$;


ALTER FUNCTION zapp.fn_queue_autoassign_tick(p_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_queue_autoassign_tick(p_limit integer); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.fn_queue_autoassign_tick(p_limit integer) IS 'Roteador automatico v1 (pg-cron 1min). Escopo: inbound <15min ou ja enfileirado, sem agente. Atribui a agente online+com folga (menos carregado); senao enfileira. Backlog historico fora de escopo. Kill switch: UPDATE zapp.queues SET auto_assign=false, ou cron.unschedule(queue-autoassign-tick).';


--
-- Name: fn_queue_dequeue(uuid); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_queue_dequeue(p_contact_id uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$
DECLARE v_queue uuid; v_pos integer;
BEGIN
  SELECT queue_id, position INTO v_queue, v_pos
    FROM zapp.queue_positions WHERE contact_id = p_contact_id;
  IF NOT FOUND THEN RETURN false; END IF;
  DELETE FROM zapp.queue_positions WHERE contact_id = p_contact_id;
  UPDATE zapp.queue_positions SET position = position - 1
   WHERE queue_id = v_queue AND position > v_pos;
  RETURN true;
END $$;


ALTER FUNCTION zapp.fn_queue_dequeue(p_contact_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_queue_dequeue(p_contact_id uuid); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.fn_queue_dequeue(p_contact_id uuid) IS 'Remove contato de queue_positions e renumera. Contraparte do enqueue - chamar quando o contato e atribuido.';


--
-- Name: fn_queue_enqueue(uuid, uuid); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_queue_enqueue(p_contact_id uuid, p_queue_id uuid) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$
DECLARE v_pos integer; v_cur_queue uuid;
BEGIN
  IF p_contact_id IS NULL OR p_queue_id IS NULL THEN
    RAISE EXCEPTION 'contact_id e queue_id obrigatorios';
  END IF;
  SELECT queue_id, position INTO v_cur_queue, v_pos
    FROM zapp.queue_positions WHERE contact_id = p_contact_id;
  IF FOUND THEN
    IF v_cur_queue = p_queue_id THEN RETURN v_pos;
    ELSE PERFORM zapp.fn_queue_dequeue(p_contact_id); END IF;
  END IF;
  SELECT COALESCE(MAX(position),0)+1 INTO v_pos
    FROM zapp.queue_positions WHERE queue_id = p_queue_id;
  INSERT INTO zapp.queue_positions(contact_id, queue_id, position, entered_at, created_at, notified)
  VALUES (p_contact_id, p_queue_id, v_pos, now(), now(), false);
  RETURN v_pos;
END $$;


ALTER FUNCTION zapp.fn_queue_enqueue(p_contact_id uuid, p_queue_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION fn_queue_enqueue(p_contact_id uuid, p_queue_id uuid); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.fn_queue_enqueue(p_contact_id uuid, p_queue_id uuid) IS 'Enfileira contato em queue_positions (FIFO, idempotente, 1 fila por contato). Produtor da fila de espera - issues #1000/#1001. Ainda NAO ligado a gatilho automatico.';


