--
-- Name: fn_rate_limit_check(text, text, integer, integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_rate_limit_check(p_identifier text, p_rpc_name text, p_max_calls integer DEFAULT 60, p_window_minutes integer DEFAULT 1) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog'
    AS $_$
DECLARE
  v_count int;
  v_ws    timestamptz;
  v_id    text;
  v_rpc   text;
BEGIN
  -- Normalise: strip ALL whitespace (space, tab, newline, carriage-return)
  v_id  := regexp_replace(p_identifier, '^[\s]+|[\s]+$', '', 'g');
  v_rpc := regexp_replace(p_rpc_name,   '^[\s]+|[\s]+$', '', 'g');

  -- Fail-closed: NULL, empty-after-trim, zero/negative numeric args
  IF p_identifier IS NULL OR v_id = ''
    OR p_rpc_name IS NULL OR v_rpc = ''
    OR p_window_minutes IS NULL OR p_window_minutes <= 0
    OR p_max_calls IS NULL OR p_max_calls <= 0
  THEN
    RETURN FALSE;
  END IF;

  v_ws := to_timestamp(
    floor(EXTRACT(epoch FROM now()) / (p_window_minutes * 60))
    * (p_window_minutes * 60)
  );

  INSERT INTO rpc_rate_limits (identifier, rpc_name, window_start, call_count)
  VALUES (v_id, v_rpc, v_ws, 1)
  ON CONFLICT (identifier, rpc_name, window_start)
    DO UPDATE SET call_count = rpc_rate_limits.call_count + 1
  RETURNING call_count INTO v_count;

  RETURN v_count <= p_max_calls;
END;
$_$;


ALTER FUNCTION zapp.fn_rate_limit_check(p_identifier text, p_rpc_name text, p_max_calls integer, p_window_minutes integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_rate_limit_check(p_identifier text, p_rpc_name text, p_max_calls integer, p_window_minutes integer); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.fn_rate_limit_check(p_identifier text, p_rpc_name text, p_max_calls integer, p_window_minutes integer) IS 'Rate limiter canonico por (identifier, rpc_name, janela de p_window_minutes minutos). Grava em zapp.rpc_rate_limits. Retorna TRUE se dentro do limite, FALSE se estourou. Janela alinhada: floor(epoch/(N*60))*N*60 - garante que multiplas chamadas dentro do mesmo periodo caem na mesma janela. Para N=1 (default): backward-compatible com comportamento anterior. CORRIGIDO 2026-07-17: p_window_minutes agora e USADO (era ignorado antes, janela fixa de 1 min). Callers devem ser fail-CLOSED: negar quando error IS NOT NULL.';


--
-- Name: fn_realtime_events_retention(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_realtime_events_retention() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE v integer;
BEGIN DELETE FROM evolution_realtime_events WHERE created_at<now()-interval '48 hours'; GET DIAGNOSTICS v=ROW_COUNT; RETURN v; EXCEPTION WHEN OTHERS THEN RETURN 0; END; $$;


