--
-- Name: fn_release_quarantine(uuid, text); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.fn_release_quarantine(p_quarantine_id uuid, p_reviewed_by text DEFAULT 'admin'::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'zapp', 'evo', 'public', 'pg_catalog'
    AS $$
DECLARE
  v_q RECORD;
BEGIN
  SELECT * INTO v_q FROM media_quarantine WHERE id = p_quarantine_id;
  IF v_q IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'quarantine record not found');
  END IF;
  UPDATE media_quarantine SET reviewed = true, reviewed_by = p_reviewed_by, reviewed_at = now(), released = true, released_at = now() WHERE id = p_quarantine_id;
  INSERT INTO media_scan_log (message_id, instance_name, scan_type, scan_result, details) VALUES (v_q.message_id, v_q.instance_name, 'manual_review', 'clean', 'Released by ' || p_reviewed_by || '. Original reason: ' || v_q.block_reason);
  RETURN jsonb_build_object('ok', true, 'released', true, 'message_id', v_q.message_id, 'block_reason', v_q.block_reason);
END;
$$;


ALTER FUNCTION zapp.fn_release_quarantine(p_quarantine_id uuid, p_reviewed_by text) OWNER TO supabase_admin;

--
-- Name: fn_replay_failed_webhooks(interval); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_replay_failed_webhooks(p_since interval DEFAULT '24:00:00'::interval) RETURNS TABLE(event_id uuid, event_type text, remote_jid text)
    LANGUAGE plpgsql
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$ BEGIN RETURN QUERY UPDATE zapp.evolution_webhook_events SET processed = false, processed_at = NULL, error_message = NULL WHERE error_message IS NOT NULL AND created_at >= now() - p_since RETURNING id, evolution_webhook_events.event_type, evolution_webhook_events.remote_jid; END $$;


ALTER FUNCTION zapp.fn_replay_failed_webhooks(p_since interval) OWNER TO postgres;

--
-- Name: fn_replay_webhook_event(uuid); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_replay_webhook_event(p_event_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$ DECLARE v_event record; v_result jsonb; BEGIN SELECT * INTO v_event FROM zapp.evolution_webhook_events WHERE id = p_event_id; IF v_event IS NULL THEN RETURN jsonb_build_object('status', 'error', 'message', 'event_id not found'); END IF; UPDATE zapp.evolution_webhook_events SET processed = false, processed_at = NULL, error_message = NULL WHERE id = p_event_id; v_result := jsonb_build_object('status', 'queued_for_replay', 'event_id', p_event_id, 'event_type', v_event.event_type, 'remote_jid', v_event.remote_jid, 'original_error', v_event.error_message, 'original_created', v_event.created_at); INSERT INTO zapp.migration_audit (phase, entity, action, rows_affected, status, notes) VALUES ('operacional', 'webhook_events', 'replay', 1, 'success', format('Event %s re-queued. Original error: %s', p_event_id, COALESCE(v_event.error_message, 'none'))); RETURN v_result; END $$;


ALTER FUNCTION zapp.fn_replay_webhook_event(p_event_id uuid) OWNER TO postgres;

--
-- Name: fn_repontar_filhas_graveyard(boolean); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_repontar_filhas_graveyard(p_dry_run boolean DEFAULT true) RETURNS TABLE(tabela text, linhas_afetadas bigint)
    LANGUAGE plpgsql
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$
DECLARE
  v_g record; v_pares int := 0; v_pulados int := 0; v_n bigint;
  v_msgs bigint := 0; v_conv bigint := 0; v_notif bigint := 0; v_status bigint := 0; v_events bigint := 0;
BEGIN
  IF p_dry_run THEN RAISE NOTICE 'fn_repontar_filhas_graveyard: DRY RUN';
  ELSE RAISE NOTICE 'fn_repontar_filhas_graveyard: MODO REAL'; END IF;
  FOR v_g IN SELECT * FROM evo.rpc_boundary_graveyard_pairs()
  LOOP
    v_pares := v_pares + 1;
    IF p_dry_run THEN SELECT count(*) INTO v_n FROM zapp.evolution_messages WHERE contact_id=v_g.deleted_contact_id;
    ELSE UPDATE zapp.evolution_messages SET contact_id=v_g.merged_into_contact_id WHERE contact_id=v_g.deleted_contact_id; GET DIAGNOSTICS v_n = ROW_COUNT; END IF;
    v_msgs := v_msgs + v_n;
    IF p_dry_run THEN SELECT count(*) INTO v_n FROM zapp.evolution_conversations WHERE contact_id=v_g.deleted_contact_id;
    ELSE UPDATE zapp.evolution_conversations SET contact_id=v_g.merged_into_contact_id WHERE contact_id=v_g.deleted_contact_id; GET DIAGNOSTICS v_n = ROW_COUNT; END IF;
    v_conv := v_conv + v_n;
    IF p_dry_run THEN SELECT count(*) INTO v_n FROM zapp.evolution_notifications WHERE contact_id=v_g.deleted_contact_id;
    ELSE UPDATE zapp.evolution_notifications SET contact_id=v_g.merged_into_contact_id WHERE contact_id=v_g.deleted_contact_id; GET DIAGNOSTICS v_n = ROW_COUNT; END IF;
    v_notif := v_notif + v_n;
    IF p_dry_run THEN SELECT count(*) INTO v_n FROM zapp.evolution_whatsapp_status WHERE contact_id=v_g.deleted_contact_id;
    ELSE UPDATE zapp.evolution_whatsapp_status SET contact_id=v_g.merged_into_contact_id WHERE contact_id=v_g.deleted_contact_id; GET DIAGNOSTICS v_n = ROW_COUNT; END IF;
    v_status := v_status + v_n;
    IF p_dry_run THEN SELECT count(*) INTO v_n FROM zapp.conversation_events WHERE contact_id=v_g.deleted_contact_id;
    ELSE UPDATE zapp.conversation_events SET contact_id=v_g.merged_into_contact_id WHERE contact_id=v_g.deleted_contact_id; GET DIAGNOSTICS v_n = ROW_COUNT; END IF;
    v_events := v_events + v_n;
  END LOOP;
  SELECT evo.rpc_boundary_graveyard_pending_count() INTO v_pulados;
  IF v_pulados > 0 THEN RAISE NOTICE '  pares PULADOS: %', v_pulados; END IF;
  tabela := 'zapp.evolution_messages';       linhas_afetadas := v_msgs;   RETURN NEXT;
  tabela := 'zapp.evolution_conversations';  linhas_afetadas := v_conv;   RETURN NEXT;
  tabela := 'zapp.evolution_notifications'; linhas_afetadas := v_notif;  RETURN NEXT;
  tabela := 'zapp.evolution_whatsapp_status'; linhas_afetadas := v_status; RETURN NEXT;
  tabela := 'zapp.conversation_events';     linhas_afetadas := v_events; RETURN NEXT;
END; $$;


ALTER FUNCTION zapp.fn_repontar_filhas_graveyard(p_dry_run boolean) OWNER TO postgres;

--
-- Name: fn_report_to_csv(jsonb); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_report_to_csv(p_data jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
  v_keys   text[];
  v_row    jsonb;
  v_key    text;
  v_val    text;
  v_line   text;
  v_csv    text := '';
BEGIN
  IF p_data IS NULL OR jsonb_typeof(p_data) <> 'array'
     OR jsonb_array_length(p_data) = 0 THEN
    RETURN '';
  END IF;

  v_keys := ARRAY(SELECT jsonb_object_keys(jsonb_array_element(p_data, 0)));
  v_csv  := array_to_string(v_keys, ',') || E'\n';

  FOR v_row IN SELECT * FROM jsonb_array_elements(p_data) LOOP
    v_line := '';
    FOREACH v_key IN ARRAY v_keys LOOP
      v_val := COALESCE(v_row ->> v_key, '');
      IF v_val ~ '["\n\r,]' THEN
        v_val := '"' || replace(replace(replace(v_val, '"', '""'), E'\r', ''), E'\n', ' ') || '"';
      END IF;
      v_line := v_line || v_val || ',';
    END LOOP;
    v_csv := v_csv || rtrim(v_line, ',') || E'\n';
  END LOOP;

  RETURN v_csv;
END
$$;


ALTER FUNCTION zapp.fn_report_to_csv(p_data jsonb) OWNER TO postgres;

--
-- Name: FUNCTION fn_report_to_csv(p_data jsonb); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.fn_report_to_csv(p_data jsonb) IS 'Serializa jsonb array de objetos em CSV RFC 4180 (escape " , \\n \\r; \\n vira espaço dentro de campos quotados).';


--
-- Name: fn_reprocess_pending_webhook_events(integer); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.fn_reprocess_pending_webhook_events(p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$
DECLARE
  e RECORD;
  v_ok int := 0;
  v_fail int := 0;
  v_stats jsonb := '{}'::jsonb;
  v_action_count int;
BEGIN
  FOR e IN
    SELECT * FROM evo.rpc_boundary_events_pull(p_limit)
  LOOP
    BEGIN
      IF e.event_type IN ('contacts.upsert','contacts.update','CONTACTS_UPSERT','CONTACTS_UPDATE') THEN
        PERFORM zapp.fn_process_contacts_batch(e.payload, COALESCE(e.instance_name, 'wpp2'));
        v_action_count := COALESCE((v_stats->>'contacts')::int, 0) + 1;
        v_stats := v_stats || jsonb_build_object('contacts', v_action_count);

      ELSIF e.event_type IN ('messages.edited','MESSAGES_EDITED') THEN
        PERFORM zapp.fn_process_message_edited(e.payload, COALESCE(e.instance_name, 'wpp2'));
        v_action_count := COALESCE((v_stats->>'messages_edited')::int, 0) + 1;
        v_stats := v_stats || jsonb_build_object('messages_edited', v_action_count);

      ELSIF e.event_type IN ('chats.update','CHATS_UPDATE') THEN
        PERFORM zapp.fn_process_chat_update(e.payload, COALESCE(e.instance_name, 'wpp2'));
        v_action_count := COALESCE((v_stats->>'chats_update')::int, 0) + 1;
        v_stats := v_stats || jsonb_build_object('chats_update', v_action_count);

      ELSIF e.event_type IN ('messages.upsert','MESSAGES_UPSERT') THEN
        PERFORM zapp.fn_process_whatsapp_message(e.payload, COALESCE(e.instance_name, 'wpp2'));
        v_action_count := COALESCE((v_stats->>'messages_upsert')::int, 0) + 1;
        v_stats := v_stats || jsonb_build_object('messages_upsert', v_action_count);

      ELSE
        v_action_count := COALESCE((v_stats->>'skipped_no_handler')::int, 0) + 1;
        v_stats := v_stats || jsonb_build_object('skipped_no_handler', v_action_count);
      END IF;

      PERFORM evo.rpc_boundary_event_mark_ok(e.id);
      v_ok := v_ok + 1;

    EXCEPTION WHEN OTHERS THEN
      PERFORM evo.rpc_boundary_event_mark_fail(e.id, SQLERRM);
      v_fail := v_fail + 1;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', v_ok,
    'failed', v_fail,
    'distribution', v_stats,
    'source_table', 'evolution_webhook_events_v2',
    'timestamp', NOW()
  );
END $$;


ALTER FUNCTION zapp.fn_reprocess_pending_webhook_events(p_limit integer) OWNER TO supabase_admin;

--
-- Name: fn_require_app_user(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_require_app_user() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM zapp.profiles WHERE user_id = auth.uid())
       OR NOT EXISTS (SELECT 1 FROM zapp.user_roles WHERE user_id = auth.uid())
       AND NOT EXISTS (SELECT 1 FROM zapp.workspace_members WHERE user_id = auth.uid()) THEN
      RAISE EXCEPTION 'forbidden: app member required' USING ERRCODE = '42501';
    END IF;
  END IF;
END;
$$;


ALTER FUNCTION zapp.fn_require_app_user() OWNER TO postgres;

--
-- Name: fn_resolve_agent_for_routing(uuid, uuid, uuid); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.fn_resolve_agent_for_routing(p_contact_id uuid, p_channel_connection_id uuid DEFAULT NULL::uuid, p_queue_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  v_agent_id uuid;
  v_resolved_queue uuid;
  v_strategy text;
  v_required_skills text[];
BEGIN
  -- 1) Sticky: último agente do contato neste canal, ainda válido e ativo
  SELECT s.agent_profile_id, s.queue_id
    INTO v_agent_id, v_resolved_queue
  FROM zapp.sticky_assignments s
  JOIN zapp.profiles p ON p.id = s.agent_profile_id
  WHERE s.contact_id = p_contact_id
    AND (p_channel_connection_id IS NULL OR s.channel_connection_id = p_channel_connection_id)
    AND s.expires_at > now()
    AND p.is_active = true
  ORDER BY s.last_assigned_at DESC
  LIMIT 1;

  IF v_agent_id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'agent_profile_id', v_agent_id,
      'queue_id', v_resolved_queue,
      'strategy', 'sticky'
    );
  END IF;

  -- 2) Resolver fila: parâmetro > regra de roteamento do canal
  v_resolved_queue := p_queue_id;

  IF v_resolved_queue IS NULL AND p_channel_connection_id IS NOT NULL THEN
    SELECT queue_id INTO v_resolved_queue
    FROM zapp.channel_routing_rules
    WHERE channel_connection_id = p_channel_connection_id
      AND queue_id IS NOT NULL
    ORDER BY priority DESC
    LIMIT 1;
  END IF;

  IF v_resolved_queue IS NULL THEN
    RETURN jsonb_build_object(
      'agent_profile_id', NULL,
      'queue_id', NULL,
      'strategy', 'unassigned',
      'reason', 'no_queue_resolved'
    );
  END IF;

  -- 3) Skills exigidas pela fila
  SELECT COALESCE(array_agg(skill_name), ARRAY[]::text[])
    INTO v_required_skills
  FROM zapp.queue_skill_requirements
  WHERE queue_id = v_resolved_queue;

  -- 4) Round-robin: agente da fila com menos atribuições nas últimas 24h, com skills
  SELECT qm.profile_id INTO v_agent_id
  FROM zapp.queue_members qm
  JOIN zapp.profiles p ON p.id = qm.profile_id
  WHERE qm.queue_id = v_resolved_queue
    AND qm.is_active = true
    AND p.is_active = true
    AND (
      array_length(v_required_skills, 1) IS NULL
      OR NOT EXISTS (
        SELECT 1 FROM unnest(v_required_skills) rs(name)
        WHERE NOT EXISTS (
          SELECT 1 FROM zapp.agent_skills s
          WHERE s.profile_id = qm.profile_id AND s.skill_name = rs.name
        )
      )
    )
  ORDER BY (
    SELECT COUNT(*) FROM zapp.sticky_assignments sa
    WHERE sa.agent_profile_id = qm.profile_id
      AND sa.last_assigned_at > now() - interval '24 hours'
  ) ASC, random()
  LIMIT 1;

  IF v_agent_id IS NULL THEN
    RETURN jsonb_build_object(
      'agent_profile_id', NULL,
      'queue_id', v_resolved_queue,
      'strategy', 'unassigned',
      'reason', 'no_eligible_agent'
    );
  END IF;

  RETURN jsonb_build_object(
    'agent_profile_id', v_agent_id,
    'queue_id', v_resolved_queue,
    'strategy', 'round_robin'
  );
END;
$$;


ALTER FUNCTION zapp.fn_resolve_agent_for_routing(p_contact_id uuid, p_channel_connection_id uuid, p_queue_id uuid) OWNER TO supabase_admin;

--
-- Name: fn_resolve_alerts_by_type(text, text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_resolve_alerts_by_type(p_alert_type text, p_resolved_by text DEFAULT 'system'::text) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$
DECLARE v_count integer;
BEGIN
    UPDATE evolution_alerts SET acknowledged=true, acknowledged_at=NOW(), acknowledged_by=p_resolved_by, resolved_at=NOW(), resolved_by=p_resolved_by WHERE alert_type=p_alert_type AND acknowledged=false;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_count;
END;
$$;


ALTER FUNCTION zapp.fn_resolve_alerts_by_type(p_alert_type text, p_resolved_by text) OWNER TO postgres;

--
-- Name: fn_resolve_contact_id_by_jid(text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_resolve_contact_id_by_jid(p_jid text) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog', 'pg_temp'
    AS $$
  SELECT c.id
    FROM zapp.evolution_contacts c
   WHERE c.deleted_at IS NULL
     AND (
           -- 1. Match exato por remote_jid (índice unique)
           lower(c.remote_jid) = lower(p_jid)
        -- 2. Match EXATO por phone_number (índice) — p_jid "55...@s.whatsapp.net" ou "55..."
        OR c.phone_number = split_part(p_jid, '@', 1)
        -- 3. Fallback: phone com formatação arbitrária (guard LID-as-phone 14+ dígitos)
        OR ( regexp_replace(lower(split_part(p_jid,'@',1)),'[^0-9]','','g') <> '' AND regexp_replace(lower(c.phone_number), '[^0-9]', '', 'g')
               = regexp_replace(lower(split_part(p_jid, '@', 1)), '[^0-9]', '', 'g')
           AND length(regexp_replace(c.phone_number, '[^0-9]', '', 'g')) <= 13
           )
     )
   ORDER BY
     CASE
       WHEN lower(c.remote_jid) = lower(p_jid) THEN 1
       WHEN c.phone_number = split_part(p_jid, '@', 1) THEN 2
       ELSE 3
     END,
     c.updated_at DESC NULLS LAST
   LIMIT 1
$$;


ALTER FUNCTION zapp.fn_resolve_contact_id_by_jid(p_jid text) OWNER TO postgres;

--
-- Name: fn_resolve_kpi_alerts_stale(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_resolve_kpi_alerts_stale() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'extensions'
    AS $$
DECLARE
  v_resolved integer;
BEGIN
  WITH resolved AS (
    UPDATE zapp.warroom_alerts
    SET
      resolved_at     = now(),
      resolved_reason = 'Auto-resolvido: trigger KPI não re-disparou nas últimas 4h'
    WHERE source IN (
        'evo-wpp2-uptime-kpi',
        'evo-instance-health-check',
        'evo-default-partition-guard',
        'host-disk-collector-guard'
      )
      AND resolved_at IS NULL
      AND created_at < now() - interval '4 hours'
    RETURNING id
  )
  SELECT COUNT(*) INTO v_resolved FROM resolved;
  RETURN v_resolved;
END;
$$;


ALTER FUNCTION zapp.fn_resolve_kpi_alerts_stale() OWNER TO postgres;

--
-- Name: FUNCTION fn_resolve_kpi_alerts_stale(); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.fn_resolve_kpi_alerts_stale() IS 'Auto-resolve alertas de KPI (uptime, instance health, etc.) que não foram re-disparados nas últimas 4 horas, indicando normalização. Executado via cron kpi-alerts-auto-resolve a cada hora (minuto 55).';


--
-- Name: fn_resolve_stale_connection_alerts(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_resolve_stale_connection_alerts() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'pg_catalog'
    AS $$
DECLARE v_n int;
BEGIN
  WITH latest AS (
    SELECT DISTINCT ON (instance_name) instance_name, state, created_at
    FROM public.evo_connection_history
    ORDER BY instance_name, created_at DESC
  ),
  connected AS (
    SELECT instance_name, created_at AS connected_at FROM latest WHERE state = 'connected'
  ),
  upd AS (
    UPDATE zapp.warroom_alerts w
    SET resolved_at = now(),
        resolved_reason = 'auto: instancia reconectada ('||c.instance_name||') em '||to_char(c.connected_at,'YYYY-MM-DD HH24:MI')
    FROM connected c
    WHERE w.resolved_at IS NULL
      AND w.source = 'evolution-webhook'
      AND w.alert_type = 'critical'
      AND (w.title ILIKE '%deslogada%' OR w.title ILIKE '%desconect%')
      AND w.title ILIKE '%'||c.instance_name||'%'
      AND w.created_at <= c.connected_at
    RETURNING 1
  )
  SELECT count(*) INTO v_n FROM upd;
  RETURN v_n;
END $$;


ALTER FUNCTION zapp.fn_resolve_stale_connection_alerts() OWNER TO postgres;

--
-- Name: fn_response_time_analysis(text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_response_time_analysis(p_instance text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$
DECLARE v jsonb;
BEGIN SELECT jsonb_build_object('avg_response_minutes',(SELECT round(avg(EXTRACT(EPOCH FROM (last_outbound_at-last_inbound_at))/60)::numeric,1) FROM evolution_conversations WHERE last_inbound_at IS NOT NULL AND last_outbound_at IS NOT NULL AND last_outbound_at>last_inbound_at AND (p_instance IS NULL OR instance_name=p_instance)),'total_conversations',(SELECT count(*) FROM evolution_conversations WHERE (p_instance IS NULL OR instance_name=p_instance))) INTO v; RETURN v; END; $$;


ALTER FUNCTION zapp.fn_response_time_analysis(p_instance text) OWNER TO postgres;

--
-- Name: fn_retention_audit_tables(); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.fn_retention_audit_tables() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'archive', 'zapp', 'pg_temp'
    AS $$
DECLARE v_r jsonb := '{}'; v_c bigint;
BEGIN
  BEGIN DELETE FROM archive.audit_dump_chunks WHERE created_at < now() - interval '90 days'; GET DIAGNOSTICS v_c = ROW_COUNT; v_r := v_r || jsonb_build_object('audit_dump', v_c); EXCEPTION WHEN OTHERS THEN NULL; END;
  BEGIN DELETE FROM zapp.audit_log_tables WHERE created_at < now() - interval '90 days'; GET DIAGNOSTICS v_c = ROW_COUNT; v_r := v_r || jsonb_build_object('audit_log_tables', v_c); EXCEPTION WHEN OTHERS THEN NULL; END;
  RETURN v_r;
END;
$$;


ALTER FUNCTION zapp.fn_retention_audit_tables() OWNER TO supabase_admin;

--
-- Name: fn_retention_cleanup(integer, integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_retention_cleanup(p_processed_days integer DEFAULT 7, p_unprocessed_days integer DEFAULT 30) RETURNS TABLE(deleted_processed bigint, deleted_unprocessed bigint, freed_bytes text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE v_del_proc bigint; v_del_unproc bigint; v_size_before bigint; v_size_after bigint;
BEGIN
  v_size_before := pg_total_relation_size('evolution_webhook_events');
  DELETE FROM evolution_webhook_events WHERE processed=true AND created_at < NOW()-make_interval(days=>p_processed_days);
  GET DIAGNOSTICS v_del_proc = ROW_COUNT;
  DELETE FROM evolution_webhook_events WHERE processed=false AND created_at < NOW()-make_interval(days=>p_unprocessed_days);
  GET DIAGNOSTICS v_del_unproc = ROW_COUNT;
  v_size_after := pg_total_relation_size('evolution_webhook_events');
  INSERT INTO evolution_retention_log (processed_days_kept,unprocessed_days_kept,deleted_processed,deleted_unprocessed,freed_bytes_pretty,freed_bytes_raw,duration_ms,triggered_by)
  VALUES (p_processed_days,p_unprocessed_days,v_del_proc,v_del_unproc,pg_size_pretty(v_size_before-v_size_after),v_size_before-v_size_after,0,'manual');
  RETURN QUERY SELECT v_del_proc, v_del_unproc, pg_size_pretty(v_size_before-v_size_after);
END $$;


ALTER FUNCTION zapp.fn_retention_cleanup(p_processed_days integer, p_unprocessed_days integer) OWNER TO postgres;

--
-- Name: fn_retention_old_alerts(); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.fn_retention_old_alerts() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE v_total integer := 0; v_tmp integer;
BEGIN
  DELETE FROM zapp.evolution_alerts 
  WHERE resolved_at IS NOT NULL AND resolved_at < now() - interval '60 days';
  GET DIAGNOSTICS v_tmp = ROW_COUNT;
  v_total := v_total + v_tmp;
  
  DELETE FROM zapp.evolution_alerts 
  WHERE acknowledged = true AND created_at < now() - interval '90 days';
  GET DIAGNOSTICS v_tmp = ROW_COUNT;
  v_total := v_total + v_tmp;
  
  RETURN v_total;
END;
$$;


ALTER FUNCTION zapp.fn_retention_old_alerts() OWNER TO supabase_admin;

--
-- Name: fn_retention_webhook_events(integer, integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_retention_webhook_events(p_proc_days integer DEFAULT 30, p_unproc_days integer DEFAULT 90) RETURNS TABLE(deleted_processed bigint, deleted_unprocessed bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE v_proc bigint:=0; v_unproc bigint:=0;
BEGIN
  DELETE FROM evolution_webhook_events WHERE processed=true AND created_at<now()-(p_proc_days||' days')::interval; GET DIAGNOSTICS v_proc=ROW_COUNT;
  DELETE FROM evolution_webhook_events WHERE processed=false AND created_at<now()-(p_unproc_days||' days')::interval; GET DIAGNOSTICS v_unproc=ROW_COUNT;
  RETURN QUERY SELECT v_proc, v_unproc;
END; $$;


ALTER FUNCTION zapp.fn_retention_webhook_events(p_proc_days integer, p_unproc_days integer) OWNER TO postgres;

--
-- Name: fn_retention_webhook_events_aggressive(); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.fn_retention_webhook_events_aggressive() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE v_total bigint := 0; v_tmp bigint;
BEGIN
  DELETE FROM zapp.evolution_webhook_events 
  WHERE processed = true AND created_at < now() - interval '14 days';
  GET DIAGNOSTICS v_tmp = ROW_COUNT;
  v_total := v_total + v_tmp;
  
  DELETE FROM zapp.evolution_webhook_events 
  WHERE created_at < now() - interval '30 days';
  GET DIAGNOSTICS v_tmp = ROW_COUNT;
  v_total := v_total + v_tmp;
  
  RETURN v_total;
END;
$$;


