--
-- Name: fn_run_media_health_alert(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_run_media_health_alert() RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$ DECLARE v_report RECORD; v_alert_count int := 0; v_alert_msg text := ''; BEGIN UPDATE zapp.warroom_alerts SET resolved_at=now(), resolved_reason='auto-resolve:healthcheck' WHERE source='media_pipeline' AND resolved_at IS NULL; SELECT (SELECT count(*) FROM public.evo_media_download_queue WHERE status='failed' AND processed_at > now()-interval '1 hour') AS failed_1h, (SELECT count(*) FROM public.evo_media_download_queue WHERE status='pending') AS pending, (SELECT count(*) FROM public.evo_media_download_queue WHERE status='processing' AND processed_at < now()-interval '15 minutes') AS stuck INTO v_report; IF v_report.failed_1h > 10 THEN v_alert_count := v_alert_count + 1; v_alert_msg := v_alert_msg || format('Falhas de download: %s na ultima hora. ', v_report.failed_1h); END IF; IF v_report.pending > 1000 THEN v_alert_count := v_alert_count + 1; v_alert_msg := v_alert_msg || format('Fila com %s pending. ', v_report.pending); END IF; IF v_report.stuck > 5 THEN v_alert_count := v_alert_count + 1; v_alert_msg := v_alert_msg || format('%s itens travados. ', v_report.stuck); END IF; IF v_alert_count > 0 THEN INSERT INTO zapp.warroom_alerts (alert_type, source, severity, title, message) VALUES ((CASE WHEN v_report.failed_1h > 20 THEN 'critical' ELSE 'warning' END)::zapp.warroom_alert_type, 'media_pipeline', CASE WHEN v_report.failed_1h > 20 THEN 'critical' ELSE 'warning' END, '[MEDIA] Pipeline degradado', v_alert_msg) ON CONFLICT DO NOTHING; END IF; END; $$;


ALTER FUNCTION zapp.fn_run_media_health_alert() OWNER TO postgres;

--
-- Name: FUNCTION fn_run_media_health_alert(); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.fn_run_media_health_alert() IS 'Health check da fila de midia (cron 213, a cada 4h): auto-resolve alertas media_pipeline abertos e re-alerta em warroom_alerts se failed_1h>10, pending>1000 ou stuck>5. Corrigido 2026-08-20 (plano 100 etapas): coluna body -> message + cast enum warroom_alert_type (falhava desde a mudanca de schema do warroom).';


--
-- Name: fn_run_scheduled_reports(integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_run_scheduled_reports(p_limit integer DEFAULT 50) RETURNS TABLE(processed integer, success integer, failed integer, skipped integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'public'
    SET statement_timeout TO '120s'
    AS $$
DECLARE
  v_report     record;
  v_sql        text;
  v_data       jsonb;
  v_content    text;
  v_ext        text;
  v_mime       text;
  v_path       text;
  v_next       timestamptz;
  v_limit      integer := GREATEST(1, LEAST(COALESCE(p_limit, 50), 200));
  v_processed  integer := 0;
  v_success    integer := 0;
  v_failed     integer := 0;
  v_skipped    integer := 0;
  v_global_key bigint := hashtext('zapp.fn_run_scheduled_reports');
  v_report_key bigint;
BEGIN
  IF NOT pg_try_advisory_xact_lock(v_global_key) THEN
    RETURN QUERY SELECT 0::integer, 0::integer, 0::integer, 0::integer;
    RETURN;
  END IF;

  FOR v_report IN
    SELECT r.id, r.name, r.format, r.config, r.schedule, r.frequency
      FROM zapp.scheduled_reports r
     WHERE r.is_active
       AND r.fail_count < 5
       AND (r.next_send_at IS NULL OR r.next_send_at <= now())
       AND EXISTS (
         SELECT 1 FROM zapp.profiles p
          WHERE p.id = r.created_by
            AND zapp.is_admin_or_supervisor(p.user_id)
       )
     ORDER BY r.next_send_at NULLS FIRST
     LIMIT v_limit
  LOOP
    v_processed := v_processed + 1;
    v_report_key := hashtext('zapp.fn_run_scheduled_reports:' || v_report.id::text);

    IF NOT pg_try_advisory_xact_lock(v_report_key) THEN
      INSERT INTO zapp.scheduled_report_runs
        (report_id, status, error, started_at, finished_at)
      VALUES
        (v_report.id, 'skipped_lock', 'advisory lock ocupado (overlap)', now(), now());
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;

    BEGIN
      v_sql := NULLIF(v_report.config ->> 'sql', '');
      IF v_sql IS NULL THEN
        RAISE EXCEPTION 'config.sql vazio — defina a query read-only do relatório';
      END IF;
      IF NOT zapp.fn_validate_report_query(v_sql) THEN
        RAISE EXCEPTION 'query inválida: apenas SELECT/WITH read-only (sem DML/DDL/comentários)';
      END IF;

      EXECUTE format(
        'SELECT coalesce(jsonb_agg(to_jsonb(t)), ''[]''::jsonb) FROM (SELECT * FROM (%s) _inner LIMIT 10000) t',
        v_sql
      ) INTO v_data;

      IF v_report.format = 'csv' THEN
        v_content := zapp.fn_report_to_csv(v_data);
        v_ext     := 'csv';
        v_mime    := 'text/csv';
      ELSE
        v_content := jsonb_pretty(v_data);
        v_ext     := 'json';
        v_mime    := 'application/json';
      END IF;

      v_path := 'reports/' || to_char(now(), 'YYYY/MM/DD') || '/'
                || v_report.id::text || '-' || to_char(now(), 'YYYYMMDDHH24MISS')
                || '.' || v_ext;

      INSERT INTO zapp.scheduled_report_runs
        (report_id, status, content, storage_path, row_count, started_at, finished_at)
      VALUES
        (v_report.id, 'success', v_content, v_path,
         (SELECT count(*) FROM jsonb_array_elements(v_data)),
         now(), now());

      v_next := zapp.fn_calculate_next_send(
        COALESCE(v_report.schedule, v_report.frequency), now()
      );
      UPDATE zapp.scheduled_reports
         SET last_run_at  = now(),
             last_error   = NULL,
             fail_count   = 0,
             next_send_at = v_next,
             updated_at   = now()
       WHERE id = v_report.id;

      v_success := v_success + 1;
    EXCEPTION WHEN OTHERS THEN
      UPDATE zapp.scheduled_reports
         SET last_run_at  = now(),
             last_error   = left(SQLERRM, 500),
             fail_count   = fail_count + 1,
             next_send_at = now() + (interval '15 minutes' * (fail_count + 1)),
             is_active    = CASE WHEN fail_count + 1 >= 5 THEN false ELSE is_active END,
             updated_at   = now()
       WHERE id = v_report.id;

      INSERT INTO zapp.scheduled_report_runs
        (report_id, status, error, started_at, finished_at)
      VALUES
        (v_report.id, 'error', left(SQLERRM, 500), now(), now());

      v_failed := v_failed + 1;
    END;
  END LOOP;

  RETURN QUERY SELECT v_processed, v_success, v_failed, v_skipped;
END
$$;


ALTER FUNCTION zapp.fn_run_scheduled_reports(p_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_run_scheduled_reports(p_limit integer); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.fn_run_scheduled_reports(p_limit integer) IS 'Executor de relatórios agendados (DASHBOARD-16): gera CSV/JSON na outbox scheduled_report_runs; SECURITY DEFINER com advisory locks, statement_timeout 120s, validação read-only e execução restrita a admin/supervisor.';


--
-- Name: fn_safe_audit_log(text, text, uuid, text, text, jsonb, jsonb, jsonb, text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_safe_audit_log(p_action text, p_entity_type text, p_entity_id uuid DEFAULT NULL::uuid, p_performed_by text DEFAULT 'system'::text, p_performed_by_type text DEFAULT 'system'::text, p_old jsonb DEFAULT NULL::jsonb, p_new jsonb DEFAULT NULL::jsonb, p_metadata jsonb DEFAULT NULL::jsonb, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_temp'
    AS $$
DECLARE
  v_id   uuid;
  v_meta jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  IF p_performed_by IS NULL
     OR (p_performed_by IS DISTINCT FROM auth.uid()::text
         AND p_performed_by IS DISTINCT FROM COALESCE((SELECT email FROM auth.users WHERE id = auth.uid()), '')
         AND NOT zapp.is_admin_or_supervisor())
  THEN
    RAISE EXCEPTION 'permission denied';
  END IF;

  v_meta := COALESCE(p_metadata, '{}'::jsonb);
  IF p_notes IS NOT NULL THEN
    v_meta := v_meta || jsonb_build_object('notes', p_notes);
  END IF;

  BEGIN
    BEGIN
      INSERT INTO zapp.evolution_audit_log (
        action, entity_type, entity_id,
        performed_by, performed_by_type,
        old_values, new_values, metadata
      )
      VALUES (
        p_action, p_entity_type, p_entity_id,
        p_performed_by, p_performed_by_type,
        p_old, p_new, v_meta
      )
      RETURNING id INTO v_id;

      RETURN v_id;

    EXCEPTION WHEN check_violation THEN
      BEGIN
        INSERT INTO zapp.evolution_audit_log (
          action, entity_type, entity_id,
          performed_by, performed_by_type,
          old_values, new_values, metadata
        )
        VALUES (
          'action_not_in_vocabulary', p_entity_type, p_entity_id,
          p_performed_by, p_performed_by_type,
          p_old, p_new,
          v_meta || jsonb_build_object('original_action', p_action)
        )
        RETURNING id INTO v_id;

        RETURN v_id;
      EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'fn_safe_audit_log falhou: %', SQLERRM;
        RETURN NULL;
      END;
    END;
  END;
END;
$$;


ALTER FUNCTION zapp.fn_safe_audit_log(p_action text, p_entity_type text, p_entity_id uuid, p_performed_by text, p_performed_by_type text, p_old jsonb, p_new jsonb, p_metadata jsonb, p_notes text) OWNER TO postgres;

--
-- Name: fn_sales_forecast(integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_sales_forecast(p_months integer DEFAULT 3) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$
DECLARE v jsonb; v_avg numeric;
BEGIN
  SELECT COALESCE(avg(value),0) INTO v_avg FROM evolution_deals WHERE stage='pedido_finalizado' AND closed_at>=now()-interval '3 months';
  SELECT jsonb_build_object('avg_deal_value',round(v_avg,2),'forecast_monthly',round(v_avg*(SELECT count(*) FROM evolution_deals WHERE stage NOT IN ('perdido','pedido_finalizado'))/NULLIF(p_months,0),2),'open_deals',(SELECT count(*) FROM evolution_deals WHERE stage NOT IN ('perdido','pedido_finalizado')),'pipeline_value',(SELECT COALESCE(sum(value),0) FROM evolution_deals WHERE stage NOT IN ('perdido','pedido_finalizado'))) INTO v;
  RETURN v;
END; $$;


ALTER FUNCTION zapp.fn_sales_forecast(p_months integer) OWNER TO postgres;

--
-- Name: fn_sales_report(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_sales_report(p_from timestamp with time zone DEFAULT (now() - '30 days'::interval), p_to timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$
DECLARE v jsonb;
BEGIN
  SELECT jsonb_build_object('period',jsonb_build_object('from',p_from,'to',p_to),'deals_created',(SELECT count(*) FROM evolution_deals WHERE created_at BETWEEN p_from AND p_to),'deals_closed',(SELECT count(*) FROM evolution_deals WHERE stage='pedido_finalizado' AND closed_at BETWEEN p_from AND p_to),'total_revenue',(SELECT COALESCE(sum(value),0) FROM evolution_deals WHERE stage='pedido_finalizado' AND closed_at BETWEEN p_from AND p_to),'deals_lost',(SELECT count(*) FROM evolution_deals WHERE stage='perdido' AND updated_at BETWEEN p_from AND p_to)) INTO v;
  RETURN v;
END; $$;


ALTER FUNCTION zapp.fn_sales_report(p_from timestamp with time zone, p_to timestamp with time zone) OWNER TO postgres;

--
-- Name: fn_save_daily_kpis(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_save_daily_kpis() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'public', 'extensions'
    AS $$
DECLARE v jsonb;
BEGIN
  v := zapp.fn_calculate_daily_kpis();
  INSERT INTO evolution_daily_metrics (
    id, metric_date, new_contacts, active_contacts, total_contacts,
    messages_received, messages_sent, avg_response_time_seconds,
    conversations_opened, conversations_resolved, avg_resolution_time_seconds,
    deals_created, deals_won, deals_lost, revenue, pipeline_value,
    lead_to_deal_rate, deal_win_rate, avg_messages_per_contact,
    automations_triggered, followups_sent, calculated_at
  ) VALUES (
    gen_random_uuid(), (v->>'metric_date')::date, (v->>'new_contacts')::int,
    (v->>'active_contacts')::int, (v->>'total_contacts')::int,
    (v->>'messages_received')::int, (v->>'messages_sent')::int,
    (v->>'avg_response_time_seconds')::int, (v->>'conversations_opened')::int,
    (v->>'conversations_resolved')::int, (v->>'avg_resolution_time_seconds')::int,
    (v->>'deals_created')::int, (v->>'deals_won')::int, (v->>'deals_lost')::int,
    (v->>'revenue')::numeric, (v->>'pipeline_value')::numeric,
    (v->>'lead_to_deal_rate')::numeric, (v->>'deal_win_rate')::numeric,
    (v->>'avg_messages_per_contact')::numeric, (v->>'automations_triggered')::int,
    (v->>'followups_sent')::int, now()
  )
  ON CONFLICT (metric_date) DO UPDATE SET
    new_contacts=EXCLUDED.new_contacts, active_contacts=EXCLUDED.active_contacts,
    total_contacts=EXCLUDED.total_contacts, messages_received=EXCLUDED.messages_received,
    messages_sent=EXCLUDED.messages_sent, avg_response_time_seconds=EXCLUDED.avg_response_time_seconds,
    conversations_opened=EXCLUDED.conversations_opened, conversations_resolved=EXCLUDED.conversations_resolved,
    avg_resolution_time_seconds=EXCLUDED.avg_resolution_time_seconds, deals_created=EXCLUDED.deals_created,
    deals_won=EXCLUDED.deals_won, deals_lost=EXCLUDED.deals_lost, revenue=EXCLUDED.revenue,
    pipeline_value=EXCLUDED.pipeline_value, lead_to_deal_rate=EXCLUDED.lead_to_deal_rate,
    deal_win_rate=EXCLUDED.deal_win_rate, avg_messages_per_contact=EXCLUDED.avg_messages_per_contact,
    automations_triggered=EXCLUDED.automations_triggered, followups_sent=EXCLUDED.followups_sent,
    calculated_at=now();
END; $$;


ALTER FUNCTION zapp.fn_save_daily_kpis() OWNER TO postgres;

--
-- Name: fn_scheduled_cleanup(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_scheduled_cleanup() RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$
DECLARE v_e integer; v_m integer; v_a integer;
BEGIN
  DELETE FROM evolution_webhook_events WHERE created_at<now()-interval '30 days'; GET DIAGNOSTICS v_e=ROW_COUNT;
  DELETE FROM evolution_alerts WHERE acknowledged=true AND acknowledged_at<now()-interval '7 days'; GET DIAGNOSTICS v_a=ROW_COUNT;
END; $$;


ALTER FUNCTION zapp.fn_scheduled_cleanup() OWNER TO postgres;

