--

CREATE FUNCTION zapp.fn_sticky_on_contact_assign() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  v_profile_id uuid;
BEGIN
  IF NEW.assigned_to IS NULL THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.assigned_to IS NOT DISTINCT FROM OLD.assigned_to THEN
    RETURN NEW;
  END IF;

  SELECT id INTO v_profile_id FROM zapp.profiles WHERE user_id = NEW.assigned_to LIMIT 1;
  IF v_profile_id IS NULL THEN RETURN NEW; END IF;

  PERFORM zapp.fn_sticky_upsert(NEW.id, v_profile_id, NULL, NULL, 'contact_assignment');
  RETURN NEW;
END;
$$;


