CREATE FUNCTION zapp.fn_sync_contact_from_event(p_jid text, p_push_name text, p_instance text DEFAULT 'wpp2'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE v_id uuid;
BEGIN
  INSERT INTO evolution_contacts (remote_jid, push_name, instance_name, first_contact_at)
  VALUES (p_jid, p_push_name, p_instance, now())
  ON CONFLICT (remote_jid) DO UPDATE SET push_name=COALESCE(EXCLUDED.push_name, evolution_contacts.push_name), updated_at=now()
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


