--
-- Name: fn_sync_instance_registry_status(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_sync_instance_registry_status() RETURNS TABLE(sincronizadas integer, sem_conexao integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'pg_catalog'
    AS $$
DECLARE v_sync int; v_orfas int; v_conn int;
BEGIN
  -- 1) Instancias com linha viva em zapp.whatsapp_connections (fonte: reconcile 5min)
  UPDATE zapp.instance_registry ir
  SET status = wc.status, updated_at = now()
  FROM zapp.whatsapp_connections wc
  WHERE wc.instance_name = ir.instance_name
    AND ir.status IS DISTINCT FROM wc.status
    AND ir.status != 'archived';
  GET DIAGNOSTICS v_sync = ROW_COUNT;

  -- 2) Instancias registradas mas nunca provisionadas na Evolution (sem linha em whatsapp_connections)
  UPDATE zapp.instance_registry ir
  SET status = 'not_provisioned', updated_at = now()
  WHERE NOT EXISTS (SELECT 1 FROM zapp.whatsapp_connections wc WHERE wc.instance_name = ir.instance_name)
    AND ir.status IS DISTINCT FROM 'not_provisioned'
    AND ir.status IS DISTINCT FROM 'test'
    AND ir.status IS DISTINCT FROM 'archived';
  GET DIAGNOSTICS v_orfas = ROW_COUNT;

  -- 3) [2026-08-06 etapa 42] Alinhar connection_status (+ status conexao-derivado) com o
  --    ultimo estado de public.evo_connection_history (mesma fonte de fn_wpp2_uptime_kpi).
  --    Nao sobrescreve status gerenciais (archived/test/not_provisioned).
  WITH last_state AS (
    SELECT DISTINCT ON (instance_name) instance_name, state
    FROM public.evo_connection_history
    ORDER BY instance_name, created_at DESC
  )
  UPDATE zapp.instance_registry ir
  SET connection_status = CASE ls.state
        WHEN 'connected'  THEN 'connected'
        WHEN 'connecting' THEN 'connecting'
        WHEN 'qr_pending' THEN 'qr_pending'
        WHEN 'logged_out' THEN 'logged_out'
        WHEN 'banned'     THEN 'disconnected'
        ELSE 'disconnected'
      END,
      status = CASE WHEN ir.status IN ('connected','connecting','qr_pending','disconnected','logged_out')
        THEN CASE ls.state
          WHEN 'connected'  THEN 'connected'
          WHEN 'connecting' THEN 'connecting'
          WHEN 'qr_pending' THEN 'qr_pending'
          WHEN 'logged_out' THEN 'logged_out'
          ELSE 'disconnected'
        END ELSE ir.status END,
      updated_at = now()
  FROM last_state ls
  WHERE ls.instance_name = ir.instance_name
    AND ir.status NOT IN ('archived','test','not_provisioned')
    AND ir.connection_status IS DISTINCT FROM CASE ls.state
        WHEN 'connected'  THEN 'connected'
        WHEN 'connecting' THEN 'connecting'
        WHEN 'qr_pending' THEN 'qr_pending'
        WHEN 'logged_out' THEN 'logged_out'
        WHEN 'banned'     THEN 'disconnected'
        ELSE 'disconnected' END;
  GET DIAGNOSTICS v_conn = ROW_COUNT;

  RETURN QUERY SELECT v_sync, v_orfas + v_conn;
END $$;


ALTER FUNCTION zapp.fn_sync_instance_registry_status() OWNER TO postgres;

--
-- Name: FUNCTION fn_sync_instance_registry_status(); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.fn_sync_instance_registry_status() IS 'S5-2 (2026-07-04): sincroniza zapp.instance_registry.status a partir de public.whatsapp_connections (mantida fresca pelo reconcile). Instancias sem conexao viram not_provisioned; status=test e preservado.';


--
-- Name: fn_sync_label_to_pipeline(uuid, text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_sync_label_to_pipeline(p_contact_id uuid, p_label text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE v_stage text;
BEGIN
  v_stage:=CASE LOWER(p_label) WHEN 'novo cliente' THEN 'novo_lead' WHEN 'novo pedido' THEN 'pedido_recebido' WHEN 'pagamento pendente' THEN 'proposta_enviada' WHEN 'pago' THEN 'pedido_finalizado' ELSE NULL END;
  IF v_stage IS NOT NULL THEN UPDATE evolution_deals SET stage=v_stage,updated_at=now() WHERE contact_id=p_contact_id AND stage NOT IN ('perdido','pedido_finalizado'); END IF;
END; $$;


ALTER FUNCTION zapp.fn_sync_label_to_pipeline(p_contact_id uuid, p_label text) OWNER TO postgres;

--
-- Name: fn_sync_labels_to_pipeline(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_sync_labels_to_pipeline() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP='INSERT' OR (TG_OP='UPDATE' AND OLD.label_id IS DISTINCT FROM NEW.label_id) THEN
    PERFORM fn_sync_label_to_pipeline(NEW.contact_id,(SELECT name FROM evolution_labels WHERE id=NEW.label_id));
  END IF;
  RETURN NEW;
END; $$;


ALTER FUNCTION zapp.fn_sync_labels_to_pipeline() OWNER TO postgres;

--
-- Name: fn_sync_pipeline_from_labels(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_sync_pipeline_from_labels() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE v_count integer:=0;
BEGIN
  -- Batch sync all label associations to pipeline stages
  UPDATE evolution_deals d SET stage=CASE l.name WHEN 'Novo cliente' THEN 'novo_lead' WHEN 'Novo pedido' THEN 'pedido_recebido' WHEN 'Pagamento pendente' THEN 'proposta_enviada' WHEN 'Pago' THEN 'pedido_finalizado' ELSE d.stage END, updated_at=now()
  FROM evolution_label_associations la JOIN evolution_labels l ON la.label_id=l.id WHERE d.contact_id=la.contact_id AND d.stage NOT IN ('perdido','pedido_finalizado');
  GET DIAGNOSTICS v_count=ROW_COUNT;
  RETURN v_count;
END; $$;


ALTER FUNCTION zapp.fn_sync_pipeline_from_labels() OWNER TO postgres;

