--
-- Name: fn_test_alert_channel(integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_test_alert_channel(p_channel_id integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$
DECLARE
  v_channel record;
  v_result  jsonb;
BEGIN
  SELECT * INTO v_channel FROM zapp.alert_channels WHERE id = p_channel_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Canal não encontrado', 'channel_id', p_channel_id);
  END IF;
  IF NOT v_channel.is_active THEN
    RETURN jsonb_build_object(
      'success', false, 'error', 'Canal desabilitado',
      'channel_id', p_channel_id, 'channel_name', v_channel.name,
      'channel_type', v_channel.channel_type
    );
  END IF;
  INSERT INTO zapp.evolution_alerts (alert_type, severity, message, payload, acknowledged)
  VALUES (
    'channel_test', 'low',
    format('Teste do canal %s executado em %s', v_channel.name, now()),
    jsonb_build_object('channel_id', p_channel_id, 'channel_name', v_channel.name, 'test', true),
    true
  );
  v_result := jsonb_build_object(
    'success', true,
    'channel_id', p_channel_id,
    'channel_name', v_channel.name,
    'channel_type', v_channel.channel_type,
    'message', format('Canal %s testado com sucesso', v_channel.name),
    'tested_at', now()
  );
  RETURN v_result;
END;
$$;


