--
-- Name: fn_toggle_audio_meme_favorite(uuid); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.fn_toggle_audio_meme_favorite(p_meme_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$
DECLARE
  v_new_val boolean;
BEGIN
  UPDATE audio_memes SET is_favorite = NOT is_favorite
  WHERE id = p_meme_id
  RETURNING is_favorite INTO v_new_val;
  
  IF v_new_val IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'meme_id nao encontrado');
  END IF;
  
  RETURN jsonb_build_object('ok', true, 'id', p_meme_id, 'is_favorite', v_new_val);
END;
$$;


ALTER FUNCTION zapp.fn_toggle_audio_meme_favorite(p_meme_id uuid) OWNER TO supabase_admin;

