-- Name: FUNCTION fn_toggle_audio_meme_favorite(p_meme_id uuid); Type: COMMENT; Schema: zapp; Owner: supabase_admin
--

COMMENT ON FUNCTION zapp.fn_toggle_audio_meme_favorite(p_meme_id uuid) IS 'Toggle favorito de um meme do catalogo';


--
-- Name: fn_toggle_user_meme_favorite(uuid); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_toggle_user_meme_favorite(p_meme_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE v_exists boolean;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'unauthenticated'; END IF;
  SELECT EXISTS(SELECT 1 FROM zapp.audio_meme_favorites
                WHERE meme_id = p_meme_id AND user_id = auth.uid()) INTO v_exists;
  IF v_exists THEN
    DELETE FROM zapp.audio_meme_favorites
      WHERE meme_id = p_meme_id AND user_id = auth.uid();
    RETURN false;
  ELSE
    INSERT INTO zapp.audio_meme_favorites(user_id, meme_id)
      VALUES (auth.uid(), p_meme_id);
    RETURN true;
  END IF;
END;
$$;


ALTER FUNCTION zapp.fn_toggle_user_meme_favorite(p_meme_id uuid) OWNER TO postgres;

--
-- Name: fn_toggle_user_meme_favorite(uuid, uuid); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.fn_toggle_user_meme_favorite(p_user_id uuid, p_meme_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$
DECLARE
  v_inserted boolean;
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'invalid_argument: p_user_id nao pode ser NULL';
  END IF;

  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'unauthenticated';
  END IF;

  IF p_user_id <> auth.uid() AND NOT zapp.is_admin_or_supervisor() THEN
    RAISE EXCEPTION 'permission_denied: nao e permitido alterar favoritos de outro usuario'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  INSERT INTO zapp.audio_meme_favorites (user_id, meme_id)
  VALUES (p_user_id, p_meme_id)
  ON CONFLICT (user_id, meme_id) DO NOTHING;

  GET DIAGNOSTICS v_inserted = ROW_COUNT;

  IF v_inserted = 0 THEN
    DELETE FROM zapp.audio_meme_favorites
    WHERE user_id = p_user_id AND meme_id = p_meme_id;

    RETURN jsonb_build_object(
      'ok',          true,
      'user_id',     p_user_id,
      'meme_id',     p_meme_id,
      'is_favorite', false,
      'action',      'removed'
    );
  ELSE
    RETURN jsonb_build_object(
      'ok',          true,
      'user_id',     p_user_id,
      'meme_id',     p_meme_id,
      'is_favorite', true,
      'action',      'added'
    );
  END IF;
END;
$$;


ALTER FUNCTION zapp.fn_toggle_user_meme_favorite(p_user_id uuid, p_meme_id uuid) OWNER TO supabase_admin;

--
-- Name: FUNCTION fn_toggle_user_meme_favorite(p_user_id uuid, p_meme_id uuid); Type: COMMENT; Schema: zapp; Owner: supabase_admin
--

COMMENT ON FUNCTION zapp.fn_toggle_user_meme_favorite(p_user_id uuid, p_meme_id uuid) IS 'Toggle de favorito de meme por user_id + meme_id. Ownership guard: caller deve ser o próprio user_id ou ter role admin/supervisor. RACE CONDITION FIX (20260806200100): reescrita para INSERT ON CONFLICT DO NOTHING aproveitando UNIQUE(user_id, meme_id) — operação atômica sem risco de duplicatas. REVOKE FROM PUBLIC (20260806200100): anon não tem mais EXECUTE (defense-in-depth). A sobrecarga 1-arg (p_meme_id uuid) usa auth.uid() internamente e é preferida no cliente.';


--
-- Name: fn_toggle_user_sticker_favorite(uuid, uuid); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.fn_toggle_user_sticker_favorite(p_user_id uuid, p_sticker_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$
DECLARE
  v_existed boolean;
BEGIN
  IF p_user_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Acesso negado: não é possível modificar favoritos de outro usuário'
      USING ERRCODE = '42501';
  END IF;

  DELETE FROM sticker_favorites WHERE user_id = p_user_id AND sticker_id = p_sticker_id;
  v_existed := FOUND;

  IF v_existed THEN
    RETURN jsonb_build_object(
      'ok',          true,
      'user_id',     p_user_id,
      'sticker_id',  p_sticker_id,
      'is_favorite', false,
      'action',      'removed'
    );
  ELSE
    INSERT INTO sticker_favorites (user_id, sticker_id) VALUES (p_user_id, p_sticker_id);
    RETURN jsonb_build_object(
      'ok',          true,
      'user_id',     p_user_id,
      'sticker_id',  p_sticker_id,
      'is_favorite', true,
      'action',      'added'
    );
  END IF;
END;
$$;


