--
-- Name: fn_track_connection_changes(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_track_connection_changes() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'zapp', 'evo', 'public', 'pg_catalog'
    AS $$
DECLARE current_state TEXT; prev_state TEXT; prev_created TIMESTAMPTZ; duration INT;
BEGIN
  IF NEW.event_type='CONNECTION_UPDATE' THEN
    current_state:=COALESCE(NEW.payload->>'state',NEW.payload->'data'->>'state');
    SELECT state,created_at INTO prev_state,prev_created FROM evolution_connection_history WHERE instance_name=NEW.instance_name ORDER BY created_at DESC LIMIT 1;
    IF prev_created IS NOT NULL THEN duration:=EXTRACT(EPOCH FROM (NOW()-prev_created))::INTEGER; END IF;
    INSERT INTO evolution_connection_history (instance_name,state,previous_state,duration_seconds,metadata) VALUES (NEW.instance_name,current_state,prev_state,duration,NEW.payload);
  END IF;
  RETURN NEW;
END; $$;


ALTER FUNCTION zapp.fn_track_connection_changes() OWNER TO postgres;

--
-- Name: fn_track_stage_change(); Type: FUNCTION; Schema: zapp; Owner: postgres
