--
-- Name: fn_trg_auto_security_invoker(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_trg_auto_security_invoker() RETURNS event_trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog'
    AS $$
DECLARE obj record; v_schema text; v_name text;
BEGIN
  FOR obj IN SELECT * FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE VIEW','ALTER VIEW','CREATE OR REPLACE VIEW')
      AND object_type = 'view'
  LOOP
    v_schema := split_part(obj.object_identity, '.', 1);
    v_name   := split_part(obj.object_identity, '.', 2);
    IF v_schema IN ('public','zapp','evo','artes','financeiro','monitoring','ops','vendas','email_app','ai','bpm','archive','logistica') THEN
      BEGIN
        IF NOT EXISTS (
          SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
          WHERE n.nspname = v_schema AND c.relname = v_name AND c.relkind = 'v'
            AND c.reloptions IS NOT NULL
            AND (array_to_string(c.reloptions, ',') ILIKE ANY (ARRAY['%security_invoker=true%', '%security_invoker=on%']))
        ) THEN
          EXECUTE format('ALTER VIEW %I.%I SET (security_invoker = true)', v_schema, v_name);
        END IF;
      EXCEPTION WHEN OTHERS THEN NULL;
      END;
    END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION zapp.fn_trg_auto_security_invoker() OWNER TO postgres;

--
-- Name: fn_trg_quarantine_alert(); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.fn_trg_quarantine_alert() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'zapp', 'evo', 'public', 'pg_catalog'
    AS $$
BEGIN
  INSERT INTO media_security_alerts (alert_type, severity, title, details, message_id, instance_name)
  VALUES (
    CASE WHEN NEW.block_reason LIKE 'CLAMAV%' THEN 'virus_detected'
         WHEN NEW.block_reason LIKE 'FILE_TOO%' THEN 'size_exceeded'
         ELSE 'file_blocked' END,
    CASE WHEN NEW.block_reason LIKE 'CLAMAV%' THEN 'critical'
         WHEN NEW.block_reason LIKE 'MIMETYPE%' THEN 'high'
         ELSE 'medium' END,
    'Arquivo bloqueado: ' || COALESCE(NEW.original_mimetype, 'unknown') || ' ' || COALESCE(NEW.original_extension, ''),
    jsonb_build_object('block_reason', NEW.block_reason, 'mimetype', NEW.original_mimetype, 'extension', NEW.original_extension, 'file_size', NEW.file_size_bytes, 'remote_jid', NEW.remote_jid),
    NEW.message_id,
    NEW.instance_name
  );
  PERFORM pg_notify('media_security', json_build_object('type', 'file_blocked', 'message_id', NEW.message_id, 'reason', NEW.block_reason)::text);
  RETURN NEW;
END;
$$;


ALTER FUNCTION zapp.fn_trg_quarantine_alert() OWNER TO supabase_admin;

--
-- Name: fn_trigger_audio_transcription(integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_trigger_audio_transcription(p_batch_size integer DEFAULT 3) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog'
    AS $$
DECLARE
  v_supabase_url    text;
  v_service_key     text;
  v_health_secret   text;
  v_row             RECORD;
  v_request_id      bigint;
  v_queued          int := 0;
  v_recovered       int := 0;
  v_in_processing   int := 0;
  MAX_CONCURRENT    CONSTANT int := 15;
BEGIN
  v_supabase_url := COALESCE(ops.fn_get_vault_secret('supabase_api_url'), 'https://supabase.atomicabr.com.br');
  SELECT decrypted_secret INTO v_service_key
    FROM vault.decrypted_secrets WHERE name='supabase_service_role_key' LIMIT 1;
  IF v_service_key IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'JWT nao encontrado no vault');
  END IF;

  SELECT decrypted_secret INTO v_health_secret FROM vault.decrypted_secrets WHERE name='health_secret' LIMIT 1;
  IF v_health_secret IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'health_secret nao encontrado no vault');
  END IF;

  UPDATE zapp.evolution_messages_wpp2
     SET transcription_status = 'queued', updated_at = now()
   WHERE message_type IN ('audio', 'audioMessage')
     AND transcription_status = 'processing'
     AND updated_at < now() - interval '15 minutes';
  GET DIAGNOSTICS v_recovered = ROW_COUNT;

  UPDATE zapp.evolution_messages_wpp2
     SET transcription_status = 'queued', media_status = 'ready', updated_at = now()
   WHERE message_type IN ('audio', 'audioMessage')
     AND transcription_status = 'expired'
     AND media_status IN ('expired', 'ready')
     AND media_url LIKE '%supabase.atomicabr.com.br/storage%'
     AND media_url IS NOT NULL;

  UPDATE zapp.evolution_messages_wpp2
     SET transcription_status = 'queued', error_code = NULL, error_reason = NULL, updated_at = now()
   WHERE message_type IN ('audio', 'audioMessage')
     AND transcription_status = 'failed'
     AND error_code = 'concurrent_limit_exceeded'
     AND updated_at < now() - interval '10 minutes';

  SELECT COUNT(*) INTO v_in_processing
    FROM zapp.evolution_messages_wpp2
   WHERE message_type IN ('audio', 'audioMessage')
     AND transcription_status = 'processing';

  IF v_in_processing >= MAX_CONCURRENT THEN
    RETURN jsonb_build_object(
      'ok', true, 'queued', 0, 'recovered', v_recovered,
      'skipped', true, 'reason', 'concurrent_limit_guard',
      'in_processing', v_in_processing, 'max_concurrent', MAX_CONCURRENT,
      'executed_at', now()
    );
  END IF;

  p_batch_size := LEAST(p_batch_size, GREATEST(0, MAX_CONCURRENT - v_in_processing));

  FOR v_row IN
    SELECT message_id, media_url
      FROM zapp.evolution_messages_wpp2
     WHERE message_type IN ('audio', 'audioMessage')
       AND media_status = 'ready'
       AND media_url IS NOT NULL
       AND (transcription_status IS NULL OR transcription_status = 'queued')
     ORDER BY created_at ASC
     LIMIT p_batch_size
  LOOP
    UPDATE zapp.evolution_messages_wpp2
       SET transcription_status = 'processing', updated_at = now()
     WHERE message_id = v_row.message_id;

    SELECT net.http_post(
      url                  := v_supabase_url || '/functions/v1/transcribe-audio-internal',
      body                 := jsonb_build_object('messageId', v_row.message_id, 'audioUrl', v_row.media_url),
      headers              := jsonb_build_object(
        'Content-Type',     'application/json',
        'Authorization',    'Bearer ' || v_service_key,
        'x-internal-secret', v_health_secret
      ),
      timeout_milliseconds := 120000
    ) INTO v_request_id;

    v_queued := v_queued + 1;
  END LOOP;

  IF v_queued = 0 THEN
    RETURN jsonb_build_object(
      'ok', true, 'queued', 0, 'recovered', v_recovered,
      'in_processing', v_in_processing,
      'message', 'Nenhum audio pendente', 'executed_at', now()
    );
  END IF;

  RETURN jsonb_build_object(
    'ok', true, 'queued', v_queued, 'recovered', v_recovered,
    'in_processing', v_in_processing,
    'first_request_id', v_request_id,
    'timeout_ms', 120000, 'executed_at', now()
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('ok', false, 'error', SQLERRM);
END;
$$;


ALTER FUNCTION zapp.fn_trigger_audio_transcription(p_batch_size integer) OWNER TO postgres;

