--
-- Name: fn_update_instance_health(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_update_instance_health() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog'
    AS $$
DECLARE
  v_gap          numeric;
  v_msgs_1h      int;
  v_status       text;
  v_socket_ok    boolean;
  v_dow          int  := EXTRACT(DOW FROM NOW() AT TIME ZONE 'America/Sao_Paulo');
  v_is_fds       boolean := v_dow IN (0, 6);
  v_gap_healthy  int := 10;   -- gap < 10min = healthy sempre
  v_gap_degraded int;         -- threshold FDS-adaptativo
BEGIN
  -- Fonte canônica: zapp.evolution_messages (pós-migração self-hosted)
  SELECT
    ROUND(EXTRACT(EPOCH FROM (now() - MAX(created_at))) / 60, 1),
    COUNT(*) FILTER (WHERE created_at > now() - INTERVAL '1h')
  INTO v_gap, v_msgs_1h
  FROM zapp.evolution_messages;

  -- Threshold adaptativo dia da semana
  v_gap_degraded := CASE WHEN v_is_fds THEN 120 ELSE 30 END;

  v_status := CASE
    WHEN v_msgs_1h > 0 AND v_gap < v_gap_healthy THEN 'healthy'
    WHEN v_gap < v_gap_degraded                   THEN 'degraded'
    WHEN v_is_fds AND v_msgs_1h > 0               THEN 'degraded'
    ELSE 'unhealthy'
  END;

  -- GUARD v3: se socket WhatsApp REALMENTE conectado e tabela atualizada < 20min,
  -- nunca reportar 'unhealthy' só por volume baixo de mensagens.
  -- Distingue "conexão técnica OK" de "empresa quieta" (B2B domingo).
  IF v_status = 'unhealthy' THEN
    SELECT (status = 'connected' AND updated_at > now() - INTERVAL '20 minutes')
    INTO v_socket_ok
    FROM zapp.whatsapp_connections
    WHERE instance_name = 'wpp2'
    LIMIT 1;

    IF COALESCE(v_socket_ok, false) THEN
      v_status := 'degraded';  -- socket ok, empresa quieta → degraded (não unhealthy)
    END IF;
  END IF;

  UPDATE zapp.evolution_instance_credentials
  SET health_status      = v_status,
      last_health_check  = NOW(),
      online_instances   = CASE WHEN v_status IN ('healthy', 'degraded') THEN 1 ELSE 0 END,
      notes = FORMAT(
        'gap=%smin msgs1h=%s auto-check=%s src=evolution_messages fds=%s gap_thr=%s socket_guard=%s v3',
        v_gap, v_msgs_1h, NOW()::text, v_is_fds, v_gap_degraded,
        COALESCE(v_socket_ok, false)
      )
  WHERE instance_name = 'wpp2';
END;
$$;


ALTER FUNCTION zapp.fn_update_instance_health() OWNER TO postgres;

--
-- Name: FUNCTION fn_update_instance_health(); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.fn_update_instance_health() IS 'Atualiza health_status de wpp2 (cron 172 evo-instance-health-check, */10min). Threshold adaptativo FDS (sab/dom). Sem referencias Lovable desde 2026-08-03.';


--
-- Name: fn_update_lead_score(uuid); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_update_lead_score(p_contact_id uuid) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$
DECLARE v_score INTEGER := 0; v_data RECORD;
BEGIN
  SELECT total_messages, total_purchases, EXTRACT(DAY FROM NOW() - last_message_at) as days_since_last, (SELECT COUNT(*) FROM evolution_deals WHERE contact_id = p_contact_id AND stage = 'pago') as deals_won INTO v_data FROM evolution_contacts WHERE id = p_contact_id;
  v_score := v_score + LEAST(v_data.total_messages, 50);
  v_score := v_score + (v_data.deals_won * 20);
  v_score := v_score + CASE WHEN v_data.days_since_last <= 1 THEN 30 WHEN v_data.days_since_last <= 7 THEN 20 WHEN v_data.days_since_last <= 30 THEN 10 ELSE 0 END;
  UPDATE evolution_contacts SET lead_score = v_score WHERE id = p_contact_id;
  RETURN v_score;
END;
$$;


ALTER FUNCTION zapp.fn_update_lead_score(p_contact_id uuid) OWNER TO postgres;

