--
-- Name: fn_update_sticker_category_count(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_update_sticker_category_count() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    UPDATE sticker_categories SET sticker_count = sticker_count + 1 WHERE slug = NEW.category;
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    UPDATE sticker_categories SET sticker_count = GREATEST(sticker_count - 1, 0) WHERE slug = OLD.category;
    RETURN OLD;
  ELSIF TG_OP = 'UPDATE' AND OLD.category != NEW.category THEN
    UPDATE sticker_categories SET sticker_count = GREATEST(sticker_count - 1, 0) WHERE slug = OLD.category;
    UPDATE sticker_categories SET sticker_count = sticker_count + 1 WHERE slug = NEW.category;
    RETURN NEW;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION zapp.fn_update_sticker_category_count() OWNER TO postgres;

