    v_last_audit_event text;
  BEGIN
    SELECT COUNT(*), MAX(event_type) INTO v_audit_1h, v_last_audit_event
    FROM zapp.webhook_audit_log
    WHERE created_at > now()-INTERVAL '1 hour' AND status='processed';
    IF v_audit_1h = 0 THEN
