--
-- Name: fn_vacuum_critical_tables(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_vacuum_critical_tables() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_tables text[] := ARRAY[
    'zapp.webhook_events_processed','zapp.webhook_audit_log','zapp.app_notifications',
    'zapp.webhook_rate_limits','zapp.instance_registry','zapp.profiles',
    'zapp.empresas','logistica.cotacoes','zapp.evolution_alerts'
  ];
  v_tbl text;
  v_vacuumed int := 0;
  v_errors text[] := ARRAY[]::text[];
BEGIN
  FOREACH v_tbl IN ARRAY v_tables LOOP
    BEGIN
      PERFORM dblink_exec(
        'host=localhost port=5432 user=postgres dbname=postgres',
        'VACUUM ANALYZE '||v_tbl,
        true
      );
      v_vacuumed := v_vacuumed + 1;
    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors || (v_tbl||': '||SQLERRM);
    END;
  END LOOP;
  RETURN jsonb_build_object(
    'vacuumed', v_vacuumed,
    'total', array_length(v_tables,1),
    'errors', to_jsonb(v_errors),
    'executed_at', now()
  );
END;
$$;


ALTER FUNCTION zapp.fn_vacuum_critical_tables() OWNER TO postgres;

