--
-- Name: fn_validate_report_query(text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_validate_report_query(p_sql text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
  v_clean   text;
  v_blocked text[] := ARRAY[
    '\minsert\M', '\mupdate\M', '\mdelete\M', '\mdrop\M', '\malter\M',
    '\mcreate\M', '\mtruncate\M', '\mgrant\M', '\mrevoke\M', '\mcall\M',
    '\mcopy\M', '\minto\M', '\mdo\M', '\mmerge\M',
    '\mexecute\M', '\mprepare\M', '\mdeallocate\M', '\mlisten\M',
    '\mnotify\M', '\mvacuum\M', '\manalyze\M',
    '\mreindex\M', '\mcluster\M', '\mpg_[a-z_]*\s*\(',
    '\mlo_import\b', '\mlo_export\b', '\mdblink\b', '\mnet\.[a-z_]+',
    '\mhttp_post\b', '\mcron\.[a-z_]+', '\mstorage\.[a-z_]+'
  ];
  v_kw      text;
BEGIN
  IF p_sql IS NULL OR btrim(p_sql) = '' THEN
    RETURN false;
  END IF;

  v_clean := regexp_replace(p_sql, '--[^\n]*', '', 'g');
  v_clean := regexp_replace(v_clean, '/\*.*?\*/', '', 'gs');

  IF NOT (v_clean ~* '^\s*(SELECT|WITH)\b') THEN
    RETURN false;
  END IF;

  FOREACH v_kw IN ARRAY v_blocked LOOP
    IF v_clean ~* v_kw THEN
      RETURN false;
    END IF;
  END LOOP;

  RETURN true;
END
$$;


ALTER FUNCTION zapp.fn_validate_report_query(p_sql text) OWNER TO postgres;

--
-- Name: FUNCTION fn_validate_report_query(p_sql text); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.fn_validate_report_query(p_sql text) IS 'Valida que config.sql é SELECT/WITH read-only (blocklist DML/DDL/funções pg_). Defesa em profundidade — execução é restrita a admin/supervisor.';


