--
-- Name: fn_vault_healthcheck(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_vault_healthcheck() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  rec RECORD;
  v_decrypted text;
  v_ok int := 0;
  v_fail int := 0;
  v_defer int := 0;
  v_failed_names text[] := '{}';
BEGIN
  FOR rec IN SELECT name, description FROM vault.secrets ORDER BY name
  LOOP
    IF rec.description LIKE 'DEFER%' THEN
      v_defer := v_defer + 1;
    ELSE
      BEGIN
        SELECT decrypted_secret INTO v_decrypted FROM vault.decrypted_secrets WHERE name = rec.name;
        IF v_decrypted IS NOT NULL AND v_decrypted != '' THEN
          v_ok := v_ok + 1;
        ELSE
          v_fail := v_fail + 1;
          v_failed_names := v_failed_names || rec.name;
        END IF;
      EXCEPTION WHEN OTHERS THEN
        v_fail := v_fail + 1;
        v_failed_names := v_failed_names || rec.name;
      END;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'checked_at', now(),
    'ok', v_ok,
    'fail', v_fail,
    'defer', v_defer,
    'failed_names', to_jsonb(v_failed_names),
    'status', CASE WHEN v_fail = 0 THEN 'healthy' ELSE 'degraded' END
  );
END
$$;


ALTER FUNCTION zapp.fn_vault_healthcheck() OWNER TO postgres;

