--
-- Name: fn_wal_slot_lag_alert(integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_wal_slot_lag_alert(p_threshold_mb integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'pg_catalog'
    AS $$
DECLARE
  r          record;
  v_checked  int := 0;
  v_open     int := 0;
  v_resolved int := 0;
  v_rows     int;
BEGIN
  FOR r IN
    SELECT slot_name, lag_mb, is_active
    FROM zapp.fn_wal_slot_lag_check(p_threshold_mb)
    ORDER BY lag_mb DESC NULLS LAST
  LOOP
    v_checked := v_checked + 1;

    IF r.lag_mb > p_threshold_mb THEN
      -- Alerta aberto (dedupe: não empilha se já há alerta aberto p/ o slot < 60min)
      INSERT INTO zapp.evolution_alerts (alert_type, severity, title, message, payload)
      SELECT 'wal_slot_high_lag', 'high',
        format('[WAL-ALERTA] Slot %s retendo %s MB', r.slot_name, round(r.lag_mb, 1)),
        format('Cainophile/Logflare retendo %s MB de WAL. Consumer ativo=%s. Limiar=%s MB. Acao: reiniciar supabase_analytics se nao reduzir em 15min.',
               round(r.lag_mb, 1), r.is_active, p_threshold_mb),
        jsonb_build_object(
          'slot', r.slot_name, 'lag_mb', r.lag_mb, 'active', r.is_active,
          'threshold_alert_mb', p_threshold_mb, 'checked_at', now())
      WHERE NOT EXISTS (
        SELECT 1 FROM zapp.evolution_alerts
        WHERE alert_type = 'wal_slot_high_lag'
          AND resolved_at IS NULL
          AND (payload->>'slot') = r.slot_name
          AND created_at >= now() - INTERVAL '60 minutes'
      );
      GET DIAGNOSTICS v_rows = ROW_COUNT;
      v_open := v_open + v_rows;
    ELSE
      -- Resolução SÓ via colunas base (resolved_at/resolved_by) — NUNCA SET resolved
      UPDATE zapp.evolution_alerts
      SET resolved_at = now(),
          resolved_by = 'fn_wal_slot_lag_alert:recovered'
      WHERE alert_type IN ('wal_slot_high_lag', 'wal_slot_lag')
        AND resolved_at IS NULL
        AND (payload->>'slot') = r.slot_name;
      GET DIAGNOSTICS v_rows = ROW_COUNT;
      v_resolved := v_resolved + v_rows;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'slots_verificados', v_checked,
    'alertas_abertos', v_open,
    'resolvidos', v_resolved,
    'threshold_mb', p_threshold_mb
  );
END $$;


ALTER FUNCTION zapp.fn_wal_slot_lag_alert(p_threshold_mb integer) OWNER TO postgres;

--
-- Name: fn_wal_slot_lag_check(integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_wal_slot_lag_check(p_threshold_mb integer DEFAULT 200) RETURNS TABLE(slot_name text, lag_mb numeric, is_active boolean, exceeds_threshold boolean)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
  SELECT
    slot_name::TEXT,
    ROUND(pg_wal_lsn_diff(pg_current_wal_lsn(), confirmed_flush_lsn)
          / (1024.0 * 1024.0), 2) AS lag_mb,
    active AS is_active,
    ROUND(pg_wal_lsn_diff(pg_current_wal_lsn(), confirmed_flush_lsn)
          / (1024.0 * 1024.0), 2) > p_threshold_mb AS exceeds_threshold
  FROM pg_replication_slots
  WHERE slot_type = 'logical'
  ORDER BY lag_mb DESC NULLS LAST;
$$;


ALTER FUNCTION zapp.fn_wal_slot_lag_check(p_threshold_mb integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_wal_slot_lag_check(p_threshold_mb integer); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.fn_wal_slot_lag_check(p_threshold_mb integer) IS 'Returns WAL lag in MB per logical replication slot. Slots exceeding p_threshold_mb flag exceeds_threshold=true. Monitor cainophile_kzabiv0d (Logflare) which was at 313 MB lag on 2026-07-24 with ~35 MB/day growth.';


