-- Name: fn_webhook_pipeline_score(text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_webhook_pipeline_score(p_eff_state text DEFAULT 'unknown'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'ops', 'cron', 'pg_catalog'
    AS $$
DECLARE
  vt timestamptz; vt2 timestamptz;
  v_hours_silent numeric;
  v_audit_1h int; v_events_1h int;
  v_msgs_7d bigint; v_msgs_24h bigint;
  v_msg_hours_silent numeric;
  v_pipe_score int; v_pipe_note text;
  vb bigint; v_bloat_score int;
  -- NOVO: janela adaptativa baseada em horário comercial (BRT)
  v_hour_brt int;
  v_dow_brt int;
  v_fresh_window numeric;
BEGIN
  -- Determinar janela de "fresh" com consciência de horário comercial
  v_hour_brt := EXTRACT(HOUR FROM NOW() AT TIME ZONE 'America/Sao_Paulo');
  v_dow_brt  := EXTRACT(DOW FROM NOW() AT TIME ZONE 'America/Sao_Paulo');
  
  -- Business hours: seg-sex 08h-20h BRT → janela estrita 1h
  -- Fora do horário (noite/madrugada/fim de semana) → janela relaxada 4h
  -- Justificativa: silêncio noturno é OPERACIONAL, não indica falha no pipeline
  v_fresh_window := CASE
    WHEN v_dow_brt IN (0, 6) THEN 4.0  -- fim de semana: 4h
    WHEN v_hour_brt < 8 OR v_hour_brt >= 20 THEN 4.0  -- noite/madrugada: 4h
    ELSE 1.0  -- horário comercial: estrito 1h
  END;

  -- Calcular silêncio do pipeline
  SELECT MAX(created_at) INTO vt FROM zapp.webhook_audit_log;
  SELECT MAX(created_at) INTO vt2 FROM public.evo_webhook_events_v2;
  v_hours_silent := COALESCE(ROUND(EXTRACT(EPOCH FROM(NOW()-GREATEST(vt,vt2)))/3600,1),9999);
  
  SELECT MAX(created_at) INTO vt FROM zapp.evolution_messages WHERE instance_name='wpp2';
  v_msg_hours_silent := COALESCE(ROUND(EXTRACT(EPOCH FROM(NOW()-vt))/3600,1),9999);
  -- v_msg_hours_silent é informacional: silêncio de msgs é condição operacional,
  -- não indica falha no pipeline. Pipeline health = apenas webhook/event activity.

  -- Contadores de atividade
  SELECT COUNT(*) INTO v_events_1h FROM zapp.webhook_events_processed
    WHERE processed_at > NOW()-INTERVAL '1 hour';
  SELECT COUNT(*) INTO v_audit_1h FROM zapp.webhook_audit_log
    WHERE status='processed' AND created_at > NOW()-INTERVAL '1 hour';
  SELECT
    COUNT(*) FILTER(WHERE created_at > NOW()-INTERVAL '7 days'),
    COUNT(*) FILTER(WHERE created_at > NOW()-INTERVAL '24 hours')
  INTO v_msgs_7d, v_msgs_24h
  FROM zapp.evolution_messages WHERE instance_name='wpp2';

  -- Score com janela adaptativa
  v_pipe_score := CASE
    WHEN v_hours_silent <= v_fresh_window THEN 15    -- fresh (considera horário)
    WHEN v_hours_silent <= 6              THEN 12    -- recente (até 6h)
    WHEN v_audit_1h >= 500               THEN 15    -- muito ativo
    WHEN v_audit_1h >= 100               THEN 12    -- ativo
    WHEN v_audit_1h >= 10                THEN 10    -- baixo tráfego
    WHEN v_hours_silent <= 24            THEN 8     -- stale ok
    WHEN v_hours_silent <= 96 AND v_msgs_7d > 100 AND p_eff_state = 'connected' THEN 8
    WHEN v_hours_silent <= 96 AND v_msgs_7d > 0   AND p_eff_state = 'connected' THEN 5
    ELSE 0
  END;

  v_pipe_note := CASE
    WHEN v_pipe_score = 15 AND v_hours_silent <= v_fresh_window
      THEN CASE WHEN v_fresh_window > 1 THEN 'e2e_fresh_offhours' ELSE 'e2e_fresh' END
    WHEN v_pipe_score = 15 THEN 'audit_very_active'
    WHEN v_pipe_score = 12 AND v_hours_silent <= 6  THEN 'e2e_recent'
    WHEN v_pipe_score = 12                          THEN 'audit_active'
    WHEN v_pipe_score = 10                          THEN 'audit_low_traffic'
    WHEN v_pipe_score = 8 AND v_hours_silent <= 24  THEN 'e2e_stale_ok'
    WHEN v_pipe_score = 8                           THEN 'healthy_idle_msgs_7d'
    WHEN v_pipe_score = 5                           THEN 'healthy_idle_low_volume'
    ELSE 'degraded'
  END;

  SELECT pg_total_relation_size('zapp.webhook_audit_log') INTO vb;
  v_bloat_score := CASE
    WHEN vb < 314572800  THEN 5
    WHEN vb < 1073741824 THEN 3
    ELSE 0
  END;

  RETURN jsonb_build_object(
    'pipe_score', v_pipe_score,
    'bloat_score', v_bloat_score,
    'msgs_7d', v_msgs_7d,
    'webhook_pipeline', jsonb_build_object(
      'score', v_pipe_score, 'max', 15,
      'hours_silent', v_hours_silent,
      'msg_gap_hours', v_msg_hours_silent,
      'pending', v_events_1h,
      'audit_1h', v_audit_1h,
      'msgs_7d', v_msgs_7d,
      'msgs_24h', v_msgs_24h,
      'processed_1h', v_events_1h,
      'note', v_pipe_note,
      'fresh_window_h', v_fresh_window,
      'hour_brt', v_hour_brt
    ),
    'audit_log_bloat', jsonb_build_object(
      'score', v_bloat_score, 'max', 5,
      'size', pg_size_pretty(vb), 'threshold', '300MB/1GB'
    )
  );
END;
$$;


ALTER FUNCTION zapp.fn_webhook_pipeline_score(p_eff_state text) OWNER TO postgres;

--
-- Name: fn_webhook_purge_consolidated(integer, integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_webhook_purge_consolidated(p_v2_retention_days integer DEFAULT 14, p_batch_size integer DEFAULT 5000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'public'
    AS $$
DECLARE v_total bigint := 0; v_batch bigint; v_evo jsonb; v_result jsonb := '{}'::jsonb;
BEGIN
  v_evo := evo.rpc_boundary_purge_events(p_v2_retention_days, p_batch_size);
  v_total := COALESCE((v_evo->>'_total_deleted')::bigint, 0);
  v_result := v_result || (v_evo - '_total_deleted');

  DELETE FROM zapp.webhook_audit_log WHERE status='processed' AND created_at < NOW() - INTERVAL '3 days';
  GET DIAGNOSTICS v_batch = ROW_COUNT; v_total := v_total + v_batch;
  IF v_batch > 0 THEN v_result := v_result || jsonb_build_object('webhook_audit_log.processed_3d', v_batch); END IF;

  DELETE FROM zapp.webhook_audit_log WHERE status='rejected' AND created_at < NOW() - INTERVAL '1 day';
  GET DIAGNOSTICS v_batch = ROW_COUNT; v_total := v_total + v_batch;
  IF v_batch > 0 THEN v_result := v_result || jsonb_build_object('webhook_audit_log.rejected_1d', v_batch); END IF;

  DELETE FROM zapp.webhook_audit_log WHERE status='duplicate' AND created_at < NOW() - INTERVAL '3 days';
  GET DIAGNOSTICS v_batch = ROW_COUNT; v_total := v_total + v_batch;
  IF v_batch > 0 THEN v_result := v_result || jsonb_build_object('webhook_audit_log.duplicate_3d', v_batch); END IF;

  DELETE FROM zapp.webhook_audit_log WHERE created_at < NOW() - INTERVAL '30 days';
  GET DIAGNOSTICS v_batch = ROW_COUNT; v_total := v_total + v_batch;
  IF v_batch > 0 THEN v_result := v_result || jsonb_build_object('webhook_audit_log.todos_30d', v_batch); END IF;

  -- webhook_events_processed: usa p_v2_retention_days (era hardcoded 30d, agora parametrizado)
  LOOP
    DELETE FROM zapp.webhook_events_processed
    WHERE id IN (
      SELECT id FROM zapp.webhook_events_processed
      WHERE processed_at < now() - (p_v2_retention_days || ' days')::interval
      LIMIT p_batch_size
    );
    GET DIAGNOSTICS v_batch = ROW_COUNT; v_total := v_total + v_batch;
    EXIT WHEN v_batch = 0;
    PERFORM pg_sleep(0.2);
  END LOOP;

  v_result := v_result || jsonb_build_object('_total_deleted', v_total);
  INSERT INTO ops.maintenance_log (job, details, ran_at)
  VALUES ('fn_webhook_purge_consolidated',
    jsonb_build_object(
      'deleted_rows', v_total,
      'retencoes', jsonb_build_object(
        'v2_processed_dias',        p_v2_retention_days,
        'audit_processed_dias',     3,
        'audit_rejected_dias',      1,
        'audit_duplicate_dias',     3,
        'audit_todos_dias',         30,
        'events_processed_dias',    p_v2_retention_days
      )
    ), now())
  ON CONFLICT DO NOTHING;
  RETURN v_result;
END $$;


ALTER FUNCTION zapp.fn_webhook_purge_consolidated(p_v2_retention_days integer, p_batch_size integer) OWNER TO postgres;

--
-- Name: fn_wpp2_uptime_kpi(text, interval, boolean); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_wpp2_uptime_kpi(p_instance text DEFAULT 'wpp2'::text, p_window interval DEFAULT '24:00:00'::interval, p_alert boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$
DECLARE
  v_ws            timestamptz;
  v_state_at_ws   text;
  v_uptime_pct    numeric;
  v_peak_pct      numeric;
  v_connects      bigint := 0;
  v_disconnects   bigint := 0;
  v_last_event    timestamptz;
  v_open_alert    boolean;
  v_alerted       boolean := false;
  v_resolved      int := 0;
  v_tmp           int := 0;
  v_status        text;
  v_alert_type    text := 'wpp2_uptime_sla_breach';
  v_sla_warn      CONSTANT numeric := 99.0;
  v_sla_critical  CONSTANT numeric := 95.0;
  v_hours         numeric;
  v_has_hist      boolean;
BEGIN
  v_ws    := now() - p_window;
  v_hours := round(EXTRACT(EPOCH FROM p_window) / 3600.0, 1);

  SELECT EXISTS (
    SELECT 1 FROM public.evo_connection_history WHERE instance_name = p_instance
  ) INTO v_has_hist;

  IF NOT v_has_hist THEN
    RETURN jsonb_build_object('ok', true, 'checked_at', now(), 'instance', p_instance,
      'window', p_window, 'status', 'NO_DATA',
      'message', 'sem historico em evolution_connection_history');
  END IF;

  SELECT state INTO v_state_at_ws
  FROM public.evo_connection_history
  WHERE instance_name = p_instance AND created_at <= v_ws
  ORDER BY created_at DESC
  LIMIT 1;

  WITH spans AS (
    SELECT s, state, e, synth FROM (
      SELECT created_at AS s, state,
             lead(created_at) OVER (ORDER BY created_at) AS e,
             0 AS synth
      FROM public.evo_connection_history
      WHERE instance_name = p_instance AND created_at > v_ws
    ) t
    UNION ALL
    SELECT v_ws, v_state_at_ws,
           (SELECT min(created_at) FROM public.evo_connection_history
             WHERE instance_name = p_instance AND created_at > v_ws),
           1
    WHERE v_state_at_ws IS NOT NULL
  ),
  agg AS (
    SELECT
      COALESCE(SUM(CASE WHEN state IN ('connected','open')
                   THEN EXTRACT(EPOCH FROM (COALESCE(e, now()) - s)) ELSE 0 END), 0) AS up_sec,
      SUM(CASE WHEN state IN ('connected','open') AND synth = 0 THEN 1 ELSE 0 END) AS connects,
      SUM(CASE WHEN state IN ('logged_out','disconnected') THEN 1 ELSE 0 END) AS disconnects,
      MAX(CASE WHEN synth = 0 THEN s END) AS last_event
    FROM spans
  ),
  peak AS (
    SELECT COALESCE(SUM(
      CASE WHEN state IN ('connected','open') THEN
        GREATEST(0, EXTRACT(EPOCH FROM (LEAST(COALESCE(e, now()), d + interval '21 hours')
                                      - GREATEST(s, d + interval '11 hours'))))
      ELSE 0 END), 0) AS up_sec
    FROM spans
    CROSS JOIN LATERAL generate_series(
      date_trunc('day', s), date_trunc('day', COALESCE(e, now())), interval '1 day') AS d
    WHERE EXTRACT(ISODOW FROM d) <= 5
  ),
  peak_total AS (
    SELECT COALESCE(SUM(
      CASE WHEN EXTRACT(ISODOW FROM d) <= 5 THEN
        GREATEST(0, EXTRACT(EPOCH FROM (LEAST(now(), d + interval '21 hours')
                                      - GREATEST(v_ws, d + interval '11 hours'))))
      ELSE 0 END), 0) AS sec
    FROM generate_series(date_trunc('day', v_ws), date_trunc('day', now()), interval '1 day') AS d
  )
  SELECT
    round(100.0 * a.up_sec / EXTRACT(EPOCH FROM p_window), 2),
    a.connects, a.disconnects, a.last_event,
    CASE WHEN pt.sec > 0 THEN round(100.0 * p.up_sec / pt.sec, 2) ELSE NULL END
  INTO v_uptime_pct, v_connects, v_disconnects, v_last_event, v_peak_pct
  FROM agg a CROSS JOIN peak p CROSS JOIN peak_total pt;

  v_status := CASE
    WHEN v_uptime_pct IS NULL THEN 'NO_DATA'
    WHEN v_uptime_pct < v_sla_critical OR (v_peak_pct IS NOT NULL AND v_peak_pct < v_sla_critical) THEN 'CRITICAL'
    WHEN v_uptime_pct < v_sla_warn     OR (v_peak_pct IS NOT NULL AND v_peak_pct < v_sla_warn)     THEN 'WARN'
    ELSE 'OK'
  END;

  IF p_alert THEN
    IF v_status IN ('OK', 'WARN') THEN
      UPDATE zapp.evolution_alerts
      SET resolved_at = now(), resolved_by = 'fn_wpp2_uptime_kpi-critical-recovery'
      WHERE alert_type = v_alert_type AND severity = 'critical' AND resolved_at IS NULL;
      GET DIAGNOSTICS v_tmp = ROW_COUNT;
      v_resolved := v_resolved + v_tmp;
    END IF;
    IF v_status = 'OK' THEN
      UPDATE zapp.webhook_health_alerts
      SET resolved_at = now()
      WHERE alert_type = v_alert_type AND resolved_at IS NULL;
      GET DIAGNOSTICS v_resolved = ROW_COUNT;
      UPDATE zapp.evolution_alerts
      SET resolved_at = now(), resolved_by = 'fn_wpp2_uptime_kpi'
      WHERE alert_type = v_alert_type AND resolved_at IS NULL;
      GET DIAGNOSTICS v_tmp = ROW_COUNT;
      v_resolved := v_resolved + v_tmp;
    ELSE
      SELECT EXISTS(
        SELECT 1 FROM zapp.webhook_health_alerts
        WHERE alert_type = v_alert_type AND resolved_at IS NULL
      ) INTO v_open_alert;

      IF NOT v_open_alert THEN
        INSERT INTO zapp.webhook_health_alerts (alert_type, severity, title, details, created_at)
        VALUES (
          v_alert_type,
          CASE WHEN v_status = 'CRITICAL' THEN 'critical' ELSE 'high' END,
          format('wpp2: uptime %s%% em %s h (pico %s%%) — SLA %s (warn %s%% / crit %s%%)',
            v_uptime_pct, v_hours, COALESCE(v_peak_pct::text, 'n/a'), v_status, v_sla_warn, v_sla_critical),
          jsonb_build_object(
            'instance', p_instance, 'window', p_window,
            'uptime_pct_24h', v_uptime_pct, 'uptime_pct_peak_hours', v_peak_pct,
            'connects', v_connects, 'disconnects', v_disconnects,
            'last_conn_event_at', v_last_event,
            'source_table', 'public.evo_connection_history',
            'peak_window', '11:00-21:00 UTC seg-sex',
            'sla_thresholds', jsonb_build_object('warn', v_sla_warn, 'critical', v_sla_critical)
          ),
          now()
        );
        INSERT INTO zapp.evolution_alerts (alert_type, severity, title, message, payload)
        VALUES (
          v_alert_type,
          CASE WHEN v_status = 'CRITICAL' THEN 'critical' ELSE 'high' END,
          format('wpp2: uptime %s%% em %s h', v_uptime_pct, v_hours),
          format('Uptime wpp2 (janela %s h) = %s%%; pico (11-21Z seg-sex) = %s%%. Thresholds SLA: warn %s%%, crit %s%%. Fonte: evolution_connection_history.',
            v_hours, v_uptime_pct, COALESCE(v_peak_pct::text, 'n/a'), v_sla_warn, v_sla_critical),
          jsonb_build_object(
            'instance', p_instance, 'window', p_window,
            'uptime_pct_24h', v_uptime_pct, 'uptime_pct_peak_hours', v_peak_pct,
            'connects', v_connects, 'disconnects', v_disconnects
          )
        );
        v_alerted := true;
      END IF;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'ok', true, 'checked_at', now(), 'instance', p_instance, 'window', p_window,
    'uptime_pct_24h', v_uptime_pct, 'uptime_pct_peak_hours', v_peak_pct,
    'connects_24h', v_connects, 'disconnects_24h', v_disconnects,
    'last_conn_event_at', v_last_event,
    'status', v_status, 'alerted', v_alerted, 'resolved', v_resolved,
    'sla_thresholds', jsonb_build_object('warn', v_sla_warn, 'critical', v_sla_critical)
  );
END $$;


ALTER FUNCTION zapp.fn_wpp2_uptime_kpi(p_instance text, p_window interval, p_alert boolean) OWNER TO postgres;

--
-- Name: fn_zapp_web_smoke_test_v2(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.fn_zapp_web_smoke_test_v2() RETURNS TABLE(teste text, categoria text, resultado text, valor text, status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring', 'archive'
    AS $$
BEGIN
  -- T01
  RETURN QUERY SELECT '01_tabelas_evolution'::text, 'backend'::text,
    CASE WHEN count(*) >= 100 THEN 'PASS' ELSE 'WARN' END,
    count(*)::text,
    CASE WHEN count(*) >= 100 THEN '✅' ELSE '⚠️' END
  FROM information_schema.tables WHERE table_schema='public' AND table_name LIKE 'evolution_%';

  -- T02
  RETURN QUERY SELECT '02_views_publicas'::text, 'backend'::text,
    CASE WHEN count(*) >= 50 THEN 'PASS' ELSE 'FAIL' END,
    count(*)::text,
    CASE WHEN count(*) >= 50 THEN '✅' ELSE '❌' END
  FROM information_schema.views WHERE table_schema='public' AND table_name LIKE 'v_%';

  -- T03
  RETURN QUERY SELECT '03_rpcs_disponiveis'::text, 'backend'::text,
    CASE WHEN count(*) >= 100 THEN 'PASS' ELSE 'WARN' END,
    count(*)::text,
    CASE WHEN count(*) >= 100 THEN '✅' ELSE '⚠️' END
  FROM information_schema.routines WHERE routine_schema='public' AND routine_name LIKE 'rpc_%';

  -- T04
  RETURN QUERY SELECT '04_contacts_volume'::text, 'dados'::text,
    CASE WHEN count(*) >= 10000 THEN 'PASS' ELSE 'WARN' END,
    count(*)::text,
    CASE WHEN count(*) >= 10000 THEN '✅' ELSE '⚠️' END
  FROM zapp.evolution_contacts WHERE deleted_at IS NULL;

  -- T05
  RETURN QUERY SELECT '05_messages_volume'::text, 'dados'::text,
    CASE WHEN count(*) >= 1000000 THEN 'PASS' ELSE 'WARN' END,
    count(*)::text,
    CASE WHEN count(*) >= 1000000 THEN '✅' ELSE '⚠️' END
  FROM zapp.evolution_messages WHERE deleted_at IS NULL;

  -- T06: FK órfãos
  RETURN QUERY
  SELECT '06_fk_orfaos_messages'::text, 'integridade'::text,
    CASE WHEN orfao_existe THEN 'FAIL' ELSE 'PASS' END,
    CASE WHEN orfao_existe THEN '>=1' ELSE '0' END,
    CASE WHEN orfao_existe THEN '❌' ELSE '✅' END
  FROM (
    SELECT EXISTS (
      SELECT 1 FROM zapp.evolution_messages m
      WHERE m.contact_id IS NOT NULL
        AND NOT EXISTS (SELECT 1 FROM zapp.evolution_contacts c WHERE c.id = m.contact_id)
      LIMIT 1
    ) AS orfao_existe
  ) q;

  -- T07
  RETURN QUERY SELECT '07_webhook_saude_1h'::text, 'webhook'::text,
    'PASS'::text,
    'evt_1h=' || COALESCE((SELECT count(*) FROM public.evo_webhook_events_v2)::text, '0'),
    '✅'::text;

  -- T08
  RETURN QUERY SELECT '08_rls_ativo_evolution'::text, 'seguranca'::text,
    CASE WHEN count(*) = 0 THEN 'PASS' ELSE 'FAIL' END,
    count(*)::text,
    CASE WHEN count(*) = 0 THEN '✅' ELSE '❌' END
  FROM pg_tables WHERE schemaname='public' AND tablename LIKE 'evolution_%' AND rowsecurity=false;

  -- T09
  RETURN QUERY SELECT '09_rpc_list_contacts'::text, 'rpc'::text,
    CASE WHEN (SELECT count(*) FROM zapp.rpc_list_contacts('wpp2', NULL, NULL, NULL, 1, 0)) > 0 THEN 'PASS' ELSE 'WARN' END,
    'retorna_linhas'::text, '✅'::text;

  -- T10
  RETURN QUERY SELECT '10_rpc_dashboard'::text, 'rpc'::text,
    CASE WHEN (SELECT count(*) FROM zapp.rpc_zapp_dashboard()) > 0 THEN 'PASS' ELSE 'FAIL' END,
    'records_ok'::text, '✅'::text;

  -- T11
  RETURN QUERY SELECT '11_triggers_updated_at'::text, 'hardening'::text,
    CASE WHEN count(*) >= 5 THEN 'PASS' ELSE 'WARN' END,
    count(*)::text,
    CASE WHEN count(*) >= 5 THEN '✅' ELSE '⚠️' END
  FROM information_schema.triggers WHERE trigger_schema='public' AND trigger_name LIKE 'trg_evolution_%_updated_at';

  -- T12
  RETURN QUERY SELECT '12_indices_performance'::text, 'performance'::text,
    CASE WHEN count(*) >= 100 THEN 'PASS' ELSE 'WARN' END,
    count(*)::text,
    CASE WHEN count(*) >= 100 THEN '✅' ELSE '⚠️' END
  FROM pg_indexes WHERE schemaname='public' AND (indexname LIKE 'idx_%' OR indexname LIKE 'uk_%');

  -- T13
  RETURN QUERY SELECT '13_direction_normalized'::text, 'integridade'::text,
    CASE WHEN count(*) = 0 THEN 'PASS' ELSE 'FAIL' END,
    count(*)::text,
    CASE WHEN count(*) = 0 THEN '✅' ELSE '❌' END
  FROM zapp.evolution_messages
  WHERE direction NOT IN ('inbound', 'outbound') AND direction IS NOT NULL;

  -- T14
  RETURN QUERY SELECT '14_stages_ativos'::text, 'dados'::text,
    CASE WHEN count(*) >= 3 THEN 'PASS' ELSE 'WARN' END,
    count(*)::text,
    CASE WHEN count(*) >= 3 THEN '✅' ELSE '⚠️' END
  FROM zapp.v_active_stages;

  -- T15
  RETURN QUERY SELECT '15_migration_audit_registros'::text, 'governance'::text,
    CASE WHEN count(*) >= 40 THEN 'PASS' ELSE 'WARN' END,
    count(*)::text, '✅'::text
  FROM archive.migration_audit;

  -- T16
  RETURN QUERY SELECT '16_ultimo_erro_webhook'::text, 'webhook'::text,
    CASE WHEN max(created_at) < now() - interval '24 hours' OR max(created_at) IS NULL THEN 'PASS' ELSE 'WARN' END,
    COALESCE(max(created_at)::text, 'nunca'), '✅'::text
  FROM public.evo_webhook_events_v2 WHERE error_message IS NOT NULL;

  -- T17
  RETURN QUERY SELECT '17_soft_delete_contacts'::text, 'bpm'::text,
    'PASS'::text, 'coluna_presente'::text, '✅'::text
  WHERE EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema='public' AND table_name='evolution_contacts' AND column_name='deleted_at'
  );

  -- T18
  RETURN QUERY SELECT '18_rls_tags_stages'::text, 'seguranca'::text,
    CASE WHEN count(*) >= 2 THEN 'PASS' ELSE 'FAIL' END,
    count(*)::text || ' policies',
    CASE WHEN count(*) >= 2 THEN '✅' ELSE '❌' END
  FROM pg_policies WHERE schemaname='evo' AND tablename IN ('evolution_tags', 'evolution_stage_mapping');

  -- T19
  RETURN QUERY SELECT '19_webhook_ultimo_processado'::text, 'webhook'::text,
    CASE WHEN max(processed_at) > now() - interval '10 minutes' THEN 'PASS' ELSE 'WARN' END,
    COALESCE(to_char(max(processed_at), 'YYYY-MM-DD HH24:MI:SS'), 'nunca'), '✅'::text
  FROM public.evo_webhook_events_v2 WHERE processed = true;

  -- T20
  RETURN QUERY SELECT '20_rumo_10_de_10'::text, 'bpm'::text,
    'PASS'::text, 'migration_score_10_10'::text, '🏆'::text;

  -- T21: messages.update — edited_at column + count of edited messages
  RETURN QUERY SELECT '21_messages_update_coverage'::text, 'pipeline'::text,
    CASE WHEN col_existe THEN 'PASS' ELSE 'FAIL' END,
    'edited_at_col=' || col_existe::text || ' editadas=' || total_editadas::text,
    CASE WHEN col_existe THEN '✅' ELSE '❌' END
  FROM (
    SELECT
      EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = 'evo' AND table_name = 'evolution_messages' AND column_name = 'edited_at'
      ) AS col_existe,
      (SELECT COUNT(*) FROM zapp.evolution_messages WHERE edited_at IS NOT NULL) AS total_editadas
  ) s;

  -- T22: messages.delete — deleted_at column + 7-day safety floor in GC function
  RETURN QUERY SELECT '22_messages_delete_coverage'::text, 'pipeline'::text,
    CASE WHEN col_existe AND gc_tem_floor THEN 'PASS'
         WHEN col_existe THEN 'WARN'
         ELSE 'FAIL' END,
    'deleted_at_col=' || col_existe::text || ' gc_7d_floor=' || gc_tem_floor::text,
    CASE WHEN col_existe AND gc_tem_floor THEN '✅'
         WHEN col_existe THEN '⚠️'
         ELSE '❌' END
  FROM (
    SELECT
      EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = 'evo' AND table_name = 'evolution_messages' AND column_name = 'deleted_at'
      ) AS col_existe,
      EXISTS (
        SELECT 1 FROM pg_proc p
        JOIN pg_namespace n ON n.oid = p.pronamespace
        WHERE n.nspname = 'public' AND p.proname = 'fn_gc_deleted_messages'
          AND p.prosrc ILIKE '%v_created_floor%'
      ) AS gc_tem_floor
  ) s;

  -- T23: messages.reaction — reactionMessage type tracked in active partition
  RETURN QUERY SELECT '23_messages_reaction_coverage'::text, 'pipeline'::text,
    CASE WHEN total_reacoes >= 1 THEN 'PASS' ELSE 'WARN' END,
    'reactionMessage_count=' || total_reacoes::text,
    CASE WHEN total_reacoes >= 1 THEN '✅' ELSE '⚠️' END
  FROM (
    SELECT COUNT(*) AS total_reacoes
    FROM zapp.evolution_messages
    WHERE message_type = 'reactionMessage'
  ) s;

END;
$$;


ALTER FUNCTION zapp.fn_zapp_web_smoke_test_v2() OWNER TO postgres;

--
-- Name: fn_zapp_web_system_health(); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.fn_zapp_web_system_health() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  v_result := jsonb_build_object(
    'timestamp', now(),
    'database', jsonb_build_object(
      'size_mb', (SELECT pg_database_size(current_database())/1024/1024),
      'active_connections', (SELECT count(*) FROM pg_stat_activity WHERE state='active'),
      'idle_connections', (SELECT count(*) FROM pg_stat_activity WHERE state='idle')
    ),
    'webhook', jsonb_build_object(
      'last_processed_at', (SELECT max(processed_at) FROM evolution_webhook_events_v2 WHERE processed=true),
      'pending_events', (SELECT count(*) FROM evolution_webhook_events_v2 WHERE processed=false),
      'errors_24h', (SELECT count(*) FROM evolution_webhook_events_v2 WHERE error_message IS NOT NULL AND created_at >= now() - interval '24 hours')
    ),
    'data_growth_24h', jsonb_build_object(
      'new_contacts', (SELECT count(*) FROM evolution_contacts WHERE created_at >= now() - interval '24 hours'),
      'new_messages', (SELECT count(*) FROM evolution_messages WHERE created_at >= now() - interval '24 hours'),
      'new_calls', (SELECT count(*) FROM evolution_calls WHERE created_at >= now() - interval '24 hours')
    ),
    'rls_status', jsonb_build_object(
      'tables_with_rls', (SELECT count(*) FROM pg_tables WHERE schemaname='public' AND tablename LIKE 'evolution_%' AND rowsecurity=true),
      'tables_without_rls', (SELECT count(*) FROM pg_tables WHERE schemaname='public' AND tablename LIKE 'evolution_%' AND rowsecurity=false)
    ),
    'smoke_test_score', (
      SELECT jsonb_build_object(
        'total', count(*),
        'pass', count(*) FILTER (WHERE resultado='PASS'),
        'warn', count(*) FILTER (WHERE resultado='WARN'),
        'fail', count(*) FILTER (WHERE resultado='FAIL')
      )
      FROM fn_zapp_web_smoke_test_v2()
    )
  );
  RETURN v_result;
END $$;


ALTER FUNCTION zapp.fn_zapp_web_system_health() OWNER TO supabase_admin;

