--

CREATE FUNCTION zapp.generate_transfer_ticket() RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    today TEXT := to_char(CURRENT_DATE, 'YYYYMMDD');
    seq_val INT;
BEGIN
    seq_val := nextval('transfer_ticket_seq');
    RETURN 'TRF-' || today || '-' || lpad(seq_val::text, 4, '0');
END;
$$;


