--
-- Name: get_active_encryption_key(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.get_active_encryption_key() RETURNS bytea
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_key_material BYTEA;
BEGIN
  SELECT key_material INTO v_key_material
  FROM _encryption_keys
  WHERE active = TRUE
  ORDER BY key_version DESC
  LIMIT 1;

  IF v_key_material IS NULL THEN
    RAISE EXCEPTION 'No active encryption key found' USING ERRCODE = '22P02';
  END IF;

  RETURN v_key_material;
END;
$$;


ALTER FUNCTION zapp.get_active_encryption_key() OWNER TO postgres;

--
-- Name: get_analytics_summary(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.get_analytics_summary(p_workspace_id uuid, p_from_timestamp timestamp with time zone DEFAULT (now() - '30 days'::interval), p_to_timestamp timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog'
    AS $$
DECLARE
  v_summary       jsonb;
  v_total_events  bigint;
  v_by_category   jsonb;
BEGIN
  PERFORM zapp.fn_require_app_user();

  SELECT COUNT(*) INTO v_total_events
  FROM zapp.analytics_events
  WHERE workspace_id = p_workspace_id
    AND timestamp BETWEEN p_from_timestamp AND p_to_timestamp;

  SELECT jsonb_object_agg(category, count) INTO v_by_category
  FROM (
    SELECT category, COUNT(*) AS count
    FROM zapp.analytics_events
    WHERE workspace_id = p_workspace_id
      AND timestamp BETWEEN p_from_timestamp AND p_to_timestamp
    GROUP BY category
  ) sub;

  v_summary := jsonb_build_object(
    'workspace_id', p_workspace_id,
    'period', jsonb_build_object('from', p_from_timestamp, 'to', p_to_timestamp),
    'total_events', v_total_events,
    'by_category', COALESCE(v_by_category, '{}'::jsonb)
  );

  RETURN v_summary;
END;
$$;


ALTER FUNCTION zapp.get_analytics_summary(p_workspace_id uuid, p_from_timestamp timestamp with time zone, p_to_timestamp timestamp with time zone) OWNER TO postgres;

