--
-- Name: get_contact_intelligence_by_phone(text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.get_contact_intelligence_by_phone(p_phone text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_contact        zapp.evolution_contacts%ROWTYPE;
  v_phone_clean    text;
  v_jid_s          text;
  v_jid_lid        text;
  v_jid_colon      text;
  v_msg_count      int  := 0;
  v_last_msg_at    timestamptz;
  v_last_msg_txt   text;
  v_inbound_count  int  := 0;
  v_outbound_count int  := 0;
  v_days_silent    int;
  v_engagement     numeric(5,2);
  v_risk_level     text;
  v_churn_prob     numeric(5,2);
  v_sentiment      text := 'neutral';
  v_briefing       jsonb;
  v_triggers       jsonb := '[]'::jsonb;
  v_rapport        jsonb;
  v_disc_tips      jsonb;
  v_churn          jsonb;
  v_last_ints      jsonb := '[]'::jsonb;
BEGIN
  PERFORM zapp.fn_require_app_user();

  IF p_phone IS NULL OR length(trim(p_phone)) = 0 THEN
    RETURN jsonb_build_object('found', false, 'phone', p_phone, 'error', 'empty_phone');
  END IF;
  IF lower(trim(p_phone)) = 'unknown' THEN
    RETURN jsonb_build_object('found', false, 'phone', p_phone, 'error', 'sentinel_unknown');
  END IF;
  IF p_phone LIKE '%@%' THEN
    v_phone_clean := split_part(p_phone, '@', 1);
    v_phone_clean := split_part(v_phone_clean, ':', 1);
    v_phone_clean := regexp_replace(v_phone_clean, '[^0-9]', '', 'g');
  ELSE
    v_phone_clean := regexp_replace(p_phone, '[^0-9]', '', 'g');
  END IF;
  IF length(v_phone_clean) < 8 THEN
    RETURN jsonb_build_object('found', false, 'phone', p_phone, 'error', 'too_few_digits', 'digits', v_phone_clean);
  END IF;
  v_jid_s     := v_phone_clean || '@s.whatsapp.net';
  v_jid_lid   := v_phone_clean || '@lid';
  v_jid_colon := v_phone_clean || '%@s.whatsapp.net';

  SELECT ec.* INTO v_contact FROM zapp.evolution_contacts ec
  WHERE ec.deleted_at IS NULL AND (ec.phone_number = v_phone_clean OR ec.phone_number = p_phone
    OR ec.remote_jid = v_jid_s OR ec.remote_jid = v_jid_lid OR ec.remote_jid LIKE v_jid_colon OR ec.remote_jid = p_phone)
  ORDER BY CASE WHEN ec.phone_number = v_phone_clean OR ec.phone_number = p_phone THEN 1
    WHEN ec.remote_jid = v_jid_s THEN 2 WHEN ec.remote_jid = v_jid_lid THEN 3 ELSE 4 END LIMIT 1;

  -- F5-19 FIX: evolution_messages_wpp2 → evolution_messages (tabela particionada pai)
  SELECT count(*), count(*) FILTER (WHERE NOT from_me), count(*) FILTER (WHERE from_me),
    max(created_at), (array_agg(content ORDER BY created_at DESC) FILTER (WHERE content IS NOT NULL AND length(content) > 0))[1]
  INTO v_msg_count, v_inbound_count, v_outbound_count, v_last_msg_at, v_last_msg_txt
  FROM zapp.evolution_messages m
  WHERE m.deleted_at IS NULL AND (m.remote_jid = v_jid_s OR m.remote_jid = v_jid_lid
    OR m.remote_jid LIKE v_jid_colon OR (v_contact.id IS NOT NULL AND m.contact_id = v_contact.id));

  IF v_contact.total_messages IS NOT NULL AND v_contact.total_messages > v_msg_count THEN
    v_msg_count := v_contact.total_messages;
  END IF;

  SELECT jsonb_agg(jsonb_build_object(
    'channel','whatsapp','assunto',COALESCE(m.category,'geral'),'resumo',left(m.content,120),
    'sentiment',COALESCE(m.sentiment,'neutral'),
    'data',to_char(m.created_at AT TIME ZONE 'America/Sao_Paulo','YYYY-MM-DD"T"HH24:MI:SS"Z"'))
  ORDER BY m.created_at DESC) INTO v_last_ints
  FROM (SELECT m2.content, m2.created_at, m2.category, m2.sentiment
    FROM zapp.evolution_messages m2
    WHERE m2.deleted_at IS NULL AND m2.content IS NOT NULL AND length(m2.content) > 0
      AND (m2.remote_jid = v_jid_s OR m2.remote_jid = v_jid_lid OR m2.remote_jid LIKE v_jid_colon
        OR (v_contact.id IS NOT NULL AND m2.contact_id = v_contact.id))
    ORDER BY m2.created_at DESC LIMIT 3) m;

  v_days_silent := CASE WHEN v_last_msg_at IS NOT NULL THEN EXTRACT(DAY FROM (now()-v_last_msg_at))::int
    WHEN v_contact.last_message_at IS NOT NULL THEN EXTRACT(DAY FROM (now()-v_contact.last_message_at))::int ELSE NULL END;
  v_engagement := LEAST(100, GREATEST(0, COALESCE(v_contact.lead_score,0)::numeric*0.5 + LEAST(50,v_msg_count*0.5) - COALESCE(v_days_silent,0)*0.3));
  v_sentiment := CASE WHEN v_inbound_count > v_outbound_count*2 THEN 'positive'
    WHEN v_outbound_count > v_inbound_count*3 THEN 'negative' ELSE 'neutral' END;
  v_risk_level := CASE WHEN v_engagement<20 OR COALESCE(v_days_silent,999)>60 OR v_contact.lead_status IN ('lost','churned') THEN 'high'
    WHEN v_engagement<50 OR COALESCE(v_days_silent,999)>30 THEN 'medium' ELSE 'low' END;
  v_churn_prob := GREATEST(0, LEAST(100, 100-v_engagement));

  v_briefing := jsonb_build_object('contact_name',COALESCE(v_contact.full_name,v_contact.push_name,'Contato'),
    'company_name',v_contact.company,'cargo',v_contact.role_title,'relationship_stage',COALESCE(v_contact.lead_status,'open'),
    'relationship_score',v_engagement,'sentiment',v_sentiment,'days_since_last_contact',v_days_silent,
    'total_interactions',v_msg_count,'cliente_ativado',v_contact.id IS NOT NULL,
    'ja_comprou',COALESCE(v_contact.total_purchases,0)>0,'total_pedidos',0,'valor_total_compras',COALESCE(v_contact.total_purchases,0),
    'ticket_medio',NULL,'vendedor',v_contact.assigned_to,'rfm_segment',NULL,'preferred_channel','whatsapp',
    'opening_tip',CASE WHEN v_days_silent IS NULL OR v_msg_count=0 THEN 'Primeiro contato — apresente-se e pergunte a necessidade principal.'
      WHEN v_days_silent>30 THEN 'Cliente sem contato há '||v_days_silent||' dias — reative com mensagem personalizada.'
      WHEN v_days_silent<=1 THEN 'Conversa recente — dê continuidade natural ao último tópico.'
      ELSE 'Inicie com pergunta aberta relacionada à necessidade principal.' END,
    'risk_alert',CASE WHEN v_risk_level='high' THEN 'Alto risco de churn — priorize este contato.' ELSE NULL END);

  RETURN jsonb_build_object('found',v_contact.id IS NOT NULL OR v_msg_count>0,'contact_id',v_contact.id,
    'briefing',v_briefing,'triggers',v_triggers,'rapport',v_rapport,'best_times','[]'::jsonb,'churn',v_churn,'disc_tips',v_disc_tips,
    'last_interactions',COALESCE(v_last_ints,'[]'::jsonb));
END; $$;


ALTER FUNCTION zapp.get_contact_intelligence_by_phone(p_phone text) OWNER TO postgres;

