CREATE FUNCTION zapp.get_contact_notes(p_contact_id uuid, p_limit integer DEFAULT 30) RETURNS TABLE(id uuid, content text, author_id uuid, name text, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
  SELECT
    n.id,
    n.content,
    n.author_id,
    p.name,
    n.created_at
  FROM zapp.contact_notes n
  LEFT JOIN zapp.profiles p ON p.id = n.author_id
  WHERE n.contact_id = p_contact_id
  ORDER BY n.created_at DESC
  LIMIT COALESCE(p_limit, 30);
$$;


