--
-- Name: get_contacts_360_batch(text[]); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.get_contacts_360_batch(p_phones text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$ DECLARE v_phone text; v_contact_record jsonb; v_workspace_id uuid; v_phone_results jsonb[] := ARRAY[]::jsonb[]; BEGIN IF auth.uid() IS NOT NULL THEN SELECT workspace_id INTO v_workspace_id FROM zapp.workspace_members WHERE user_id = auth.uid() LIMIT 1; IF v_workspace_id IS NULL THEN RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501'; END IF; END IF; FOREACH v_phone IN ARRAY p_phones LOOP SELECT jsonb_build_object('contact', CASE WHEN c.id IS NOT NULL THEN row_to_json(c) ELSE NULL END, 'conversation_id', (SELECT ec.id FROM zapp.evolution_conversations ec WHERE (ec.remote_jid = v_phone OR ec.remote_jid = (replace(v_phone, '@s.whatsapp.net', '') || '@s.whatsapp.net')) ORDER BY ec.created_at DESC LIMIT 1), 'phone', v_phone, 'found', c.id IS NOT NULL) INTO v_contact_record FROM zapp.contacts c WHERE (c.phone = v_phone OR c.phone = replace(v_phone, '@s.whatsapp.net', '') OR (v_phone || '@s.whatsapp.net') = c.phone) AND (v_workspace_id IS NULL OR c.workspace_id = v_workspace_id) LIMIT 1; IF v_contact_record IS NULL THEN v_contact_record := jsonb_build_object('contact', NULL, 'conversation_id', NULL, 'phone', v_phone, 'found', false); END IF; v_phone_results := array_append(v_phone_results, v_contact_record); END LOOP; RETURN jsonb_build_object('results', array_to_json(v_phone_results), 'count', COALESCE(array_length(v_phone_results, 1), 0)); END; $$;


ALTER FUNCTION zapp.get_contacts_360_batch(p_phones text[]) OWNER TO postgres;

--
-- Name: get_contacts_via_cte_safe(text, text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.get_contacts_via_cte_safe(p_search_field text, p_search_value text) RETURNS TABLE(id uuid, name text, email text, phone text, deleted_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $_$
DECLARE
  v_user_id UUID;
  v_is_admin BOOLEAN;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  v_is_admin := is_admin_or_supervisor(v_user_id);

  -- Only allow known safe fields to prevent injection
  IF p_search_field NOT IN ('phone','email','id','remote_jid','instance_name') THEN
    RAISE EXCEPTION 'Invalid search field' USING ERRCODE = '42703';
  END IF;

  RETURN QUERY EXECUTE format(
    'SELECT c.id, c.name::TEXT, c.email::TEXT, c.phone::TEXT, c.deleted_at
     FROM zapp.contacts c
     WHERE c.%I = $1
       AND (TRUE = $2 OR EXISTS (
         SELECT 1 FROM zapp.workspace_members wm
         WHERE wm.user_id = $3
       ))',
    p_search_field
  ) USING p_search_value, v_is_admin, v_user_id;
END;
$_$;


ALTER FUNCTION zapp.get_contacts_via_cte_safe(p_search_field text, p_search_value text) OWNER TO postgres;

--
-- Name: get_conversations_safe_join(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.get_conversations_safe_join() RETURNS TABLE(conversation_id uuid, contact_id uuid, contact_name text, message_count bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_user_id UUID;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    conv.id,
    ec.id,
    COALESCE(ec.full_name, ec.push_name, 'Sem nome')::TEXT,
    COALESCE(conv.message_count, 0)::BIGINT
  FROM zapp.evolution_conversations conv
  INNER JOIN zapp.evolution_contacts ec ON conv.contact_id = ec.id
  WHERE ec.deleted_at IS NULL
    AND (
      is_admin_or_supervisor(v_user_id)
      OR EXISTS (
        SELECT 1 FROM zapp.workspace_members wm
        WHERE wm.user_id = v_user_id
      )
    );
END;
$$;


ALTER FUNCTION zapp.get_conversations_safe_join() OWNER TO postgres;

--
-- Name: get_csat_stats(text, integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.get_csat_stats(p_instance_name text DEFAULT NULL::text, p_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
WITH base AS (
  SELECT r.rating, r.agent_id
  FROM zapp.csat_responses r
  WHERE r.created_at >= now() - make_interval(days => GREATEST(p_days,1))
    AND (p_instance_name IS NULL OR r.instance_name = p_instance_name)
)
SELECT jsonb_build_object(
  'total_responses', count(*),
  'avg_score', round(avg(rating)::numeric, 2),
  'nps_promoters', count(*) FILTER (WHERE rating = 5),
  'nps_passives', count(*) FILTER (WHERE rating = 4),
  'nps_detractors', count(*) FILTER (WHERE rating <= 3),
  'nps_score', CASE WHEN count(*)=0 THEN 0 ELSE round(100.0*(count(*) FILTER (WHERE rating=5) - count(*) FILTER (WHERE rating<=3))/count(*)) END,
  'score_distribution', COALESCE((SELECT jsonb_object_agg(rating::text, n) FROM (SELECT rating, count(*) n FROM base GROUP BY rating) d), '{}'::jsonb),
  'by_agent', (SELECT jsonb_object_agg(agent_id::text, avg_r) FROM (SELECT agent_id, round(avg(rating)::numeric,2) avg_r FROM base WHERE agent_id IS NOT NULL GROUP BY agent_id) a),
  'period_days', p_days
) FROM base;
$$;


ALTER FUNCTION zapp.get_csat_stats(p_instance_name text, p_days integer) OWNER TO postgres;

