CREATE FUNCTION zapp.get_duplicate_report(p_instance_name text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
BEGIN
  PERFORM zapp.fn_require_app_user();
  RETURN (
    WITH grupos AS (SELECT regexp_replace(coalesce(phone_number,''),'\D','','g') AS pn, count(*) AS qtd, array_agg(coalesce(full_name,push_name,phone_number)::text) AS nomes FROM zapp.evolution_contacts WHERE deleted_at IS NULL AND instance_name=p_instance_name AND length(regexp_replace(coalesce(phone_number,''),'\D','','g'))>=10 GROUP BY 1 HAVING count(*)>1)
    SELECT jsonb_build_object('instance', p_instance_name, 'grupos_duplicados', (SELECT count(*) FROM grupos), 'contatos_em_duplicidade', coalesce((SELECT sum(qtd) FROM grupos),0), 'excedentes_a_mesclar', coalesce((SELECT sum(qtd-1) FROM grupos),0), 'amostra_top5', coalesce((SELECT jsonb_agg(jsonb_build_object('phone',pn,'qtd',qtd,'nomes',nomes)) FROM (SELECT * FROM grupos ORDER BY qtd DESC LIMIT 5) t), '[]'::jsonb))
  );
END;
$$;


