--
-- Name: get_normalized_phone(text); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.get_normalized_phone(phone text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$
  SELECT CASE
    WHEN phone IS NULL OR phone = '' THEN NULL
    ELSE
      regexp_replace(
        CASE
          -- Strip leading 55 country code
          WHEN regexp_replace(phone, '[^0-9]', '', 'g') ~ '^55[1-9][0-9]' AND
               length(regexp_replace(phone, '[^0-9]', '', 'g')) IN (12, 13)
          THEN substring(regexp_replace(phone, '[^0-9]', '', 'g') FROM 3)
          ELSE regexp_replace(phone, '[^0-9]', '', 'g')
        END,
        '^',
        ''
      )
  END
$$;


ALTER FUNCTION zapp.get_normalized_phone(phone text) OWNER TO supabase_admin;

