--
-- Name: get_page_via_cursor(character varying, integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.get_page_via_cursor(p_cursor_id character varying, p_page_size integer DEFAULT 50) RETURNS TABLE(row_number integer, id uuid, name text, email text, phone text, deleted_at timestamp with time zone, next_cursor character varying)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_last_record_id UUID;
  v_user_id        UUID;
BEGIN
  v_user_id := auth.uid();

  SELECT last_record_id INTO v_last_record_id
  FROM _pagination_state
  WHERE cursor_id   = p_cursor_id
    AND created_by  = v_user_id
    AND expires_at  > NOW();

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invalid or expired cursor' USING ERRCODE = '22023';
  END IF;

  RETURN QUERY WITH page_data AS (
    SELECT
      ROW_NUMBER() OVER (ORDER BY c.id)::INT AS row_num,
      c.id,
      c.name::TEXT,
      c.email::TEXT,
      c.phone::TEXT,
      c.deleted_at
    FROM zapp.contacts c
    WHERE c.deleted_at IS NULL
      AND (
        is_admin_or_supervisor(v_user_id)
        OR EXISTS (
          SELECT 1 FROM zapp.workspace_members wm WHERE wm.user_id = v_user_id
        )
      )
      AND CASE
        WHEN v_last_record_id IS NULL THEN TRUE
        ELSE c.id > v_last_record_id
      END
    ORDER BY c.id
    LIMIT p_page_size + 1
  )
  SELECT
    pd.row_num,
    pd.id,
    pd.name,
    pd.email,
    pd.phone,
    pd.deleted_at,
    CASE
      WHEN COUNT(*) OVER () > p_page_size
        THEN create_pagination_cursor('contacts', pd.id)
      ELSE NULL
    END::VARCHAR
  FROM page_data pd
  WHERE pd.row_num <= p_page_size;

  -- Cleanup expired cursors for this user
  DELETE FROM _pagination_state
  WHERE expires_at < NOW()
    AND created_by = v_user_id;
END;
$$;


