--
-- Name: get_platform_health(text, integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.get_platform_health(p_instance_name text DEFAULT NULL::text, p_days integer DEFAULT 1) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo'
    AS $$ SELECT jsonb_build_object('contacts', jsonb_build_object('total_active', (SELECT count(*) FROM zapp.evolution_contacts WHERE deleted_at IS NULL), 'new_today', (SELECT count(*) FROM zapp.evolution_contacts WHERE created_at >= date_trunc('day', now()) AND deleted_at IS NULL), 'duplicates', (SELECT COALESCE(sum(n-1),0) FROM (SELECT count(*) n FROM zapp.evolution_contacts WHERE deleted_at IS NULL AND phone_number IS NOT NULL GROUP BY phone_number HAVING count(*)>1) d), 'consent_rate_pct', 'n/a'), 'conversations', jsonb_build_object('open', (SELECT count(*) FROM zapp.evolution_conversations WHERE status NOT IN ('closed','resolved') OR status IS NULL), 'closed_today', (SELECT count(*) FROM zapp.evolution_conversations WHERE status IN ('closed','resolved') AND updated_at >= date_trunc('day', now())), 'unread', (SELECT COALESCE(sum(unread_count),0) FROM zapp.evolution_conversations), 'bot_active', (SELECT count(*) FROM zapp.evolution_conversations WHERE COALESCE(is_bot_active,false)), 'avg_response_s', NULL), 'messages', jsonb_build_object('total_today', (SELECT count(*) FROM zapp.evolution_messages WHERE created_at >= date_trunc('day', now())), 'inbound_today', (SELECT count(*) FROM zapp.evolution_messages WHERE created_at >= date_trunc('day', now()) AND COALESCE(from_me,false)=false), 'outbound_today', (SELECT count(*) FROM zapp.evolution_messages WHERE created_at >= date_trunc('day', now()) AND COALESCE(from_me,false)=true), 'failed_today', (SELECT count(*) FROM zapp.failed_messages WHERE created_at >= date_trunc('day', now()))), 'webhooks', jsonb_build_object('total_events', (SELECT count(*) FROM public.evo_webhook_events_v2 WHERE created_at >= now() - make_interval(days => GREATEST(p_days,1))), 'processed_events', (SELECT count(*) FROM public.evo_webhook_events_v2 WHERE created_at >= now() - make_interval(days => GREATEST(p_days,1)) AND processed_at IS NOT NULL), 'pending_events', (SELECT count(*) FROM public.evo_webhook_events_v2 WHERE created_at >= now() - make_interval(days => GREATEST(p_days,1)) AND processed_at IS NULL), 'dlq_pending', (SELECT count(*) FROM zapp.failed_messages WHERE status IN ('pending','retrying'))), 'instance_name', COALESCE(p_instance_name,'all'), 'generated_at', now()::text) $$;


ALTER FUNCTION zapp.get_platform_health(p_instance_name text, p_days integer) OWNER TO postgres;

