--
-- Name: get_segment_contacts(uuid, integer, integer); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.get_segment_contacts(p_segment_id uuid, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, remote_jid text, phone_number text, full_name text, push_name text, lead_status text, lead_score integer, last_message_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  v_filters jsonb; v_instance text; v_lead_status text; v_min_score int;
  v_created_after timestamptz; v_no_consent boolean;
BEGIN
  -- FIX: qualificar contact_segments.id pra evitar ambiguidade com p_segment_id no Self-Hosted
  SELECT cs.filters, cs.instance_name INTO v_filters, v_instance
  FROM zapp.contact_segments cs WHERE cs.id = p_segment_id;

  IF NOT FOUND THEN RETURN; END IF;

  v_lead_status := v_filters->>'lead_status';
  v_min_score := (v_filters->>'min_lead_score')::int;
  v_no_consent := (v_filters->>'no_lgpd_consent')::boolean;

  IF v_filters->>'created_after' = '7d' THEN
    v_created_after := now() - interval '7 days';
  ELSIF v_filters->>'created_after' = '30d' THEN
    v_created_after := now() - interval '30 days';
  END IF;

  RETURN QUERY
  SELECT c.id, c.remote_jid::text, c.phone_number::text,
    c.full_name::text, c.push_name::text,
    c.lead_status::text, c.lead_score, c.last_message_at
  FROM zapp.evolution_contacts c
  WHERE c.deleted_at IS NULL
    AND c.instance_name = v_instance
    AND (v_lead_status IS NULL OR c.lead_status = v_lead_status)
    AND (v_min_score IS NULL OR c.lead_score >= v_min_score)
    AND (v_created_after IS NULL OR c.created_at >= v_created_after)
    AND (v_no_consent IS NOT TRUE OR (c.lgpd_consent_at IS NULL AND c.lgpd_opt_out_at IS NULL))
  ORDER BY c.last_message_at DESC NULLS LAST
  LIMIT p_limit OFFSET p_offset;
END;
$$;


ALTER FUNCTION zapp.get_segment_contacts(p_segment_id uuid, p_limit integer, p_offset integer) OWNER TO supabase_admin;

--
-- Name: get_server_time(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.get_server_time() RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_server_time TIMESTAMPTZ;
BEGIN
  SELECT server_time INTO v_server_time
  FROM _authoritative_time
  WHERE id = 1;

  UPDATE _authoritative_time
  SET server_time = NOW()
  WHERE id = 1;

  RETURN COALESCE(v_server_time, NOW());
END;
$$;


ALTER FUNCTION zapp.get_server_time() OWNER TO postgres;

--
-- Name: get_sla_dashboard(text, integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.get_sla_dashboard(p_instance_name text DEFAULT NULL::text, p_days integer DEFAULT 7) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$ WITH v AS (SELECT * FROM zapp.sla_delivery_violations WHERE detected_at >= now() - make_interval(days => GREATEST(p_days,1))), conv AS (SELECT count(*) AS total FROM zapp.evolution_conversations WHERE created_at >= now() - make_interval(days => GREATEST(p_days,1))) SELECT jsonb_build_object('total_violations', (SELECT count(*) FROM v), 'unresolved_violations', (SELECT count(*) FROM v WHERE NOT is_resolved), 'first_response_violations', (SELECT count(*) FROM v WHERE threshold_type ILIKE '%first%' OR threshold_type ILIKE '%response%'), 'resolution_violations', (SELECT count(*) FROM v WHERE threshold_type ILIKE '%resol%'), 'breached_conversations', (SELECT count(DISTINCT contact_id) FROM v), 'compliance_rate_pct', (SELECT CASE WHEN c.total=0 THEN 100 ELSE round(100.0*GREATEST(c.total - (SELECT count(DISTINCT contact_id) FROM v),0)/c.total, 1) END FROM conv c), 'avg_overdue_minutes', (SELECT round(avg(EXTRACT(EPOCH FROM (COALESCE(resolved_at, now()) - detected_at))/60.0)::numeric,1) FROM v), 'period_days', p_days) $$;


ALTER FUNCTION zapp.get_sla_dashboard(p_instance_name text, p_days integer) OWNER TO postgres;

--
-- Name: get_snapshot_version(character varying); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.get_snapshot_version(p_table_name character varying) RETURNS bigint
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog'
    AS $$
DECLARE
  v_version BIGINT;
BEGIN
  SELECT version_number INTO v_version
  FROM _snapshot_version_state
  WHERE table_name = p_table_name;
  RETURN COALESCE(v_version, 1);
END;
$$;


