    name text DEFAULT ''::text NOT NULL,
    email text,
    avatar_url text,
    role text DEFAULT 'agent'::text NOT NULL,
    max_chats integer DEFAULT 5 NOT NULL,
    department text,
    is_online boolean DEFAULT false,
    last_seen timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    access_level text DEFAULT 'basic'::text,
    birthday date,
    can_download boolean DEFAULT false NOT NULL,
    department_id uuid,
    is_active boolean DEFAULT true,
    job_title text,
    nickname text,
    permissions jsonb DEFAULT '{}'::jsonb,
    phone text,
    session_invalidated_at timestamp with time zone,
    signature text,
    _admin_user_id uuid,
    online_status text DEFAULT 'offline'::text,
    onboarding_status text DEFAULT 'active'::text NOT NULL,
    CONSTRAINT check_department CHECK ((department = ANY (ARRAY[('comercial'::character varying)::text, ('financeiro'::character varying)::text, ('compras'::character varying)::text, ('logistica'::character varying)::text, ('artes'::character varying)::text, ('gravacao'::character varying)::text, ('marketing'::character varying)::text, ('ti'::character varying)::text, ('sistema'::character varying)::text]))),
    CONSTRAINT profiles_onboarding_status_check CHECK ((onboarding_status = ANY (ARRAY['pending'::text, 'active'::text, 'suspended'::text]))),
    CONSTRAINT profiles_online_status_check CHECK ((online_status = ANY (ARRAY['online'::text, 'offline'::text, 'busy'::text]))),
    CONSTRAINT profiles_role_check CHECK ((role = ANY (ARRAY['admin'::text, 'supervisor'::text, 'agent'::text])))
);


