--

COMMENT ON FUNCTION zapp.grant_lgpd_consent(p_contact_id uuid, p_channel text, p_marketing_consent boolean, p_data_sharing boolean, p_profiling boolean) IS 'FATOR X v6.1.0: registra consentimento LGPD com trilha de auditoria e limpa opt-out.';


--
-- Name: handle_new_auth_user_painel(); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.handle_new_auth_user_painel() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$
DECLARE
  v_role TEXT;
  v_apps JSONB;
  v_pertence_painel BOOLEAN;
BEGIN
  v_role := NEW.raw_user_meta_data->>'role';
  v_apps := COALESCE(NEW.raw_user_meta_data->'apps', '{}'::jsonb);

  -- Pertence ao Painel Cotação se: role válido OU metadata.apps.painel_cotacao=true
  -- FIX: use COALESCE to handle NULL v_role properly
  v_pertence_painel := (
    COALESCE(v_role, '') IN ('admin','cotacao')
    OR (v_apps->>'painel_cotacao')::boolean IS TRUE
    OR (v_apps->>'logistica')::boolean IS TRUE
  );

  IF NOT v_pertence_painel THEN
    RETURN NEW;
  END IF;

  -- Sanitiza role: se não for admin ou cotacao, usa cotacao como default
  IF v_role IS NULL OR v_role NOT IN ('admin','cotacao') THEN
    v_role := 'cotacao';
  END IF;

  INSERT INTO zapp.perfis_usuarios (id, email, nome, role, ativo, deletado)
  VALUES (
    NEW.id,
    NEW.email,
    COALESCE(NEW.raw_user_meta_data->>'nome', split_part(NEW.email, '@', 1)),
    v_role,
    TRUE,
    FALSE
  )
  ON CONFLICT (id) DO NOTHING;

  RETURN NEW;
END;
$$;


ALTER FUNCTION zapp.handle_new_auth_user_painel() OWNER TO supabase_admin;

--
-- Name: handle_new_user(); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  -- Cria profile (zapp.profiles.id = gen_random_uuid() ≠ NEW.id)
  -- O trigger on_profile_created_init_stats vai criar o agent_stats automaticamente
  -- com o profile.id correto via init_agent_stats()
  INSERT INTO zapp.profiles (user_id, email, name, role)
  VALUES (
    NEW.id,
    NEW.email,
    COALESCE(NEW.raw_user_meta_data ->> 'name', split_part(NEW.email, '@', 1)),
    COALESCE(NEW.raw_user_meta_data ->> 'role', 'agent')
  );

  -- REMOVIDO: INSERT INTO zapp.agent_stats (profile_id) VALUES (NEW.id)
  -- BUG: NEW.id é o auth.users.id, não o zapp.profiles.id
  -- Já tratado por: on_profile_created_init_stats → init_agent_stats()

  INSERT INTO zapp.user_settings (user_id) VALUES (NEW.id)
  ON CONFLICT (user_id) DO NOTHING;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- Não bloquear criação de usuário por erro de trigger
  RAISE WARNING 'handle_new_user error for %: %', NEW.email, SQLERRM;
  RETURN NEW;
END;
$$;


ALTER FUNCTION zapp.handle_new_user() OWNER TO supabase_admin;

