--
-- Name: has_role(uuid, zapp.app_role); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.has_role(_user_id uuid, _role zapp.app_role) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
  SELECT
    (_user_id IS NOT DISTINCT FROM auth.uid())
    AND EXISTS (
      SELECT 1 FROM zapp.user_roles
      WHERE user_id = _user_id AND role = _role
    )
$$;


