CREATE FUNCTION zapp.increment_snapshot_version(entity_name text DEFAULT 'unknown'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog'
    AS $$
BEGIN
  -- Stub criado em s16 2026-08-11: função estava missing causando trigger crash
  -- Inserir no histórico de versão de snapshot se a tabela existir
  BEGIN
    INSERT INTO zapp._snapshot_version_log (entity_name, incremented_at)
    VALUES (entity_name, now())
    ON CONFLICT DO NOTHING;
  EXCEPTION WHEN OTHERS THEN
    NULL; -- tabela pode não existir, ignora silenciosamente
  END;
END;
$$;


ALTER FUNCTION zapp.increment_snapshot_version(entity_name text) OWNER TO postgres;

--
-- Name: increment_snapshot_version(character varying); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.increment_snapshot_version(p_table_name character varying) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog'
    AS $$
DECLARE
  v_new_version BIGINT;
BEGIN
  UPDATE _snapshot_version_state
  SET version_number = version_number + 1, last_mutation_at = now()
  WHERE table_name = p_table_name
  RETURNING version_number INTO v_new_version;
  RETURN COALESCE(v_new_version, 1);
END;
$$;


ALTER FUNCTION zapp.increment_snapshot_version(p_table_name character varying) OWNER TO postgres;

--
-- Name: increment_webhook_rate_limit(text, text, timestamp with time zone, integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.increment_webhook_rate_limit(p_instance_id text, p_event_type text, p_window_start timestamp with time zone, p_limit integer) RETURNS TABLE(current_count integer, is_allowed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE v_count int;
BEGIN
  INSERT INTO zapp.webhook_rate_limits(instance_id,event_type,window_start,event_count,created_at)
  VALUES(p_instance_id,p_event_type,p_window_start,1,now())
  ON CONFLICT (instance_id,event_type,window_start)
  DO UPDATE SET event_count = zapp.webhook_rate_limits.event_count + 1
  RETURNING event_count INTO v_count;
  RETURN QUERY SELECT v_count, (v_count <= p_limit * 10);
END;
$$;


ALTER FUNCTION zapp.increment_webhook_rate_limit(p_instance_id text, p_event_type text, p_window_start timestamp with time zone, p_limit integer) OWNER TO postgres;

