--
-- Name: invite_user(text, text, text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.invite_user(p_email text, p_role text DEFAULT 'agent'::text, p_message text DEFAULT NULL::text) RETURNS TABLE(invite_id uuid, token text, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog'
    AS $_$
DECLARE
  v_caller uuid := auth.uid();
  v_id     uuid;
  v_token  text;
  v_exp    timestamptz;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'permission denied for invite_user' USING ERRCODE = '42501';
  END IF;
  IF p_email IS NULL OR p_email !~ '^[^@]+@[^@]+\.[^@]+$' THEN
    RAISE EXCEPTION 'invalid email' USING ERRCODE = '22023';
  END IF;
  IF p_role NOT IN ('admin', 'supervisor', 'agent') THEN
    RAISE EXCEPTION 'invalid role' USING ERRCODE = '22023';
  END IF;

  v_token := encode(gen_random_bytes(24), 'hex');
  v_exp := now() + interval '7 days';

  BEGIN
    INSERT INTO zapp.invites (email, role, message, token, expires_at, created_by)
    VALUES (lower(p_email), p_role, p_message, v_token, v_exp, v_caller)
    RETURNING id INTO v_id;
  EXCEPTION
    WHEN unique_violation THEN
      RAISE EXCEPTION 'email already invited' USING ERRCODE = '23505';
  END;

  RETURN QUERY SELECT v_id, v_token, v_exp;
END;
$_$;


ALTER FUNCTION zapp.invite_user(p_email text, p_role text, p_message text) OWNER TO postgres;

--
-- Name: is_account_locked(text); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.is_account_locked(check_email text) RETURNS TABLE(is_locked boolean, locked_until timestamp with time zone, attempts integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  v_attempt RECORD;
BEGIN
  SELECT la.attempt_count, la.locked_until, la.last_attempt_at
  INTO v_attempt
  FROM zapp.login_attempts la
  WHERE la.email = LOWER(check_email);
  
  IF NOT FOUND THEN
    RETURN QUERY SELECT false, NULL::TIMESTAMP WITH TIME ZONE, 0;
    RETURN;
  END IF;
  
  -- Check if still locked
  IF v_attempt.locked_until IS NOT NULL AND v_attempt.locked_until > now() THEN
    RETURN QUERY SELECT true, v_attempt.locked_until, v_attempt.attempt_count;
    RETURN;
  END IF;
  
  -- Not locked
  RETURN QUERY SELECT false, NULL::TIMESTAMP WITH TIME ZONE, v_attempt.attempt_count;
END;
$$;


ALTER FUNCTION zapp.is_account_locked(check_email text) OWNER TO supabase_admin;

