--
-- Name: manage_department_member(uuid, uuid, uuid, text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.manage_department_member(_admin_user_id uuid, _target_profile_id uuid, _department_id uuid, _action text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$
DECLARE
  v_admin_role text;
  v_dept_name  text;
  v_profile    record;
BEGIN
  -- Verificar permissão do admin
  SELECT role INTO v_admin_role
  FROM zapp.user_roles
  WHERE user_id = _admin_user_id
  LIMIT 1;

  IF v_admin_role NOT IN ('admin','manager','supervisor') THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Permissão insuficiente',
      'required_role', 'admin/manager/supervisor',
      'current_role', v_admin_role
    );
  END IF;

  -- Verificar se dept existe
  SELECT name INTO v_dept_name FROM zapp.departments WHERE id = _department_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Departamento não encontrado');
  END IF;

  -- Verificar target profile
  SELECT * INTO v_profile FROM zapp.profiles WHERE id = _target_profile_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Perfil não encontrado');
  END IF;

  IF _action = 'add' THEN
    UPDATE zapp.profiles
    SET department_id = _department_id,
        department    = v_dept_name
    WHERE id = _target_profile_id;
    RETURN jsonb_build_object(
      'success', true, 'action', 'add',
      'profile_id', _target_profile_id,
      'department_id', _department_id,
      'department_name', v_dept_name
    );
  ELSIF _action = 'remove' THEN
    UPDATE zapp.profiles
    SET department_id = NULL,
        department    = NULL
    WHERE id = _target_profile_id AND department_id = _department_id;
    RETURN jsonb_build_object(
      'success', true, 'action', 'remove',
      'profile_id', _target_profile_id,
      'removed_from', v_dept_name
    );
  ELSE
    RETURN jsonb_build_object('success', false, 'error', format('Ação inválida: %s', _action));
  END IF;
END;
$$;


ALTER FUNCTION zapp.manage_department_member(_admin_user_id uuid, _target_profile_id uuid, _department_id uuid, _action text) OWNER TO postgres;

--
-- Name: manage_department_member(uuid, uuid, text, uuid, uuid); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.manage_department_member(p_profile_id uuid DEFAULT NULL::uuid, p_department_id uuid DEFAULT NULL::uuid, p_action text DEFAULT NULL::text, _admin_user_id uuid DEFAULT NULL::uuid, _target_profile_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
    v_target_id UUID;
BEGIN
    v_target_id := COALESCE(p_profile_id, _target_profile_id);
    
    IF v_target_id IS NULL THEN
        RETURN FALSE;
    END IF;

    IF p_action = 'add' AND p_department_id IS NOT NULL THEN
        UPDATE zapp.profiles SET department_id = p_department_id WHERE id = v_target_id;
    ELSIF p_action = 'remove' THEN
        UPDATE zapp.profiles SET department_id = NULL WHERE id = v_target_id;
    END IF;
    RETURN TRUE;
END;
$$;


ALTER FUNCTION zapp.manage_department_member(p_profile_id uuid, p_department_id uuid, p_action text, _admin_user_id uuid, _target_profile_id uuid) OWNER TO postgres;

