--
-- Name: mark_pause_investigated(uuid, text); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.mark_pause_investigated(p_pause_id uuid, p_notes text DEFAULT NULL::text) RETURNS zapp.instance_processing_pauses
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  v_row zapp.instance_processing_pauses;
BEGIN
  IF NOT zapp.is_admin_or_supervisor(auth.uid()) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  UPDATE zapp.instance_processing_pauses
     SET investigated_at = now(),
         investigated_by = auth.uid(),
         investigation_notes = COALESCE(NULLIF(trim(p_notes), ''), investigation_notes)
   WHERE id = p_pause_id
   RETURNING * INTO v_row;

  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'pause_not_found';
  END IF;

  RETURN v_row;
END;
$$;


ALTER FUNCTION zapp.mark_pause_investigated(p_pause_id uuid, p_notes text) OWNER TO supabase_admin;

