--
-- Name: mask_cpf(text); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.mask_cpf(cpf text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$
  SELECT CASE
    WHEN cpf IS NULL THEN NULL
    ELSE '***.' || substring(cpf, 5, 3) || '.***-**'
  END
$$;


ALTER FUNCTION zapp.mask_cpf(cpf text) OWNER TO supabase_admin;

--
-- Name: mask_email(text); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.mask_email(email text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$
  SELECT CASE
    WHEN email IS NULL OR position('@' IN email) < 2 THEN email
    ELSE
      left(email, 1) ||
      repeat('*', greatest(0, position('@' IN email) - 2)) ||
      substring(email FROM position('@' IN email))
  END
$$;


ALTER FUNCTION zapp.mask_email(email text) OWNER TO supabase_admin;

--
-- Name: mask_phone(text); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.mask_phone(phone text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$
  SELECT CASE
    WHEN phone IS NULL OR length(phone) < 4 THEN phone
    ELSE
      -- Show first 2 + last 4 digits, mask middle
      left(phone, 2) || repeat('*', greatest(0, length(phone) - 6)) || right(phone, 4)
  END
$$;


ALTER FUNCTION zapp.mask_phone(phone text) OWNER TO supabase_admin;

