--
-- Name: pause_instance(text, text, integer, integer); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.pause_instance(p_instance text, p_reason text, p_minutes integer DEFAULT 15, p_trigger_count integer DEFAULT 0) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  v_id uuid;
BEGIN
  IF NOT zapp.is_admin_or_supervisor(auth.uid()) THEN
    RAISE EXCEPTION 'Access denied: admin or supervisor role required';
  END IF;

  IF p_minutes <= 0 OR p_minutes > 1440 THEN
    RAISE EXCEPTION 'p_minutes must be between 1 and 1440';
  END IF;

  INSERT INTO zapp.instance_processing_pauses (
    instance_name, paused_until, reason, trigger_count, paused_by, auto_paused
  )
  VALUES (
    p_instance,
    now() + (p_minutes || ' minutes')::interval,
    COALESCE(NULLIF(trim(p_reason), ''), 'manual_pause'),
    GREATEST(0, COALESCE(p_trigger_count, 0)),
    auth.uid(),
    false
  )
  RETURNING id INTO v_id;

  INSERT INTO zapp.audit_logs (user_id, action, entity_type, entity_id, details)
  VALUES (
    auth.uid(),
    'instance_paused',
    'instance_processing_pauses',
    v_id::text,
    jsonb_build_object(
      'instance', p_instance,
      'minutes', p_minutes,
      'reason', p_reason,
      'trigger_count', p_trigger_count
    )
  );

  RETURN v_id;
END;
$$;


ALTER FUNCTION zapp.pause_instance(p_instance text, p_reason text, p_minutes integer, p_trigger_count integer) OWNER TO supabase_admin;

--
-- Name: pg_stat_database_simple(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.pg_stat_database_simple() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp, pg_temp'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  PERFORM zapp.fn_require_app_user();
  SELECT jsonb_build_object(
           'datname', datname,
           'numbackends', numbackends,
           'xact_commit', xact_commit,
           'xact_rollback', xact_rollback,
           'blks_read', blks_read,
           'blks_hit', blks_hit,
           'tup_returned', tup_returned,
           'tup_fetched', tup_fetched,
           'tup_inserted', tup_inserted,
           'tup_updated', tup_updated,
           'tup_deleted', tup_deleted,
           'sampled_at', now()
         )
  INTO v_result
  FROM pg_catalog.pg_stat_database
  WHERE datname = current_database();
  RETURN coalesce(v_result, '{}'::jsonb);
END;
$$;


ALTER FUNCTION zapp.pg_stat_database_simple() OWNER TO postgres;

--
-- Name: populate_contact_intelligence_batch(integer, integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.populate_contact_intelligence_batch(p_batch_size integer DEFAULT 500, p_offset integer DEFAULT 0) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_contact_id uuid;
  v_count      int := 0;
BEGIN
  FOR v_contact_id IN
    SELECT ec.id
    FROM zapp.evolution_contacts ec
    LEFT JOIN zapp.contact_intelligence ci ON ci.contact_id = ec.id
    WHERE ec.deleted_at IS NULL
      AND ci.contact_id IS NULL   -- ainda não tem registro de CI
    ORDER BY ec.last_message_at DESC NULLS LAST
    LIMIT p_batch_size
    OFFSET p_offset
  LOOP
    PERFORM zapp.upsert_contact_intelligence(v_contact_id);
    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END;
$$;


