--
-- Name: prevent_profile_privilege_escalation(); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.prevent_profile_privilege_escalation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
BEGIN
  -- If role, permissions, or access_level are being changed
  IF (OLD.role IS DISTINCT FROM NEW.role) OR 
     (OLD.permissions IS DISTINCT FROM NEW.permissions) OR 
     (OLD.access_level IS DISTINCT FROM NEW.access_level) THEN
    -- Only allow if user is admin or supervisor
    IF NOT is_admin_or_supervisor(auth.uid()) THEN
      RAISE EXCEPTION 'Only administrators can modify role, permissions, or access_level';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION zapp.prevent_profile_privilege_escalation() OWNER TO supabase_admin;

--
-- Name: prevent_role_escalation(); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.prevent_role_escalation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions', 'pg_catalog'
    AS $$
DECLARE
  v_uid        uuid;
  v_blocked    text[] := '{}';
BEGIN
  -- service_role always permitted
  IF current_setting('request.jwt.claim.role', true) = 'service_role' THEN
    RETURN NEW;
  END IF;

  -- Resolve caller identity safely (NULL if no JWT context)
  BEGIN
    v_uid := auth.uid();
  EXCEPTION WHEN OTHERS THEN
    v_uid := NULL;
  END;

  -- Check role escalation
  IF OLD.role IS DISTINCT FROM NEW.role
     AND NOT COALESCE(zapp.is_admin_or_supervisor(v_uid), false) THEN
    v_blocked := array_append(v_blocked,
      format('role: %s -> %s',
        COALESCE(OLD.role,'null'), COALESCE(NEW.role,'null')));
    NEW.role := OLD.role;
  END IF;

  -- Check access_level escalation
  IF OLD.access_level IS DISTINCT FROM NEW.access_level
     AND NOT COALESCE(zapp.is_admin_or_supervisor(v_uid), false) THEN
    v_blocked := array_append(v_blocked,
      format('access_level: %s -> %s',
        COALESCE(OLD.access_level::text,'null'),
        COALESCE(NEW.access_level::text,'null')));
    NEW.access_level := OLD.access_level;
  END IF;

  -- Check permissions escalation
  IF OLD.permissions IS DISTINCT FROM NEW.permissions
     AND NOT COALESCE(zapp.is_admin_or_supervisor(v_uid), false) THEN
    v_blocked := array_append(v_blocked, 'permissions');
    NEW.permissions := OLD.permissions;
  END IF;

  -- If any violation: server-log (survives rollback) + audit + raise
  IF array_length(v_blocked, 1) > 0 THEN

    RAISE LOG 'PRIVILEGE_ESCALATION_BLOCKED | user=% | profile=% | fields=[%]',
      v_uid, OLD.id, array_to_string(v_blocked, ', ');

    BEGIN
      INSERT INTO zapp.audit_logs
        (id, action, entity_id, entity_type, user_id, details, event_type, status)
      VALUES (
        gen_random_uuid(),
        'PRIVILEGE_ESCALATION_BLOCKED',
        OLD.id,
        'profile',
        v_uid,
        jsonb_build_object(
          'blocked_fields', v_blocked,
          'old_role', OLD.role,
          'new_role_attempted', NEW.role,
          'trigger', TG_NAME,
          'table', TG_TABLE_SCHEMA || '.' || TG_TABLE_NAME
        ),
        'security',
        'blocked'
      );
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;

    RAISE EXCEPTION 'PRIVILEGE_ESCALATION_BLOCKED: Unauthorized attempt on field(s) [%] for profile %. Operation aborted (42501).',
      array_to_string(v_blocked, ', '), OLD.id
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION zapp.prevent_role_escalation() OWNER TO supabase_admin;

