--
-- Name: restore_contact(uuid); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.restore_contact(p_contact_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  v_workspace_id uuid;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM zapp.profiles p
    WHERE p.user_id = auth.uid()
      AND p.role IN ('admin', 'supervisor', 'manager')
  ) THEN
    RAISE EXCEPTION 'Permission denied: only managers can restore contacts';
  END IF;

  SELECT wm.workspace_id INTO v_workspace_id
  FROM zapp.workspace_members wm
  WHERE wm.user_id = auth.uid()
  LIMIT 1;

  UPDATE evo.evolution_contacts
  SET deleted_at     = NULL,
      deleted_reason = NULL,
      updated_at     = now()
  WHERE id = p_contact_id
    AND deleted_at IS NOT NULL
    AND deleted_at >= now() - interval '30 days';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Contact % not found, not deleted, or outside 30-day recovery window', p_contact_id;
  END IF;
END;
$$;


ALTER FUNCTION zapp.restore_contact(p_contact_id uuid) OWNER TO supabase_admin;

