--
-- Name: rls_auto_enable(); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.rls_auto_enable() RETURNS event_trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog'
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
    IF cmd.schema_name IS NOT NULL
       AND cmd.schema_name IN ('public', 'evo', 'zapp', 'ops')
       AND cmd.schema_name NOT IN ('pg_catalog','information_schema')
       AND cmd.schema_name NOT LIKE 'pg_toast%'
       AND cmd.schema_name NOT LIKE 'pg_temp%'
    THEN
      BEGIN
        EXECUTE format('ALTER TABLE IF EXISTS %s ENABLE ROW LEVEL SECURITY',
                       cmd.object_identity);
        RAISE LOG 'rls_auto_enable: habilitou RLS em %', cmd.object_identity;
      EXCEPTION WHEN OTHERS THEN
        RAISE LOG 'rls_auto_enable: FALHOU em % : %', cmd.object_identity, SQLERRM;
      END;
    ELSE
      RAISE LOG 'rls_auto_enable: skip % (schema % nao monitorado)',
                cmd.object_identity, cmd.schema_name;
    END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION zapp.rls_auto_enable() OWNER TO supabase_admin;

--
-- Name: rpc_add_xp(uuid, numeric, text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_add_xp(p_profile_id uuid, p_xp_delta numeric, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'zapp', 'public'
    AS $$
DECLARE
  v_profile_id  uuid;
  v_prev_level  integer;
  v_xp          numeric;
  v_level       integer;
BEGIN
  IF p_profile_id IS NULL OR p_xp_delta IS NULL OR p_xp_delta <= 0 THEN
    RAISE EXCEPTION 'rpc_add_xp: delta invalido (%)', p_xp_delta
      USING ERRCODE = '22013';
  END IF;

  v_profile_id := zapp.get_profile_id_for_user(auth.uid());
  IF v_profile_id IS NULL
     OR (p_profile_id <> v_profile_id AND NOT zapp.is_admin_or_supervisor()) THEN
    RAISE EXCEPTION 'rpc_add_xp: sem permissao para o perfil %', p_profile_id
      USING ERRCODE = '42501';
  END IF;

  -- Serializa escritas concorrentes no MESMO perfil: a 2ª transação espera a
  -- 1ª commitada e lê o nível/XP já atualizados (leveled_up correto).
  SELECT level INTO v_prev_level
    FROM zapp.agent_stats
   WHERE profile_id = p_profile_id
   FOR UPDATE;

  IF NOT FOUND THEN
    -- Perfil antigo sem linha de stats: cria e soma (upsert atômico).
    -- level é recalculado pelo trigger update_level_on_xp_change.
    INSERT INTO zapp.agent_stats (profile_id, xp)
    VALUES (p_profile_id, p_xp_delta)
    ON CONFLICT (profile_id) DO UPDATE
      SET xp = zapp.agent_stats.xp + EXCLUDED.xp,
          updated_at = pg_catalog.now()
    RETURNING xp, level INTO v_xp, v_level;
    v_prev_level := 1;
  ELSE
    -- ATOMICIDADE: xp = xp + delta (nunca valor absoluto vindo do cliente).
    UPDATE zapp.agent_stats
       SET xp = xp + p_xp_delta,
           updated_at = pg_catalog.now()
     WHERE profile_id = p_profile_id
    RETURNING xp, level INTO v_xp, v_level;
  END IF;

  RETURN pg_catalog.jsonb_build_object(
    'profile_id',     p_profile_id,
    'xp_delta',       p_xp_delta,
    'xp',             v_xp,
    'level',          v_level,
    'previous_level', v_prev_level,
    'leveled_up',     v_level > v_prev_level,
    'reason',         p_reason
  );
END;
$$;


ALTER FUNCTION zapp.rpc_add_xp(p_profile_id uuid, p_xp_delta numeric, p_reason text) OWNER TO postgres;

--
-- Name: FUNCTION rpc_add_xp(p_profile_id uuid, p_xp_delta numeric, p_reason text); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.rpc_add_xp(p_profile_id uuid, p_xp_delta numeric, p_reason text) IS 'E59: incrementa XP de forma atomica (xp = xp + delta, FOR UPDATE). Level recalculado pelo trigger update_level_on_xp_change. Somente o dono do perfil ou admin/supervisor.';


