--
-- Name: rpc_backfill_messages_contact_id(text, integer, boolean); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_backfill_messages_contact_id(p_instance_name text DEFAULT 'wpp2'::text, p_batch_size integer DEFAULT 5000, p_dry_run boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_start timestamptz := clock_timestamp();
  v_cap int := LEAST(p_batch_size, 20000);
  v_repaired bigint := 0;
  v_remaining bigint;
BEGIN
  PERFORM zapp.fn_require_app_user();

  IF NOT p_dry_run THEN
    WITH candidates AS (
      SELECT m.id FROM zapp.evolution_messages m
      WHERE m.instance_name = p_instance_name
        AND m.contact_id IS NULL
        AND m.remote_jid NOT LIKE '%@g.us'
        AND m.remote_jid NOT LIKE '%@broadcast'
        AND m.remote_jid NOT IN ('unknown@s.whatsapp.net','unknown@deleted')
        AND split_part(m.remote_jid,'@',1) NOT LIKE 'smoke%'
      LIMIT v_cap
      FOR UPDATE SKIP LOCKED
    ),
    contact_match AS (
      -- Match by remote_jid (exact)
      SELECT DISTINCT ON (m.id) m.id AS msg_id, c.id AS contact_id
      FROM candidates cand
      JOIN zapp.evolution_messages m ON m.id = cand.id
      JOIN zapp.evolution_contacts c
        ON c.instance_name = m.instance_name
       AND c.remote_jid = m.remote_jid
       AND c.deleted_at IS NULL
      UNION ALL
      -- Match by phone_number (normalized)
      SELECT DISTINCT ON (m.id) m.id, c.id
      FROM candidates cand
      JOIN zapp.evolution_messages m ON m.id = cand.id
      LEFT JOIN zapp.evolution_contacts c
        ON c.instance_name = m.instance_name
       AND c.phone_number = regexp_replace(split_part(m.remote_jid,'@',1), '\D','','g')
       AND c.deleted_at IS NULL
      WHERE c.id IS NOT NULL
    ),
    best_match AS (
      SELECT DISTINCT ON (msg_id) msg_id, contact_id
      FROM contact_match
      WHERE contact_id IS NOT NULL
      ORDER BY msg_id
    ),
    updated AS (
      UPDATE zapp.evolution_messages em
      SET contact_id = bm.contact_id
      FROM best_match bm
      WHERE em.id = bm.msg_id
        AND em.contact_id IS NULL
      RETURNING em.id
    )
    SELECT COUNT(*) INTO v_repaired FROM updated;
  ELSE
    SELECT COUNT(*) INTO v_repaired
    FROM (
      SELECT m.id FROM zapp.evolution_messages m
      WHERE m.instance_name = p_instance_name
        AND m.contact_id IS NULL
        AND m.remote_jid NOT LIKE '%@g.us'
      LIMIT v_cap
    ) sub;
  END IF;

  SELECT COUNT(*) INTO v_remaining
  FROM zapp.evolution_messages
  WHERE instance_name = p_instance_name
    AND contact_id IS NULL
    AND remote_jid NOT LIKE '%@g.us';

  RETURN jsonb_build_object(
    'repaired',          v_repaired,
    'remaining_estimate',v_remaining,
    'instance_name',     p_instance_name,
    'dry_run',           p_dry_run,
    'elapsed_ms',        EXTRACT(EPOCH FROM (clock_timestamp()-v_start))*1000
  );
END;
$$;


ALTER FUNCTION zapp.rpc_backfill_messages_contact_id(p_instance_name text, p_batch_size integer, p_dry_run boolean) OWNER TO postgres;

--
-- Name: FUNCTION rpc_backfill_messages_contact_id(p_instance_name text, p_batch_size integer, p_dry_run boolean); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.rpc_backfill_messages_contact_id(p_instance_name text, p_batch_size integer, p_dry_run boolean) IS 'Match by remote_jid (exact) (extraido do cabecalho do fonte). Args: (p_instance_name text, p_batch_size integer, p_dry_run boolean).';


--
-- Name: rpc_boundary_apply_lid_mappings(boolean, integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_boundary_apply_lid_mappings(p_dry_run boolean DEFAULT true, p_batch integer DEFAULT 10000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog'
    AS $_$
DECLARE
  v_convs_fixed      INT := 0;
  v_msgs_fixed       INT := 0;
  v_contacts_fixed   INT := 0;
  v_fake_fixed       INT := 0;
  v_noop_entries     INT := 0;
BEGIN
  SELECT count(*) INTO v_noop_entries
  FROM public.evo_lid_phone_map
  WHERE confidence IN ('none', 'bootstrap_invalid');

  IF NOT p_dry_run THEN
    -- 1. conversações @lid — apenas mappings REAIS, com guard NOT EXISTS
    WITH mappings AS (
      SELECT lid_jid, phone_number || '@s.whatsapp.net' AS phone_jid
      FROM public.evo_lid_phone_map
      WHERE phone_number IS NOT NULL
        AND confidence IN ('high', 'medium', 'low')
        AND phone_number <> split_part(lid_jid, '@', 1)
    )
    UPDATE zapp.evolution_conversations_wpp2 c
    SET remote_jid = m.phone_jid
    FROM mappings m
    WHERE c.remote_jid = m.lid_jid
      AND c.remote_jid LIKE '%@lid'
      AND NOT EXISTS (
        SELECT 1 FROM zapp.evolution_conversations_wpp2 c2
        WHERE c2.remote_jid = m.phone_jid AND c2.instance_name = c.instance_name
      );
    GET DIAGNOSTICS v_convs_fixed = ROW_COUNT;

    -- 2. mensagens @lid
    WITH mappings AS (
      SELECT lid_jid, phone_number || '@s.whatsapp.net' AS phone_jid
      FROM public.evo_lid_phone_map
      WHERE phone_number IS NOT NULL
        AND confidence IN ('high', 'medium', 'low')
        AND phone_number <> split_part(lid_jid, '@', 1)
      LIMIT p_batch
    )
    UPDATE zapp.evolution_messages m
    SET remote_jid = mp.phone_jid, updated_at = now()
    FROM mappings mp
    WHERE m.remote_jid = mp.lid_jid
      AND m.remote_jid LIKE '%@lid';
    GET DIAGNOSTICS v_msgs_fixed = ROW_COUNT;

    -- 3. contatos — phone_number real
    UPDATE zapp.evolution_contacts c
    SET phone_number = m.phone_number, updated_at = now()
    FROM public.evo_lid_phone_map m
    WHERE c.remote_jid = m.lid_jid
      AND m.phone_number IS NOT NULL
      AND m.confidence IN ('high', 'medium', 'low')
      AND m.phone_number <> split_part(m.lid_jid, '@', 1)
      AND (c.phone_number IS NULL
           OR c.phone_number = split_part(c.remote_jid, '@', 1));
    GET DIAGNOSTICS v_contacts_fixed = ROW_COUNT;

    -- 4. fake @s.whatsapp.net JIDs
    WITH fake_mappings AS (
      SELECT
        split_part(lm.lid_jid, '@', 1) || '@s.whatsapp.net' AS fake_jid,
        lm.phone_number || '@s.whatsapp.net' AS real_jid
      FROM public.evo_lid_phone_map lm
      WHERE lm.phone_number IS NOT NULL
        AND lm.confidence IN ('high', 'medium', 'low')
        AND lm.phone_number <> split_part(lm.lid_jid, '@', 1)
      LIMIT p_batch
    )
    UPDATE zapp.evolution_messages_wpp2 m
    SET remote_jid = fm.real_jid
    FROM fake_mappings fm
    WHERE m.remote_jid = fm.fake_jid
      AND m.remote_jid ~ '^[0-9]{14,}@s\.whatsapp\.net$';
    GET DIAGNOSTICS v_fake_fixed = ROW_COUNT;

  ELSE
    -- DRY-RUN
    SELECT count(*) INTO v_convs_fixed
    FROM zapp.evolution_conversations_wpp2 c
    JOIN public.evo_lid_phone_map m ON c.remote_jid = m.lid_jid
    WHERE c.remote_jid LIKE '%@lid'
      AND m.phone_number IS NOT NULL
      AND m.confidence IN ('high', 'medium', 'low')
      AND m.phone_number <> split_part(m.lid_jid, '@', 1)
      AND NOT EXISTS (
        SELECT 1 FROM zapp.evolution_conversations_wpp2 c2
        WHERE c2.remote_jid = m.phone_number || '@s.whatsapp.net'
          AND c2.instance_name = c.instance_name
      );

    SELECT count(*) INTO v_msgs_fixed
    FROM zapp.evolution_messages msg
    JOIN public.evo_lid_phone_map mp ON msg.remote_jid = mp.lid_jid
    WHERE msg.remote_jid LIKE '%@lid'
      AND mp.phone_number IS NOT NULL
      AND mp.confidence IN ('high', 'medium', 'low')
      AND mp.phone_number <> split_part(mp.lid_jid, '@', 1);

    SELECT count(*) INTO v_fake_fixed
    FROM zapp.evolution_messages_wpp2 m
    JOIN public.evo_lid_phone_map lm ON
      m.remote_jid = split_part(lm.lid_jid, '@', 1) || '@s.whatsapp.net'
    WHERE m.remote_jid ~ '^[0-9]{14,}@s\.whatsapp\.net$'
      AND lm.phone_number IS NOT NULL
      AND lm.confidence IN ('high', 'medium', 'low')
      AND lm.phone_number <> split_part(lm.lid_jid, '@', 1);
  END IF;

  RETURN jsonb_build_object(
    'dry_run',             p_dry_run,
    'convs_would_fix',     v_convs_fixed,
    'msgs_would_fix',      v_msgs_fixed,
    'contacts_would_fix',  v_contacts_fixed,
    'fake_jids_would_fix', v_fake_fixed,
    'map_total',           (SELECT count(*) FROM public.evo_lid_phone_map),
    'map_real_phone',      (SELECT count(*) FROM public.evo_lid_phone_map
                            WHERE phone_number IS NOT NULL
                              AND confidence IN ('high','medium','low')
                              AND phone_number <> split_part(lid_jid,'@',1)),
    'map_invalid_noop',    v_noop_entries,
    'note',                'v2 — inclui correção de fake @s.whatsapp.net JIDs (passo 4)',
    'ts',                  now()
  );
END
$_$;


