--
-- Name: rpc_bulk_repair_dedup_hashes(text, integer, boolean); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_bulk_repair_dedup_hashes(p_instance_name text DEFAULT 'wpp2'::text, p_batch_size integer DEFAULT 5000, p_dry_run boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'extensions'
    AS $$
DECLARE
  v_start timestamptz := clock_timestamp();
  v_cap int := LEAST(p_batch_size, 17000);
  v_updated bigint := 0;
  v_skipped bigint;
BEGIN
  PERFORM zapp.fn_require_app_user();

  SELECT COUNT(*) INTO v_skipped
  FROM zapp.evolution_contacts
  WHERE instance_name = p_instance_name
    AND dedup_hash IS NOT NULL
    AND deleted_at IS NULL;

  IF NOT p_dry_run THEN
    WITH candidates AS (
      SELECT id FROM zapp.evolution_contacts
      WHERE instance_name = p_instance_name
        AND dedup_hash IS NULL
        AND pii_masked_at IS NULL
        AND deleted_at IS NULL
      LIMIT v_cap
      FOR UPDATE SKIP LOCKED
    ),
    updated AS (
      UPDATE zapp.evolution_contacts ec
      SET dedup_hash = encode(
            extensions.digest(
              regexp_replace(coalesce(ec.phone_number,''), '\D', '', 'g')
              || '|' || lower(coalesce(ec.email,''))
              || '|' || lower(coalesce(ec.full_name,'')),
              'sha256'
            ), 'hex'),
          updated_at = now()
      FROM candidates c
      WHERE ec.id = c.id AND ec.pii_masked_at IS NULL
      RETURNING ec.id
    )
    SELECT COUNT(*) INTO v_updated FROM updated;
  ELSE
    SELECT COUNT(*) INTO v_updated
    FROM zapp.evolution_contacts
    WHERE instance_name = p_instance_name
      AND dedup_hash IS NULL AND pii_masked_at IS NULL AND deleted_at IS NULL
    LIMIT v_cap;
  END IF;

  RETURN jsonb_build_object(
    'updated', v_updated, 'skipped', v_skipped,
    'dry_run', p_dry_run, 'batch_size', v_cap,
    'instance_name', p_instance_name,
    'elapsed_ms', EXTRACT(EPOCH FROM (clock_timestamp()-v_start))*1000
  );
END;
$$;


ALTER FUNCTION zapp.rpc_bulk_repair_dedup_hashes(p_instance_name text, p_batch_size integer, p_dry_run boolean) OWNER TO postgres;

--
-- Name: rpc_campaign_assign_variant(uuid, uuid, uuid); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_campaign_assign_variant(p_campaign_id uuid, p_contact_id uuid, p_variant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog'
    AS $$
DECLARE
  v_campaign_owner uuid;
  v_profile_id     uuid;
  v_variant_name   text;
  v_assigned       uuid;
BEGIN
  -- 1. campanha precisa existir
  SELECT c.created_by INTO v_campaign_owner
    FROM zapp.campaigns c
   WHERE c.id = p_campaign_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'campaign % not found', p_campaign_id
      USING ERRCODE = 'no_data_found';
  END IF;

  -- 2. permissão (fail-closed): admin/supervisor OU dono da campanha
  IF NOT zapp.is_admin_or_supervisor(auth.uid()) THEN
    SELECT p.id INTO v_profile_id
      FROM zapp.profiles p
     WHERE p.user_id = auth.uid();
    IF v_campaign_owner IS DISTINCT FROM v_profile_id THEN
      RAISE EXCEPTION 'permission denied: campaign owner or admin/supervisor required'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
  END IF;

  -- 3. variante precisa pertencer à campanha
  IF p_variant_id IS NOT NULL THEN
    SELECT variant_name INTO v_variant_name
      FROM zapp.campaign_ab_variants
     WHERE id = p_variant_id
       AND campaign_id = p_campaign_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'variant % not found in campaign %', p_variant_id, p_campaign_id
        USING ERRCODE = 'no_data_found';
    END IF;
  END IF;

  -- 4. persistência atômica e idempotente: a UNIQUE (campaign_id, contact_id)
  --    garante 1 linha por contato; o DO UPDATE ... WHERE variant IS NULL
  --    garante que uma variante já atribuída NUNCA é sobrescrita (mesmo sob
  --    concorrência). RETURNING devolve a linha final (a existente se o
  --    conflito não atualizou).
  INSERT INTO zapp.campaign_contacts (campaign_id, contact_id, status, variant)
  VALUES (p_campaign_id, p_contact_id, 'pending', p_variant_id)
  ON CONFLICT (campaign_id, contact_id)
  DO UPDATE SET variant = EXCLUDED.variant
   WHERE zapp.campaign_contacts.variant IS NULL
  RETURNING variant INTO v_assigned;

  IF v_assigned IS NULL THEN
    RETURN jsonb_build_object('variant_id', NULL, 'variant_name', NULL, 'assigned', false);
  END IF;

  RETURN jsonb_build_object(
    'variant_id', v_assigned,
    'variant_name', (SELECT variant_name FROM zapp.campaign_ab_variants WHERE id = v_assigned),
    'assigned', true
  );
END;
$$;


