CREATE TABLE zapp.evolution_deals (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    contact_id uuid,
    conversation_id uuid,
    deal_number integer DEFAULT nextval('zapp.evolution_deals_deal_number_seq'::regclass) NOT NULL,
    title character varying(255) NOT NULL,
    description text,
    stage character varying(50) DEFAULT 'novo_pedido'::character varying,
