-- Name: FUNCTION rpc_check_audio_meme_duplicate(p_audio_url text, p_file_hash text); Type: COMMENT; Schema: zapp; Owner: supabase_admin
--

COMMENT ON FUNCTION zapp.rpc_check_audio_meme_duplicate(p_audio_url text, p_file_hash text) IS 'Verifica duplicata de audio-meme por hash SHA256 ou URL.';


--
-- Name: rpc_check_rls_compliance(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_check_rls_compliance() RETURNS TABLE(table_name text, schema_name text, reason text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
  SELECT
    c.relname::text AS table_name,
    n.nspname::text AS schema_name,
    'RLS desabilitado em tabela sensível'::text AS reason
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public'
    AND c.relkind = 'r'
    AND c.relrowsecurity = false
    AND c.relname NOT LIKE E'\\_%'
    AND c.relname NOT IN (
      'spatial_ref_sys',
      'schema_migrations'
    )
  ORDER BY c.relname;
$$;


ALTER FUNCTION zapp.rpc_check_rls_compliance() OWNER TO postgres;

