--
-- Name: rpc_claim_csat_due(integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_claim_csat_due(p_limit integer DEFAULT 50) RETURNS TABLE(survey_id uuid, contact_id uuid, agent_id uuid, conversation_id uuid, whatsapp_connection_id uuid, message_text text, phone text, instance_name text, send_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'public'
    AS $$
DECLARE v_limit integer := GREATEST(1, LEAST(COALESCE(p_limit, 50), 100));
BEGIN
  UPDATE zapp.csat_surveys s SET status = 'scheduled', updated_at = now()
   WHERE s.status = 'sending' AND s.updated_at < now() - interval '10 minutes';
  UPDATE zapp.csat_surveys s SET status = 'sending', attempts = attempts + 1, updated_at = now()
   WHERE s.id IN (SELECT s2.id FROM zapp.csat_surveys s2 WHERE s2.status = 'scheduled' AND s2.send_at <= now() ORDER BY s2.send_at LIMIT v_limit FOR UPDATE OF s2 SKIP LOCKED);
  RETURN QUERY
  SELECT s.id, s.contact_id, s.agent_id, s.conversation_id, s.whatsapp_connection_id, s.message_text, c.phone, w.instance_name, s.send_at
    FROM zapp.csat_surveys s
    LEFT JOIN zapp.contacts c ON c.id = s.contact_id
    LEFT JOIN zapp.whatsapp_connections w ON w.id = s.whatsapp_connection_id
   WHERE s.status = 'sending';
END;
$$;


ALTER FUNCTION zapp.rpc_claim_csat_due(p_limit integer) OWNER TO postgres;

