-- Name: rpc_claim_outbound_message(uuid, text, text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_claim_outbound_message(p_row_id uuid, p_message_id text, p_status text DEFAULT 'sent'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$ DECLARE v_id uuid; BEGIN UPDATE zapp.evolution_messages SET status=p_status, message_id=p_message_id, status_at=now(), updated_at=now() WHERE id=p_row_id AND message_id IS NULL RETURNING id INTO v_id; RETURN jsonb_build_object('ok',true,'claimed_id',v_id,'claimed', v_id IS NOT NULL); EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('ok',false,'error',SQLERRM); END; $$;


