--
-- Name: rpc_claim_pending_report_runs(integer, uuid); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_claim_pending_report_runs(p_limit integer DEFAULT 20, p_report_id uuid DEFAULT NULL::uuid) RETURNS TABLE(run_id uuid, report_id uuid, report_name text, format text, recipients text[], content text, storage_path text, row_count integer, signed_url text, send_attempts integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'public'
    AS $$
DECLARE
  v_limit integer := GREATEST(1, LEAST(COALESCE(p_limit, 20), 50));
BEGIN
  UPDATE zapp.scheduled_report_runs r
     SET status = 'success', claimed_at = NULL
   WHERE r.status = 'sending'
     AND r.claimed_at < now() - interval '10 minutes';

  CREATE TEMP TABLE _claimed_runs (run_id uuid PRIMARY KEY) ON COMMIT DROP;

  WITH claimed AS (
    UPDATE zapp.scheduled_report_runs r
       SET status = 'sending', claimed_at = now(), send_attempts = send_attempts + 1
     WHERE r.id IN (
       SELECT r2.id
         FROM zapp.scheduled_report_runs r2
        WHERE r2.status = 'success'
          AND r2.delivered_at IS NULL
          AND r2.send_attempts < 5
          AND (p_report_id IS NULL OR r2.report_id = p_report_id)
        ORDER BY r2.started_at
        LIMIT v_limit
          FOR UPDATE OF r2 SKIP LOCKED
     )
     RETURNING r.id
  )
  INSERT INTO _claimed_runs SELECT id FROM claimed;

  RETURN QUERY
  SELECT r.id, r.report_id, s.name, s.format, s.recipients,
         r.content, r.storage_path, r.row_count, r.signed_url, r.send_attempts
    FROM zapp.scheduled_report_runs r
    JOIN zapp.scheduled_reports s ON s.id = r.report_id
   WHERE r.id IN (SELECT run_id FROM _claimed_runs)
   ORDER BY r.started_at;
END
$$;


ALTER FUNCTION zapp.rpc_claim_pending_report_runs(p_limit integer, p_report_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION rpc_claim_pending_report_runs(p_limit integer, p_report_id uuid); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.rpc_claim_pending_report_runs(p_limit integer, p_report_id uuid) IS 'Claim atômico (SKIP LOCKED) da outbox scheduled_report_runs p/ a edge send-scheduled-report; recupera sending órfão >10min; send_attempts>=5 vira DLQ (permanece success, não re-claimado).';


--
-- Name: rpc_complete_followup(uuid); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_complete_followup(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'public', 'pg_catalog'
    AS $$
DECLARE
  v_id uuid;
BEGIN
  PERFORM zapp.fn_require_app_user();

  UPDATE zapp.evolution_followups
     SET status = 'completed',
         response_at = now()
   WHERE id = p_id
     AND status IN ('pending', 'scheduled', 'triggered')
   RETURNING id INTO v_id;

  RETURN jsonb_build_object('ok', true, 'completed', v_id IS NOT NULL);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('ok', false, 'error', SQLERRM);
END;
$$;


ALTER FUNCTION zapp.rpc_complete_followup(p_id uuid) OWNER TO postgres;

