CREATE TABLE zapp.evolution_tasks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    contact_id uuid,
    deal_id uuid,
    conversation_id uuid,
    title character varying(255) NOT NULL,
    description text,
    task_type character varying(50) DEFAULT 'task'::character varying,
    assigned_to character varying(100),
    assigned_by character varying(100),
    due_date date,
    due_time time without time zone,
    reminder_at timestamp with time zone,
    priority character varying(20) DEFAULT 'normal'::character varying,
    status character varying(20) DEFAULT 'pending'::character varying,
    completed_at timestamp with time zone,
    completed_by character varying(100),
    is_recurring boolean DEFAULT false,
    recurrence_rule character varying(50),
    recurrence_end date,
    parent_task_id uuid,
    tags text[],
    notes text,
    metadata jsonb,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    deleted_at timestamp with time zone,
    CONSTRAINT evolution_tasks_status_check CHECK (((status IS NULL) OR ((status)::text = ANY (ARRAY['pending'::text, 'in_progress'::text, 'completed'::text, 'cancelled'::text, 'overdue'::text]))))
);


