--
-- Name: rpc_contract_inventory(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_contract_inventory() RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'zapp, pg_temp'
    AS $$
  SELECT jsonb_build_object(
    'functions', (
      SELECT jsonb_agg(jsonb_build_object(
        'name', p.proname,
        'args', pg_get_function_identity_arguments(p.oid),
        'auth_exec', has_function_privilege('authenticated', p.oid, 'EXECUTE')
      ) ORDER BY p.proname)
      FROM pg_proc p
      JOIN pg_namespace n ON n.oid = p.pronamespace
      WHERE n.nspname = 'zapp'
        AND p.prokind = 'f'
    ),
    'tables', (
      SELECT jsonb_agg(jsonb_build_object(
        'name', c.relname,
        'kind', c.relkind::text
      ) ORDER BY c.relname)
      FROM pg_class c
      JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE n.nspname = 'zapp'
        AND c.relkind IN ('r', 'v', 'm', 'f', 'p')
    )
  );
$$;


ALTER FUNCTION zapp.rpc_contract_inventory() OWNER TO postgres;

