--
-- Name: rpc_dashboard_home(text, text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_dashboard_home(p_instance text DEFAULT 'wpp_pink_test'::text, p_assigned_to text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$

BEGIN
  PERFORM zapp.fn_require_app_user();
RETURN (SELECT jsonb_build_object(
  'instance', p_instance,
  'generated_at', now(),
  'conversas', jsonb_build_object(
    'abertas',      COUNT(*) FILTER (WHERE c.status='aberta'),
    'arquivadas',   COUNT(*) FILTER (WHERE c.status='arquivada'),
    'nao_lidas',    COUNT(*) FILTER (WHERE c.unread_count>0),
    'sem_resposta', COUNT(*) FILTER (WHERE c.last_inbound_at > COALESCE(c.last_outbound_at,'-infinity'))
  ),
  'mensagens', (
    SELECT jsonb_build_object(
      'hoje',         COUNT(*) FILTER (WHERE m.created_at >= date_trunc('day',now())),
      'ultimos_7d',   COUNT(*) FILTER (WHERE m.created_at >= now()-INTERVAL '7 days'),
      'inbound_hoje', COUNT(*) FILTER (WHERE m.created_at >= date_trunc('day',now()) AND m.from_me=false),
      'outbound_hoje',COUNT(*) FILTER (WHERE m.created_at >= date_trunc('day',now()) AND m.from_me=true)
    )
    FROM zapp.evolution_messages m
    WHERE m.instance_name=p_instance AND m.created_at >= now()-INTERVAL '7 days'
  ),
  'contatos', (
    SELECT jsonb_build_object(
      'total',    COUNT(*),
      'novos_30d',COUNT(*) FILTER (WHERE ct.created_at >= now()-INTERVAL '30 days')
    )
    FROM zapp.evolution_contacts ct
    WHERE ct.instance_name=p_instance AND ct.deleted_at IS NULL
  ),
  'sla', jsonb_build_object(
    'primeira_resposta_media_seg',
    ROUND(AVG(c.first_response_seconds) FILTER (WHERE c.first_response_seconds IS NOT NULL))::int
  )
)
FROM zapp.evolution_conversations c
WHERE c.instance_name=p_instance
  AND (p_assigned_to IS NULL OR c.assigned_to=p_assigned_to));
END;$$;


ALTER FUNCTION zapp.rpc_dashboard_home(p_instance text, p_assigned_to text) OWNER TO postgres;

