--
-- Name: rpc_delete_contact(text, text, text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_delete_contact(p_remote_jid text, p_instance text DEFAULT 'wpp_pink_test'::text, p_performed_by text DEFAULT 'frontend'::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_temp'
    AS $$
DECLARE v_affected int;
BEGIN
  IF auth.uid() IS NOT NULL AND NOT zapp.is_admin_or_supervisor() THEN
    RAISE EXCEPTION 'forbidden: admin or supervisor required' USING ERRCODE = '42501';
  END IF;
  UPDATE zapp.evolution_contacts
  SET deleted_at = now(), updated_at = now()
  WHERE remote_jid = p_remote_jid
    AND instance_name = p_instance
    AND deleted_at IS NULL;
  GET DIAGNOSTICS v_affected = ROW_COUNT;
  RETURN v_affected > 0;
END;
$$;


