--

CREATE FUNCTION zapp.rpc_delete_followup_sequence(p_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$ DECLARE v_count int; v_id uuid := p_id::uuid; BEGIN DELETE FROM zapp.evolution_followup_rules WHERE sequence_group=v_id OR (sequence_group IS NULL AND id=v_id); GET DIAGNOSTICS v_count = ROW_COUNT; RETURN jsonb_build_object('ok',true,'deleted',v_count); EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('ok',false,'error',SQLERRM); END; $$;


