--
-- Name: rpc_disable_service_channel(uuid, text); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.rpc_disable_service_channel(p_id uuid, p_reason text DEFAULT NULL::text) RETURNS zapp.service_channels
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE v_row zapp.service_channels;
BEGIN
  IF NOT zapp.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Access denied: admin role required';
  END IF;

  UPDATE zapp.service_channels SET
    status = 'disabled',
    disabled_at = now(),
    disabled_reason = NULLIF(trim(COALESCE(p_reason,'')), '')
  WHERE id = p_id
  RETURNING * INTO v_row;

  IF v_row.id IS NULL THEN RAISE EXCEPTION 'channel not found'; END IF;

  -- Marca conexão whatsapp como desconectada (se houver)
  IF v_row.whatsapp_connection_id IS NOT NULL THEN
    UPDATE zapp.whatsapp_connections
       SET status = 'disconnected', updated_at = now()
     WHERE id = v_row.whatsapp_connection_id;
  END IF;

  INSERT INTO zapp.audit_logs (user_id, action, entity_type, entity_id, details)
  VALUES (auth.uid(), 'service_channel_disabled', 'service_channels', p_id::text,
          jsonb_build_object('reason', p_reason, 'wpp_connection', v_row.whatsapp_connection_id));

  RETURN v_row;
END;
$$;


ALTER FUNCTION zapp.rpc_disable_service_channel(p_id uuid, p_reason text) OWNER TO supabase_admin;

