--

CREATE FUNCTION zapp.rpc_dismiss_warroom_alert(p_alert_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$ DECLARE v_is_member boolean; v_updated integer; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'unauthenticated'; END IF; SELECT EXISTS (SELECT 1 FROM zapp.workspace_members WHERE user_id = auth.uid()) OR zapp.is_admin_or_supervisor(auth.uid()) INTO v_is_member; IF NOT v_is_member THEN RETURN false; END IF; UPDATE zapp.warroom_alerts SET is_read = true, dismissed_by = auth.uid(), resolved_at = COALESCE(resolved_at, now()) WHERE id = p_alert_id; GET DIAGNOSTICS v_updated = ROW_COUNT; RETURN v_updated > 0; END; $$;


