--
-- Name: rpc_dlq_retry_now(uuid, uuid); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_dlq_retry_now(p_id uuid DEFAULT NULL::uuid, p_item_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_target  uuid;
  v_updated int;
BEGIN
  IF NOT (zapp.has_role(auth.uid(), 'admin') OR zapp.has_role(auth.uid(), 'supervisor')) THEN
    PERFORM zapp.log_rls_denied(
      'failed_messages', 'admin|supervisor',
      jsonb_build_object('rpc', 'rpc_dlq_retry_now', 'p_id', COALESCE(p_id, p_item_id))
    );
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  v_target := COALESCE(p_id, p_item_id);
  IF v_target IS NULL THEN RETURN FALSE; END IF;
  UPDATE zapp.failed_messages
     SET status          = 'pending',
         next_attempt_at = now(),
         updated_at      = now()
   WHERE id     = v_target
     AND status NOT IN ('processing', 'succeeded');
  GET DIAGNOSTICS v_updated = ROW_COUNT;
  RETURN v_updated > 0;
END;
$$;


ALTER FUNCTION zapp.rpc_dlq_retry_now(p_id uuid, p_item_id uuid) OWNER TO postgres;

--
-- Name: rpc_dlq_stats(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_dlq_stats() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_total          bigint;
  v_total_24h      bigint;
  v_oldest_pending timestamptz;
  v_by_status      jsonb;
  v_by_instance    jsonb;
BEGIN
  IF NOT (zapp.has_role(auth.uid(), 'admin') OR zapp.has_role(auth.uid(), 'supervisor')) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT COUNT(*) INTO v_total FROM zapp.failed_messages;

  SELECT COUNT(*) INTO v_total_24h
  FROM zapp.failed_messages
  WHERE created_at >= NOW() - INTERVAL '24 hours';

  SELECT MIN(created_at) INTO v_oldest_pending
  FROM zapp.failed_messages
  WHERE status = 'pending';

  SELECT jsonb_object_agg(status, cnt) INTO v_by_status
  FROM (
    SELECT status, COUNT(*) AS cnt
    FROM zapp.failed_messages
    GROUP BY status
  ) s;

  SELECT jsonb_agg(
    jsonb_build_object('instance', instance_name, 'count', cnt)
    ORDER BY cnt DESC
  ) INTO v_by_instance
  FROM (
    SELECT instance_name, COUNT(*) AS cnt
    FROM zapp.failed_messages
    GROUP BY instance_name
    ORDER BY cnt DESC
    LIMIT 10
  ) i;

  RETURN jsonb_build_object(
    'total',             COALESCE(v_total, 0),
    'total_24h',         COALESCE(v_total_24h, 0),
    'oldest_pending_at', v_oldest_pending,
    'by_status',         COALESCE(v_by_status, '{}'::jsonb),
    'by_instance',       COALESCE(v_by_instance, '[]'::jsonb)
  );
END;
$$;


ALTER FUNCTION zapp.rpc_dlq_stats() OWNER TO postgres;

--
-- Name: rpc_dr_health_check(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_dr_health_check() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'pg_temp'
    AS $$
DECLARE
  v_db_stats      record;
  v_wh_health     record;
  v_cron_failing  bigint;
  v_open_inc      bigint;
  v_evo_cred      record;
  v_result        jsonb;
BEGIN
  SELECT
  CASE WHEN count(*) FILTER (WHERE created_at >= now() - interval '1 hour') > 0 THEN 'healthy'
       WHEN count(*) FILTER (WHERE created_at >= now() - interval '24 hours') > 0 THEN 'degraded'
       ELSE 'critical' END AS health_status,
  max(created_at) AS last_event_at,
  count(*) FILTER (WHERE NOT processed) AS unresponded,
  count(*) FILTER (WHERE created_at >= now() - interval '1 hour') AS events_1h,
  count(*) FILTER (WHERE created_at >= now() - interval '24 hours') AS events_24h,
  count(*) FILTER (WHERE processed_at >= now() - interval '1 hour') AS processed_1h
INTO v_wh_health
FROM public.evo_webhook_events_v2;

  BEGIN
    SELECT count(*) INTO v_cron_failing FROM cron.job WHERE active = false;
  EXCEPTION WHEN OTHERS THEN
    v_cron_failing := 0;
  END;

  BEGIN
    SELECT count(*) INTO v_open_inc
    FROM zapp.system_health_incidents WHERE status IN ('open','investigating');
  EXCEPTION WHEN OTHERS THEN
    v_open_inc := 0;
  END;

  BEGIN
    SELECT * INTO v_evo_cred
    FROM zapp.evolution_instance_credentials WHERE instance_name='wpp2' LIMIT 1;
  EXCEPTION WHEN OTHERS THEN
    v_evo_cred := NULL;
  END;

  v_result := jsonb_build_object(
    'overall_status', CASE
      WHEN v_wh_health.health_status = 'critical' THEN 'critical'
      WHEN v_open_inc > 0 OR v_cron_failing > 0 THEN 'degraded'
      ELSE 'healthy'
    END,
    'checks', jsonb_build_object(
      'pipeline', jsonb_build_object(
        'status',       v_wh_health.health_status,
        'last_event_at', v_wh_health.last_event_at,
        'pending',      v_wh_health.unresponded
      ),
      'cron_jobs', jsonb_build_object(
        'disabled_count', COALESCE(v_cron_failing, 0),
        'status', CASE WHEN COALESCE(v_cron_failing,0)=0 THEN 'ok' ELSE 'warning' END
      ),
      'incidents', jsonb_build_object(
        'open_count', COALESCE(v_open_inc, 0),
        'status', CASE WHEN COALESCE(v_open_inc,0)=0 THEN 'ok' ELSE 'warning' END
      ),
      'evo_api', jsonb_build_object(
        'instance',       'wpp2',
        'health_status',  COALESCE(v_evo_cred.health_status, 'unknown'),
        'last_check',     v_evo_cred.last_health_check
      ),
      'database', jsonb_build_object('status','ok','checked_at',now())
    ),
    'runbook_steps', 8,
    'generated_at', now()
  );

  RETURN v_result;
END;
$$;


ALTER FUNCTION zapp.rpc_dr_health_check() OWNER TO postgres;

--
-- Name: rpc_e2e_cleanup(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_e2e_cleanup() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'public'
    AS $$ DECLARE v_contacts int := 0; v_conversations int := 0; v_messages int := 0; v_evo_messages int := 0; v_evo_contacts int := 0; v_result jsonb; BEGIN ALTER TABLE zapp.evolution_contacts DISABLE TRIGGER USER; BEGIN WITH e2e_contacts AS (SELECT id FROM zapp.contacts WHERE phone LIKE '55119999999%' OR email LIKE '%@zappweb.test' OR name LIKE 'E2E %') DELETE FROM zapp.messages WHERE contact_id IN (SELECT id FROM e2e_contacts) OR remote_jid LIKE '55119999999%@s.whatsapp.net'; GET DIAGNOSTICS v_messages = ROW_COUNT; WITH e2e_contacts AS (SELECT id FROM zapp.contacts WHERE phone LIKE '55119999999%' OR email LIKE '%@zappweb.test' OR name LIKE 'E2E %') DELETE FROM zapp.conversations WHERE contact_id IN (SELECT id FROM e2e_contacts) OR remote_jid LIKE '55119999999%@s.whatsapp.net'; GET DIAGNOSTICS v_conversations = ROW_COUNT; DELETE FROM zapp.evolution_messages WHERE remote_jid LIKE '55119999999%@s.whatsapp.net' AND created_at >= now() - interval '90 days'; GET DIAGNOSTICS v_evo_messages = ROW_COUNT; DELETE FROM zapp.evolution_contacts WHERE remote_jid LIKE '55119999999%@s.whatsapp.net' AND created_at >= now() - interval '90 days'; GET DIAGNOSTICS v_evo_contacts = ROW_COUNT; DELETE FROM zapp.contacts WHERE phone LIKE '55119999999%' OR email LIKE '%@zappweb.test' OR name LIKE 'E2E %'; GET DIAGNOSTICS v_contacts = ROW_COUNT; v_result := jsonb_build_object('contacts_deleted', v_contacts, 'conversations_deleted', v_conversations, 'messages_deleted', v_messages, 'evo_messages_deleted', v_evo_messages, 'evo_contacts_deleted', v_evo_contacts); ALTER TABLE zapp.evolution_contacts ENABLE TRIGGER USER; RETURN v_result; EXCEPTION WHEN others THEN ALTER TABLE zapp.evolution_contacts ENABLE TRIGGER USER; RAISE; END; END; $$;


ALTER FUNCTION zapp.rpc_e2e_cleanup() OWNER TO postgres;

--
-- Name: rpc_e2e_seed_contacts(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_e2e_seed_contacts() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'public'
    AS $$ DECLARE v_seeds jsonb := jsonb_build_array(jsonb_build_object('phone','5511999999901','name','E2E Contact Alpha','email','e2e-alpha@zappweb.test'), jsonb_build_object('phone','5511999999902','name','E2E Contact Beta','email','e2e-beta@zappweb.test'), jsonb_build_object('phone','5511999999903','name','E2E Contact Gamma','email','e2e-gamma@zappweb.test'), jsonb_build_object('phone','5511999999904','name','E2E Contact Delta','email','e2e-delta@zappweb.test'), jsonb_build_object('phone','5511999999905','name','E2E Contact Epsilon','email','e2e-epsilon@zappweb.test')); v_row jsonb; v_phone text; v_name text; v_email text; v_jid text; v_has_email boolean; v_has_jid boolean; v_has_active boolean; v_has_tags boolean; v_cols text; v_vals text; v_updates text; v_inserted int := 0; v_updated int := 0; v_id uuid; BEGIN SELECT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='zapp' AND table_name='contacts' AND column_name='email') INTO v_has_email; SELECT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='zapp' AND table_name='contacts' AND column_name='remote_jid') INTO v_has_jid; SELECT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='zapp' AND table_name='contacts' AND column_name='is_active') INTO v_has_active; SELECT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='zapp' AND table_name='contacts' AND column_name='tags') INTO v_has_tags; FOR v_row IN SELECT * FROM jsonb_array_elements(v_seeds) LOOP v_phone := v_row->>'phone'; v_name := v_row->>'name'; v_email := v_row->>'email'; v_jid := v_phone || '@s.whatsapp.net'; SELECT id INTO v_id FROM zapp.contacts WHERE phone = v_phone LIMIT 1; IF v_id IS NULL THEN v_cols := 'phone, name'; v_vals := format('%L, %L', v_phone, v_name); IF v_has_email THEN v_cols := v_cols || ', email'; v_vals := v_vals || format(', %L', v_email); END IF; IF v_has_jid THEN v_cols := v_cols || ', remote_jid'; v_vals := v_vals || format(', %L', v_jid); END IF; IF v_has_active THEN v_cols := v_cols || ', is_active'; v_vals := v_vals || ', true'; END IF; IF v_has_tags THEN v_cols := v_cols || ', tags'; v_vals := v_vals || format(', %L::text[]', '{e2e,seed}'); END IF; EXECUTE format('INSERT INTO zapp.contacts (%s) VALUES (%s)', v_cols, v_vals); v_inserted := v_inserted + 1; ELSE v_updates := 'name = ' || quote_literal(v_name); IF v_has_email THEN v_updates := v_updates || ', email = ' || quote_literal(v_email); END IF; IF v_has_jid THEN v_updates := v_updates || ', remote_jid = ' || quote_literal(v_jid); END IF; IF v_has_active THEN v_updates := v_updates || ', is_active = true'; END IF; EXECUTE format('UPDATE zapp.contacts SET %s WHERE id = %L', v_updates, v_id); v_updated := v_updated + 1; END IF; END LOOP; RETURN jsonb_build_object('kind','contacts','table','zapp.contacts','inserted',v_inserted,'updated',v_updated,'total',v_inserted+v_updated); END; $$;


ALTER FUNCTION zapp.rpc_e2e_seed_contacts() OWNER TO postgres;

--
-- Name: rpc_e2e_seed_user(text, text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_e2e_seed_user(p_email text, p_password text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions', 'public'
    AS $$ DECLARE v_user_id uuid; v_encrypted text; v_user_action text := 'unchanged'; v_roles_before int := 0; v_roles_after int := 0; v_roles_added int := 0; v_roles_list text[]; v_workspace uuid := 'd188f2f8-1ca3-4176-bcbc-1a1c481e24ad'; BEGIN IF p_email IS NULL OR p_password IS NULL OR p_email = '' OR p_password = '' THEN RETURN jsonb_build_object('ok', false, 'error', 'email e password obrigatorios'); END IF; v_encrypted := extensions.crypt(p_password, extensions.gen_salt('bf', 10)); SELECT id INTO v_user_id FROM auth.users WHERE email = p_email; IF v_user_id IS NULL THEN v_user_id := extensions.gen_random_uuid(); INSERT INTO auth.users (id, instance_id, aud, role, email, encrypted_password, email_confirmed_at, created_at, updated_at, raw_app_meta_data, raw_user_meta_data, is_super_admin) VALUES (v_user_id, '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', p_email, v_encrypted, now(), now(), now(), jsonb_build_object('provider','email','providers',jsonb_build_array('email')), jsonb_build_object('name','E2E Bot','seed','e2e'), false); v_user_action := 'inserted'; ELSE UPDATE auth.users SET encrypted_password = v_encrypted, email_confirmed_at = COALESCE(email_confirmed_at, now()), updated_at = now(), banned_until = NULL, deleted_at = NULL WHERE id = v_user_id; v_user_action := 'updated'; END IF; INSERT INTO zapp.profiles (user_id, name, email, role, is_active, access_level) VALUES (v_user_id, 'E2E Bot', p_email, 'agent', true, 'agent') ON CONFLICT (user_id) DO UPDATE SET is_active = true, role = COALESCE(zapp.profiles.role, 'agent'), access_level = COALESCE(zapp.profiles.access_level, 'agent'), email = EXCLUDED.email, updated_at = now(); SELECT COUNT(*) INTO v_roles_before FROM zapp.user_roles WHERE user_id = v_user_id; INSERT INTO zapp.user_roles (id, user_id, role_key, workspace_id, role, created_at) VALUES (extensions.gen_random_uuid(), v_user_id, 'agent', v_workspace, 'agent', now()) ON CONFLICT (user_id, workspace_id) DO UPDATE SET role = 'agent', role_key = 'agent'; SELECT COUNT(*), array_agg(role::text ORDER BY role::text) INTO v_roles_after, v_roles_list FROM zapp.user_roles WHERE user_id = v_user_id; v_roles_added := v_roles_after - v_roles_before; RETURN jsonb_build_object('ok', true, 'email', p_email, 'user_id', v_user_id, 'user_action', v_user_action, 'roles', to_jsonb(v_roles_list), 'roles_total', v_roles_after, 'roles_added', v_roles_added); END; $$;


ALTER FUNCTION zapp.rpc_e2e_seed_user(p_email text, p_password text) OWNER TO postgres;

--
-- Name: rpc_e2e_validate_user(text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_e2e_validate_user(p_email text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'public'
    AS $$ DECLARE v_user_id uuid; v_confirmed timestamptz; v_banned_until timestamptz; v_is_active boolean; v_role_count integer; v_has_crm boolean; v_checks jsonb; BEGIN IF p_email IS NULL OR p_email = '' THEN RETURN jsonb_build_object('valid', false, 'error', 'email vazio'); END IF; SELECT id, email_confirmed_at, banned_until INTO v_user_id, v_confirmed, v_banned_until FROM auth.users WHERE email = p_email; v_checks := jsonb_build_object('user_exists', v_user_id IS NOT NULL, 'email_confirmed', v_confirmed IS NOT NULL, 'not_banned', v_banned_until IS NULL OR v_banned_until <= now()); IF v_user_id IS NOT NULL THEN SELECT is_active INTO v_is_active FROM zapp.profiles WHERE user_id = v_user_id; v_checks := v_checks || jsonb_build_object('profile_exists', v_is_active IS NOT NULL, 'profile_active', v_is_active IS TRUE); SELECT count(*), bool_or(role::text IN ('agent','supervisor','admin')) INTO v_role_count, v_has_crm FROM zapp.user_roles WHERE user_id = v_user_id; v_checks := v_checks || jsonb_build_object('has_roles', coalesce(v_role_count,0) > 0, 'has_crm_role', coalesce(v_has_crm, false)); ELSE v_checks := v_checks || jsonb_build_object('profile_exists', false, 'profile_active', false, 'has_roles', false, 'has_crm_role', false); END IF; RETURN jsonb_build_object('valid', (v_checks->>'user_exists')::boolean AND (v_checks->>'email_confirmed')::boolean AND (v_checks->>'not_banned')::boolean AND (v_checks->>'profile_exists')::boolean AND (v_checks->>'profile_active')::boolean AND (v_checks->>'has_roles')::boolean AND (v_checks->>'has_crm_role')::boolean, 'email', p_email, 'checks', v_checks); END; $$;


ALTER FUNCTION zapp.rpc_e2e_validate_user(p_email text) OWNER TO postgres;

