--
-- Name: rpc_email_cleanup_old_events(integer); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.rpc_email_cleanup_old_events(p_retention_days integer DEFAULT 90) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  v_deleted_events int;
  v_deleted_clicks int;
  v_cutoff timestamptz;
BEGIN
  v_cutoff := now() - (p_retention_days || ' days')::interval;

  -- Delete old tracking events (keep the aggregated counts in tracked_messages)
  DELETE FROM email_tracking_events WHERE created_at < v_cutoff;
  GET DIAGNOSTICS v_deleted_events = ROW_COUNT;

  -- Delete old click events
  DELETE FROM email_link_click_events WHERE created_at < v_cutoff;
  GET DIAGNOSTICS v_deleted_clicks = ROW_COUNT;

  RETURN jsonb_build_object(
    'ok', true,
    'deleted_events', v_deleted_events,
    'deleted_clicks', v_deleted_clicks,
    'cutoff_date', v_cutoff
  );
END;
$$;


ALTER FUNCTION zapp.rpc_email_cleanup_old_events(p_retention_days integer) OWNER TO supabase_admin;

