--

COMMENT ON FUNCTION zapp.rpc_email_cleanup_old_events(p_retention_days integer) IS 'Delete old tracking events (keep the aggregated counts in tracked_messages) (extraido do cabecalho do fonte). Args: (p_retention_days integer).';


--
-- Name: rpc_email_create_tracking(text, text, text, text, text, text, text, uuid, jsonb, jsonb); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.rpc_email_create_tracking(p_recipient_email text, p_recipient_name text DEFAULT NULL::text, p_sender_email text DEFAULT ''::text, p_subject text DEFAULT ''::text, p_thread_id text DEFAULT NULL::text, p_gmail_message_id text DEFAULT NULL::text, p_provider text DEFAULT 'gmail'::text, p_account_id uuid DEFAULT NULL::uuid, p_links jsonb DEFAULT '[]'::jsonb, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tracking_id uuid;
  v_link_count int := 0;
  v_link record;
  v_link_ids jsonb := '[]'::jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('error', 'auth required');
  END IF;

  -- 1. Criar tracked message
  INSERT INTO email_tracked_messages (
    user_id, account_id, provider, recipient_email, recipient_name,
    sender_email, subject, thread_id, gmail_message_id,
    has_tracking_pixel, has_tracked_links,
    tracked_link_count, metadata
  ) VALUES (
    v_uid, p_account_id, p_provider, p_recipient_email, p_recipient_name,
    p_sender_email, p_subject, p_thread_id, p_gmail_message_id,
    true, (jsonb_array_length(p_links) > 0),
    jsonb_array_length(p_links), p_metadata
  )
  RETURNING tracking_id INTO v_tracking_id;

  -- 2. Criar links rastreados
  IF jsonb_array_length(p_links) > 0 THEN
    FOR v_link IN SELECT * FROM jsonb_array_elements(p_links) WITH ORDINALITY AS t(val, pos)
    LOOP
      INSERT INTO email_tracked_links (
        tracking_id, original_url, display_text, position
      ) VALUES (
        v_tracking_id,
        v_link.val->>'url',
        v_link.val->>'text',
        (v_link.pos - 1)::int
      );
      v_link_count := v_link_count + 1;
    END LOOP;
  END IF;

  -- 3. UPSERT contact score (total_sent)
  INSERT INTO email_contact_scores (
    user_id, email, display_name, total_sent
  ) VALUES (
    v_uid, p_recipient_email, p_recipient_name, 1
  )
  ON CONFLICT (user_id, email) DO UPDATE SET
    total_sent = email_contact_scores.total_sent + 1,
    display_name = COALESCE(EXCLUDED.display_name, email_contact_scores.display_name),
    updated_at = now();

  -- 4. Buscar link_ids criados
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object('link_id', link_id, 'original_url', original_url, 'position', position)
  ), '[]'::jsonb) INTO v_link_ids
  FROM email_tracked_links WHERE tracking_id = v_tracking_id;

  RETURN jsonb_build_object(
    'ok', true,
    'tracking_id', v_tracking_id,
    'link_count', v_link_count,
    'links', v_link_ids
  );
END;
$$;


ALTER FUNCTION zapp.rpc_email_create_tracking(p_recipient_email text, p_recipient_name text, p_sender_email text, p_subject text, p_thread_id text, p_gmail_message_id text, p_provider text, p_account_id uuid, p_links jsonb, p_metadata jsonb) OWNER TO supabase_admin;

