--
-- Name: rpc_email_device_breakdown(integer); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.rpc_email_device_breakdown(p_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RETURN '{}'::jsonb; END IF;

  RETURN jsonb_build_object(
    'by_device', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('device', device_type, 'count', cnt)), '[]'::jsonb)
      FROM (
        SELECT e.device_type, COUNT(*) as cnt
        FROM email_tracking_events e
        JOIN email_tracked_messages m ON m.tracking_id = e.tracking_id
        WHERE m.user_id = v_uid AND e.created_at >= now() - (p_days || ' days')::interval
          AND e.is_bot = false
        GROUP BY e.device_type ORDER BY cnt DESC
      ) sub
    ),
    'by_browser', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('browser', browser, 'count', cnt)), '[]'::jsonb)
      FROM (
        SELECT e.browser, COUNT(*) as cnt
        FROM email_tracking_events e
        JOIN email_tracked_messages m ON m.tracking_id = e.tracking_id
        WHERE m.user_id = v_uid AND e.created_at >= now() - (p_days || ' days')::interval
          AND e.is_bot = false
        GROUP BY e.browser ORDER BY cnt DESC
      ) sub
    ),
    'by_country', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('country', country, 'count', cnt)), '[]'::jsonb)
      FROM (
        SELECT e.country, COUNT(*) as cnt
        FROM email_tracking_events e
        JOIN email_tracked_messages m ON m.tracking_id = e.tracking_id
        WHERE m.user_id = v_uid AND e.created_at >= now() - (p_days || ' days')::interval
          AND e.country IS NOT NULL AND e.is_bot = false
        GROUP BY e.country ORDER BY cnt DESC LIMIT 20
      ) sub
    ),
    'bot_percentage', (
      SELECT ROUND(
        (COUNT(*) FILTER (WHERE e.is_bot = true)::numeric /
         NULLIF(COUNT(*), 0)) * 100, 1
      )
      FROM email_tracking_events e
      JOIN email_tracked_messages m ON m.tracking_id = e.tracking_id
      WHERE m.user_id = v_uid AND e.created_at >= now() - (p_days || ' days')::interval
    )
  );
END;
$$;


ALTER FUNCTION zapp.rpc_email_device_breakdown(p_days integer) OWNER TO supabase_admin;

--
-- Name: rpc_email_health_check(); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.rpc_email_health_check() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  v_result jsonb := '{}'::jsonb;
  v_count bigint;
  v_ok boolean := true;
BEGIN
  -- Check tables
  SELECT COUNT(*) INTO v_count FROM pg_tables WHERE schemaname='public' 
    AND tablename IN ('email_tracked_messages','email_tracking_events','email_tracked_links','email_link_click_events','email_contact_scores');
  v_result := v_result || jsonb_build_object('tracking_tables', v_count, 'tables_ok', v_count = 5);
  IF v_count != 5 THEN v_ok := false; END IF;

  -- Check RPCs
  SELECT COUNT(*) INTO v_count FROM pg_proc WHERE proname LIKE 'rpc_email_%';
  v_result := v_result || jsonb_build_object('rpcs', v_count, 'rpcs_ok', v_count >= 10);

  -- Check RLS
  SELECT COUNT(*) INTO v_count FROM pg_tables WHERE schemaname='public' 
    AND tablename IN ('email_tracked_messages','email_tracking_events','email_tracked_links','email_link_click_events','email_contact_scores')
    AND rowsecurity = true;
  v_result := v_result || jsonb_build_object('rls_enabled', v_count, 'rls_ok', v_count = 5);
  IF v_count != 5 THEN v_ok := false; END IF;

  -- Check indexes
  SELECT COUNT(*) INTO v_count FROM pg_indexes WHERE schemaname='public' AND tablename LIKE 'email_track%' AND indexname LIKE 'idx_%';
  v_result := v_result || jsonb_build_object('indexes', v_count, 'indexes_ok', v_count >= 10);

  -- Check edge functions (via HTTP would need separate test)
  v_result := v_result || jsonb_build_object('edge_functions', jsonb_build_array('email-track-pixel', 'email-track-link'));

  -- Data stats
  SELECT COUNT(*) INTO v_count FROM email_tracked_messages;
  v_result := v_result || jsonb_build_object('total_tracked_messages', v_count);
  SELECT COUNT(*) INTO v_count FROM email_tracking_events;
  v_result := v_result || jsonb_build_object('total_events', v_count);
  SELECT COUNT(*) INTO v_count FROM email_contact_scores;
  v_result := v_result || jsonb_build_object('total_contacts_scored', v_count);

  -- Realtime
  SELECT COUNT(*) INTO v_count FROM pg_publication_tables WHERE pubname='supabase_realtime' AND tablename IN ('email_tracking_events','email_tracked_messages');
  v_result := v_result || jsonb_build_object('realtime_tables', v_count);

  -- FTS
  SELECT EXISTS(SELECT 1 FROM pg_indexes WHERE tablename='email_messages' AND indexdef LIKE '%gin%fts%') INTO v_ok;
  v_result := v_result || jsonb_build_object('fts_enabled', v_ok);

  v_result := v_result || jsonb_build_object('status', CASE WHEN v_ok THEN 'healthy' ELSE 'degraded' END, 'checked_at', now());

  RETURN v_result;
END;
$$;


ALTER FUNCTION zapp.rpc_email_health_check() OWNER TO supabase_admin;

--
-- Name: FUNCTION rpc_email_health_check(); Type: COMMENT; Schema: zapp; Owner: supabase_admin
--

COMMENT ON FUNCTION zapp.rpc_email_health_check() IS 'Check tables (extraido do cabecalho do fonte). Args: ().';


--
-- Name: rpc_email_link_performance(uuid, integer, integer); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.rpc_email_link_performance(p_tracking_id uuid DEFAULT NULL::uuid, p_days integer DEFAULT 30, p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RETURN '[]'::jsonb; END IF;

  -- If tracking_id provided, show links for that specific email
  IF p_tracking_id IS NOT NULL THEN
    RETURN (
      SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
          'link_id', l.link_id,
          'original_url', l.original_url,
          'display_text', l.display_text,
          'position', l.position,
          'click_count', l.click_count,
          'first_clicked_at', l.first_clicked_at,
          'last_clicked_at', l.last_clicked_at
        ) ORDER BY l.click_count DESC
      ), '[]'::jsonb)
      FROM email_tracked_links l
      JOIN email_tracked_messages m ON m.tracking_id = l.tracking_id
      WHERE l.tracking_id = p_tracking_id AND m.user_id = v_uid
    );
  END IF;

  -- Otherwise, show top links across all emails
  RETURN (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'original_url', sub.original_url,
        'total_clicks', sub.total_clicks,
        'email_count', sub.email_count,
        'avg_clicks', sub.avg_clicks
      ) ORDER BY sub.total_clicks DESC
    ), '[]'::jsonb)
    FROM (
      SELECT
        l.original_url,
        SUM(l.click_count) as total_clicks,
        COUNT(DISTINCT l.tracking_id) as email_count,
        ROUND(AVG(l.click_count), 1) as avg_clicks
      FROM email_tracked_links l
      JOIN email_tracked_messages m ON m.tracking_id = l.tracking_id
      WHERE m.user_id = v_uid
        AND l.created_at >= now() - (p_days || ' days')::interval
        AND l.click_count > 0
      GROUP BY l.original_url
      ORDER BY total_clicks DESC
      LIMIT p_limit
    ) sub
  );
END;
$$;


ALTER FUNCTION zapp.rpc_email_link_performance(p_tracking_id uuid, p_days integer, p_limit integer) OWNER TO supabase_admin;

--
-- Name: FUNCTION rpc_email_link_performance(p_tracking_id uuid, p_days integer, p_limit integer); Type: COMMENT; Schema: zapp; Owner: supabase_admin
--

COMMENT ON FUNCTION zapp.rpc_email_link_performance(p_tracking_id uuid, p_days integer, p_limit integer) IS 'If tracking_id provided, show links for that specific email (extraido do cabecalho do fonte). Args: (p_tracking_id uuid, p_days integer, p_limit integer).';


--
-- Name: rpc_email_mark_thread_read(uuid, boolean, boolean, uuid[]); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_email_mark_thread_read(p_thread_id uuid, p_read boolean DEFAULT NULL::boolean, p_unread boolean DEFAULT NULL::boolean, p_message_ids uuid[] DEFAULT NULL::uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE v_unread boolean;
BEGIN
  v_unread := CASE WHEN p_unread IS NOT NULL THEN p_unread
                   WHEN p_read   IS NOT NULL THEN NOT p_read
                   ELSE false END;

  UPDATE email_app.email_threads SET is_unread = v_unread, updated_at = now() WHERE id = p_thread_id;

  UPDATE email_app.email_messages SET is_read = NOT v_unread
  WHERE thread_id = p_thread_id AND (p_message_ids IS NULL OR id = ANY(p_message_ids));

  RETURN jsonb_build_object('updated', true, 'thread_id', p_thread_id, 'is_unread', v_unread);
END;
$$;


ALTER FUNCTION zapp.rpc_email_mark_thread_read(p_thread_id uuid, p_read boolean, p_unread boolean, p_message_ids uuid[]) OWNER TO postgres;

--
-- Name: rpc_email_message_details(uuid); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.rpc_email_message_details(p_tracking_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_msg jsonb;
  v_events jsonb;
  v_links jsonb;
BEGIN
  IF v_uid IS NULL THEN RETURN jsonb_build_object('error', 'auth required'); END IF;

  -- Message details
  SELECT jsonb_build_object(
    'id', m.id, 'tracking_id', m.tracking_id, 'recipient_email', m.recipient_email,
    'recipient_name', m.recipient_name, 'sender_email', m.sender_email,
    'subject', m.subject, 'provider', m.provider, 'delivery_status', m.delivery_status,
    'bounce_type', m.bounce_type, 'open_count', m.open_count, 'click_count', m.click_count,
    'first_opened_at', m.first_opened_at, 'last_opened_at', m.last_opened_at,
    'created_at', m.created_at, 'metadata', m.metadata
  ) INTO v_msg
  FROM email_tracked_messages m
  WHERE m.tracking_id = p_tracking_id AND m.user_id = v_uid;

  IF v_msg IS NULL THEN RETURN jsonb_build_object('error', 'not found'); END IF;

  -- Open events (last 50)
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'event_type', e.event_type, 'device_type', e.device_type, 'browser', e.browser,
    'os', e.os, 'country', e.country, 'city', e.city, 'is_bot', e.is_bot,
    'created_at', e.created_at
  ) ORDER BY e.created_at DESC), '[]'::jsonb) INTO v_events
  FROM email_tracking_events e WHERE e.tracking_id = p_tracking_id LIMIT 50;

  -- Links with click details
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'link_id', l.link_id, 'original_url', l.original_url, 'display_text', l.display_text,
    'position', l.position, 'click_count', l.click_count,
    'first_clicked_at', l.first_clicked_at, 'last_clicked_at', l.last_clicked_at
  ) ORDER BY l.position), '[]'::jsonb) INTO v_links
  FROM email_tracked_links l WHERE l.tracking_id = p_tracking_id;

  RETURN jsonb_build_object(
    'message', v_msg,
    'events', v_events,
    'links', v_links
  );
END;
$$;


