-- Name: rpc_email_register_bounce(uuid, text, text); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.rpc_email_register_bounce(p_tracking_id uuid, p_bounce_type text DEFAULT 'soft'::text, p_error_message text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
BEGIN
  UPDATE zapp.email_tracked_messages
  SET delivery_status='bounced', bounce_type=p_bounce_type,
      metadata=metadata||jsonb_build_object('bounce_error',p_error_message,'bounced_at',now()),
      updated_at=now()
  WHERE tracking_id=p_tracking_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error','tracking_id not found'); END IF;
  RETURN jsonb_build_object('ok',true,'bounce_type',p_bounce_type);
END; $$;


