--
-- Name: rpc_email_register_click(uuid, text, text, text, text, text, text, text); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.rpc_email_register_click(p_link_id uuid, p_ip text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text, p_country text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_device_type text DEFAULT 'unknown'::text, p_browser text DEFAULT 'unknown'::text, p_os text DEFAULT 'unknown'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  v_link record; v_msg record; v_now timestamptz := now();
BEGIN
  SELECT link_id, tracking_id, original_url INTO v_link FROM zapp.email_tracked_links WHERE link_id = p_link_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'link_id not found'); END IF;

  SELECT user_id, recipient_email INTO v_msg FROM zapp.email_tracked_messages WHERE tracking_id = v_link.tracking_id;

  INSERT INTO zapp.email_link_click_events (
    link_id, tracking_id, ip_address, user_agent, country, city, device_type, browser, os
  ) VALUES (p_link_id, v_link.tracking_id, p_ip::inet, p_user_agent, p_country, p_city, p_device_type, p_browser, p_os);

  UPDATE zapp.email_tracked_links SET click_count = click_count + 1,
    first_clicked_at = COALESCE(first_clicked_at, v_now), last_clicked_at = v_now
  WHERE link_id = p_link_id;

  UPDATE zapp.email_tracked_messages SET click_count = click_count + 1, updated_at = v_now
  WHERE tracking_id = v_link.tracking_id;

  IF v_msg IS NOT NULL THEN
    INSERT INTO zapp.email_contact_scores (user_id, email, total_clicks, engagement_score, last_interaction)
    VALUES (v_msg.user_id, v_msg.recipient_email, 1, 2, v_now)
    ON CONFLICT (user_id, email) DO UPDATE SET
      total_clicks = email_contact_scores.total_clicks + 1,
      engagement_score = email_contact_scores.engagement_score + 2,
      last_interaction = v_now, updated_at = v_now;
  END IF;

  RETURN jsonb_build_object('ok', true, 'original_url', v_link.original_url);
END;
$$;


ALTER FUNCTION zapp.rpc_email_register_click(p_link_id uuid, p_ip text, p_user_agent text, p_country text, p_city text, p_device_type text, p_browser text, p_os text) OWNER TO supabase_admin;

--
-- Name: rpc_email_register_failure(uuid, text); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.rpc_email_register_failure(p_tracking_id uuid, p_error text DEFAULT 'unknown'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
BEGIN
  UPDATE zapp.email_tracked_messages
  SET delivery_status='failed',
      metadata=metadata||jsonb_build_object('failure_error',p_error,'failed_at',now()),
      updated_at=now()
  WHERE tracking_id=p_tracking_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error','tracking_id not found'); END IF;
  RETURN jsonb_build_object('ok',true);
END; $$;


ALTER FUNCTION zapp.rpc_email_register_failure(p_tracking_id uuid, p_error text) OWNER TO supabase_admin;

--
-- Name: rpc_email_register_open(uuid, text, text, text, text, text, text, text, boolean); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.rpc_email_register_open(p_tracking_id uuid, p_ip text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text, p_country text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_device_type text DEFAULT 'unknown'::text, p_browser text DEFAULT 'unknown'::text, p_os text DEFAULT 'unknown'::text, p_is_self_open boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  v_msg record;
  v_is_bot boolean := false;
  v_now timestamptz := now();
BEGIN
  SELECT id, user_id, recipient_email, open_count
    INTO v_msg FROM zapp.email_tracked_messages
   WHERE tracking_id = p_tracking_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'tracking_id not found'); END IF;

  v_is_bot := (p_device_type = 'bot');

  INSERT INTO zapp.email_tracking_events (
    tracking_id, event_type, ip_address, user_agent,
    country, city, device_type, browser, os, is_self_open, is_bot
  ) VALUES (
    p_tracking_id, 'open', p_ip::inet, p_user_agent,
    p_country, p_city, p_device_type, p_browser, p_os,
    p_is_self_open, v_is_bot
  );

  UPDATE zapp.email_tracked_messages
     SET open_count = open_count + 1,
         first_opened_at = COALESCE(first_opened_at, v_now),
         last_opened_at = v_now,
         delivery_status = CASE WHEN delivery_status = 'sent' THEN 'delivered' ELSE delivery_status END,
         updated_at = v_now
   WHERE tracking_id = p_tracking_id;

  INSERT INTO zapp.email_contact_scores (user_id, email, total_opens, engagement_score, last_interaction)
  VALUES (v_msg.user_id, v_msg.recipient_email, 1, 1, v_now)
  ON CONFLICT (user_id, email) DO UPDATE SET
    total_opens = email_contact_scores.total_opens + 1,
    engagement_score = email_contact_scores.engagement_score + 1,
    last_interaction = v_now,
    updated_at = v_now;

  RETURN jsonb_build_object('ok', true, 'open_count', v_msg.open_count + 1);
END;
$$;


ALTER FUNCTION zapp.rpc_email_register_open(p_tracking_id uuid, p_ip text, p_user_agent text, p_country text, p_city text, p_device_type text, p_browser text, p_os text, p_is_self_open boolean) OWNER TO supabase_admin;

--
-- Name: rpc_email_search(text, uuid, integer); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.rpc_email_search(p_query text, p_account_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tsquery tsquery;
BEGIN
  IF v_uid IS NULL THEN RETURN '[]'::jsonb; END IF;
  
  -- Converter query para tsquery com tratamento de erros
  BEGIN
    v_tsquery := plainto_tsquery('portuguese', p_query);
  EXCEPTION WHEN OTHERS THEN
    v_tsquery := to_tsquery('portuguese', regexp_replace(p_query, '[^a-zA-Z0-9à-ú\s]', '', 'g'));
  END;

  RETURN (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'id', m.id,
        'thread_id', m.thread_id,
        'subject', m.subject,
        'snippet', m.snippet,
        'from_name', m.from_name,
        'from_address', m.from_address,
        'internal_date', m.internal_date,
        'is_read', m.is_read,
        'has_attachments', m.has_attachments,
        'rank', ts_rank(m.fts_vector, v_tsquery)
      ) ORDER BY ts_rank(m.fts_vector, v_tsquery) DESC
    ), '[]'::jsonb)
    FROM email_messages m
    WHERE m.fts_vector @@ v_tsquery
      AND (p_account_id IS NULL OR m.gmail_account_id = p_account_id)
    LIMIT p_limit
  );
END;
$$;


ALTER FUNCTION zapp.rpc_email_search(p_query text, p_account_id uuid, p_limit integer) OWNER TO supabase_admin;

