COMMENT ON FUNCTION zapp.rpc_email_tracking_stats(p_days integer) IS 'Total de emails rastreados no período (extraido do cabecalho do fonte). Args: (p_days integer).';


--
-- Name: rpc_email_unopened_followup(integer, integer, integer); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.rpc_email_unopened_followup(p_min_hours integer DEFAULT 24, p_max_days integer DEFAULT 7, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RETURN '[]'::jsonb; END IF;
  RETURN (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'tracking_id', m.tracking_id,
        'recipient_email', m.recipient_email,
        'recipient_name', m.recipient_name,
        'subject', m.subject,
        'sent_at', m.created_at,
        'hours_ago', EXTRACT(EPOCH FROM now()-m.created_at)/3600
      ) ORDER BY m.created_at
    ), '[]'::jsonb)
    FROM email_tracked_messages m
    WHERE m.user_id = v_uid
      AND m.open_count = 0
      AND m.delivery_status IN ('sent','delivered')
      AND m.created_at < now() - (p_min_hours || ' hours')::interval
      AND m.created_at > now() - (p_max_days || ' days')::interval
    LIMIT p_limit
  );
END; $$;


