--
-- Name: rpc_email_update_delivery(uuid, text, text); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.rpc_email_update_delivery(p_tracking_id uuid, p_status text, p_bounce_type text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('error', 'auth required');
  END IF;

  IF p_status NOT IN ('sent','delivered','bounced','deferred','failed') THEN
    RETURN jsonb_build_object('error', 'invalid status');
  END IF;

  UPDATE email_tracked_messages
  SET delivery_status = p_status,
      bounce_type = CASE WHEN p_status = 'bounced' THEN COALESCE(p_bounce_type, 'soft') ELSE bounce_type END,
      updated_at = now()
  WHERE tracking_id = p_tracking_id AND user_id = v_uid;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'tracking_id not found or unauthorized');
  END IF;

  RETURN jsonb_build_object('ok', true);
END;
$$;


ALTER FUNCTION zapp.rpc_email_update_delivery(p_tracking_id uuid, p_status text, p_bounce_type text) OWNER TO supabase_admin;

--
-- Name: rpc_enqueue_reprocess(text, uuid, text, text); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.rpc_enqueue_reprocess(p_target_kind text, p_target_id uuid, p_action text, p_reason text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  v_key TEXT;
  v_id UUID;
BEGIN
  IF NOT zapp.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Access denied: admin role required';
  END IF;

  v_key := encode(digest(
    p_target_kind || ':' || p_target_id::text || ':' || p_action || ':' ||
    COALESCE(auth.uid()::text, 'system') || ':' ||
    to_char(date_trunc('hour', now()), 'YYYY-MM-DD HH24'),
    'sha256'
  ), 'hex');

  INSERT INTO zapp.reprocess_jobs (
    idempotency_key, target_kind, target_id, action, requested_by, reason
  )
  VALUES (v_key, p_target_kind, p_target_id, p_action, auth.uid(), p_reason)
  ON CONFLICT (idempotency_key) DO UPDATE
    SET reason = COALESCE(EXCLUDED.reason, reprocess_jobs.reason),
        updated_at = now()
  RETURNING id INTO v_id;

  INSERT INTO zapp.audit_logs (user_id, action, entity_type, entity_id, details)
  VALUES (
    auth.uid(),
    'reprocess_enqueued',
    'reprocess_jobs',
    v_id::text,
    jsonb_build_object(
      'target_kind', p_target_kind,
      'target_id', p_target_id,
      'action', p_action,
      'reason', p_reason
    )
  );

  RETURN v_id;
END;
$$;


ALTER FUNCTION zapp.rpc_enqueue_reprocess(p_target_kind text, p_target_id uuid, p_action text, p_reason text) OWNER TO supabase_admin;

--
-- Name: rpc_evolution_fallback_stats(integer); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.rpc_evolution_fallback_stats(p_hours integer DEFAULT 24) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  v_hours integer;
  v_total bigint;
  v_total_7d bigint;
  v_total_1h bigint;
  v_last_event timestamptz;
  v_first_event timestamptz;
  v_by_action jsonb;
  v_by_reason jsonb;
  v_by_instance jsonb;
  v_recent jsonb;
BEGIN
  IF NOT zapp.is_admin_or_supervisor(auth.uid()) THEN
    RAISE EXCEPTION 'Access denied: admin or supervisor role required';
  END IF;

  v_hours := GREATEST(1, LEAST(COALESCE(p_hours, 24), 720));

  SELECT COUNT(*), MIN(ts), MAX(ts)
    INTO v_total, v_first_event, v_last_event
    FROM zapp.evolution_fallback_events
   WHERE ts > now() - (v_hours || ' hours')::interval;

  SELECT COUNT(*) INTO v_total_7d
    FROM zapp.evolution_fallback_events
   WHERE ts > now() - interval '7 days';

  SELECT COUNT(*) INTO v_total_1h
    FROM zapp.evolution_fallback_events
   WHERE ts > now() - interval '1 hour';

  SELECT COALESCE(jsonb_agg(t.*), '[]'::jsonb) INTO v_by_action FROM (
    SELECT action, COUNT(*)::int AS count
      FROM zapp.evolution_fallback_events
     WHERE ts > now() - (v_hours || ' hours')::interval
     GROUP BY action
     ORDER BY COUNT(*) DESC
  ) t;

  SELECT COALESCE(jsonb_agg(t.*), '[]'::jsonb) INTO v_by_reason FROM (
    SELECT reason, COUNT(*)::int AS count
      FROM zapp.evolution_fallback_events
     WHERE ts > now() - (v_hours || ' hours')::interval
     GROUP BY reason
     ORDER BY COUNT(*) DESC
  ) t;

  SELECT COALESCE(jsonb_agg(t.*), '[]'::jsonb) INTO v_by_instance FROM (
    SELECT COALESCE(instance, '(sem instância)') AS instance, COUNT(*)::int AS count
      FROM zapp.evolution_fallback_events
     WHERE ts > now() - (v_hours || ' hours')::interval
     GROUP BY instance
     ORDER BY COUNT(*) DESC
     LIMIT 10
  ) t;

  SELECT COALESCE(jsonb_agg(t.* ORDER BY t.ts DESC), '[]'::jsonb) INTO v_recent FROM (
    SELECT ts, action, instance, status, reason, mode, fallback_target, primary_ms
      FROM zapp.evolution_fallback_events
     WHERE ts > now() - (v_hours || ' hours')::interval
     ORDER BY ts DESC
     LIMIT 25
  ) t;

  RETURN jsonb_build_object(
    'window_hours', v_hours,
    'total', COALESCE(v_total, 0),
    'total_last_hour', COALESCE(v_total_1h, 0),
    'total_last_7d', COALESCE(v_total_7d, 0),
    'first_event_at', v_first_event,
    'last_event_at', v_last_event,
    'by_action', v_by_action,
    'by_reason', v_by_reason,
    'by_instance', v_by_instance,
    'recent', v_recent
  );
END;
$$;


ALTER FUNCTION zapp.rpc_evolution_fallback_stats(p_hours integer) OWNER TO supabase_admin;

