--
-- Name: rpc_find_contact_by_phone(text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_find_contact_by_phone(p_phone text) RETURNS TABLE(id uuid, name text, phone text, remote_jid text, instance_name character varying)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  cleaned text;
BEGIN
  PERFORM zapp.fn_require_app_user();

  cleaned := zapp.fn_normalize_br_phone(p_phone);
  RETURN QUERY
  SELECT ec.id, COALESCE(ec.full_name, ec.push_name)::text, ec.phone_number::text, ec.remote_jid::text, ec.instance_name
  FROM evolution_contacts ec
  WHERE ec.deleted_at IS NULL
    AND (
      ec.phone_number = cleaned
      OR ec.phone_number = p_phone
      OR split_part(ec.remote_jid, '@', 1) = cleaned
      OR split_part(ec.remote_jid, '@', 1) = p_phone
    )
  LIMIT 5;
END;
$$;


