--

CREATE FUNCTION zapp.rpc_get_pipeline() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$ DECLARE result JSONB; stage_data JSONB := '[]'; stages TEXT[] := ARRAY['novo_cliente','novo_pedido','orcamento_enviado','pagamento_pendente','pago','em_producao','pedido_enviado','pedido_finalizado','perdido']; stage_names TEXT[] := ARRAY['Novo Cliente','Novo Pedido','Orcamento Enviado','Pagamento Pendente','Pago','Em Producao','Pedido Enviado','Finalizado','Perdido']; i INT; BEGIN
  PERFORM zapp.fn_require_app_user();
 FOR i IN 1..array_length(stages,1) LOOP stage_data := stage_data || jsonb_build_array(jsonb_build_object('stage',stages[i],'name',stage_names[i],'position',i,'deals_count',(SELECT COUNT(*) FROM evolution_deals WHERE stage=stages[i]),'deals_value',(SELECT COALESCE(SUM(value),0) FROM evolution_deals WHERE stage=stages[i]))); END LOOP; RETURN stage_data; END; $$;


