--
-- Name: rpc_get_pipeline_health(text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_get_pipeline_health(p_instance_name text DEFAULT 'wpp2'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_msg_total           bigint;
  v_msg_no_contact      bigint;
  v_msg_deleted         bigint;
  v_msg_latest_at       timestamptz;
  v_contact_total       bigint;
  v_contact_no_hash     bigint;
  v_contact_lgpd_pending bigint;
  v_contact_anonymized  bigint;
  v_conv_total          bigint;
  v_conv_no_contact     bigint;
  v_conv_open           bigint;
  v_conv_pending        bigint;
  v_score               int;
  v_penalties           jsonb := '[]'::jsonb;
BEGIN
  IF NOT zapp.is_admin_or_supervisor() THEN
    RAISE EXCEPTION 'Access denied: admin or supervisor role required'
      USING ERRCODE = 'P0001';
  END IF;

  SELECT
    COUNT(*),
    COUNT(*) FILTER (
      WHERE contact_id IS NULL
        AND remote_jid NOT LIKE '%@g.us'
        AND remote_jid NOT LIKE '%@broadcast'
        AND remote_jid NOT IN ('unknown@s.whatsapp.net', 'unknown@deleted')
        AND split_part(remote_jid, '@', 1) NOT LIKE 'smoke%'
    ),
    COUNT(*) FILTER (WHERE status = 'deleted'),
    MAX(created_at)
  INTO v_msg_total, v_msg_no_contact, v_msg_deleted, v_msg_latest_at
  FROM zapp.evolution_messages
  WHERE instance_name = p_instance_name;

  SELECT
    COUNT(*) FILTER (WHERE deleted_at IS NULL),
    COUNT(*) FILTER (WHERE deleted_at IS NULL AND dedup_hash IS NULL),
    COUNT(*) FILTER (WHERE lgpd_deletion_requested_at IS NOT NULL AND pii_masked_at IS NULL),
    COUNT(*) FILTER (WHERE pii_masked_at IS NOT NULL)
  INTO v_contact_total, v_contact_no_hash, v_contact_lgpd_pending, v_contact_anonymized
  FROM zapp.evolution_contacts
  WHERE instance_name = p_instance_name;

  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE contact_id IS NULL),
    COUNT(*) FILTER (WHERE status = 'open'),
    COUNT(*) FILTER (WHERE status = 'pending')
  INTO v_conv_total, v_conv_no_contact, v_conv_open, v_conv_pending
  FROM zapp.evolution_conversations
  WHERE instance_name = p_instance_name;

  v_score := 100;

  IF v_msg_total > 0 AND v_msg_no_contact::float / v_msg_total > 0.005 THEN
    v_score := v_score - 20;
    v_penalties := v_penalties || jsonb_build_object(
      'code', 'messages_no_contact',
      'detail', format('%s messages (%s%%) lack contact_id', v_msg_no_contact, round(100.0 * v_msg_no_contact / v_msg_total, 1)),
      'points', -20
    );
  END IF;

  IF v_conv_no_contact > 0 THEN
    v_score := v_score - 10;
    v_penalties := v_penalties || jsonb_build_object(
      'code', 'conversations_no_contact',
      'detail', format('%s conversations lack contact_id', v_conv_no_contact),
      'points', -10
    );
  END IF;

  IF v_contact_total > 0 AND v_contact_no_hash::float / v_contact_total > 0.5 THEN
    v_score := v_score - 10;
    v_penalties := v_penalties || jsonb_build_object(
      'code', 'contacts_no_dedup_hash',
      'detail', format('%s/%s contacts missing dedup_hash', v_contact_no_hash, v_contact_total),
      'points', -10
    );
  END IF;

  IF v_contact_lgpd_pending > 0 THEN
    v_score := v_score - 5;
    v_penalties := v_penalties || jsonb_build_object(
      'code', 'lgpd_pending_deletion',
      'detail', format('%s contacts pending LGPD anonymization', v_contact_lgpd_pending),
      'points', -5
    );
  END IF;

  v_score := GREATEST(0, v_score);

  RETURN jsonb_build_object(
    'instance_name',  p_instance_name,
    'checked_at',     NOW(),
    'health_score',   v_score,
    'health_label',   CASE WHEN v_score >= 90 THEN 'healthy' WHEN v_score >= 70 THEN 'degraded' ELSE 'critical' END,
    'penalties',      v_penalties,
    'messages',       jsonb_build_object('total', v_msg_total, 'no_contact', v_msg_no_contact, 'deleted', v_msg_deleted, 'latest_at', v_msg_latest_at),
    'contacts',       jsonb_build_object('total', v_contact_total, 'no_dedup_hash', v_contact_no_hash, 'lgpd_pending', v_contact_lgpd_pending, 'anonymized', v_contact_anonymized),
    'conversations',  jsonb_build_object('total', v_conv_total, 'no_contact', v_conv_no_contact, 'open', v_conv_open, 'pending', v_conv_pending)
  );
END;
$$;


ALTER FUNCTION zapp.rpc_get_pipeline_health(p_instance_name text) OWNER TO postgres;

--
-- Name: rpc_get_pipeline_health_v2(text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_get_pipeline_health_v2(p_instance_name text DEFAULT NULL::text) RETURNS TABLE(checked_at timestamp with time zone, instance_name text, pending_messages bigint, stuck_messages_5m bigint, stuck_messages_30m bigint, failed_messages_24h bigint, oldest_pending_minutes double precision)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    NOW()::TIMESTAMPTZ,
    m.instance_name::TEXT,
    COUNT(*) FILTER (WHERE m.status IN ('pending','queued'))::BIGINT,
    COUNT(*) FILTER (WHERE m.status='pending' AND m.created_at < NOW()-INTERVAL '5 minutes')::BIGINT,
    COUNT(*) FILTER (WHERE m.status='pending' AND m.created_at < NOW()-INTERVAL '30 minutes')::BIGINT,
    COUNT(*) FILTER (WHERE m.status='failed'  AND m.created_at > NOW()-INTERVAL '24 hours')::BIGINT,
    (EXTRACT(EPOCH FROM (NOW()-MIN(CASE WHEN m.status='pending' THEN m.created_at END)))/60)::DOUBLE PRECISION
  FROM zapp.messages m
  WHERE (p_instance_name IS NULL OR m.instance_name::TEXT = p_instance_name)
  GROUP BY m.instance_name;
END;
$$;


ALTER FUNCTION zapp.rpc_get_pipeline_health_v2(p_instance_name text) OWNER TO postgres;

--
-- Name: rpc_get_reactions_batch(uuid[]); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_get_reactions_batch(p_message_ids uuid[]) RETURNS TABLE(id uuid, message_id uuid, contact_id uuid, user_id uuid, emoji text, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
  SELECT
    r.id,
    r.message_id,
    r.contact_id,
    r.user_id,
    r.emoji,
    r.created_at
  FROM zapp.message_reactions r
  WHERE r.message_id = ANY(p_message_ids)
    AND (
      zapp.is_contact_visible_to_user(r.contact_id, auth.uid())
      OR r.user_id = zapp.get_profile_id_for_user(auth.uid())
    )
  ORDER BY r.message_id, r.created_at DESC;
$$;


ALTER FUNCTION zapp.rpc_get_reactions_batch(p_message_ids uuid[]) OWNER TO postgres;

