--
-- Name: rpc_global_search(text, integer, text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_global_search(p_query text, p_limit integer DEFAULT 10, p_instance text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE v_result jsonb;
BEGIN
  PERFORM zapp.fn_require_app_user();
  SELECT jsonb_build_object(
    'contacts', COALESCE((SELECT jsonb_agg(jsonb_build_object('id',id,'name',COALESCE(full_name,push_name),'phone',phone_number,'jid',remote_jid,'score',lead_score)) FROM (SELECT * FROM zapp.evolution_contacts WHERE deleted_at IS NULL AND (full_name ILIKE '%'||p_query||'%' OR push_name ILIKE '%'||p_query||'%' OR phone_number ILIKE '%'||p_query||'%' OR company ILIKE '%'||p_query||'%') ORDER BY last_message_at DESC NULLS LAST LIMIT p_limit) t), '[]'::jsonb),
    'messages', COALESCE((SELECT jsonb_agg(jsonb_build_object('id',id,'content',LEFT(content,100),'jid',remote_jid,'type',message_type,'date',created_at,'instance',instance_name)) FROM (SELECT * FROM zapp.evolution_messages WHERE content ILIKE '%'||p_query||'%' AND (p_instance IS NULL OR instance_name=p_instance) AND deleted_at IS NULL ORDER BY created_at DESC LIMIT p_limit) t), '[]'::jsonb),
    'deals', COALESCE((SELECT jsonb_agg(jsonb_build_object('id',id,'title',title,'stage',stage,'value',value)) FROM (SELECT * FROM zapp.evolution_deals WHERE title ILIKE '%'||p_query||'%' OR description ILIKE '%'||p_query||'%' ORDER BY updated_at DESC LIMIT p_limit) t), '[]'::jsonb)
  ) INTO v_result;
  RETURN v_result;
END; $$;


