--
-- Name: rpc_gmail_update_sla_status(uuid, integer, integer); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.rpc_gmail_update_sla_status(p_account_id uuid DEFAULT NULL::uuid, p_threshold_min integer DEFAULT 480, p_warning_pct integer DEFAULT 80) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  v_updated_breached INT; v_updated_warning INT; v_updated_ok INT;
BEGIN
  UPDATE zapp.gmail_threads SET sla_status = 'breached', updated_at = NOW()
  WHERE first_reply_at IS NULL
    AND (p_account_id IS NULL OR account_id = p_account_id)
    AND EXTRACT(EPOCH FROM (NOW() - last_message_at)) / 60 >= p_threshold_min
    AND (label_ids && ARRAY['INBOX']::text[]);
  GET DIAGNOSTICS v_updated_breached = ROW_COUNT;

  UPDATE zapp.gmail_threads SET sla_status = 'warning', updated_at = NOW()
  WHERE first_reply_at IS NULL
    AND (p_account_id IS NULL OR account_id = p_account_id)
    AND EXTRACT(EPOCH FROM (NOW() - last_message_at)) / 60 >= (p_threshold_min * p_warning_pct / 100.0)
    AND EXTRACT(EPOCH FROM (NOW() - last_message_at)) / 60 < p_threshold_min
    AND (label_ids && ARRAY['INBOX']::text[]);
  GET DIAGNOSTICS v_updated_warning = ROW_COUNT;

  UPDATE zapp.gmail_threads SET sla_status = 'ok', updated_at = NOW()
  WHERE first_reply_at IS NULL
    AND (p_account_id IS NULL OR account_id = p_account_id)
    AND EXTRACT(EPOCH FROM (NOW() - last_message_at)) / 60 < (p_threshold_min * p_warning_pct / 100.0)
    AND (label_ids && ARRAY['INBOX']::text[]);
  GET DIAGNOSTICS v_updated_ok = ROW_COUNT;

  UPDATE zapp.gmail_threads SET sla_status = 'met', updated_at = NOW()
  WHERE first_reply_at IS NOT NULL
    AND (p_account_id IS NULL OR account_id = p_account_id)
    AND EXTRACT(EPOCH FROM (first_reply_at - last_message_at)) / 60 < p_threshold_min;

  RETURN jsonb_build_object('success', true, 'breached_updated', v_updated_breached, 'warning_updated', v_updated_warning, 'ok_updated', v_updated_ok);
END;
$$;


ALTER FUNCTION zapp.rpc_gmail_update_sla_status(p_account_id uuid, p_threshold_min integer, p_warning_pct integer) OWNER TO supabase_admin;

--
-- Name: rpc_grant_achievement(uuid, text, text, text, numeric); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_grant_achievement(p_profile_id uuid, p_type text, p_name text, p_description text DEFAULT NULL::text, p_xp_reward numeric DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'zapp', 'public'
    AS $$
DECLARE
  v_profile_id  uuid;
  v_ach_id      uuid;
  v_prev_level  integer;
  v_xp          numeric;
  v_level       integer;
BEGIN
  IF p_profile_id IS NULL OR p_type IS NULL OR pg_catalog.btrim(p_type) = '' THEN
    RAISE EXCEPTION 'rpc_grant_achievement: parametros invalidos'
      USING ERRCODE = '22023';
  END IF;
  IF p_xp_reward < 0 THEN
    RAISE EXCEPTION 'rpc_grant_achievement: reward negativo (%)', p_xp_reward
      USING ERRCODE = '22013';
  END IF;

  v_profile_id := zapp.get_profile_id_for_user(auth.uid());
  IF v_profile_id IS NULL
     OR (p_profile_id <> v_profile_id AND NOT zapp.is_admin_or_supervisor()) THEN
    RAISE EXCEPTION 'rpc_grant_achievement: sem permissao para o perfil %', p_profile_id
      USING ERRCODE = '42501';
  END IF;

  -- Dedupe ATOMICO via indice unico (profile_id, achievement_type): 2 grants
  -- simultâneos do mesmo tipo → exatamente 1 row e 1 XP.
  INSERT INTO zapp.agent_achievements (
    profile_id, achievement_type, achievement_name, achievement_description, xp_earned
  )
  VALUES (p_profile_id, p_type, p_name, p_description, p_xp_reward)
  ON CONFLICT (profile_id, achievement_type) DO NOTHING
  RETURNING id INTO v_ach_id;

  IF v_ach_id IS NULL THEN
    RETURN pg_catalog.jsonb_build_object('already_had', pg_catalog.to_jsonb(true));
  END IF;

  -- Serializa escritas concorrentes no MESMO perfil.
  SELECT level INTO v_prev_level
    FROM zapp.agent_stats
   WHERE profile_id = p_profile_id
   FOR UPDATE;

  IF NOT FOUND THEN
    INSERT INTO zapp.agent_stats (profile_id, xp, achievements_count)
    VALUES (p_profile_id, p_xp_reward, 1)
    ON CONFLICT (profile_id) DO UPDATE
      SET xp = zapp.agent_stats.xp + EXCLUDED.xp,
          achievements_count = zapp.agent_stats.achievements_count + 1,
          updated_at = pg_catalog.now()
    RETURNING xp, level INTO v_xp, v_level;
    v_prev_level := 1;
  ELSE
    -- xp e achievements_count incrementais no MESMO UPDATE (atômico).
    UPDATE zapp.agent_stats
       SET xp = xp + p_xp_reward,
           achievements_count = achievements_count + 1,
           updated_at = pg_catalog.now()
     WHERE profile_id = p_profile_id
    RETURNING xp, level INTO v_xp, v_level;
  END IF;

  RETURN pg_catalog.jsonb_build_object(
    'already_had',    pg_catalog.to_jsonb(false),
    'achievement_id', v_ach_id,
    'xp',             v_xp,
    'level',          v_level,
    'previous_level', v_prev_level,
    'leveled_up',     v_level > v_prev_level
  );
END;
$$;


ALTER FUNCTION zapp.rpc_grant_achievement(p_profile_id uuid, p_type text, p_name text, p_description text, p_xp_reward numeric) OWNER TO postgres;

--
-- Name: FUNCTION rpc_grant_achievement(p_profile_id uuid, p_type text, p_name text, p_description text, p_xp_reward numeric); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.rpc_grant_achievement(p_profile_id uuid, p_type text, p_name text, p_description text, p_xp_reward numeric) IS 'E59: concede conquista de forma atomica (ON CONFLICT DO NOTHING + xp/achievements_count incrementais no mesmo UPDATE). Conquista repetida → already_had sem XP. Somente o dono do perfil ou admin/supervisor.';


--
-- Name: rpc_grant_xp(uuid, integer, text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_grant_xp(p_profile_id uuid, p_amount integer, p_reason text DEFAULT 'xp'::text) RETURNS TABLE(new_xp numeric, new_level integer, leveled_up boolean, previous_level integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_temp'
    AS $$
DECLARE
  v_prev_xp numeric;
  v_prev_level integer;
  v_new_xp numeric;
  v_new_level integer;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'unauthenticated';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM zapp.profiles WHERE id = p_profile_id AND user_id = auth.uid()) THEN
    RAISE EXCEPTION 'permission denied: perfil não pertence ao usuário';
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'grant_xp: amount deve ser > 0 (recebido %)', p_amount;
  END IF;

  -- Ledger (auditoria): uma linha por concessão.
  INSERT INTO zapp.xp_transactions (profile_id, amount, reason)
  VALUES (p_profile_id, p_amount, COALESCE(p_reason, 'xp'));

  -- Estado atual (serializa concorrentes no caminho comum).
  SELECT xp, level INTO v_prev_xp, v_prev_level
    FROM zapp.agent_stats
   WHERE profile_id = p_profile_id
   FOR UPDATE;

  v_new_xp := COALESCE(v_prev_xp, 0) + p_amount;
  v_new_level := GREATEST(1, FLOOR(SQRT(v_new_xp / 50.0)) + 1)::integer;

  -- Upsert atômico: no conflito (row criada por outro tx no meio do caminho)
  -- soma APENAS o delta sobre o valor commitado — nunca um total stale.
  INSERT INTO zapp.agent_stats (profile_id, xp, level, updated_at)
  VALUES (p_profile_id, v_new_xp, v_new_level, now())
  ON CONFLICT (profile_id) DO UPDATE
    SET xp = zapp.agent_stats.xp + p_amount,
        level = GREATEST(1, FLOOR(SQRT((zapp.agent_stats.xp + p_amount) / 50.0)) + 1)::integer,
        updated_at = now()
  RETURNING xp, level INTO v_new_xp, v_new_level;

  RETURN QUERY
  SELECT v_new_xp, v_new_level, (v_new_level > COALESCE(v_prev_level, 1)), COALESCE(v_prev_level, 1);
END;
$$;


ALTER FUNCTION zapp.rpc_grant_xp(p_profile_id uuid, p_amount integer, p_reason text) OWNER TO postgres;

--
-- Name: FUNCTION rpc_grant_xp(p_profile_id uuid, p_amount integer, p_reason text); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.rpc_grant_xp(p_profile_id uuid, p_amount integer, p_reason text) IS 'Ledger (auditoria): uma linha por concessão. (extraido do cabecalho do fonte). Args: (p_profile_id uuid, p_amount integer, p_reason text).';


