CREATE FUNCTION zapp.rpc_inbox_preview_batch(p_remote_jids text[], p_instance text DEFAULT NULL::text, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$ 
BEGIN
  PERFORM zapp.fn_require_app_user();
RETURN (SELECT jsonb_build_object('previews', COALESCE(jsonb_agg(preview), '[]'::jsonb)) FROM ( SELECT DISTINCT ON (remote_jid) jsonb_build_object('remote_jid', remote_jid, 'latest', row_to_json(msg.*)) AS preview FROM ( SELECT DISTINCT ON (remote_jid) * FROM zapp.evolution_messages WHERE remote_jid = ANY(p_remote_jids) AND (p_instance IS NULL OR instance_name = p_instance) AND deleted_at IS NULL ORDER BY remote_jid, created_at DESC ) msg LIMIT p_limit ) sub);
END;$$;


