    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$ DECLARE v_count int; BEGIN INSERT INTO zapp.evolution_followup_rules (name, description, trigger_type, trigger_config, template_id, delay_hours, conditions, sequence_order, sequence_group, is_active) SELECT (r->>'name')::text, (r->>'description')::text, (r->>'trigger_type')::text, (r->>'trigger_config')::jsonb, (r->>'template_id')::uuid, (r->>'delay_hours')::integer, (r->>'conditions')::jsonb, (r->>'sequence_order')::integer, (r->>'sequence_group')::uuid, coalesce((r->>'is_active')::boolean, true) FROM jsonb_array_elements(p_rows) r; GET DIAGNOSTICS v_count = ROW_COUNT; RETURN jsonb_build_object('ok',true,'inserted',v_count); EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('ok',false,'error',SQLERRM); END; $$;


