--

CREATE FUNCTION zapp.rpc_list_audit_log(p_entity_type text DEFAULT NULL::text, p_entity_id uuid DEFAULT NULL::uuid, p_action text DEFAULT NULL::text, p_performed_by text DEFAULT NULL::text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS SETOF zapp.evolution_audit_log
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$ 
BEGIN
  PERFORM zapp.fn_require_app_user();
RETURN QUERY SELECT * FROM evolution_audit_log WHERE (p_entity_type IS NULL OR entity_type=p_entity_type) AND (p_entity_id IS NULL OR entity_id=p_entity_id) AND (p_action IS NULL OR action=p_action) AND (p_performed_by IS NULL OR performed_by=p_performed_by) ORDER BY created_at DESC LIMIT p_limit OFFSET p_offset; 
END;$$;


