--
-- Name: rpc_list_calls(text, text, integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_list_calls(p_remote_jid text DEFAULT NULL::text, p_instance text DEFAULT NULL::text, p_limit integer DEFAULT 100) RETURNS SETOF zapp.evolution_calls
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'public', 'extensions'
    AS $$
BEGIN
  PERFORM zapp.fn_require_app_user();
  RETURN QUERY
  SELECT * FROM evolution_calls
  WHERE (p_instance   IS NULL OR instance_name = p_instance)
    AND (p_remote_jid IS NULL OR remote_jid    = p_remote_jid)
  ORDER BY started_at DESC NULLS LAST
  LIMIT p_limit;
END; $$;


ALTER FUNCTION zapp.rpc_list_calls(p_remote_jid text, p_instance text, p_limit integer) OWNER TO postgres;

--
-- Name: rpc_list_channel_queues(uuid); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.rpc_list_channel_queues(p_channel_id uuid) RETURNS TABLE(queue_id uuid, name text, status text, priority integer, is_default boolean, is_active boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$ SELECT q.id, q.name, q.status, COALESCE(cq.priority, 0), (sc.default_queue_id = q.id), COALESCE(cq.is_active, true) FROM zapp.service_channels sc LEFT JOIN zapp.channel_queues cq ON cq.channel_id = sc.id LEFT JOIN zapp.queues q ON q.id = cq.queue_id OR q.id = sc.default_queue_id WHERE sc.id = p_channel_id AND q.id IS NOT NULL ORDER BY (sc.default_queue_id = q.id) DESC, COALESCE(cq.priority,0) DESC, q.name; $$;


ALTER FUNCTION zapp.rpc_list_channel_queues(p_channel_id uuid) OWNER TO supabase_admin;

--
-- Name: rpc_list_contact_links(uuid, integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_list_contact_links(p_contact_id uuid, p_limit integer DEFAULT 50) RETURNS TABLE(id uuid, content text, from_me boolean, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
BEGIN
  PERFORM zapp.fn_require_app_user();

  RETURN QUERY
  SELECT em.id, em.content::text, COALESCE(em.from_me, false), em.created_at
  FROM zapp.evolution_messages em  -- FIX
  WHERE em.contact_id=p_contact_id AND em.content ~ 'https?://[^\s]+'
    AND em.deleted_at IS NULL
  ORDER BY em.created_at DESC LIMIT p_limit;
END; $$;


ALTER FUNCTION zapp.rpc_list_contact_links(p_contact_id uuid, p_limit integer) OWNER TO postgres;

--
-- Name: rpc_list_contacts(text, text, text, text, integer, integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_list_contacts(p_instance text DEFAULT NULL::text, p_lead_status text DEFAULT NULL::text, p_assigned_to text DEFAULT NULL::text, p_search text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS SETOF evo.evolution_contacts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$

BEGIN
  PERFORM zapp.fn_require_app_user();
RETURN QUERY  SELECT *
  FROM zapp.evolution_contacts
  WHERE
    deleted_at IS NULL
    AND (p_instance IS NULL OR instance_name = p_instance)
    AND (p_lead_status IS NULL OR lead_status = p_lead_status)
    AND (p_assigned_to IS NULL OR assigned_to = p_assigned_to)
    AND (
      p_search IS NULL
      OR full_name  ILIKE '%' || p_search || '%'
      OR push_name  ILIKE '%' || p_search || '%'
      OR phone_number ILIKE '%' || p_search || '%'
      OR remote_jid ILIKE '%' || p_search || '%'
    )
  ORDER BY last_message_at DESC NULLS LAST
  LIMIT  GREATEST(COALESCE(p_limit, 50), 0)   -- FIX
  OFFSET GREATEST(COALESCE(p_offset, 0), 0);

END;$$;


ALTER FUNCTION zapp.rpc_list_contacts(p_instance text, p_lead_status text, p_assigned_to text, p_search text, p_limit integer, p_offset integer) OWNER TO postgres;

--
-- Name: rpc_list_conversations(text, text, text, integer, integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_list_conversations(p_instance text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_assigned_to text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS SETOF evo.evolution_conversations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
BEGIN
  PERFORM zapp.fn_require_app_user();
  RETURN QUERY
    SELECT *
    FROM zapp.evolution_conversations
    WHERE
      (p_instance IS NULL OR instance_name = p_instance)
      AND (p_status IS NULL OR status = p_status)
      AND (p_assigned_to IS NULL OR assigned_to = p_assigned_to)
    ORDER BY last_message_at DESC NULLS LAST
    LIMIT  GREATEST(COALESCE(p_limit, 50), 0)
    OFFSET GREATEST(COALESCE(p_offset, 0), 0);
END;
$$;


ALTER FUNCTION zapp.rpc_list_conversations(p_instance text, p_status text, p_assigned_to text, p_limit integer, p_offset integer) OWNER TO postgres;

--
-- Name: rpc_list_cron_jobs(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_list_cron_jobs() RETURNS TABLE(jobid bigint, jobname text, schedule text, command text, active boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'cron', 'zapp'
    AS $$
BEGIN
  IF NOT zapp.is_admin_or_supervisor() THEN
    RAISE EXCEPTION 'Acesso negado: apenas admins e supervisores podem listar cron jobs'
      USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    j.jobid,
    j.jobname,
    j.schedule,
    j.command,
    j.active
  FROM cron.job j
  ORDER BY j.jobname;
END;
$$;


ALTER FUNCTION zapp.rpc_list_cron_jobs() OWNER TO postgres;

