CREATE FUNCTION zapp.rpc_list_deals(p_stage text DEFAULT NULL::text, p_assigned_to text DEFAULT NULL::text, p_contact_id uuid DEFAULT NULL::uuid, p_instance text DEFAULT NULL::text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS SETOF zapp.evolution_deals
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
