--
-- Name: rpc_list_dispatch_error_logs(timestamp with time zone, timestamp with time zone, text, text, text, text, integer, integer); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.rpc_list_dispatch_error_logs(p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_instance text DEFAULT NULL::text, p_agent text DEFAULT NULL::text, p_error_code text DEFAULT NULL::text, p_search text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, failed_message_id uuid, instance_name text, remote_jid text, channel_type text, agent_email text, agent_user_id uuid, error_code text, error_message text, http_status integer, retry_count integer, payload jsonb, context jsonb, occurred_at timestamp with time zone, total_count bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  v_limit INTEGER;
  v_search TEXT;
BEGIN
  IF NOT zapp.is_admin_or_supervisor(auth.uid()) THEN
    RAISE EXCEPTION 'Access denied: admin or supervisor role required';
  END IF;

  v_limit := LEAST(GREATEST(COALESCE(p_limit, 50), 1), 500);
  v_search := NULLIF(TRIM(COALESCE(p_search, '')), '');

  RETURN QUERY
  WITH filtered AS (
    SELECT d.*
    FROM zapp.dispatch_error_logs d
    WHERE (p_from IS NULL OR d.occurred_at >= p_from)
      AND (p_to IS NULL OR d.occurred_at <= p_to)
      AND (p_instance IS NULL OR d.instance_name = p_instance)
      AND (p_agent IS NULL OR d.agent_email = p_agent)
      AND (p_error_code IS NULL OR d.error_code = p_error_code)
      AND (
        v_search IS NULL OR (
          d.remote_jid ILIKE '%' || v_search || '%' OR
          d.error_message ILIKE '%' || v_search || '%' OR
          d.error_code ILIKE '%' || v_search || '%'
        )
      )
  ), counted AS (
    SELECT COUNT(*)::BIGINT AS total FROM filtered
  )
  SELECT
    f.id, f.failed_message_id, f.instance_name, f.remote_jid,
    f.channel_type, f.agent_email, f.agent_user_id,
    f.error_code, f.error_message, f.http_status, f.retry_count,
    f.payload, f.context, f.occurred_at,
    c.total
  FROM filtered f
  CROSS JOIN counted c
  ORDER BY f.occurred_at DESC
  LIMIT v_limit
  OFFSET GREATEST(COALESCE(p_offset, 0), 0);
END;
$$;


ALTER FUNCTION zapp.rpc_list_dispatch_error_logs(p_from timestamp with time zone, p_to timestamp with time zone, p_instance text, p_agent text, p_error_code text, p_search text, p_limit integer, p_offset integer) OWNER TO supabase_admin;

--
-- Name: rpc_list_dispatch_error_logs_cursor(timestamp with time zone, timestamp with time zone, text, text, text, text, integer, uuid); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_list_dispatch_error_logs_cursor(p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_instance text DEFAULT NULL::text, p_agent text DEFAULT NULL::text, p_error_code text DEFAULT NULL::text, p_search text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_cursor_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, failed_message_id uuid, instance_name text, remote_jid text, channel_type text, agent_email text, agent_user_id uuid, error_code text, error_message text, http_status integer, retry_count integer, payload jsonb, context jsonb, occurred_at timestamp with time zone, total_count bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
BEGIN
  IF NOT zapp.is_admin_or_supervisor(auth.uid()) THEN
    PERFORM zapp.log_rls_denied(
      'dispatch_error_logs', 'admin|supervisor',
      jsonb_build_object('rpc', 'rpc_list_dispatch_error_logs_cursor')
    );
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH filtered AS (
    SELECT
      d.id,
      d.failed_message_id,
      d.instance_name,
      d.remote_jid,
      d.channel_type,
      d.agent_email,
      d.agent_user_id,
      d.error_code,
      d.error_message,
      d.http_status,
      d.retry_count,
      d.payload,
      d.context,
      d.occurred_at
    FROM dispatch_error_logs d
    WHERE (p_from       IS NULL OR d.occurred_at   >= p_from)
      AND (p_to         IS NULL OR d.occurred_at   <= p_to)
      AND (p_instance   IS NULL OR d.instance_name  = p_instance)
      AND (p_agent      IS NULL OR d.agent_email    = p_agent)
      AND (p_error_code IS NULL OR d.error_code     = p_error_code)
      AND (p_search     IS NULL
           OR d.error_message ILIKE '%' || p_search || '%'
           OR d.error_code    ILIKE '%' || p_search || '%')
  ),
  total AS (SELECT COUNT(*)::bigint AS cnt FROM filtered)
  SELECT
    f.id, f.failed_message_id, f.instance_name, f.remote_jid,
    f.channel_type, f.agent_email, f.agent_user_id, f.error_code,
    f.error_message, f.http_status, f.retry_count, f.payload,
    f.context, f.occurred_at, t.cnt AS total_count
  FROM filtered f, total t
  WHERE (p_cursor_id IS NULL OR
         ROW(f.occurred_at, f.id) < (
           SELECT ROW(c.occurred_at, c.id)
           FROM dispatch_error_logs c
           WHERE c.id = p_cursor_id
         ))
  ORDER BY f.occurred_at DESC, f.id DESC
  LIMIT COALESCE(p_limit, 50);
END;
$$;


ALTER FUNCTION zapp.rpc_list_dispatch_error_logs_cursor(p_from timestamp with time zone, p_to timestamp with time zone, p_instance text, p_agent text, p_error_code text, p_search text, p_limit integer, p_cursor_id uuid) OWNER TO postgres;

--
-- Name: rpc_list_eligible_agents(uuid); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.rpc_list_eligible_agents(p_queue_id uuid) RETURNS TABLE(user_id uuid, display_name text, department_id uuid, max_chats integer, active_chats bigint, is_active boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$ WITH q AS (SELECT department_id FROM zapp.queues WHERE id = p_queue_id) SELECT p.user_id, COALESCE(p.name, p.email), p.department_id, COALESCE(p.max_chats, 5), (SELECT COUNT(*) FROM zapp.contacts c WHERE c.assigned_to::uuid = p.user_id), COALESCE(p.is_active, true) FROM zapp.profiles p, q WHERE (q.department_id IS NULL OR p.department_id = q.department_id) AND COALESCE(p.is_active, true) = true AND p.role IN ('agent','supervisor','admin'); $$;


ALTER FUNCTION zapp.rpc_list_eligible_agents(p_queue_id uuid) OWNER TO supabase_admin;

--
-- Name: rpc_list_failed_messages(text[], text, text, timestamp with time zone, timestamp with time zone, integer, integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_list_failed_messages(p_status text[] DEFAULT NULL::text[], p_instance text DEFAULT NULL::text, p_search text DEFAULT NULL::text, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, instance_name text, remote_jid text, payload jsonb, error_code text, error_message text, http_status numeric, retry_count integer, max_retries numeric, status text, last_attempt_at timestamp with time zone, next_attempt_at timestamp with time zone, succeeded_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone, total_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
BEGIN
  IF NOT (zapp.has_role(auth.uid(), 'admin') OR zapp.has_role(auth.uid(), 'supervisor')) THEN
    PERFORM zapp.log_rls_denied(
      'failed_messages', 'admin|supervisor',
      jsonb_build_object(
        'rpc', 'rpc_list_failed_messages',
        'filters', jsonb_build_object(
          'status', p_status, 'instance', p_instance, 'search', p_search
        )
      )
    );
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    fm.id,
    fm.instance_name,
    fm.remote_jid,
    fm.payload,
    fm.error_code,
    fm.error_message,
    fm.http_status,
    fm.retry_count,
    fm.max_retries,
    fm.status,
    fm.last_attempt_at,
    fm.next_attempt_at,
    fm.succeeded_at,
    fm.created_at,
    fm.updated_at,
    COUNT(*) OVER()::bigint AS total_count
  FROM zapp.failed_messages fm
  WHERE
    (p_status IS NULL OR fm.status = ANY(p_status))
    AND (p_instance IS NULL OR fm.instance_name = p_instance)
    AND (p_search IS NULL
         OR fm.remote_jid ILIKE '%' || p_search || '%'
         OR fm.error_message ILIKE '%' || p_search || '%'
         OR fm.message_id ILIKE '%' || p_search || '%')
    AND (p_from IS NULL OR fm.created_at >= p_from)
    AND (p_to   IS NULL OR fm.created_at <= p_to)
  ORDER BY fm.created_at DESC
  LIMIT  COALESCE(p_limit,  50)
  OFFSET COALESCE(p_offset, 0);
END;
$$;


ALTER FUNCTION zapp.rpc_list_failed_messages(p_status text[], p_instance text, p_search text, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer, p_offset integer) OWNER TO postgres;

--
-- Name: rpc_list_failed_messages_cursor(text[], text, text, timestamp with time zone, timestamp with time zone, integer, uuid, text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_list_failed_messages_cursor(p_status text[], p_instance text, p_search text, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer, p_cursor_id uuid DEFAULT NULL::uuid, p_error_code text DEFAULT NULL::text) RETURNS TABLE(id uuid, instance_name text, remote_jid text, payload jsonb, error_code text, error_message text, http_status numeric, retry_count integer, max_retries numeric, status text, last_attempt_at timestamp with time zone, next_attempt_at timestamp with time zone, succeeded_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone, total_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
BEGIN
  IF NOT zapp.is_admin_or_supervisor(auth.uid()) THEN
    PERFORM zapp.log_rls_denied('failed_messages', 'admin|supervisor',
      jsonb_build_object('rpc', 'rpc_list_failed_messages_cursor', 'filters',
        jsonb_build_object('status', p_status, 'instance', p_instance, 'search', p_search)));
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH base AS (
    SELECT
      fm.id,
      fm.instance_name,
      fm.remote_jid,
      fm.payload,
      fm.error_code,
      fm.error_message,
      fm.http_status,
      fm.retry_count,
      fm.max_retries,
      fm.status,
      fm.last_attempt_at,
      fm.next_attempt_at,
      fm.succeeded_at,
      fm.created_at,
      fm.updated_at
    FROM zapp.failed_messages fm
    WHERE (p_status    IS NULL OR fm.status        = ANY(p_status))
      AND (p_instance  IS NULL OR fm.instance_name = p_instance)
      AND (p_search    IS NULL
           OR fm.error_message ILIKE '%' || p_search || '%'
           OR fm.error_code    ILIKE '%' || p_search || '%'
           OR fm.remote_jid    ILIKE '%' || p_search || '%')
      AND (p_from      IS NULL OR fm.created_at >= p_from)
      AND (p_to        IS NULL OR fm.created_at <= p_to)
      AND (p_error_code IS NULL
           OR fm.error_code = p_error_code
           OR (fm.error_code IS NULL AND fm.http_status IS NOT NULL
               AND 'http_' || fm.http_status::text = p_error_code)
           OR (fm.error_code IS NULL AND fm.http_status IS NULL
               AND p_error_code = 'unknown'))
  ),
  total AS (SELECT COUNT(*)::bigint AS cnt FROM base)
  SELECT
    b.id, b.instance_name, b.remote_jid, b.payload,
    b.error_code, b.error_message, b.http_status,
    b.retry_count, b.max_retries, b.status,
    b.last_attempt_at, b.next_attempt_at, b.succeeded_at,
    b.created_at, b.updated_at,
    t.cnt AS total_count
  FROM base b, total t
  WHERE (p_cursor_id IS NULL OR
         (b.created_at, b.id) < (
           SELECT c.created_at, c.id
           FROM zapp.failed_messages c
           WHERE c.id = p_cursor_id
         ))
  ORDER BY b.created_at DESC, b.id DESC
  LIMIT COALESCE(p_limit, 50);
END;
$$;


ALTER FUNCTION zapp.rpc_list_failed_messages_cursor(p_status text[], p_instance text, p_search text, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer, p_cursor_id uuid, p_error_code text) OWNER TO postgres;

