--
-- Name: rpc_list_messages(text, text, integer, timestamp with time zone); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_list_messages(p_remote_jid text, p_instance text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_before_date timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS SETOF evo.evolution_messages
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_temp'
    AS $$
BEGIN
  PERFORM zapp.fn_require_app_user();
  RETURN QUERY
  SELECT *
  FROM zapp.evolution_messages
  WHERE
    remote_jid = p_remote_jid
    AND (p_instance IS NULL OR instance_name = p_instance)
    AND deleted_at IS NULL
    AND (p_before_date IS NULL OR created_at < p_before_date)
  ORDER BY created_at DESC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION zapp.rpc_list_messages(p_remote_jid text, p_instance text, p_limit integer, p_before_date timestamp with time zone) OWNER TO postgres;

