    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
BEGIN
  PERFORM zapp.fn_require_app_user();

  RETURN QUERY SELECT * FROM zapp.evolution_messages
  WHERE (p_instance IS NULL OR instance_name = p_instance)
    AND deleted_at IS NULL
    AND (p_contact_id IS NULL OR contact_id = p_contact_id)
    AND (p_conversation_id IS NULL OR conversation_id = p_conversation_id)
    AND (p_direction IS NULL OR direction = p_direction)
    AND (p_message_type IS NULL OR message_type = p_message_type)
    AND (p_search IS NULL OR content ILIKE '%'||p_search||'%')
  ORDER BY created_at DESC LIMIT p_limit OFFSET p_offset;
END; $$;


ALTER FUNCTION zapp.rpc_list_messages_all(p_instance text, p_contact_id uuid, p_conversation_id uuid, p_direction text, p_message_type text, p_search text, p_limit integer, p_offset integer) OWNER TO postgres;

--
-- Name: rpc_list_messages_lite(text, text, integer, integer, timestamp with time zone); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_list_messages_lite(p_remote_jid text, p_instance text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0, p_before_date timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS SETOF evo.evolution_messages
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_temp'
    AS $_$
DECLARE
  v_limit   int := GREATEST(COALESCE(p_limit,  50), 0);
  v_offset  int := GREATEST(COALESCE(p_offset,  0), 0);
BEGIN
  PERFORM zapp.fn_require_app_user();
  IF p_before_date IS NULL THEN
    IF p_instance IS NOT NULL THEN
      RETURN QUERY EXECUTE
        'SELECT * FROM zapp.evolution_messages
         WHERE remote_jid   = $1
           AND instance_name = $2
           AND deleted_at   IS NULL
         ORDER BY created_at DESC
         LIMIT $3 OFFSET $4'
      USING p_remote_jid, p_instance, v_limit, v_offset;
    ELSE
      RETURN QUERY EXECUTE
        'SELECT * FROM zapp.evolution_messages
         WHERE remote_jid = $1
           AND deleted_at IS NULL
         ORDER BY created_at DESC
         LIMIT $2 OFFSET $3'
      USING p_remote_jid, v_limit, v_offset;
    END IF;
  ELSE
    IF p_instance IS NOT NULL THEN
      RETURN QUERY EXECUTE
        'SELECT * FROM zapp.evolution_messages
         WHERE remote_jid   = $1
           AND instance_name = $2
           AND deleted_at   IS NULL
           AND created_at   < $3
         ORDER BY created_at DESC
         LIMIT $4 OFFSET $5'
      USING p_remote_jid, p_instance, p_before_date, v_limit, v_offset;
    ELSE
      RETURN QUERY EXECUTE
        'SELECT * FROM zapp.evolution_messages
         WHERE remote_jid = $1
           AND deleted_at IS NULL
           AND created_at < $2
         ORDER BY created_at DESC
         LIMIT $3 OFFSET $4'
      USING p_remote_jid, p_before_date, v_limit, v_offset;
    END IF;
  END IF;
END;
$_$;


ALTER FUNCTION zapp.rpc_list_messages_lite(p_remote_jid text, p_instance text, p_limit integer, p_offset integer, p_before_date timestamp with time zone) OWNER TO postgres;

