--
-- Name: rpc_list_service_channels(text, text, text); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.rpc_list_service_channels(p_status text DEFAULT NULL::text, p_channel_type text DEFAULT NULL::text, p_search text DEFAULT NULL::text) RETURNS SETOF zapp.service_channels
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
BEGIN
  IF NOT zapp.is_admin_or_supervisor(auth.uid()) THEN
    RAISE EXCEPTION 'Access denied: admin or supervisor role required';
  END IF;

  RETURN QUERY
  SELECT * FROM zapp.service_channels sc
   WHERE (p_status IS NULL OR sc.status = p_status)
     AND (p_channel_type IS NULL OR sc.channel_type = p_channel_type)
     AND (p_search IS NULL OR sc.name ILIKE '%'||p_search||'%' OR sc.display_name ILIKE '%'||p_search||'%')
   ORDER BY sc.is_default DESC, sc.name ASC;
END;
$$;


ALTER FUNCTION zapp.rpc_list_service_channels(p_status text, p_channel_type text, p_search text) OWNER TO supabase_admin;

