CREATE FUNCTION zapp.rpc_log_assignment_change(p_conversation_id uuid, p_from_agent uuid, p_to_agent uuid, p_action text, p_performed_by uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_temp'
    AS $$
BEGIN
  PERFORM zapp.fn_require_app_user();
  INSERT INTO zapp.conversation_events
    (contact_id, event_type, from_agent_id, to_agent_id, performed_by, metadata)
  VALUES
    (p_conversation_id, p_action, p_from_agent, p_to_agent, p_performed_by,
     jsonb_build_object('source', 'zapp.rpc_log_assignment_change'));
END;
$$;


