--
-- Name: rpc_log_provider_message(text, text, text, text, text, text, uuid, jsonb, text, uuid); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.rpc_log_provider_message(p_idempotency_key text, p_provider text, p_instance_name text, p_external_message_id text, p_direction text, p_remote_jid text, p_external_contact_id uuid, p_payload jsonb, p_trace_id text DEFAULT NULL::text, p_thread_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  v_id UUID;
  v_hash TEXT;
BEGIN
  IF p_idempotency_key IS NULL OR length(p_idempotency_key) = 0 THEN
    RAISE EXCEPTION 'idempotency_key required';
  END IF;

  v_hash := encode(digest(p_payload::text, 'sha256'), 'hex');

  INSERT INTO zapp.provider_message_log (
    idempotency_key, provider, instance_name, external_message_id,
    direction, remote_jid, external_contact_id, payload, payload_hash,
    trace_id, thread_id
  )
  VALUES (
    p_idempotency_key, p_provider, p_instance_name, p_external_message_id,
    p_direction, p_remote_jid, p_external_contact_id, p_payload, v_hash,
    p_trace_id, p_thread_id
  )
  ON CONFLICT (idempotency_key) DO UPDATE
    SET metadata = provider_message_log.metadata || jsonb_build_object(
      'duplicate_attempts',
      COALESCE((provider_message_log.metadata->>'duplicate_attempts')::int, 0) + 1,
      'last_duplicate_at', now()
    )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


