--
-- Name: rpc_log_search_event(text, jsonb); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_log_search_event(p_query text, p_entities jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$
BEGIN
  INSERT INTO zapp.query_telemetry
    (query_text, query_hash, source, user_id, duration_ms)
  VALUES (
    p_query,
    md5(lower(trim(p_query))),
    'global_search',
    auth.uid(),
    0
  )
  ON CONFLICT DO NOTHING;

  -- Registrar entidades pesquisadas no log de diagnóstico se fornecido
  IF p_entities IS NOT NULL AND jsonb_array_length(p_entities) > 0 THEN
    INSERT INTO zapp.dev_diagnostic_logs (action, category, details, user_id)
    VALUES (
      'search_event',
      'Search',
      jsonb_build_object(
        'query',    p_query,
        'entities', p_entities,
        'ts',       extract(epoch FROM now())
      ),
      auth.uid()
    );
  END IF;
END;
$$;


