-- Name: FUNCTION rpc_mark_conversation_read(p_id uuid); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.rpc_mark_conversation_read(p_id uuid) IS 'FIX A2: parent table em vez de _wpp2 (funciona para qualquer instancia) (extraido do cabecalho do fonte). Args: (p_id uuid).';


--
-- Name: rpc_mark_message_failed(uuid, text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_mark_message_failed(p_queue_id uuid, p_error text DEFAULT 'Unknown error'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
BEGIN
  UPDATE zapp.outbound_message_queue 
  SET 
    status = CASE WHEN retry_count < max_retries THEN 'pending' ELSE 'failed' END,
    retry_count = retry_count + 1,
    error_message = p_error
  WHERE id = p_queue_id;
END;
$$;


ALTER FUNCTION zapp.rpc_mark_message_failed(p_queue_id uuid, p_error text) OWNER TO postgres;

--
-- Name: rpc_mark_messages_as_read(uuid); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_mark_messages_as_read(p_contact_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
BEGIN
  PERFORM zapp.fn_require_app_user();

  IF p_contact_id IS NULL THEN
    RAISE EXCEPTION 'rpc_mark_messages_as_read: p_contact_id cannot be null';
  END IF;

  UPDATE zapp.evolution_messages
  SET
    is_read    = true,
    updated_at = now()
  WHERE contact_id = p_contact_id
    AND from_me    = false
    AND is_read    = false
    AND deleted_at IS NULL;
END;
$$;


ALTER FUNCTION zapp.rpc_mark_messages_as_read(p_contact_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION rpc_mark_messages_as_read(p_contact_id uuid); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.rpc_mark_messages_as_read(p_contact_id uuid) IS 'Marks all inbound (from_me=false) messages for a contact as read in evo.evolution_messages. SECURITY DEFINER bypasses the missing UPDATE RLS policy on the evo schema.';


