    color text DEFAULT '#3B82F6'::text,
    icon text DEFAULT 'inbox'::text,
    is_active boolean DEFAULT true,
    max_capacity integer,
    auto_assign boolean DEFAULT true,
    round_robin boolean DEFAULT true,
    priority integer DEFAULT 0,
    sla_policy_id uuid,
    business_hours jsonb DEFAULT '{}'::jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    auto_rebalance_enabled boolean DEFAULT true NOT NULL,
    department_id uuid,
    distribution_algorithm text DEFAULT 'least_busy'::text NOT NULL,
    last_assigned_at timestamp with time zone,
    last_assigned_user_id uuid,
    max_concurrent_per_agent integer,
    max_per_queue_per_agent integer,
    max_queue_size integer,
    max_wait_seconds integer,
    max_wait_time_minutes integer DEFAULT 30,
    overflow_queue_id uuid,
    paused_at timestamp with time zone,
    paused_by uuid,
    paused_reason text,
    routing_weight integer DEFAULT 1 NOT NULL,
    sla_priority text DEFAULT 'medium'::text NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
