--
-- Name: rpc_pause_queue(uuid, text); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.rpc_pause_queue(p_queue_id uuid, p_reason text DEFAULT NULL::text) RETURNS zapp.queues
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE v_row zapp.queues;
BEGIN
  IF NOT is_admin_or_supervisor(auth.uid()) THEN RAISE EXCEPTION 'forbidden'; END IF;
  UPDATE zapp.queues
     SET status='paused', paused_at=now(), paused_by=auth.uid(), paused_reason=p_reason, is_active=false
   WHERE id=p_queue_id RETURNING * INTO v_row;
  IF v_row.id IS NULL THEN RAISE EXCEPTION 'queue not found'; END IF;
  RETURN v_row;
END $$;


ALTER FUNCTION zapp.rpc_pause_queue(p_queue_id uuid, p_reason text) OWNER TO supabase_admin;

--
-- Name: rpc_pause_service_channel(uuid, text); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.rpc_pause_service_channel(p_id uuid, p_reason text DEFAULT NULL::text) RETURNS zapp.service_channels
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE v_row zapp.service_channels;
BEGIN
  IF NOT zapp.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Access denied: admin role required';
  END IF;

  UPDATE zapp.service_channels SET
    status = 'paused',
    paused_at = now(),
    paused_reason = NULLIF(trim(COALESCE(p_reason,'')), '')
  WHERE id = p_id
  RETURNING * INTO v_row;

  IF v_row.id IS NULL THEN RAISE EXCEPTION 'channel not found'; END IF;

  INSERT INTO zapp.audit_logs (user_id, action, entity_type, entity_id, details)
  VALUES (auth.uid(), 'service_channel_paused', 'service_channels', p_id::text,
          jsonb_build_object('reason', p_reason));

  RETURN v_row;
END;
$$;


ALTER FUNCTION zapp.rpc_pause_service_channel(p_id uuid, p_reason text) OWNER TO supabase_admin;

--
-- Name: rpc_pick_next_agent(uuid); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.rpc_pick_next_agent(p_queue_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  v_algo text;
  v_last uuid;
  v_pick uuid;
BEGIN
  SELECT distribution_algorithm, last_assigned_user_id
    INTO v_algo, v_last
    FROM zapp.queues
   WHERE id = p_queue_id AND status = 'active';

  IF v_algo IS NULL OR v_algo = 'manual_pull' THEN
    RETURN NULL;
  END IF;

  IF v_algo = 'round_robin' THEN
    -- Próximo elegível depois do último atribuído (ordem determinística por user_id),
    -- com fallback para o primeiro elegível se já passou do fim da lista.
    WITH cand AS (
      SELECT user_id, active_chats, max_chats
        FROM zapp.rpc_list_eligible_agents(p_queue_id)
       WHERE active_chats < max_chats
       ORDER BY user_id
    )
    SELECT user_id INTO v_pick FROM cand
     WHERE v_last IS NULL OR user_id > v_last
     ORDER BY user_id
     LIMIT 1;

    IF v_pick IS NULL THEN
      SELECT user_id INTO v_pick FROM (
        SELECT user_id, active_chats, max_chats
          FROM zapp.rpc_list_eligible_agents(p_queue_id)
         WHERE active_chats < max_chats
         ORDER BY user_id
         LIMIT 1
      ) s;
    END IF;
  ELSIF v_algo = 'longest_idle' THEN
    SELECT a.user_id INTO v_pick
      FROM zapp.rpc_list_eligible_agents(p_queue_id) a
      LEFT JOIN zapp.profiles p ON p.user_id = a.user_id
     WHERE a.active_chats < a.max_chats
     ORDER BY p.last_active_at NULLS FIRST, a.active_chats ASC, random()
     LIMIT 1;
  ELSE
    -- least_busy (default)
    SELECT user_id INTO v_pick
      FROM zapp.rpc_list_eligible_agents(p_queue_id)
     WHERE active_chats < max_chats
     ORDER BY active_chats ASC, random()
     LIMIT 1;
  END IF;

  IF v_pick IS NOT NULL THEN
    UPDATE zapp.queues
       SET last_assigned_user_id = v_pick,
           last_assigned_at = now()
     WHERE id = p_queue_id;
  END IF;

  RETURN v_pick;
END
$$;


ALTER FUNCTION zapp.rpc_pick_next_agent(p_queue_id uuid) OWNER TO supabase_admin;

--
-- Name: FUNCTION rpc_pick_next_agent(p_queue_id uuid); Type: COMMENT; Schema: zapp; Owner: supabase_admin
--

COMMENT ON FUNCTION zapp.rpc_pick_next_agent(p_queue_id uuid) IS 'Próximo elegível depois do último atribuído (ordem determinística por user_id), (extraido do cabecalho do fonte). Args: (p_queue_id uuid).';


--
-- Name: rpc_pipeline_dashboard(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_pipeline_dashboard() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'pg_temp'
    AS $$
DECLARE
  v_wh_health       record;
  v_pending_count   bigint;
  v_failed_count    bigint;
  v_hours_silent    numeric;
  v_health_status   text;
  v_result          jsonb;
BEGIN
  SELECT
  CASE WHEN count(*) FILTER (WHERE created_at >= now() - interval '1 hour') > 0 THEN 'healthy'
       WHEN count(*) FILTER (WHERE created_at >= now() - interval '24 hours') > 0 THEN 'degraded'
       ELSE 'critical' END AS health_status,
  max(created_at) AS last_event_at,
  count(*) FILTER (WHERE NOT processed) AS unresponded,
  count(*) FILTER (WHERE created_at >= now() - interval '1 hour') AS events_1h,
  count(*) FILTER (WHERE created_at >= now() - interval '24 hours') AS events_24h,
  count(*) FILTER (WHERE processed_at >= now() - interval '1 hour') AS processed_1h
INTO v_wh_health
FROM public.evo_webhook_events_v2;

  SELECT count(*) INTO v_pending_count
  FROM public.evo_webhook_events_v2 WHERE status = 'pending';

  SELECT count(*) INTO v_failed_count
  FROM public.evo_webhook_events_v2 WHERE status = 'failed';

  v_hours_silent := CASE
    WHEN v_wh_health.last_event_at IS NOT NULL
    THEN ROUND(EXTRACT(EPOCH FROM (now() - v_wh_health.last_event_at))/3600, 1)
    ELSE 9999
  END;

  v_health_status := CASE
    WHEN v_wh_health.events_1h > 0 THEN 'healthy'
    WHEN v_wh_health.events_24h > 0 THEN 'degraded'
    WHEN v_hours_silent > 24        THEN 'critical'
    ELSE 'unknown'
  END;

  v_result := jsonb_build_object(
    'health_status',       v_health_status,
    'last_event_at',       v_wh_health.last_event_at,
    'events_last_hour',    COALESCE(v_wh_health.events_1h, 0),
    'events_last_24h',     COALESCE(v_wh_health.events_24h, 0),
    'processed_last_hour', COALESCE(v_wh_health.processed_1h, 0),
    'pending_webhooks',    COALESCE(v_pending_count, 0),
    'failed_webhooks',     COALESCE(v_failed_count, 0),
    'hours_silent',        v_hours_silent,
    'source_table',        'evolution_webhook_events_v2',
    'snapshot_at',         now()
  );

  RETURN v_result;
END;
$$;


ALTER FUNCTION zapp.rpc_pipeline_dashboard() OWNER TO postgres;

--
-- Name: rpc_provider_panel(); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.rpc_provider_panel() RETURNS TABLE(provider_id uuid, name text, provider_type zapp.provider_type, base_url text, is_active boolean, priority integer, status text, last_ping_at timestamp with time zone, last_ping_latency_ms integer, last_error text, open_sessions bigint, events_24h bigint, errors_24h bigint, routes_primary bigint, routes_fallback bigint, routes_active bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
BEGIN
  IF NOT zapp.is_admin_or_supervisor(auth.uid()) THEN
    RAISE EXCEPTION 'Access denied: admin or supervisor role required';
  END IF;

  RETURN QUERY
  SELECT
    p.id, p.name, p.provider_type, p.base_url, p.is_active, p.priority,
    p.status, p.last_ping_at, p.last_ping_latency_ms, p.last_error,
    COALESCE((SELECT COUNT(*) FROM provider_sessions s
              WHERE s.provider_id = p.id AND s.ended_at IS NULL), 0),
    COALESCE((SELECT COUNT(*) FROM provider_session_logs l
              WHERE l.provider_id = p.id AND l.created_at > now() - interval '24 hours'), 0),
    COALESCE((SELECT COUNT(*) FROM provider_session_logs l
              WHERE l.provider_id = p.id AND l.level = 'error'
                AND l.created_at > now() - interval '24 hours'), 0),
    COALESCE((SELECT COUNT(*) FROM channel_provider_routes r WHERE r.primary_provider_id = p.id), 0),
    COALESCE((SELECT COUNT(*) FROM channel_provider_routes r WHERE r.fallback_provider_id = p.id), 0),
    COALESCE((SELECT COUNT(*) FROM channel_provider_routes r WHERE r.current_provider_id = p.id), 0)
  FROM provider_configs p
  ORDER BY p.priority ASC, p.name ASC;
END;
$$;


ALTER FUNCTION zapp.rpc_provider_panel() OWNER TO supabase_admin;

--
-- Name: rpc_provider_session_timeline(uuid, uuid, integer); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.rpc_provider_session_timeline(p_provider_id uuid DEFAULT NULL::uuid, p_session_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 100) RETURNS TABLE(log_id uuid, session_id uuid, provider_id uuid, provider_name text, level text, event text, message text, latency_ms integer, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
BEGIN
  IF NOT zapp.is_admin_or_supervisor(auth.uid()) THEN
    RAISE EXCEPTION 'Access denied: admin or supervisor role required';
  END IF;

  RETURN QUERY
  SELECT l.id, l.session_id, l.provider_id, p.name,
         l.level, l.event, l.message, l.latency_ms, l.created_at
  FROM provider_session_logs l
  JOIN provider_configs p ON p.id = l.provider_id
  WHERE (p_provider_id IS NULL OR l.provider_id = p_provider_id)
    AND (p_session_id IS NULL OR l.session_id = p_session_id)
  ORDER BY l.created_at DESC
  LIMIT GREATEST(1, LEAST(p_limit, 500));
END;
$$;


ALTER FUNCTION zapp.rpc_provider_session_timeline(p_provider_id uuid, p_session_id uuid, p_limit integer) OWNER TO supabase_admin;

--
-- Name: rpc_publish_outbox(text, uuid, text, jsonb, text, text); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.rpc_publish_outbox(p_aggregate_type text, p_aggregate_id uuid, p_event_type text, p_payload jsonb, p_idempotency_key text DEFAULT NULL::text, p_trace_id text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  v_key TEXT;
  v_id UUID;
BEGIN
  v_key := COALESCE(
    p_idempotency_key,
    encode(digest(
      p_aggregate_type || ':' || p_aggregate_id::text || ':' || p_event_type || ':' ||
      encode(digest(p_payload::text, 'sha256'), 'hex'),
      'sha256'
    ), 'hex')
  );

  INSERT INTO zapp.outbox_events (
    aggregate_type, aggregate_id, event_type, payload, idempotency_key, trace_id
  )
  VALUES (p_aggregate_type, p_aggregate_id, p_event_type, p_payload, v_key, p_trace_id)
  ON CONFLICT (idempotency_key) DO NOTHING
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


ALTER FUNCTION zapp.rpc_publish_outbox(p_aggregate_type text, p_aggregate_id uuid, p_event_type text, p_payload jsonb, p_idempotency_key text, p_trace_id text) OWNER TO supabase_admin;

--
-- Name: rpc_purge_channel_sticky(uuid); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.rpc_purge_channel_sticky(p_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  v_wpp_id UUID;
  v_count INTEGER := 0;
BEGIN
  IF NOT zapp.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Access denied: admin role required';
  END IF;

  SELECT whatsapp_connection_id INTO v_wpp_id
    FROM zapp.service_channels WHERE id = p_id;

  IF v_wpp_id IS NULL THEN
    RETURN 0;
  END IF;

  DELETE FROM zapp.sticky_assignments
   WHERE channel_connection_id = v_wpp_id;

  GET DIAGNOSTICS v_count = ROW_COUNT;

  INSERT INTO zapp.audit_logs (user_id, action, entity_type, entity_id, details)
  VALUES (auth.uid(), 'service_channel_sticky_purged', 'service_channels', p_id::text,
          jsonb_build_object('purged_count', v_count));

  RETURN v_count;
END;
$$;


ALTER FUNCTION zapp.rpc_purge_channel_sticky(p_id uuid) OWNER TO supabase_admin;

