CREATE FUNCTION zapp.rpc_record_automation_error(p_execution_id uuid, p_error text, p_context jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
BEGIN
  UPDATE zapp.automation_executions
  SET status = 'failed',
      error_message = LEFT(COALESCE(p_error, 'unknown error'), 2000),
      error_at = now(),
      trigger_payload = COALESCE(trigger_payload, '{}'::jsonb) || jsonb_build_object('error_context', p_context)
  WHERE id = p_execution_id;
END;
$$;


