--
-- Name: rpc_register_automation_execution(uuid, text, text, uuid, jsonb); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.rpc_register_automation_execution(p_rule_id uuid, p_remote_jid text, p_instance_name text, p_assigned_to uuid, p_trigger_payload jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  v_cooldown INTEGER;
  v_recent_count INTEGER;
  v_id UUID;
BEGIN
  SELECT cooldown_seconds INTO v_cooldown
  FROM zapp.automation_rules WHERE id = p_rule_id AND is_active = true;
  IF v_cooldown IS NULL THEN RETURN NULL; END IF;

  SELECT COUNT(*) INTO v_recent_count
  FROM zapp.automation_executions
  WHERE rule_id = p_rule_id
    AND remote_jid = p_remote_jid
    AND created_at > now() - make_interval(secs => v_cooldown);

  IF v_recent_count > 0 THEN RETURN NULL; END IF;

  INSERT INTO zapp.automation_executions (
    rule_id, remote_jid, instance_name, assigned_to, trigger_payload, status
  ) VALUES (
    p_rule_id, p_remote_jid, p_instance_name, p_assigned_to, p_trigger_payload, 'pending'
  ) RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


ALTER FUNCTION zapp.rpc_register_automation_execution(p_rule_id uuid, p_remote_jid text, p_instance_name text, p_assigned_to uuid, p_trigger_payload jsonb) OWNER TO supabase_admin;

--
-- Name: rpc_register_automation_execution(uuid, text, text, text, jsonb, uuid, uuid); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.rpc_register_automation_execution(p_rule_id uuid, p_remote_jid text, p_instance_name text, p_assigned_to text DEFAULT NULL::text, p_trigger_payload jsonb DEFAULT '{}'::jsonb, p_channel_id uuid DEFAULT NULL::uuid, p_department_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  v_cooldown INT;
  v_last TIMESTAMPTZ;
  v_id UUID;
  v_channel UUID;
  v_department UUID;
  v_snapshot JSONB;
BEGIN
  SELECT cooldown_seconds, channel_id, department_id,
         jsonb_build_object(
           'name', name,
           'description', description,
           'trigger_type', trigger_type,
           'trigger_config', trigger_config,
           'actions', actions,
           'priority', priority,
           'cooldown_seconds', cooldown_seconds,
           'channel_id', channel_id,
           'department_id', department_id,
           'captured_at', now()
         )
    INTO v_cooldown, v_channel, v_department, v_snapshot
  FROM zapp.automation_rules WHERE id = p_rule_id AND is_active = true;

  IF v_cooldown IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT MAX(created_at) INTO v_last
  FROM zapp.automation_executions
  WHERE rule_id = p_rule_id AND remote_jid = p_remote_jid;

  IF v_last IS NOT NULL AND v_last > now() - make_interval(secs => v_cooldown) THEN
    RETURN NULL;
  END IF;

  INSERT INTO zapp.automation_executions (
    rule_id, remote_jid, instance_name, assigned_to, trigger_payload,
    channel_id, department_id, rule_snapshot, status
  ) VALUES (
    p_rule_id, p_remote_jid, p_instance_name, p_assigned_to, p_trigger_payload,
    COALESCE(p_channel_id, v_channel),
    COALESCE(p_department_id, v_department),
    v_snapshot,
    'pending'
  ) RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


ALTER FUNCTION zapp.rpc_register_automation_execution(p_rule_id uuid, p_remote_jid text, p_instance_name text, p_assigned_to text, p_trigger_payload jsonb, p_channel_id uuid, p_department_id uuid) OWNER TO supabase_admin;

--
-- Name: rpc_register_webhook_event(text, text, text, text); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.rpc_register_webhook_event(p_event_key text, p_instance_name text, p_event_type text, p_payload_hash text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  v_inserted BOOLEAN;
BEGIN
  IF p_event_key IS NULL OR length(p_event_key) = 0 THEN
    RAISE EXCEPTION 'event_key required';
  END IF;

  INSERT INTO zapp.webhook_event_dedup (event_key, instance_name, event_type, payload_hash)
  VALUES (p_event_key, p_instance_name, p_event_type, p_payload_hash)
  ON CONFLICT (event_key) DO NOTHING;

  GET DIAGNOSTICS v_inserted = ROW_COUNT;
  RETURN v_inserted > 0;
END;
$$;


ALTER FUNCTION zapp.rpc_register_webhook_event(p_event_key text, p_instance_name text, p_event_type text, p_payload_hash text) OWNER TO supabase_admin;

--
-- Name: rpc_reset_conversation_unread(uuid, text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_reset_conversation_unread(p_contact_id uuid, p_instance text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'public', 'auth'
    AS $$
BEGIN
  IF auth.role() <> 'service_role' THEN
    IF NOT (
      zapp.is_admin_or_supervisor() OR
      zapp.is_contact_visible_to_user(p_contact_id, auth.uid())
    ) THEN
      RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
    END IF;
  END IF;
  UPDATE zapp.evolution_conversations
  SET unread_count = 0, updated_at = now()
  WHERE contact_id = p_contact_id
    AND (p_instance IS NULL OR instance_name = p_instance);
END;
$$;


ALTER FUNCTION zapp.rpc_reset_conversation_unread(p_contact_id uuid, p_instance text) OWNER TO postgres;

--
-- Name: rpc_resolve_instance_by_phone(text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_resolve_instance_by_phone(p_phone text) RETURNS TABLE(instance_name text, api_url text, api_key text, connection_id uuid, contact_phone text, remote_jid text, contact_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $_$
DECLARE
  cleaned text;
BEGIN
  PERFORM zapp.fn_require_app_user();
  cleaned := zapp.fn_normalize_br_phone(p_phone);

  RETURN QUERY
  SELECT
    ec.instance_name::text,
    wc.api_url,
    CASE WHEN wc.api_key IS NULL THEN NULL ELSE '********' END AS api_key,
    wc.id AS connection_id,
    -- LID-FIX-01 (lid-s7 2026-08-11): não propagar LID como telefone
    CASE
      WHEN ec.phone_number IS NOT NULL
           AND ec.phone_number ~ '^[0-9]+$'
           AND length(ec.phone_number) <= 13
      THEN ec.phone_number::text
      WHEN length(split_part(ec.remote_jid,'@',1)) <= 13
           AND split_part(ec.remote_jid,'@',1) ~ '^[0-9]+$'
           AND ec.remote_jid NOT LIKE '%@lid'
      THEN split_part(ec.remote_jid,'@',1)::text
      ELSE NULL  -- LID-only: sem phone real até Evolution 2.4.x
    END AS contact_phone,
    ec.remote_jid::text,
    ec.id AS contact_id
  FROM zapp.evolution_contacts ec
  JOIN zapp.whatsapp_connections wc ON wc.instance_name = ec.instance_name AND wc.is_active = true
  WHERE ec.deleted_at IS NULL
    AND (
      ec.phone_number = cleaned
      OR split_part(ec.remote_jid, '@', 1) = cleaned
      OR ec.phone_number = p_phone
      OR split_part(ec.remote_jid, '@', 1) = p_phone
    )
  ORDER BY ec.last_message_at DESC NULLS LAST
  LIMIT 1;
END;
$_$;


ALTER FUNCTION zapp.rpc_resolve_instance_by_phone(p_phone text) OWNER TO postgres;

--
-- Name: FUNCTION rpc_resolve_instance_by_phone(p_phone text); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.rpc_resolve_instance_by_phone(p_phone text) IS 'LID-FIX-01 (lid-s7 2026-08-11): não propagar LID como telefone (extraido do cabecalho do fonte). Args: (p_phone text).';


--
-- Name: rpc_resolve_whatsapp_instance(uuid); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_resolve_whatsapp_instance(p_contact_id uuid) RETURNS TABLE(instance_name text, api_url text, api_key text, connection_id uuid, contact_phone text, remote_jid text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $_$
BEGIN
  PERFORM zapp.fn_require_app_user();
  RETURN QUERY
  SELECT
    ec.instance_name::text,
    wc.api_url,
    CASE WHEN wc.api_key IS NULL THEN NULL ELSE '********' END AS api_key,
    wc.id AS connection_id,
    -- LID-FIX-01 (2026-08-11): se phone_number for LID (14+ dígitos) ou NULL,
    -- retornar NULL em vez de propagar o LID como telefone
    CASE
      WHEN ec.phone_number IS NOT NULL
           AND ec.phone_number ~ '^[0-9]+$'
           AND length(ec.phone_number) <= 13
      THEN ec.phone_number::text
      WHEN length(split_part(ec.remote_jid,'@',1)) <= 13
           AND split_part(ec.remote_jid,'@',1) ~ '^[0-9]+$'
           AND ec.remote_jid NOT LIKE '%@lid'
      THEN split_part(ec.remote_jid,'@',1)::text
      ELSE NULL  -- LID-only: contato sem telefone real até Evolution 2.4.x
    END AS contact_phone,
    ec.remote_jid::text
  FROM zapp.evolution_contacts ec
  JOIN zapp.whatsapp_connections wc ON wc.instance_name = ec.instance_name AND wc.is_active = true
  WHERE ec.id = p_contact_id AND ec.deleted_at IS NULL
  LIMIT 1;
END;
$_$;


