--
-- Name: rpc_schema_columns(text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_schema_columns(p_schema text DEFAULT 'zapp'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp, pg_temp'
    AS $$
BEGIN
  IF p_schema NOT IN ('zapp', 'evo', 'public') THEN
    RAISE EXCEPTION 'permission denied: schema not allowed: %', p_schema
      USING ERRCODE = '42501';
  END IF;

  RETURN COALESCE(
    (
      SELECT jsonb_agg(
               jsonb_build_object(
                 'table_name',   t.table_name::text,
                 'column_name',  c.column_name::text,
                 'data_type',    c.data_type::text,
                 'is_nullable',  c.is_nullable::text
               )
               ORDER BY t.table_name, c.ordinal_position
             )
      FROM information_schema.columns c
      JOIN information_schema.tables t
        ON t.table_schema = c.table_schema AND t.table_name = c.table_name
      WHERE c.table_schema = p_schema
    ),
    '[]'::jsonb
  );
END;
$$;


ALTER FUNCTION zapp.rpc_schema_columns(p_schema text) OWNER TO postgres;

--
-- Name: rpc_schema_tables(text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_schema_tables(p_schema text DEFAULT 'zapp'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp, pg_temp'
    AS $$
BEGIN
  IF p_schema NOT IN ('zapp', 'evo', 'public') THEN
    RAISE EXCEPTION 'permission denied: schema not allowed: %', p_schema
      USING ERRCODE = '42501';
  END IF;

  RETURN COALESCE(
    (
      SELECT jsonb_agg(
               jsonb_build_object(
                 'table_name', table_name::text,
                 'table_type', table_type::text
               )
               ORDER BY table_name
             )
      FROM information_schema.tables
      WHERE table_schema = p_schema
    ),
    '[]'::jsonb
  );
END;
$$;


ALTER FUNCTION zapp.rpc_schema_tables(p_schema text) OWNER TO postgres;

--
-- Name: rpc_search_audio_memes(text, text, integer); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.rpc_search_audio_memes(p_search text, p_category text DEFAULT NULL::text, p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$
BEGIN
  RETURN (
    SELECT jsonb_build_object(
      'ok', true,
      'query', p_search,
      'total', count(*),
      'results', COALESCE(jsonb_agg(
        jsonb_build_object(
          'id', id, 'name', name, 'category', category,
          'audio_url', audio_url, 'use_count', use_count,
          'tags', tags, 'similarity', round(similarity(name, p_search)::numeric, 3)
        ) ORDER BY similarity(name, p_search) DESC, use_count DESC
      ), '[]'::jsonb)
    )
    FROM (
      SELECT * FROM audio_memes
      WHERE is_active = true
        AND (
          name % p_search
          OR name ILIKE '%' || p_search || '%'
          OR EXISTS (SELECT 1 FROM unnest(tags) t WHERE t ILIKE '%' || p_search || '%')
        )
        AND (p_category IS NULL OR category = p_category)
      ORDER BY similarity(name, p_search) DESC, use_count DESC
      LIMIT p_limit
    ) sub
  );
END;
$$;


ALTER FUNCTION zapp.rpc_search_audio_memes(p_search text, p_category text, p_limit integer) OWNER TO supabase_admin;

--
-- Name: FUNCTION rpc_search_audio_memes(p_search text, p_category text, p_limit integer); Type: COMMENT; Schema: zapp; Owner: supabase_admin
--

COMMENT ON FUNCTION zapp.rpc_search_audio_memes(p_search text, p_category text, p_limit integer) IS 'Busca fuzzy por nome (trigram) e tags. Retorna com score de similaridade.';


--
-- Name: rpc_search_insights(integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_search_insights(p_days integer DEFAULT 7) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$
DECLARE
  v_result         jsonb;
  v_total_searches bigint;
  v_zero_results   bigint;
  v_avg_results    numeric;
  v_top_queries    jsonb;
BEGIN
  SELECT count(*) INTO v_total_searches
  FROM zapp.query_telemetry
  WHERE created_at >= now() - (p_days || ' days')::interval
    AND source = 'global_search';

  SELECT COALESCE(jsonb_agg(q ORDER BY cnt DESC), '[]'::jsonb)
  INTO v_top_queries
  FROM (
    SELECT query_text AS query, count(*) AS cnt
    FROM zapp.query_telemetry
    WHERE created_at >= now() - (p_days || ' days')::interval
      AND source = 'global_search'
      AND query_text IS NOT NULL
    GROUP BY query_text
    ORDER BY cnt DESC
    LIMIT 10
  ) q;

  SELECT count(*) INTO v_zero_results
  FROM zapp.dev_diagnostic_logs
  WHERE action = 'search_click'
    AND created_at >= now() - (p_days || ' days')::interval;

  v_result := jsonb_build_object(
    'total_searches',       COALESCE(v_total_searches, 0),
    'zero_result_queries',  0,
    'avg_result_count',     0,
    'click_through_rate',   CASE
                              WHEN v_total_searches > 0
                              THEN ROUND(v_zero_results::numeric / v_total_searches * 100, 2)
                              ELSE 0
                            END,
    'top_queries',          COALESCE(v_top_queries, '[]'::jsonb),
    'window_days',          p_days,
    'generated_at',         now()
  );

  RETURN v_result;
END;
$$;


ALTER FUNCTION zapp.rpc_search_insights(p_days integer) OWNER TO postgres;

--
-- Name: rpc_search_messages(text, text, integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_search_messages(p_query text, p_instance text DEFAULT 'wpp2'::text, p_limit integer DEFAULT 20) RETURNS TABLE(id uuid, message_id text, remote_jid text, from_me boolean, content text, message_type text, created_at timestamp with time zone, push_name text, rank real)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$

BEGIN
  PERFORM zapp.fn_require_app_user();
RETURN QUERY  SELECT m.id, m.message_id, m.remote_jid, m.from_me,
    m.content, m.message_type, m.created_at, m.push_name,
    ts_rank(
      to_tsvector('portuguese', COALESCE(m.content,'')),
      plainto_tsquery('portuguese', p_query)
    ) AS rank
  FROM zapp.evolution_messages m
  WHERE (p_instance IS NULL OR m.instance_name = p_instance)
    AND m.content IS NOT NULL AND m.deleted_at IS NULL
    AND to_tsvector('portuguese', COALESCE(m.content,''))
        @@ plainto_tsquery('portuguese', p_query)
  ORDER BY rank DESC, m.created_at DESC
  LIMIT p_limit;

END;$$;


