--
-- Name: rpc_search_stickers(text, text, boolean, integer, integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_search_stickers(p_query text DEFAULT NULL::text, p_category text DEFAULT NULL::text, p_favorites_only boolean DEFAULT false, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS SETOF zapp.stickers
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
BEGIN
  RETURN QUERY
  SELECT s.*
  FROM zapp.stickers s
  WHERE s.is_active = true
    AND (p_query IS NULL OR s.name ILIKE '%' || p_query || '%' OR s.category ILIKE '%' || p_query || '%')
    AND (p_category IS NULL OR s.category = p_category)
    AND (NOT p_favorites_only OR s.is_favorite = true)
  ORDER BY 
    CASE WHEN p_favorites_only THEN s.use_count END DESC,
    s.use_count DESC,
    s.created_at DESC
  LIMIT p_limit
  OFFSET p_offset;
END;
$$;


ALTER FUNCTION zapp.rpc_search_stickers(p_query text, p_category text, p_favorites_only boolean, p_limit integer, p_offset integer) OWNER TO postgres;

--
-- Name: rpc_send_sticker(uuid, text, text, uuid, uuid); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_send_sticker(p_contact_id uuid, p_sticker_url text DEFAULT NULL::text, p_instance_name text DEFAULT 'wpp_pink_test'::text, p_sticker_id uuid DEFAULT NULL::uuid, p_created_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth'
    AS $$
DECLARE
  v_remote_jid text; v_queue_id uuid; v_sticker record; v_url text;
BEGIN
  PERFORM zapp.fn_require_app_user();

  SELECT remote_jid INTO v_remote_jid FROM zapp.evolution_contacts WHERE id=p_contact_id;
  IF v_remote_jid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'contact_id nao encontrado');
  END IF;
  v_url := p_sticker_url;
  IF p_sticker_id IS NOT NULL THEN
    SELECT * INTO v_sticker FROM zapp.stickers WHERE id=p_sticker_id;
    IF v_sticker IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'sticker_id nao encontrado no catalogo');
    END IF;
    v_url := v_sticker.image_url;
    UPDATE zapp.stickers SET use_count=COALESCE(use_count,0)+1 WHERE id=p_sticker_id;
  END IF;
  IF v_url IS NULL OR v_url = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'sticker_url obrigatoria (ou fornecer sticker_id)');
  END IF;
  INSERT INTO zapp.outbound_message_queue(
    contact_id, remote_jid, instance_name, message_type, content,
    media_url, media_mime_type, sticker_id, metadata, status, retry_count, max_retries, created_by
  ) VALUES(
    p_contact_id, v_remote_jid, p_instance_name, 'sticker', '',
    v_url, 'image/webp', p_sticker_id,
    CASE WHEN v_sticker IS NOT NULL THEN
      jsonb_build_object('sticker_name', v_sticker.name, 'sticker_category', v_sticker.category)
    ELSE NULL END,
    'pending', 0, 3, p_created_by
  ) RETURNING id INTO v_queue_id;
  RETURN jsonb_build_object(
    'ok', true, 'queue_id', v_queue_id, 'remote_jid', v_remote_jid,
    'sticker_url', v_url, 'sticker_id', p_sticker_id, 'instance_name', p_instance_name
  );
END; $$;


ALTER FUNCTION zapp.rpc_send_sticker(p_contact_id uuid, p_sticker_url text, p_instance_name text, p_sticker_id uuid, p_created_by uuid) OWNER TO postgres;

--
-- Name: rpc_set_whatsapp_mode(text); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.rpc_set_whatsapp_mode(p_mode text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
BEGIN
  IF NOT zapp.is_admin_or_supervisor(v_uid) THEN
    RAISE EXCEPTION 'forbidden: only admin/supervisor can change whatsapp_mode';
  END IF;

  -- NULL NOT IN (...) = NULL -> IF NULL = FALSE: guarda explícita contra NULL
  -- (achado A3 da auditoria de confirmação 2026-08-05)
  IF p_mode IS NULL OR p_mode NOT IN ('official', 'unofficial') THEN
    RAISE EXCEPTION 'invalid mode: % (allowed: official, unofficial)', p_mode;
  END IF;

  INSERT INTO zapp.global_settings (key, value, updated_by)
  VALUES ('whatsapp_mode', p_mode, v_uid)
  ON CONFLICT (key) DO UPDATE
    SET value = EXCLUDED.value,
        updated_by = EXCLUDED.updated_by,
        updated_at = now();

  RETURN p_mode;
END;
$$;


ALTER FUNCTION zapp.rpc_set_whatsapp_mode(p_mode text) OWNER TO supabase_admin;

