-- Name: FUNCTION rpc_set_whatsapp_mode(p_mode text); Type: COMMENT; Schema: zapp; Owner: supabase_admin
--

COMMENT ON FUNCTION zapp.rpc_set_whatsapp_mode(p_mode text) IS 'NULL NOT IN (...) = NULL -> IF NULL = FALSE: guarda explícita contra NULL (extraido do cabecalho do fonte). Args: (p_mode text).';


--
-- Name: rpc_sla_timeline_aggregate(text, text); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.rpc_sla_timeline_aggregate(p_remote_jid text, p_instance text DEFAULT NULL::text) RETURNS TABLE(first_inbound_at timestamp with time zone, first_outbound_at timestamp with time zone, last_message_at timestamp with time zone, total_messages bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_temp'
    AS $$
BEGIN
  PERFORM zapp.fn_require_app_user();

  IF p_instance IS NOT NULL THEN
    RETURN QUERY
      SELECT MIN(created_at) FILTER (WHERE from_me = false OR direction = 'inbound'),
             MIN(created_at) FILTER (WHERE from_me = true  OR direction = 'outbound'),
             MAX(created_at),
             COUNT(*)
      FROM zapp.evolution_messages
      WHERE remote_jid    = p_remote_jid
        AND instance_name = p_instance
        AND deleted_at   IS NULL;
  ELSE
    RETURN QUERY
      SELECT MIN(created_at) FILTER (WHERE from_me = false OR direction = 'inbound'),
             MIN(created_at) FILTER (WHERE from_me = true  OR direction = 'outbound'),
             MAX(created_at),
             COUNT(*)
      FROM zapp.evolution_messages
      WHERE remote_jid  = p_remote_jid
        AND deleted_at IS NULL;
  END IF;
END;
$$;


ALTER FUNCTION zapp.rpc_sla_timeline_aggregate(p_remote_jid text, p_instance text) OWNER TO supabase_admin;

