--
-- Name: rpc_toggle_cron_job(text, boolean); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.rpc_toggle_cron_job(p_jobname text, p_active boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'cron', 'zapp'
    AS $$
BEGIN
  IF NOT zapp.is_admin_or_supervisor() THEN
    RAISE EXCEPTION 'Acesso negado: apenas admins e supervisores podem ativar/desativar cron jobs'
      USING ERRCODE = '42501';
  END IF;

  UPDATE cron.job
  SET active = p_active
  WHERE jobname = p_jobname;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'cron job % not found', p_jobname
      USING ERRCODE = 'P0002';
  END IF;
END;
$$;


