    AS $$ DECLARE v_count int; v_id uuid := p_id::uuid; BEGIN UPDATE zapp.evolution_followup_rules SET is_active=p_is_active, updated_at=now() WHERE sequence_group=v_id OR (sequence_group IS NULL AND id=v_id); GET DIAGNOSTICS v_count = ROW_COUNT; RETURN jsonb_build_object('ok',true,'updated',v_count); EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('ok',false,'error',SQLERRM); END; $$;


