--
-- Name: rpc_unified_search(text, integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_unified_search(p_query text, p_limit integer DEFAULT 20) RETURNS TABLE(result_type text, id uuid, title text, subtitle text, avatar_url text, relevance real, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $_$
BEGIN
  PERFORM zapp.fn_require_app_user();

  RETURN QUERY
  SELECT * FROM (
    -- Contatos
    SELECT
      'contact'::text AS result_type,
      ec.id,
      COALESCE(ec.full_name, ec.push_name, 'Sem nome')::text AS title,
      -- LID-FIX-01 (lid-s7 2026-08-11): evitar exibir LID 14+ como telefone
      -- Se phone_number real existe (≤13 dig) → usa. Senão → 'LID:' prefix ou vazio.
      CASE
        WHEN ec.phone_number IS NOT NULL
             AND length(ec.phone_number) <= 13
             AND ec.phone_number ~ '^[0-9]+$'
        THEN ec.phone_number
        WHEN length(split_part(ec.remote_jid::text, '@', 1)) <= 13
             AND split_part(ec.remote_jid::text, '@', 1) ~ '^[0-9]+$'
        THEN split_part(ec.remote_jid::text, '@', 1)
        ELSE 'LID: ' || left(split_part(ec.remote_jid::text,'@',1), 8) || '…'
      END::text AS subtitle,
      ec.profile_picture_url::text AS avatar_url,
      CASE
        WHEN ec.full_name  ILIKE p_query || '%' THEN 1.0
        WHEN ec.push_name  ILIKE p_query || '%' THEN 0.9
        WHEN ec.phone_number LIKE '%' || p_query || '%' THEN 0.8
        ELSE 0.5
      END::real AS relevance,
      ec.created_at
    FROM zapp.evolution_contacts ec
    WHERE ec.deleted_at IS NULL
      AND (
        ec.full_name    ILIKE '%' || p_query || '%'
        OR ec.push_name ILIKE '%' || p_query || '%'
        OR ec.phone_number LIKE '%' || p_query || '%'
        OR ec.email     ILIKE '%' || p_query || '%'
        OR ec.company   ILIKE '%' || p_query || '%'
      )

    UNION ALL

    -- Stickers
    SELECT
      'sticker'::text, s.id, s.name::text, s.category::text,
      s.image_url::text, 0.6::real, s.created_at
    FROM zapp.stickers s
    WHERE s.is_active = true
      AND (s.name ILIKE '%' || p_query || '%' OR s.category ILIKE '%' || p_query || '%')

  ) combined
  ORDER BY relevance DESC, created_at DESC
  LIMIT p_limit;
END;
$_$;


ALTER FUNCTION zapp.rpc_unified_search(p_query text, p_limit integer) OWNER TO postgres;

