CREATE FUNCTION zapp.rpc_update_email_health_state(p_status text, p_failure_count integer DEFAULT 0, p_metadata jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth', 'extensions'
    AS $$ BEGIN INSERT INTO zapp.email_health_summary (id, status, failure_count, metadata, last_checked_at, updated_at) VALUES ('current', p_status, p_failure_count, p_metadata, now(), now()) ON CONFLICT (id) DO UPDATE SET status=EXCLUDED.status, failure_count=EXCLUDED.failure_count, metadata=COALESCE(EXCLUDED.metadata, email_health_summary.metadata), last_checked_at=now(), updated_at=now(); RETURN jsonb_build_object('success',true,'status',p_status,'failure_count',p_failure_count,'updated_at',now()); END; $$;


ALTER FUNCTION zapp.rpc_update_email_health_state(p_status text, p_failure_count integer, p_metadata jsonb) OWNER TO postgres;

