-- Name: rpc_update_gmail_health_state(text, integer, jsonb); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.rpc_update_gmail_health_state(p_status text, p_failure_count integer, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
BEGIN
    INSERT INTO zapp.gmail_health_summary (id, status, last_validation, failure_count_60m, metadata, updated_at)
    VALUES ('current', p_status, now(), p_failure_count, p_metadata, now())
    ON CONFLICT (id) DO UPDATE SET
        status = EXCLUDED.status,
        last_validation = EXCLUDED.last_validation,
        failure_count_60m = EXCLUDED.failure_count_60m,
        metadata = zapp.gmail_health_summary.metadata || EXCLUDED.metadata,
        updated_at = now();
END;
$$;


