CREATE FUNCTION zapp.rpc_update_incoming_message(p_row_id uuid, p_contact_id uuid, p_content text, p_message_type text, p_media_url text DEFAULT NULL::text, p_media_bucket text DEFAULT NULL::text, p_media_path text DEFAULT NULL::text, p_media_status text DEFAULT NULL::text, p_from_me boolean DEFAULT false, p_direction text DEFAULT 'inbound'::text, p_status text DEFAULT 'received'::text, p_ingest_meta jsonb DEFAULT NULL::jsonb, p_quoted_message_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$ BEGIN UPDATE zapp.evolution_messages SET contact_id=p_contact_id, content=p_content, message_type=p_message_type, media_url=p_media_url, media_bucket=p_media_bucket, media_path=p_media_path, media_status=p_media_status, from_me=p_from_me, direction=p_direction, status=CASE WHEN status IS NOT NULL AND status<>'received' THEN status ELSE p_status END, ingest_meta=coalesce(p_ingest_meta, ingest_meta), media_meta=coalesce(p_ingest_meta, media_meta), quoted_message_id=coalesce(p_quoted_message_id, quoted_message_id), updated_at=now() WHERE id=p_row_id; RETURN jsonb_build_object('ok',true); EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('ok',false,'error',SQLERRM); END; $$;


