-- Name: rpc_update_message_transcription(uuid, text, text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_update_message_transcription(p_message_uuid uuid, p_status text, p_transcription text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'public', 'auth'
    AS $$
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'forbidden: service_role required' USING ERRCODE = '42501';
  END IF;
  UPDATE zapp.evolution_messages
  SET transcription_status = p_status,
      transcription = COALESCE(p_transcription, transcription),
      updated_at = now()
  WHERE id = p_message_uuid;
END;
$$;


