CREATE FUNCTION zapp.rpc_upsert_contact(p_remote_jid text, p_instance text, p_push_name text DEFAULT NULL::text, p_full_name text DEFAULT NULL::text, p_phone_number text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_company text DEFAULT NULL::text, p_role_title text DEFAULT NULL::text, p_lead_status text DEFAULT NULL::text, p_lead_source text DEFAULT NULL::text, p_lead_score integer DEFAULT NULL::integer, p_assigned_to text DEFAULT NULL::text, p_tags text[] DEFAULT NULL::text[], p_notes text DEFAULT NULL::text) RETURNS evo.evolution_contacts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$ DECLARE v_row zapp.evolution_contacts; BEGIN PERFORM zapp.fn_require_app_user(); INSERT INTO zapp.evolution_contacts(remote_jid, instance_name, push_name, full_name, phone_number, email, company, role_title, lead_status, lead_source, lead_score, assigned_to, tags, notes, created_at, updated_at) VALUES (p_remote_jid, p_instance, p_push_name, p_full_name, p_phone_number, p_email, p_company, p_role_title, COALESCE(p_lead_status,'novo'), p_lead_source, COALESCE(p_lead_score,0), p_assigned_to, p_tags, p_notes, now(), now()) ON CONFLICT(remote_jid) DO UPDATE SET push_name = COALESCE(EXCLUDED.push_name, evolution_contacts.push_name), full_name = COALESCE(EXCLUDED.full_name, evolution_contacts.full_name), phone_number = COALESCE(EXCLUDED.phone_number, evolution_contacts.phone_number), email = COALESCE(EXCLUDED.email, evolution_contacts.email), company = COALESCE(EXCLUDED.company, evolution_contacts.company), lead_status = COALESCE(EXCLUDED.lead_status, evolution_contacts.lead_status), lead_score = COALESCE(EXCLUDED.lead_score, evolution_contacts.lead_score), assigned_to = COALESCE(EXCLUDED.assigned_to, evolution_contacts.assigned_to), tags = COALESCE(EXCLUDED.tags, evolution_contacts.tags), notes = COALESCE(EXCLUDED.notes, evolution_contacts.notes), deleted_at = NULL, updated_at = now() RETURNING * INTO v_row; RETURN v_row; END; $$;


ALTER FUNCTION zapp.rpc_upsert_contact(p_remote_jid text, p_instance text, p_push_name text, p_full_name text, p_phone_number text, p_email text, p_company text, p_role_title text, p_lead_status text, p_lead_source text, p_lead_score integer, p_assigned_to text, p_tags text[], p_notes text) OWNER TO postgres;

--
-- Name: rpc_upsert_crm_sync_config(text, boolean, jsonb); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_upsert_crm_sync_config(p_provider text, p_enabled boolean DEFAULT false, p_settings jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_out jsonb;
BEGIN
  IF p_provider IS NULL OR p_provider NOT IN ('bitrix24', 'custom_cloud') THEN
    RAISE EXCEPTION 'provider inválido: % (esperado bitrix24|custom_cloud)', p_provider
      USING ERRCODE = '22023';
  END IF;
  IF p_settings IS NULL OR jsonb_typeof(p_settings) <> 'object' THEN
    RAISE EXCEPTION 'settings deve ser objeto jsonb — secrets NUNCA aqui (use env da edge)'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO zapp.crm_sync_config (provider, enabled, settings, created_by)
  VALUES (p_provider, COALESCE(p_enabled, false), p_settings, auth.uid())
  ON CONFLICT (provider) DO UPDATE
    SET enabled    = EXCLUDED.enabled,
        settings   = EXCLUDED.settings,
        updated_at = now()
  RETURNING jsonb_build_object(
    'provider', provider,
    'enabled',  enabled,
    'settings', settings
  ) INTO v_out;

  RETURN v_out;
END;
$$;


ALTER FUNCTION zapp.rpc_upsert_crm_sync_config(p_provider text, p_enabled boolean, p_settings jsonb) OWNER TO postgres;

--
-- Name: FUNCTION rpc_upsert_crm_sync_config(p_provider text, p_enabled boolean, p_settings jsonb); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.rpc_upsert_crm_sync_config(p_provider text, p_enabled boolean, p_settings jsonb) IS 'Upsert versionado da config de provider CRM. Valida provider (CHECK) e settings (objeto, sem secrets) antes de gravar — F8 (config corrompida).';


--
-- Name: rpc_upsert_deal(text, uuid, uuid, uuid, text, text, numeric, numeric, numeric, jsonb, date, text, integer, text, text[], text, text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_upsert_deal(p_title text, p_id uuid DEFAULT NULL::uuid, p_contact_id uuid DEFAULT NULL::uuid, p_conversation_id uuid DEFAULT NULL::uuid, p_description text DEFAULT NULL::text, p_stage text DEFAULT NULL::text, p_value numeric DEFAULT NULL::numeric, p_cost numeric DEFAULT NULL::numeric, p_discount_percent numeric DEFAULT NULL::numeric, p_products jsonb DEFAULT NULL::jsonb, p_expected_close_date date DEFAULT NULL::date, p_assigned_to text DEFAULT NULL::text, p_probability integer DEFAULT NULL::integer, p_source text DEFAULT NULL::text, p_tags text[] DEFAULT NULL::text[], p_notes text DEFAULT NULL::text, p_instance text DEFAULT 'wpp_pink_test'::text) RETURNS zapp.evolution_deals
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE v_row zapp.evolution_deals;
BEGIN
  PERFORM zapp.fn_require_app_user();
  IF p_id IS NULL THEN
    INSERT INTO zapp.evolution_deals(contact_id, conversation_id, title, description, stage, value, cost, discount_percent, products, expected_close_date, assigned_to, probability, source, tags, notes, instance_name, created_at, updated_at)
    VALUES(p_contact_id, p_conversation_id, p_title, p_description, COALESCE(p_stage,'new'), p_value, p_cost, COALESCE(p_discount_percent,0), COALESCE(p_products,'[]'), p_expected_close_date, p_assigned_to, COALESCE(p_probability,10), p_source, p_tags, p_notes, p_instance, now(), now())
    RETURNING * INTO v_row;
  ELSE
    UPDATE zapp.evolution_deals SET title=COALESCE(p_title,title), description=COALESCE(p_description,description), stage=COALESCE(p_stage,stage), value=COALESCE(p_value,value), assigned_to=COALESCE(p_assigned_to,assigned_to), probability=COALESCE(p_probability,probability), notes=COALESCE(p_notes,notes), updated_at=now()
    WHERE id=p_id RETURNING * INTO v_row;
  END IF;
  RETURN v_row;
END; $$;


