--
-- Name: rpc_upsert_label(uuid, text, text, text, text, text, integer, text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_upsert_label(p_id uuid DEFAULT NULL::uuid, p_name text DEFAULT NULL::text, p_label_id text DEFAULT NULL::text, p_color text DEFAULT NULL::text, p_label_type text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_sort_order integer DEFAULT NULL::integer, p_instance text DEFAULT 'wpp2'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'public'
    AS $$
DECLARE v_id uuid;
BEGIN
  IF p_id IS NOT NULL THEN
    -- UPDATE: apenas colunas que existem na tabela
    UPDATE zapp.evolution_labels
    SET name     = COALESCE(p_name, name),
        color    = COALESCE(p_color, color),
        updated_at = NOW()
    WHERE id = p_id
    RETURNING id INTO v_id;
  ELSE
    -- INSERT: apenas colunas que existem na tabela
    INSERT INTO zapp.evolution_labels(name, label_id, color, instance_name)
    VALUES(
      p_name,
      COALESCE(p_label_id, 'custom_' || gen_random_uuid()::text),
      p_color,
      p_instance
    )
    ON CONFLICT (label_id) DO UPDATE
      SET name       = COALESCE(EXCLUDED.name, evolution_labels.name),
          color      = COALESCE(EXCLUDED.color, evolution_labels.color),
          updated_at = NOW()
    RETURNING id INTO v_id;
  END IF;
  RETURN v_id;
END; $$;


ALTER FUNCTION zapp.rpc_upsert_label(p_id uuid, p_name text, p_label_id text, p_color text, p_label_type text, p_description text, p_sort_order integer, p_instance text) OWNER TO postgres;

