--
-- Name: rpc_upsert_service_channel(uuid, text, text, text, uuid, uuid, text, boolean, integer, boolean, text, text, text); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.rpc_upsert_service_channel(p_id uuid DEFAULT NULL::uuid, p_name text DEFAULT NULL::text, p_display_name text DEFAULT NULL::text, p_channel_type text DEFAULT 'whatsapp'::text, p_whatsapp_connection_id uuid DEFAULT NULL::uuid, p_default_queue_id uuid DEFAULT NULL::uuid, p_routing_mode text DEFAULT 'manual'::text, p_sticky_enabled boolean DEFAULT false, p_sticky_ttl_hours integer DEFAULT 24, p_is_default boolean DEFAULT false, p_description text DEFAULT NULL::text, p_icon text DEFAULT NULL::text, p_color text DEFAULT '#3B82F6'::text) RETURNS zapp.service_channels
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  v_row zapp.service_channels;
  v_old zapp.service_channels;
BEGIN
  IF NOT zapp.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Access denied: admin role required';
  END IF;

  IF p_name IS NULL OR length(trim(p_name)) = 0 THEN
    RAISE EXCEPTION 'name is required';
  END IF;

  -- Se este vai ser default, desmarca os outros do mesmo tipo
  IF p_is_default THEN
    UPDATE zapp.service_channels
       SET is_default = false
     WHERE channel_type = p_channel_type
       AND (p_id IS NULL OR id <> p_id)
       AND is_default = true;
  END IF;

  IF p_id IS NULL THEN
    INSERT INTO zapp.service_channels (
      name, display_name, channel_type, whatsapp_connection_id,
      default_queue_id, routing_mode, sticky_enabled, sticky_ttl_hours,
      is_default, description, icon, color, created_by
    ) VALUES (
      trim(p_name), p_display_name, p_channel_type, p_whatsapp_connection_id,
      p_default_queue_id, p_routing_mode, p_sticky_enabled, p_sticky_ttl_hours,
      p_is_default, p_description, p_icon, p_color, auth.uid()
    )
    RETURNING * INTO v_row;

    INSERT INTO zapp.audit_logs (user_id, action, entity_type, entity_id, details)
    VALUES (auth.uid(), 'service_channel_created', 'service_channels', v_row.id::text,
            jsonb_build_object('name', v_row.name, 'type', v_row.channel_type));
  ELSE
    SELECT * INTO v_old FROM zapp.service_channels WHERE id = p_id;
    IF v_old.id IS NULL THEN RAISE EXCEPTION 'channel not found'; END IF;

    UPDATE zapp.service_channels SET
      name = trim(p_name),
      display_name = p_display_name,
      channel_type = p_channel_type,
      whatsapp_connection_id = p_whatsapp_connection_id,
      default_queue_id = p_default_queue_id,
      routing_mode = p_routing_mode,
      sticky_enabled = p_sticky_enabled,
      sticky_ttl_hours = p_sticky_ttl_hours,
      is_default = p_is_default,
      description = p_description,
      icon = p_icon,
      color = p_color
    WHERE id = p_id
    RETURNING * INTO v_row;

    INSERT INTO zapp.audit_logs (user_id, action, entity_type, entity_id, details)
    VALUES (auth.uid(), 'service_channel_updated', 'service_channels', v_row.id::text,
            jsonb_build_object(
              'before', jsonb_build_object('name', v_old.name, 'queue', v_old.default_queue_id, 'sticky', v_old.sticky_enabled),
              'after',  jsonb_build_object('name', v_row.name, 'queue', v_row.default_queue_id, 'sticky', v_row.sticky_enabled)
            ));
  END IF;

  RETURN v_row;
END;
$$;


ALTER FUNCTION zapp.rpc_upsert_service_channel(p_id uuid, p_name text, p_display_name text, p_channel_type text, p_whatsapp_connection_id uuid, p_default_queue_id uuid, p_routing_mode text, p_sticky_enabled boolean, p_sticky_ttl_hours integer, p_is_default boolean, p_description text, p_icon text, p_color text) OWNER TO supabase_admin;

