CREATE FUNCTION zapp.rpc_upsert_task(p_title text, p_id uuid DEFAULT NULL::uuid, p_description text DEFAULT NULL::text, p_task_type text DEFAULT 'follow_up'::text, p_assigned_to text DEFAULT NULL::text, p_contact_id uuid DEFAULT NULL::uuid, p_deal_id uuid DEFAULT NULL::uuid, p_due_date date DEFAULT NULL::date, p_priority text DEFAULT 'medium'::text, p_tags text[] DEFAULT NULL::text[], p_notes text DEFAULT NULL::text) RETURNS zapp.evolution_tasks
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$ DECLARE v_row evolution_tasks; BEGIN IF p_id IS NULL THEN INSERT INTO evolution_tasks(title,description,task_type,assigned_to,contact_id,deal_id,due_date,priority,tags,notes,status,created_at,updated_at) VALUES(p_title,p_description,p_task_type,p_assigned_to,p_contact_id,p_deal_id,p_due_date,p_priority,p_tags,p_notes,'pending',now(),now()) RETURNING * INTO v_row; ELSE UPDATE evolution_tasks SET title=COALESCE(p_title,title), description=COALESCE(p_description,description), assigned_to=COALESCE(p_assigned_to,assigned_to), due_date=COALESCE(p_due_date,due_date), priority=COALESCE(p_priority,priority), notes=COALESCE(p_notes,notes), updated_at=now() WHERE id=p_id RETURNING * INTO v_row; END IF; RETURN v_row; END; $$;


