--
-- Name: rpc_webhook_health_monitor(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_webhook_health_monitor() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE v_result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'status', 'healthy',
    'events_last_hour', (SELECT count(*) FROM evolution_webhook_events WHERE created_at >= now()-interval '1 hour'),
    'events_last_24h', (SELECT count(*) FROM evolution_webhook_events WHERE created_at >= now()-interval '24 hours'),
    'last_event_at', (SELECT max(created_at) FROM evolution_webhook_events),
    'events_by_instance', (SELECT jsonb_object_agg(instance_name, cnt) FROM (SELECT instance_name, count(*) cnt FROM evolution_webhook_events WHERE created_at >= now()-interval '1 hour' GROUP BY instance_name) t),
    'events_by_type', (SELECT jsonb_object_agg(event_type, cnt) FROM (SELECT event_type, count(*) cnt FROM evolution_webhook_events WHERE created_at >= now()-interval '1 hour' GROUP BY event_type ORDER BY cnt DESC LIMIT 10) t)
  ) INTO v_result;
  RETURN v_result;
END;
$$;


ALTER FUNCTION zapp.rpc_webhook_health_monitor() OWNER TO postgres;

--
-- Name: rpc_zapp_dashboard(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_zapp_dashboard() RETURNS TABLE(metric text, value bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
BEGIN
  PERFORM zapp.fn_require_app_user();

  RETURN QUERY
  SELECT 'total_contacts'::text, count(*)::bigint FROM evolution_contacts WHERE deleted_at IS NULL
  UNION ALL
  SELECT 'total_messages', count(*) FROM evolution_messages WHERE deleted_at IS NULL
  UNION ALL
  SELECT 'total_stickers', count(*) FROM stickers WHERE is_active = true
  UNION ALL
  SELECT 'media_with_url', count(*) FROM evolution_messages WHERE media_url IS NOT NULL AND media_url != '' AND message_type IN ('image','video','audio','ptt','document','sticker') AND deleted_at IS NULL
  UNION ALL
  SELECT 'media_without_url', count(*) FROM evolution_messages WHERE (media_url IS NULL OR media_url = '') AND message_type IN ('image','video','audio','ptt','document','sticker') AND deleted_at IS NULL
  UNION ALL
  SELECT 'media_queue_pending', count(*) FROM media_download_queue WHERE status = 'pending'
  UNION ALL
  SELECT 'media_queue_done', count(*) FROM media_download_queue WHERE status = 'done'
  UNION ALL
  SELECT 'media_queue_failed', count(*) FROM media_download_queue WHERE status = 'failed'
  UNION ALL
  SELECT 'agents_online', count(*) FROM agent_presence WHERE status = 'online'
  UNION ALL
  SELECT 'sla_violations_open', count(*) FROM sla_violations WHERE resolved_at IS NULL
  UNION ALL
  SELECT 'outbound_pending', count(*) FROM outbound_message_queue WHERE status = 'pending'
  UNION ALL
  SELECT 'whatsapp_connections_active', count(*) FROM whatsapp_connections WHERE is_active = true AND status = 'connected';
END;
$$;


ALTER FUNCTION zapp.rpc_zapp_dashboard() OWNER TO postgres;

--
-- Name: rpc_zapp_health_check(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.rpc_zapp_health_check() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'monitoring'
    AS $$
DECLARE
  v_queue_pending bigint;
  v_queue_failed bigint;
  v_queue_stuck bigint;
  v_urls_r2 bigint;
  v_urls_minio bigint;
  v_status text := 'healthy';
  v_alerts jsonb := '[]'::jsonb;
BEGIN
  PERFORM zapp.fn_require_app_user();

  SELECT count(*) INTO v_queue_pending FROM media_download_queue WHERE status='pending';
  SELECT count(*) INTO v_queue_failed FROM media_download_queue WHERE status='failed' AND retry_count >= 3;
  SELECT count(*) INTO v_queue_stuck FROM media_download_queue WHERE status='processing' AND processed_at < now() - interval '10 minutes';
  SELECT count(*) INTO v_urls_r2 FROM evolution_messages WHERE media_url LIKE 'https://zapp-media-proxy%';
  SELECT count(*) INTO v_urls_minio FROM evolution_messages WHERE media_url LIKE 'http://minio%';
  
  IF v_queue_pending > 5000 THEN
    v_alerts := v_alerts || jsonb_build_object('level', 'warning', 'msg', 'Fila de download > 5000 pendentes: ' || v_queue_pending);
    v_status := 'warning';
  END IF;
  IF v_queue_failed > 100 THEN
    v_alerts := v_alerts || jsonb_build_object('level', 'danger', 'msg', 'Downloads falharam definitivamente: ' || v_queue_failed);
    v_status := 'degraded';
  END IF;
  IF v_queue_stuck > 10 THEN
    v_alerts := v_alerts || jsonb_build_object('level', 'warning', 'msg', 'Downloads stuck: ' || v_queue_stuck);
  END IF;
  IF v_urls_minio > 0 THEN
    v_alerts := v_alerts || jsonb_build_object('level', 'info', 'msg', v_urls_minio || ' URLs MinIO internas restantes');
  END IF;
  
  RETURN jsonb_build_object(
    'status', v_status,
    'r2_bucket', 'zapp-whatsapp-media',
    'r2_urls', v_urls_r2,
    'minio_urls', v_urls_minio,
    'queue_pending', v_queue_pending,
    'queue_failed', v_queue_failed,
    'queue_stuck', v_queue_stuck,
    'alerts', v_alerts,
    'checked_at', now()
  );
END;
$$;


ALTER FUNCTION zapp.rpc_zapp_health_check() OWNER TO postgres;

--
-- Name: FUNCTION rpc_zapp_health_check(); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.rpc_zapp_health_check() IS 'Health check global ZAPP WEB com alertas de R2, fila e URLs';


