--
-- Name: run_lgpd_purge(); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.run_lgpd_purge() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  v_count    integer;
  v_job_id   uuid;
  v_start    timestamptz := now();
BEGIN
  -- Log job start
  INSERT INTO zapp.scheduled_job_log (job_name, status)
  VALUES ('lgpd_purge', 'running')
  RETURNING id INTO v_job_id;

  -- Delete contacts deleted > 30 days ago
  DELETE FROM zapp.contacts
  WHERE deleted_at IS NOT NULL
    AND deleted_at < now() - interval '30 days';

  GET DIAGNOSTICS v_count = ROW_COUNT;

  -- Update log
  UPDATE zapp.scheduled_job_log
  SET
    finished_at   = now(),
    status        = 'success',
    rows_affected = v_count
  WHERE id = v_job_id;

  RETURN jsonb_build_object(
    'job_id',       v_job_id,
    'rows_purged',  v_count,
    'duration_ms',  EXTRACT(EPOCH FROM (now() - v_start)) * 1000
  );
EXCEPTION WHEN OTHERS THEN
  UPDATE zapp.scheduled_job_log
  SET finished_at = now(), status = 'error', error_msg = SQLERRM
  WHERE id = v_job_id;
  RAISE;
END;
$$;


ALTER FUNCTION zapp.run_lgpd_purge() OWNER TO supabase_admin;

