--
-- Name: safe_execute_query(text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.safe_execute_query(p_query text) RETURNS SETOF record
    LANGUAGE plpgsql
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$
BEGIN
  RETURN QUERY EXECUTE p_query;
EXCEPTION
  WHEN UNDEFINED_TABLE THEN
    RAISE EXCEPTION 'Resource not found' USING ERRCODE = '42P99';
  WHEN UNDEFINED_COLUMN THEN
    RAISE EXCEPTION 'Resource not found' USING ERRCODE = '42P99';
  WHEN UNDEFINED_FUNCTION THEN
    RAISE EXCEPTION 'Resource not found' USING ERRCODE = '42P99';
  WHEN INSUFFICIENT_PRIVILEGE THEN
    RAISE EXCEPTION 'Access denied' USING ERRCODE = '42501';
  WHEN OTHERS THEN
    RAISE EXCEPTION 'Internal error' USING ERRCODE = '58000';
END;
$$;


ALTER FUNCTION zapp.safe_execute_query(p_query text) OWNER TO postgres;

--
-- Name: sanitize_reset_request(); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.sanitize_reset_request() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'auth'
    AS $$
BEGIN
  -- Authenticated users cannot set their own tokens - only server/service role can
  IF auth.uid() IS NOT NULL THEN
    NEW.reset_token := NULL;
    NEW.token_expires_at := NULL;
    NEW.reviewed_by := NULL;
    NEW.reviewed_at := NULL;
    NEW.rejection_reason := NULL;
    NEW.status := 'pending';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION zapp.sanitize_reset_request() OWNER TO supabase_admin;

--
-- Name: sanitize_user_input(text, integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.sanitize_user_input(p_input text, p_max_length integer DEFAULT 1000) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_sanitized TEXT;
  v_i         INT;
  v_char      CHAR;
BEGIN
  IF p_input IS NULL OR p_input = '' THEN
    RETURN '';
  END IF;

  v_sanitized := normalize_input_nfkc(p_input);
  v_sanitized := decode_html_entities(v_sanitized);

  FOR v_i IN 1 .. LENGTH(v_sanitized) LOOP
    v_char := SUBSTRING(v_sanitized FROM v_i FOR 1);
    IF ASCII(v_char) < 32 AND ASCII(v_char) NOT IN (9, 10, 13) THEN
      RAISE EXCEPTION 'Input contains control characters' USING ERRCODE = '22023';
    END IF;
  END LOOP;

  IF LENGTH(v_sanitized) > p_max_length THEN
    v_sanitized := SUBSTRING(v_sanitized FROM 1 FOR p_max_length);
  END IF;

  RETURN TRIM(v_sanitized);
END;
$$;


ALTER FUNCTION zapp.sanitize_user_input(p_input text, p_max_length integer) OWNER TO postgres;

--
-- Name: search_contacts(text, text, text, text, text, timestamp with time zone, text, text, integer, integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.search_contacts(search_term text DEFAULT ''::text, contact_type_filter text DEFAULT NULL::text, company_filter text DEFAULT NULL::text, job_title_filter text DEFAULT NULL::text, tag_filter text DEFAULT NULL::text, date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, sort_field text DEFAULT 'name'::text, sort_direction text DEFAULT 'asc'::text, page_size integer DEFAULT 50, page_offset integer DEFAULT 0) RETURNS TABLE(id uuid, name text, nickname text, surname text, job_title text, company text, phone text, email text, avatar_url text, tags text[], notes text, contact_type text, created_at timestamp with time zone, updated_at timestamp with time zone, total_count bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_total bigint;
  v_search text;
BEGIN
  v_search := COALESCE(NULLIF(TRIM(search_term), ''), NULL);
  
  -- Get total count first
  SELECT COUNT(*) INTO v_total
  FROM zapp.contacts c
  WHERE
    (v_search IS NULL OR (
      c.name ILIKE '%' || v_search || '%' OR
      c.nickname ILIKE '%' || v_search || '%' OR
      c.surname ILIKE '%' || v_search || '%' OR
      c.phone ILIKE '%' || v_search || '%' OR
      c.email ILIKE '%' || v_search || '%' OR
      c.company ILIKE '%' || v_search || '%' OR
      c.job_title ILIKE '%' || v_search || '%'
    ))
    AND (contact_type_filter IS NULL OR c.contact_type = contact_type_filter)
    AND (company_filter IS NULL OR c.company = company_filter)
    AND (job_title_filter IS NULL OR c.job_title = job_title_filter)
    AND (tag_filter IS NULL OR tag_filter = ANY(c.tags))
    AND (date_from IS NULL OR c.created_at >= date_from);

  RETURN QUERY
  SELECT
    c.id, c.name::text, c.nickname::text, c.surname::text, c.job_title::text, c.company::text,
    c.phone::text, c.email::text, c.avatar_url::text, c.tags, c.notes::text, c.contact_type::text,
    c.created_at, c.updated_at,
    v_total AS total_count
  FROM zapp.contacts c
  WHERE
    (v_search IS NULL OR (
      c.name ILIKE '%' || v_search || '%' OR
      c.nickname ILIKE '%' || v_search || '%' OR
      c.surname ILIKE '%' || v_search || '%' OR
      c.phone ILIKE '%' || v_search || '%' OR
      c.email ILIKE '%' || v_search || '%' OR
      c.company ILIKE '%' || v_search || '%' OR
      c.job_title ILIKE '%' || v_search || '%'
    ))
    AND (contact_type_filter IS NULL OR c.contact_type = contact_type_filter)
    AND (company_filter IS NULL OR c.company = company_filter)
    AND (job_title_filter IS NULL OR c.job_title = job_title_filter)
    AND (tag_filter IS NULL OR tag_filter = ANY(c.tags))
    AND (date_from IS NULL OR c.created_at >= date_from)
  ORDER BY
    CASE WHEN sort_field = 'name' AND sort_direction = 'asc' THEN c.name END ASC,
    CASE WHEN sort_field = 'name' AND sort_direction = 'desc' THEN c.name END DESC,
    CASE WHEN sort_field = 'created_at' AND sort_direction = 'asc' THEN c.created_at END ASC,
    CASE WHEN sort_field = 'created_at' AND sort_direction = 'desc' THEN c.created_at END DESC,
    CASE WHEN sort_field = 'updated_at' AND sort_direction = 'desc' THEN c.updated_at END DESC,
    c.name ASC
  LIMIT page_size
  OFFSET page_offset;
END;
$$;


ALTER FUNCTION zapp.search_contacts(search_term text, contact_type_filter text, company_filter text, job_title_filter text, tag_filter text, date_from timestamp with time zone, sort_field text, sort_direction text, page_size integer, page_offset integer) OWNER TO postgres;

--
-- Name: search_contacts_advanced(text, text, text, text, text, boolean, boolean, text, integer, integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.search_contacts_advanced(p_search text DEFAULT NULL::text, p_vendedor text DEFAULT NULL::text, p_ramo text DEFAULT NULL::text, p_rfm_segment text DEFAULT NULL::text, p_estado text DEFAULT NULL::text, p_cliente_ativado boolean DEFAULT NULL::boolean, p_ja_comprou boolean DEFAULT NULL::boolean, p_sort_by text DEFAULT 'last_message_at'::text, p_page integer DEFAULT 1, p_page_size integer DEFAULT 25) RETURNS TABLE(id uuid, remote_jid text, full_name text, push_name text, phone_number text, email text, company text, lead_status text, assigned_to text, tags text[], total_purchases integer, last_message_at timestamp with time zone, total_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
BEGIN
  PERFORM zapp.fn_require_app_user();
  RETURN QUERY
SELECT ct.id, ct.remote_jid::text, ct.full_name::text, ct.push_name::text, ct.phone_number::text, ct.email::text, ct.company::text, ct.lead_status::text, ct.assigned_to::text, ct.tags, ct.total_purchases::int, ct.last_message_at, count(*) OVER() AS total_count
FROM zapp.evolution_contacts ct
WHERE ct.deleted_at IS NULL AND (p_search IS NULL OR ct.full_name ILIKE '%'||p_search||'%' OR ct.push_name ILIKE '%'||p_search||'%' OR ct.phone_number ILIKE '%'||p_search||'%' OR ct.company ILIKE '%'||p_search||'%') AND (p_vendedor IS NULL OR ct.assigned_to = p_vendedor) AND (p_ramo IS NULL OR ct.company ILIKE '%'||p_ramo||'%') AND (p_rfm_segment IS NULL OR ct.lead_status = p_rfm_segment) AND (p_cliente_ativado IS NULL OR (ct.lead_status='cliente') = p_cliente_ativado) AND (p_ja_comprou IS NULL OR (coalesce(ct.total_purchases,0)>0) = p_ja_comprou)
ORDER BY CASE WHEN p_sort_by='full_name' THEN ct.full_name END ASC NULLS LAST, CASE WHEN p_sort_by='created_at' THEN ct.created_at END DESC NULLS LAST, ct.last_message_at DESC NULLS LAST
LIMIT greatest(p_page_size,1) OFFSET greatest(p_page-1,0)*greatest(p_page_size,1);
END;
$$;


ALTER FUNCTION zapp.search_contacts_advanced(p_search text, p_vendedor text, p_ramo text, p_rfm_segment text, p_estado text, p_cliente_ativado boolean, p_ja_comprou boolean, p_sort_by text, p_page integer, p_page_size integer) OWNER TO postgres;

--
-- Name: FUNCTION search_contacts_advanced(p_search text, p_vendedor text, p_ramo text, p_rfm_segment text, p_estado text, p_cliente_ativado boolean, p_ja_comprou boolean, p_sort_by text, p_page integer, p_page_size integer); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.search_contacts_advanced(p_search text, p_vendedor text, p_ramo text, p_rfm_segment text, p_estado text, p_cliente_ativado boolean, p_ja_comprou boolean, p_sort_by text, p_page integer, p_page_size integer) IS 'FATOR X v6.1.0: busca avancada paginada em evolution_contacts. Mapeia p_vendedor=assigned_to, p_ramo=company, p_rfm_segment=lead_status; p_estado ignorado (campo inexistente no dominio evo).';


--
-- Name: search_contacts_cursor(text, text, text, text, text, timestamp with time zone, text, text, integer, uuid); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.search_contacts_cursor(search_term text DEFAULT ''::text, sort_field text DEFAULT 'name'::text, sort_direction text DEFAULT 'asc'::text, contact_type_filter text DEFAULT NULL::text, company_filter text DEFAULT NULL::text, date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, job_title_filter text DEFAULT NULL::text, tag_filter text DEFAULT NULL::text, page_size integer DEFAULT 50, cursor_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, name text, nickname text, surname text, job_title text, company text, phone text, email text, avatar_url text, tags text[], notes text, contact_type text, created_at timestamp with time zone, updated_at timestamp with time zone, total_count bigint)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'zapp'
    AS $_$
DECLARE
  v_query       text;
  v_count_where text;
  v_sort_dir    text;
  v_sort_expr   text;
  v_where       text;
  v_search_pattern text;
BEGIN
  v_sort_dir := UPPER(COALESCE(sort_direction, 'ASC'));
  IF v_sort_dir NOT IN ('ASC', 'DESC') THEN
    v_sort_dir := 'ASC';
  END IF;

  v_sort_expr := CASE
    WHEN sort_field = 'created_at' THEN 'c.created_at ' || v_sort_dir || ', c.id ' || v_sort_dir
    WHEN sort_field = 'updated_at' THEN 'c.updated_at ' || v_sort_dir || ', c.id ' || v_sort_dir
    ELSE                                 'c.name '       || v_sort_dir || ', c.id ' || v_sort_dir
  END;

  v_where := 'WHERE 1=1';

  -- F5-22 + F5-23: busca ampliada com normalização de telefone e mais campos
  IF search_term != '' THEN
    v_search_pattern := '%' || search_term || '%';
    v_where := v_where ||
      ' AND (c.name ILIKE $1 OR c.email ILIKE $1 OR c.phone ILIKE $1' ||
      ' OR c.company ILIKE $1 OR c.job_title ILIKE $1 OR c.nickname ILIKE $1' ||
      ' OR regexp_replace(c.phone, ''[^0-9]'', '''', ''g'') ILIKE regexp_replace($1, ''[^0-9]'', '''', ''g''))';
  END IF;
  IF contact_type_filter IS NOT NULL THEN v_where := v_where || ' AND c.contact_type = $2';    END IF;
  IF company_filter      IS NOT NULL THEN v_where := v_where || ' AND c.company ILIKE $3';     END IF;
  IF job_title_filter    IS NOT NULL THEN v_where := v_where || ' AND c.job_title ILIKE $4';   END IF;
  IF tag_filter          IS NOT NULL THEN v_where := v_where || ' AND $5 = ANY(c.tags)';       END IF;
  IF date_from           IS NOT NULL THEN v_where := v_where || ' AND c.created_at >= $6';     END IF;

  v_count_where := v_where;

  IF cursor_id IS NOT NULL THEN
    IF sort_field = 'created_at' THEN
      IF v_sort_dir = 'ASC' THEN
        v_where := v_where ||
          ' AND (c.created_at, c.id) > (SELECT cc.created_at, cc.id FROM zapp.contacts cc WHERE cc.id = $7)';
      ELSE
        v_where := v_where ||
          ' AND (c.created_at, c.id) < (SELECT cc.created_at, cc.id FROM zapp.contacts cc WHERE cc.id = $7)';
      END IF;
    ELSIF sort_field = 'updated_at' THEN
      IF v_sort_dir = 'ASC' THEN
        v_where := v_where ||
          ' AND (c.updated_at, c.id) > (SELECT cc.updated_at, cc.id FROM zapp.contacts cc WHERE cc.id = $7)';
      ELSE
        v_where := v_where ||
          ' AND (c.updated_at, c.id) < (SELECT cc.updated_at, cc.id FROM zapp.contacts cc WHERE cc.id = $7)';
      END IF;
    ELSE
      IF v_sort_dir = 'ASC' THEN
        v_where := v_where ||
          ' AND (c.name, c.id::text) > (SELECT cc.name, cc.id::text FROM zapp.contacts cc WHERE cc.id = $7)';
      ELSE
        v_where := v_where ||
          ' AND (c.name, c.id::text) < (SELECT cc.name, cc.id::text FROM zapp.contacts cc WHERE cc.id = $7)';
      END IF;
    END IF;
  END IF;

  v_query :=
    'WITH total AS (
       SELECT COUNT(*)::bigint AS cnt FROM zapp.contacts c ' || v_count_where || '
     )
     SELECT c.id, c.name::text, c.nickname, c.surname, c.job_title,
            c.company::text, c.phone, c.email::text, c.avatar_url,
            c.tags, c.notes, c.contact_type, c.created_at, c.updated_at,
            t.cnt AS total_count
     FROM zapp.contacts c, total t
     ' || v_where || '
     ORDER BY ' || v_sort_expr || '
     LIMIT $8';

  RETURN QUERY EXECUTE v_query
    USING '%' || search_term || '%',
          contact_type_filter,
          '%' || COALESCE(company_filter,   '') || '%',
          '%' || COALESCE(job_title_filter, '') || '%',
          tag_filter,
          date_from,
          cursor_id,
          page_size;
END;
$_$;


ALTER FUNCTION zapp.search_contacts_cursor(search_term text, sort_field text, sort_direction text, contact_type_filter text, company_filter text, date_from timestamp with time zone, job_title_filter text, tag_filter text, page_size integer, cursor_id uuid) OWNER TO postgres;

--
-- Name: search_knowledge_base(text, integer); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.search_knowledge_base(search_query text, max_results integer DEFAULT 5) RETURNS TABLE(id uuid, title text, content text, category text, tags text, rank real)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$ SELECT a.id, a.title, a.content, a.category, a.tags, CASE WHEN a.title ILIKE '%' || search_query || '%' THEN 1.0 WHEN a.content ILIKE '%' || search_query || '%' THEN 0.5 ELSE 0.0 END::real AS rank FROM zapp.knowledge_base_articles a WHERE a.is_published = true AND (a.title ILIKE '%' || search_query || '%' OR a.content ILIKE '%' || search_query || '%') ORDER BY rank DESC LIMIT max_results; $$;


ALTER FUNCTION zapp.search_knowledge_base(search_query text, max_results integer) OWNER TO supabase_admin;

--
-- Name: send_message_v2(text, text, text, text, text, text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.send_message_v2(p_remote_jid text, p_content text, p_message_type text DEFAULT 'text'::text, p_media_url text DEFAULT NULL::text, p_media_mimetype text DEFAULT NULL::text, p_instance text DEFAULT 'wpp_pink_test'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE v_contact_id uuid; v_queue_id uuid; v_conn_status text;
BEGIN
  IF p_remote_jid IS NULL OR (COALESCE(LENGTH(TRIM(p_content)),0)=0 AND p_media_url IS NULL) THEN
    RETURN jsonb_build_object('success',false,'message','remote_jid e content/media sao obrigatorios');
  END IF;

  SELECT id INTO v_contact_id
  FROM zapp.evolution_contacts
  WHERE remote_jid=p_remote_jid AND instance_name=p_instance AND deleted_at IS NULL LIMIT 1;

  SELECT status INTO v_conn_status
  FROM zapp.whatsapp_connections WHERE instance_name=p_instance;

  INSERT INTO zapp.outbound_message_queue (
    remote_jid, instance_name, message_type, content, media_url,
    media_mime_type, status, contact_id, created_by, metadata
  ) VALUES (
    p_remote_jid, p_instance, COALESCE(p_message_type,'text'), p_content,
    p_media_url, p_media_mimetype, 'pending', v_contact_id, auth.uid(),
    jsonb_build_object('source','send_message_v2',
      'connection_status_at_enqueue', v_conn_status)
  ) RETURNING id INTO v_queue_id;

  RETURN jsonb_build_object(
    'success', true,
    'message', CASE WHEN v_conn_status='connected'
      THEN 'Mensagem enfileirada para envio'
      ELSE FORMAT('Mensagem enfileirada; instancia %s esta %s - sera enviada ao reconectar',
                  p_instance, COALESCE(v_conn_status,'desconhecida'))
    END,
    'queue_id', v_queue_id,
    'instance_status', v_conn_status
  );
END;
$$;


ALTER FUNCTION zapp.send_message_v2(p_remote_jid text, p_content text, p_message_type text, p_media_url text, p_media_mimetype text, p_instance text) OWNER TO postgres;

--
-- Name: FUNCTION send_message_v2(p_remote_jid text, p_content text, p_message_type text, p_media_url text, p_media_mimetype text, p_instance text); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.send_message_v2(p_remote_jid text, p_content text, p_message_type text, p_media_url text, p_media_mimetype text, p_instance text) IS 'FATOR X v6.1.0: enfileira envio em zapp.outbound_message_queue (worker/edge consome). Retorna {success,message,queue_id,instance_status}.';


--
-- Name: sessions_list(uuid, boolean); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.sessions_list(p_target_user_id uuid, p_admin boolean DEFAULT false) RETURNS TABLE(id uuid, user_id uuid, created_at timestamp with time zone, updated_at timestamp with time zone, last_active timestamp with time zone, user_agent text, ip text, aal text, tag text, factor_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'permission denied for sessions_list' USING ERRCODE = '42501';
  END IF;
  IF NOT p_admin AND v_caller <> p_target_user_id THEN
    RAISE EXCEPTION 'permission denied for sessions_list' USING ERRCODE = '42501';
  END IF;
  IF p_admin AND NOT zapp.is_admin_or_supervisor(v_caller) THEN
    RAISE EXCEPTION 'permission denied for sessions_list' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT s.id,
         s.user_id,
         s.created_at,
         s.updated_at,
         COALESCE(s.refreshed_at, s.created_at)::timestamptz AS last_active,
         s.user_agent,
         s.ip::text AS ip,
         s.aal::text AS aal,
         s.tag,
         s.factor_id
    FROM auth.sessions s
   WHERE s.user_id = p_target_user_id
   ORDER BY last_active DESC NULLS LAST;
END;
$$;


ALTER FUNCTION zapp.sessions_list(p_target_user_id uuid, p_admin boolean) OWNER TO postgres;

--
-- Name: sessions_owner(uuid); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.sessions_owner(p_session_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_owner uuid;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'permission denied for sessions_owner' USING ERRCODE = '42501';
  END IF;

  SELECT s.user_id INTO v_owner
    FROM auth.sessions s
   WHERE s.id = p_session_id;

  RETURN v_owner; -- NULL = inexistente (idempotente)
END;
$$;


ALTER FUNCTION zapp.sessions_owner(p_session_id uuid) OWNER TO postgres;

--
-- Name: sessions_revoke(uuid, uuid[], boolean); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.sessions_revoke(p_target_user_id uuid, p_session_ids uuid[], p_admin boolean DEFAULT false) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_revoked int := 0;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'permission denied for sessions_revoke' USING ERRCODE = '42501';
  END IF;
  IF NOT p_admin AND v_caller <> p_target_user_id THEN
    RAISE EXCEPTION 'permission denied for sessions_revoke' USING ERRCODE = '42501';
  END IF;
  IF p_admin AND NOT zapp.is_admin_or_supervisor(v_caller) THEN
    RAISE EXCEPTION 'permission denied for sessions_revoke' USING ERRCODE = '42501';
  END IF;
  IF p_session_ids IS NULL OR cardinality(p_session_ids) = 0 THEN
    RETURN 0;
  END IF;

  UPDATE auth.refresh_tokens rt
     SET revoked = true, updated_at = now()
   WHERE rt.session_id = ANY(p_session_ids)
     AND rt.user_id = p_target_user_id
     AND rt.revoked = false;

  DELETE FROM auth.sessions s
   WHERE s.user_id = p_target_user_id
     AND s.id = ANY(p_session_ids);

  GET DIAGNOSTICS v_revoked = ROW_COUNT;
  RETURN v_revoked;
END;
$$;


ALTER FUNCTION zapp.sessions_revoke(p_target_user_id uuid, p_session_ids uuid[], p_admin boolean) OWNER TO postgres;

