--
-- Name: sync_contact_intelligence(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.sync_contact_intelligence() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
BEGIN
  -- INSERT ou UPDATE relevante (lead_score, total_purchases, lead_status mudou)
  IF TG_OP = 'DELETE' THEN
    -- ON DELETE CASCADE ja remove; nada a fazer
    RETURN OLD;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF NEW.lead_score      IS NOT DISTINCT FROM OLD.lead_score
    AND NEW.total_purchases IS NOT DISTINCT FROM OLD.total_purchases
    AND NEW.lead_status     IS NOT DISTINCT FROM OLD.lead_status
    AND NEW.last_message_at IS NOT DISTINCT FROM OLD.last_message_at
    AND NEW.total_messages  IS NOT DISTINCT FROM OLD.total_messages
    AND NEW.deleted_at      IS NOT DISTINCT FROM OLD.deleted_at
    THEN
      RETURN NEW;
    END IF;
  END IF;

  IF NEW.deleted_at IS NOT NULL THEN
    -- Contato soft-deleted -> remove da CI (via RPC de contrato)
    PERFORM zapp.rpc_purge_contact_intelligence(NEW.id);
    RETURN NEW;
  END IF;

  -- Executa upsert assincrono (pos-commit) via trigger AFTER
  PERFORM zapp.upsert_contact_intelligence(NEW.id);
  RETURN NEW;
END;
$$;


ALTER FUNCTION zapp.sync_contact_intelligence() OWNER TO postgres;

--
-- Name: FUNCTION sync_contact_intelligence(); Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON FUNCTION zapp.sync_contact_intelligence() IS 'Sincroniza dados de inteligência de contato (score, segmento e metadados) entre as tabelas do schema.';


--
-- Name: sync_interaction_from_zapp(text, text, text, text, text, text, text, integer, integer, text, text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.sync_interaction_from_zapp(p_phone text, p_channel text DEFAULT 'whatsapp'::text, p_direction text DEFAULT 'outbound'::text, p_assunto text DEFAULT NULL::text, p_resumo text DEFAULT NULL::text, p_conteudo text DEFAULT NULL::text, p_sentiment text DEFAULT 'neutro'::text, p_message_count integer DEFAULT 1, p_duration_seconds integer DEFAULT NULL::integer, p_agent_name text DEFAULT NULL::text, p_zapp_conversation_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$ DECLARE v_contact_id uuid; v_audit_id uuid; BEGIN SELECT id INTO v_contact_id FROM zapp.evolution_contacts WHERE regexp_replace(coalesce(phone_number,''),'\D','','g') = regexp_replace(coalesce(p_phone,''),'\D','','g') AND deleted_at IS NULL ORDER BY last_message_at DESC NULLS LAST LIMIT 1; INSERT INTO zapp.evolution_audit_log (action, entity_type, entity_id, performed_by, performed_by_type, metadata, created_at) VALUES ('interaction_sync','contact', v_contact_id, coalesce(p_agent_name, auth.uid()::text, 'system'), 'service', jsonb_build_object('phone',p_phone,'channel',p_channel,'direction',p_direction,'assunto',p_assunto,'resumo',p_resumo,'conteudo',left(p_conteudo,2000),'sentiment',p_sentiment,'message_count',p_message_count,'duration_seconds',p_duration_seconds,'zapp_conversation_id',p_zapp_conversation_id), now()) RETURNING id INTO v_audit_id; RETURN jsonb_build_object('success', true, 'contact_id', v_contact_id, 'audit_id', v_audit_id, 'matched', v_contact_id IS NOT NULL); END $$;


ALTER FUNCTION zapp.sync_interaction_from_zapp(p_phone text, p_channel text, p_direction text, p_assunto text, p_resumo text, p_conteudo text, p_sentiment text, p_message_count integer, p_duration_seconds integer, p_agent_name text, p_zapp_conversation_id text) OWNER TO postgres;

