--
-- Name: sync_tag_use_counts(); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.sync_tag_use_counts() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE v_updated int := 0; v_tag record;
BEGIN
  FOR v_tag IN SELECT name FROM zapp.evolution_tags LOOP
    UPDATE zapp.evolution_tags t
    SET use_count = (
      SELECT COUNT(*) FROM zapp.evolution_contacts c
      WHERE v_tag.name = ANY(c.tags) AND c.deleted_at IS NULL
    )
    WHERE t.name = v_tag.name;
    v_updated := v_updated + 1;
  END LOOP;
  RETURN v_updated;
END;
$$;


