-- Name: trg_process_webhook_contacts(); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.trg_process_webhook_contacts() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  v_data jsonb; v_contacts jsonb; v_c jsonb;
  v_jid text; v_name text; v_phone text;
BEGIN
  IF NEW.event_type NOT IN (
    'contacts.upsert','CONTACTS_UPSERT','contacts.update','CONTACTS_UPDATE',
    'contacts.set','CONTACTS_SET'
  ) THEN RETURN NEW; END IF;

  v_data := COALESCE(NEW.payload->'data', NEW.payload);
  IF jsonb_typeof(v_data) = 'array' THEN v_contacts := v_data;
  ELSIF v_data ? 'contacts' AND jsonb_typeof(v_data->'contacts') = 'array' THEN v_contacts := v_data->'contacts';
  ELSE v_contacts := jsonb_build_array(v_data); END IF;

  FOR v_c IN SELECT * FROM jsonb_array_elements(v_contacts)
  LOOP
    v_jid := COALESCE(v_c->>'id', v_c->>'remoteJid');
    IF v_jid IS NULL THEN CONTINUE; END IF;
    v_name := COALESCE(v_c->>'pushName', v_c->>'name', v_c->>'notify');
    v_phone := replace(replace(v_jid, '@s.whatsapp.net', ''), '@c.us', '');
    INSERT INTO evolution_contacts (remote_jid, push_name, phone_number, instance_name)
    VALUES (v_jid, v_name, v_phone, NEW.instance_name)
    ON CONFLICT (remote_jid) DO UPDATE SET
      push_name = COALESCE(EXCLUDED.push_name, evolution_contacts.push_name),
      updated_at = now();
  END LOOP;
  NEW.processed := true; NEW.processed_at := now();
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'trg_contacts: %', SQLERRM;
  RETURN NEW;
END;
$$;


