--
-- Name: trg_process_webhook_message(); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.trg_process_webhook_message() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE v_result jsonb; v_data jsonb; v_key jsonb;
BEGIN
  -- So processar messages.upsert e SEND_MESSAGE
  IF NEW.event_type NOT IN ('messages.upsert','MESSAGES_UPSERT','SEND_MESSAGE') THEN
    RETURN NEW;
  END IF;

  -- Extrair payload (EVO API v4 manda em data, v2 manda direto)
  v_data := COALESCE(NEW.payload->'data', NEW.payload);
  
  -- Se for array, pegar primeiro
  IF jsonb_typeof(v_data) = 'array' THEN v_data := v_data->0; END IF;
  
  v_key := COALESCE(v_data->'key', '{}'::jsonb);
  
  -- Pular se nao tem remoteJid ou id
  IF v_key->>'remoteJid' IS NULL OR v_key->>'id' IS NULL THEN
    RETURN NEW;
  END IF;

  -- Chamar pipeline
  BEGIN
    v_result := fn_process_whatsapp_message(v_data, NEW.instance_name);
    NEW.processed := true;
    NEW.processed_at := now();
  EXCEPTION WHEN OTHERS THEN
    NEW.error_message := SQLERRM;
    NEW.processed := false;
  END;

  RETURN NEW;
END;
$$;


ALTER FUNCTION zapp.trg_process_webhook_message() OWNER TO postgres;

