--
-- Name: trg_process_webhook_msg_update(); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.trg_process_webhook_msg_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE v_data jsonb; v_msg_id text; v_status text; v_raw text;
BEGIN
  IF NEW.event_type NOT IN ('messages.update','MESSAGES_UPDATE','messages.edited','MESSAGES_EDITED') THEN RETURN NEW; END IF;
  v_data := COALESCE(NEW.payload->'data', NEW.payload);
  v_msg_id := COALESCE(v_data->>'keyId', v_data->'key'->>'id');
  v_raw := v_data->>'status';
  IF v_msg_id IS NULL THEN RETURN NEW; END IF;
  IF v_raw IS NOT NULL THEN
    v_status := CASE upper(v_raw)
      WHEN '0' THEN 'failed' WHEN 'ERROR' THEN 'failed'
      WHEN '2' THEN 'sent' WHEN 'SERVER_ACK' THEN 'sent'
      WHEN '3' THEN 'delivered' WHEN 'DELIVERY_ACK' THEN 'delivered'
      WHEN '4' THEN 'read' WHEN 'READ' THEN 'read'
      WHEN '5' THEN 'read' ELSE lower(v_raw)
    END;
    UPDATE evolution_messages SET status = v_status, status_at = now() WHERE message_id = v_msg_id;
  END IF;
  NEW.processed := true; NEW.processed_at := now();
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'trg_msg_update: %', SQLERRM;
  RETURN NEW;
END;
$$;


ALTER FUNCTION zapp.trg_process_webhook_msg_update() OWNER TO supabase_admin;

