--
-- Name: update_contact_versioned(uuid, integer, jsonb); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.update_contact_versioned(p_contact_id uuid, p_expected_version integer, p_updates jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  v_current_version integer;
  v_result          jsonb;
BEGIN
  -- Guard de visibilidade (padrão do repo — ver add_contact_note): usuário só
  -- edita contatos visíveis a ele; admins/supervisores passam direto.
  IF NOT (zapp.is_admin_or_supervisor()
          OR (p_contact_id IS NOT NULL AND zapp.is_contact_visible_to_user(p_contact_id, auth.uid()))) THEN
    RAISE EXCEPTION 'forbidden: contato nao visivel' USING ERRCODE = '42501';
  END IF;

  -- Read current version from the BASE table (zapp.evolution_contacts) — the
  -- zapp.contacts VIEW does not expose version/updated_by.
  SELECT ec.version INTO v_current_version
  FROM zapp.evolution_contacts ec
  WHERE ec.id = p_contact_id
    AND ec.deleted_at IS NULL
  FOR UPDATE;  -- row-level lock

  IF NOT FOUND THEN
    RAISE EXCEPTION 'CONTACT_NOT_FOUND: Contact % not found', p_contact_id;
  END IF;

  IF v_current_version IS DISTINCT FROM p_expected_version THEN
    SELECT jsonb_build_object(
      'error',            'CONFLICT',
      'message',          'Este contato foi modificado por outro usuário. Recarregue e tente novamente.',
      'current_version',  ec.version,
      'your_version',     p_expected_version,
      'last_updated_at',  ec.updated_at
    ) INTO v_result
    FROM zapp.evolution_contacts ec WHERE ec.id = p_contact_id;

    RETURN v_result;
  END IF;

  -- Versions match — update via the view so the INSTEAD OF trigger
  -- (fn_contacts_view_update_handler) keeps zapp.evolution_contacts in sync.
  UPDATE zapp.contacts
  SET
    name    = COALESCE((p_updates->>'name')::text,    name),
    phone   = COALESCE((p_updates->>'phone')::text,   phone),
    email   = COALESCE((p_updates->>'email')::text,   email),
    company = COALESCE((p_updates->>'company')::text, company),
    notes   = COALESCE((p_updates->>'notes')::text,   notes),
    tags    = CASE WHEN p_updates ? 'tags' THEN
                ARRAY(SELECT jsonb_array_elements_text(p_updates->'tags'))
              ELSE tags END,
    custom_fields = CASE WHEN p_updates ? 'custom_fields' THEN
                      p_updates->'custom_fields'
                    ELSE custom_fields END
  WHERE id = p_contact_id;

  UPDATE zapp.evolution_contacts
  SET version = version + 1
  WHERE id = p_contact_id;

  SELECT jsonb_build_object(
    'success', true,
    'version', ec.version,
    'updated_at', ec.updated_at
  ) INTO v_result
  FROM zapp.evolution_contacts ec WHERE ec.id = p_contact_id;

  RETURN v_result;
END;
$$;


ALTER FUNCTION zapp.update_contact_versioned(p_contact_id uuid, p_expected_version integer, p_updates jsonb) OWNER TO supabase_admin;

