--
-- Name: upsert_contact_intelligence(uuid); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.upsert_contact_intelligence(p_contact_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $_$
DECLARE
  v_ec     zapp.evolution_contacts%ROWTYPE;
  v_msgs   int := 0;
  v_inb    int := 0;
  v_out    int := 0;
  v_last   timestamptz;
  v_eng    numeric(5,2);
  v_risk   text;
  v_disc   text := 'C';
  v_days   int;
  v_ratio  numeric(5,2) := 0;
  v_phone  text;
BEGIN
  SELECT * INTO v_ec FROM zapp.evolution_contacts WHERE id = p_contact_id LIMIT 1;
  IF NOT FOUND THEN RETURN; END IF;

  SELECT count(*), count(*) FILTER (WHERE NOT from_me), count(*) FILTER (WHERE from_me), max(created_at)
  INTO v_msgs, v_inb, v_out, v_last
  FROM zapp.evolution_messages_wpp2 m
  WHERE m.deleted_at IS NULL AND m.contact_id = p_contact_id;

  IF COALESCE(v_ec.total_messages, 0) > v_msgs THEN v_msgs := v_ec.total_messages; END IF;

  v_days := CASE WHEN v_last IS NOT NULL THEN EXTRACT(DAY FROM (now() - v_last))::int
    WHEN v_ec.last_message_at IS NOT NULL THEN EXTRACT(DAY FROM (now() - v_ec.last_message_at))::int
    ELSE NULL END;

  v_eng := LEAST(100, GREATEST(0,
    COALESCE(v_ec.lead_score, 0)::numeric * 0.5
    + LEAST(50, v_msgs * 0.5)
    - COALESCE(v_days, 0) * 0.3));

  v_risk := CASE
    WHEN v_eng < 20 OR COALESCE(v_days, 999) > 60 THEN 'high'
    WHEN v_eng < 50 OR COALESCE(v_days, 999) > 30 THEN 'medium'
    ELSE 'low' END;

  v_disc := CASE
    WHEN v_ec.lead_score >= 70 THEN 'D'
    WHEN v_inb > v_out AND v_msgs > 5 THEN 'I'
    WHEN v_inb > v_out * 1.5 THEN 'S'
    ELSE 'C' END;

  IF v_msgs > 0 THEN
    v_ratio := round((v_inb::numeric / v_msgs) * 100, 2);
  END IF;

  -- ════════════════════════════════════════════════════════════
  -- LID-FIX-01 (2026-08-11): Guard anti-LID-as-phone no campo phone
  -- phone_number NULL após limpeza → não usar split_part do remote_jid
  -- split_part fallback só se o local part for telefone real (≤13 dígitos)
  -- ════════════════════════════════════════════════════════════
  v_phone := CASE
    WHEN v_ec.phone_number IS NOT NULL
         AND v_ec.phone_number ~ '^[0-9]+$'
         AND length(v_ec.phone_number) <= 13
    THEN v_ec.phone_number
    WHEN length(split_part(v_ec.remote_jid::text, '@', 1)) <= 13
         AND split_part(v_ec.remote_jid::text, '@', 1) ~ '^[0-9]+$'
    THEN split_part(v_ec.remote_jid::text, '@', 1)
    ELSE NULL   -- LID-only: sem telefone real disponível ainda
  END;
  -- ════════════════════════════════════════════════════════════

  INSERT INTO zapp.contact_intelligence
    (contact_id, sentiment, engagement_score, predicted_value, risk_level,
     phone, contact_name, lead_status, total_messages, days_since_contact,
     disc_profile, inbound_ratio, created_at, updated_at)
  VALUES (
    p_contact_id,
    CASE WHEN v_inb > v_out * 2 THEN 'positive'
         WHEN v_out > v_inb * 3 THEN 'negative'
         ELSE 'neutral' END,
    v_eng, COALESCE(v_ec.total_purchases, 0), v_risk,
    v_phone,
    COALESCE(v_ec.full_name, v_ec.push_name),
    v_ec.lead_status, v_msgs, v_days, v_disc, v_ratio,
    now(), now()
  )
  ON CONFLICT (contact_id) DO UPDATE SET
    sentiment          = EXCLUDED.sentiment,
    engagement_score   = EXCLUDED.engagement_score,
    predicted_value    = EXCLUDED.predicted_value,
    risk_level         = EXCLUDED.risk_level,
    phone              = EXCLUDED.phone,
    contact_name       = EXCLUDED.contact_name,
    lead_status        = EXCLUDED.lead_status,
    total_messages     = EXCLUDED.total_messages,
    days_since_contact = EXCLUDED.days_since_contact,
    disc_profile       = EXCLUDED.disc_profile,
    inbound_ratio      = EXCLUDED.inbound_ratio,
    updated_at         = now();
END;
$_$;


ALTER FUNCTION zapp.upsert_contact_intelligence(p_contact_id uuid) OWNER TO postgres;

--
-- Name: upsert_conversation_tags_atomic(uuid, jsonb, jsonb); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.upsert_conversation_tags_atomic(p_contact_id uuid, p_new_tags jsonb, p_old_tags jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
BEGIN
  INSERT INTO zapp.ai_conversation_tags (contact_id, tag_name, confidence, source)
  SELECT p_contact_id, (tag->>'name'), (tag->>'confidence')::numeric, COALESCE(tag->>'source', 'ai')
  FROM jsonb_array_elements(p_new_tags) AS tag
  WHERE tag->>'name' IS NOT NULL
  ON CONFLICT (contact_id, tag_name) DO UPDATE SET
    confidence = EXCLUDED.confidence,
    updated_at = now();
  IF p_old_tags IS NOT NULL THEN
    DELETE FROM zapp.ai_conversation_tags
    WHERE contact_id = p_contact_id
      AND tag_name NOT IN (SELECT tag->>'name' FROM jsonb_array_elements(p_old_tags) AS tag);
  END IF;
END;
$$;


ALTER FUNCTION zapp.upsert_conversation_tags_atomic(p_contact_id uuid, p_new_tags jsonb, p_old_tags jsonb) OWNER TO postgres;

--
-- Name: user_has_permission(uuid, text); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.user_has_permission(_user_id uuid, _permission_name text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
  SELECT
    (_user_id IS NOT DISTINCT FROM auth.uid())
    AND EXISTS (
      SELECT 1 FROM zapp.user_roles ur
      JOIN zapp.role_permissions rp ON rp.role = ur.role
      JOIN zapp.permissions p ON p.id = rp.permission_id
      WHERE ur.user_id = _user_id
        AND p.name = _permission_name
    )
$$;


ALTER FUNCTION zapp.user_has_permission(_user_id uuid, _permission_name text) OWNER TO supabase_admin;

--
-- Name: FUNCTION user_has_permission(_user_id uuid, _permission_name text); Type: COMMENT; Schema: zapp; Owner: supabase_admin
--

COMMENT ON FUNCTION zapp.user_has_permission(_user_id uuid, _permission_name text) IS 'FIX SEC-4 (2026-08-06): guard auth.uid() adicionado — retorna FALSE quando _user_id ≠ auth.uid(), bloqueando enumeração de permissões de outros usuários. Uso em usePermissions.ts e ProtectedRoute.tsx com _user_id: user.id permanece inalterado.';


--
-- Name: validate_cnpj(text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.validate_cnpj(p_cnpj text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
DECLARE
  v_clean text; v_sum integer; v_digit integer; i integer;
  v_pesos1 integer[] := ARRAY[5,4,3,2,9,8,7,6,5,4,3,2];
  v_pesos2 integer[] := ARRAY[6,5,4,3,2,9,8,7,6,5,4,3,2];
BEGIN
  IF p_cnpj IS NULL THEN RETURN false; END IF;
  v_clean := regexp_replace(p_cnpj, '[^0-9]', '', 'g');
  IF length(v_clean) != 14 THEN RETURN false; END IF;
  IF v_clean ~ '^(\d)\1{13}$' THEN RETURN false; END IF;
  v_sum := 0;
  FOR i IN 1..12 LOOP v_sum := v_sum + (substr(v_clean, i, 1)::int * v_pesos1[i]); END LOOP;
  v_digit := 11 - (v_sum % 11); IF v_digit >= 10 THEN v_digit := 0; END IF;
  IF v_digit != substr(v_clean, 13, 1)::int THEN RETURN false; END IF;
  v_sum := 0;
  FOR i IN 1..13 LOOP v_sum := v_sum + (substr(v_clean, i, 1)::int * v_pesos2[i]); END LOOP;
  v_digit := 11 - (v_sum % 11); IF v_digit >= 10 THEN v_digit := 0; END IF;
  RETURN v_digit = substr(v_clean, 14, 1)::int;
END; $_$;


ALTER FUNCTION zapp.validate_cnpj(p_cnpj text) OWNER TO postgres;

--
-- Name: validate_cpf(text); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.validate_cpf(p_cpf text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
DECLARE
  v_clean text; v_sum integer; v_digit integer; i integer;
BEGIN
  IF p_cpf IS NULL THEN RETURN false; END IF;
  v_clean := regexp_replace(p_cpf, '[^0-9]', '', 'g');
  IF length(v_clean) != 11 THEN RETURN false; END IF;
  IF v_clean ~ '^(\d)\1{10}$' THEN RETURN false; END IF;
  v_sum := 0;
  FOR i IN 1..9 LOOP v_sum := v_sum + (substr(v_clean, i, 1)::int * (11 - i)); END LOOP;
  v_digit := (v_sum * 10) % 11; IF v_digit = 10 THEN v_digit := 0; END IF;
  IF v_digit != substr(v_clean, 10, 1)::int THEN RETURN false; END IF;
  v_sum := 0;
  FOR i IN 1..10 LOOP v_sum := v_sum + (substr(v_clean, i, 1)::int * (12 - i)); END LOOP;
  v_digit := (v_sum * 10) % 11; IF v_digit = 10 THEN v_digit := 0; END IF;
  RETURN v_digit = substr(v_clean, 11, 1)::int;
END; $_$;


ALTER FUNCTION zapp.validate_cpf(p_cpf text) OWNER TO postgres;

--
-- Name: validate_phone_numbers(jsonb); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.validate_phone_numbers(phone_numbers jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'zapp', 'public', 'pg_catalog'
    AS $$
BEGIN
  -- Must be an array
  IF jsonb_typeof(phone_numbers) != 'array' THEN
    RETURN false;
  END IF;

  -- Each element must have a non-empty 'number' field
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(phone_numbers) AS elem
    WHERE elem->>'number' IS NULL OR trim(elem->>'number') = ''
  ) THEN
    RETURN false;
  END IF;

  -- Max 10 phone numbers per contact
  IF jsonb_array_length(phone_numbers) > 10 THEN
    RETURN false;
  END IF;

  RETURN true;
END;
$$;


ALTER FUNCTION zapp.validate_phone_numbers(phone_numbers jsonb) OWNER TO supabase_admin;

--
-- Name: validate_reset_token(text); Type: FUNCTION; Schema: zapp; Owner: supabase_admin
--

CREATE FUNCTION zapp.validate_reset_token(p_token text) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'monitoring'
    AS $$
DECLARE
  v_user_id uuid;
  v_hashed text;
BEGIN
  v_hashed := encode(extensions.digest(p_token::bytea, 'sha256'), 'hex');
  
  SELECT user_id INTO v_user_id
  FROM zapp.password_reset_requests
  WHERE reset_token = v_hashed
    AND status = 'pending'
    AND token_expires_at > now()
  LIMIT 1;
  
  RETURN v_user_id;
END;
$$;


ALTER FUNCTION zapp.validate_reset_token(p_token text) OWNER TO supabase_admin;

--
-- Name: validate_snapshot_freshness(character varying, bigint); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.validate_snapshot_freshness(p_table_name character varying, p_snapshot_version bigint) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'zapp', 'pg_catalog'
    AS $$
DECLARE
  v_current BIGINT;
BEGIN
  SELECT version_number INTO v_current
  FROM _snapshot_version_state
  WHERE table_name = p_table_name;
  RETURN (COALESCE(v_current, 1) = p_snapshot_version);
END;
$$;


ALTER FUNCTION zapp.validate_snapshot_freshness(p_table_name character varying, p_snapshot_version bigint) OWNER TO postgres;

--
-- Name: validate_timestamp_freshness(timestamp with time zone, integer); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.validate_timestamp_freshness(p_timestamp timestamp with time zone, p_freshness_window_minutes integer DEFAULT 5) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp'
    AS $$
DECLARE
  v_server_time  TIMESTAMPTZ;
  v_age_minutes  INT;
BEGIN
  v_server_time := get_server_time();
  v_age_minutes := EXTRACT(EPOCH FROM (v_server_time - p_timestamp))::INT / 60;

  IF v_age_minutes < 0 THEN
    RAISE EXCEPTION 'Timestamp is in the future (clock skew detected)' USING ERRCODE = '22023';
  END IF;

  IF v_age_minutes > p_freshness_window_minutes THEN
    RAISE EXCEPTION 'Timestamp expired (% minutes old, max allowed: % minutes)',
      v_age_minutes, p_freshness_window_minutes USING ERRCODE = '22023';
  END IF;

  RETURN TRUE;
END;
$$;


ALTER FUNCTION zapp.validate_timestamp_freshness(p_timestamp timestamp with time zone, p_freshness_window_minutes integer) OWNER TO postgres;

--
-- Name: zapp_isonwa_mark(text[], text[]); Type: FUNCTION; Schema: zapp; Owner: postgres
--

CREATE FUNCTION zapp.zapp_isonwa_mark(p_jids text[], p_ok_jids text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'evo', 'public'
    AS $$
DECLARE v_now timestamptz := now(); v_done int;
BEGIN
  v_done := evo.rpc_boundary_isonwa_mark(p_jids);
  IF p_ok_jids IS NOT NULL AND cardinality(p_ok_jids) > 0 THEN
    UPDATE zapp.evolution_contacts SET is_on_whatsapp = true, whatsapp_checked_at = v_now WHERE remote_jid = ANY (p_ok_jids) AND is_on_whatsapp IS NOT TRUE;
    UPDATE zapp.evolution_contacts SET whatsapp_checked_at = v_now WHERE remote_jid = ANY (p_jids) AND whatsapp_checked_at IS NULL;
  END IF;
  RETURN jsonb_build_object('done', v_done);
END $$;


ALTER FUNCTION zapp.zapp_isonwa_mark(p_jids text[], p_ok_jids text[]) OWNER TO postgres;

