--

CREATE FUNCTION zapp.zapp_notif_config_get(p_channel text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'zapp', 'public', 'extensions'
    AS $$
DECLARE v_row evolution_notification_config%ROWTYPE;
BEGIN
  IF p_channel IS NULL OR btrim(p_channel) = '' THEN RETURN NULL; END IF;
  SELECT * INTO v_row FROM evolution_notification_config
  WHERE channel = p_channel AND enabled IS NOT FALSE LIMIT 1;
  IF NOT FOUND THEN RETURN NULL; END IF;
  RETURN to_jsonb(v_row);
END; $$;


