WITH (autovacuum_vacuum_cost_delay='2', autovacuum_vacuum_scale_factor='0', autovacuum_vacuum_threshold='10', autovacuum_analyze_scale_factor='0', autovacuum_analyze_threshold='10');


ALTER TABLE zapp.evolution_alerts OWNER TO postgres;

--
-- Name: TABLE evolution_alerts; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON TABLE zapp.evolution_alerts IS 'Fila de alertas operacionais do sistema WhatsApp CRM.
CARDINALIDADE: ~920 linhas ativas | 712 kB.
SEVERIDADE: low | medium | high | critical.
DEDUP: trigger trg_dedup_alert via (alert_type, instance_name) na última hora.
LIMPEZA: cron purge_evolution_alerts (job 65, 04:58 diário) remove resolved > 7 dias.
ÍNDICE: idx_alerts_resolved_type_created adicionado em 2026-08-09 (N-01) — 1.779 seq_scans eliminados.';


--
-- Name: COLUMN evolution_alerts.id; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON COLUMN zapp.evolution_alerts.id IS 'PK uuid.';


--
-- Name: COLUMN evolution_alerts.alert_type; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON COLUMN zapp.evolution_alerts.alert_type IS 'Código do tipo de alerta. Ex: wpp2_uptime_sla_breach | wal_slot_high_lag | ingest_loss_rate | media_download_failure | unroutable_queue. Índice: idx_alerts_resolved_type_created.';


--
-- Name: COLUMN evolution_alerts.severity; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON COLUMN zapp.evolution_alerts.severity IS 'Severidade: low | medium | high | critical. Critical dispara notificação imediata.';


--
-- Name: COLUMN evolution_alerts.message; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON COLUMN zapp.evolution_alerts.message IS 'Mensagem principal do alerta (pode duplicar description em alguns geradores). Legado.';


--
-- Name: COLUMN evolution_alerts.payload; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON COLUMN zapp.evolution_alerts.payload IS 'jsonb com dados contextuais do alerta (métricas, valores, thresholds). Schema varia por alert_type.';


--
-- Name: COLUMN evolution_alerts.acknowledged; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON COLUMN zapp.evolution_alerts.acknowledged IS 'true = alerta reconhecido por um agente (viu e está ciente). Diferente de resolved (corrigido).';


--
-- Name: COLUMN evolution_alerts.acknowledged_at; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON COLUMN zapp.evolution_alerts.acknowledged_at IS 'Timestamp de reconhecimento. NULL se não reconhecido.';


--
-- Name: COLUMN evolution_alerts.acknowledged_by; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON COLUMN zapp.evolution_alerts.acknowledged_by IS 'UUID do agente que reconheceu. NULL se não reconhecido.';


--
-- Name: COLUMN evolution_alerts.created_at; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON COLUMN zapp.evolution_alerts.created_at IS 'Timestamp de criação do alerta. Índice: idx_alerts_unresolved e idx_alerts_resolved_type_created.';


--
-- Name: COLUMN evolution_alerts.resolved_at; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON COLUMN zapp.evolution_alerts.resolved_at IS 'Timestamp de resolução. NULL se ainda ativo.';


--
-- Name: COLUMN evolution_alerts.resolved_by; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON COLUMN zapp.evolution_alerts.resolved_by IS 'UUID ou identificador de quem/o que resolveu (agente, cron, sistema). NULL se ativo.';


--
-- Name: COLUMN evolution_alerts.remote_jid; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON COLUMN zapp.evolution_alerts.remote_jid IS 'JID do contato relacionado ao alerta (quando aplicável). NULL para alertas sistêmicos.';


--
-- Name: COLUMN evolution_alerts.contact_id; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON COLUMN zapp.evolution_alerts.contact_id IS 'FK → evo.evolution_contacts.id (quando alerta é sobre um contato específico). NULL para alertas sistêmicos.';


--
-- Name: COLUMN evolution_alerts.title; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON COLUMN zapp.evolution_alerts.title IS 'Título curto do alerta para exibição no dashboard.';


--
-- Name: COLUMN evolution_alerts.description; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON COLUMN zapp.evolution_alerts.description IS 'Descrição detalhada do alerta com contexto e métricas.';


--
-- Name: COLUMN evolution_alerts.escalated_at; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON COLUMN zapp.evolution_alerts.escalated_at IS 'Timestamp de escalação para severidade superior. NULL se não escalado.';


