COMMENT ON COLUMN zapp.evolution_alerts.resolved IS 'false = alerta ativo. true = resolvido. ÍNDICE PARTIAL: idx_alerts_unresolved e idx_alerts_resolved_type_created cobrem WHERE resolved=false.';


