CREATE TABLE zapp.evolution_media (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    message_id text NOT NULL,
    remote_jid text NOT NULL,
    media_type text NOT NULL,
    mime_type text,
    file_name text,
    file_size integer,
    file_sha256 text,
    storage_path text,
    storage_url text,
    base64_data text,
    caption text,
    duration_seconds integer,
    width integer,
    height integer,
    is_animated boolean DEFAULT false,
    thumbnail_base64 text,
    created_at timestamp with time zone DEFAULT now(),
    storage_bucket text,
    storage_path_clean text,
    media_status text DEFAULT 'unknown'::text,
    instance_name text DEFAULT 'wpp2'::text NOT NULL,
    CONSTRAINT evolution_media_media_status_check CHECK ((media_status = ANY (ARRAY['pending'::text, 'processing'::text, 'ready'::text, 'failed'::text, 'expired'::text, 'unknown'::text, 'permanently_lost'::text]))),
    CONSTRAINT evolution_media_media_type_check CHECK (((media_type IS NULL) OR (media_type = ANY (ARRAY['image'::text, 'audio'::text, 'document'::text, 'video'::text, 'sticker'::text]))))
)
WITH (autovacuum_vacuum_cost_delay='2', autovacuum_freeze_max_age='50000000', autovacuum_vacuum_scale_factor='0.05', autovacuum_vacuum_threshold='1000', autovacuum_analyze_scale_factor='0.05', autovacuum_analyze_threshold='500');


ALTER TABLE zapp.evolution_media OWNER TO postgres;

--
-- Name: TABLE evolution_media; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON TABLE zapp.evolution_media IS 'Registro de arquivos de mídia das mensagens WhatsApp. Espelho normalizado de evolution_messages_wpp2 para colunas de arquivo.
CARDINALIDADE: 32.885 linhas | 13 MB dados | 17 MB com índices.
UNICIDADE: message_id é UNIQUE (uq_evolution_media_message_id). Exatamente 1 linha por mensagem de mídia.
STORAGE: storage_url aponta para Supabase Storage bucket (whatsapp-media, audio-messages ou stickers). URL pública: https://supabase.atomicabr.com.br/storage/v1/object/public/{bucket}/{path}.
ESTADOS (media_status): pending | processing | ready | failed | expired | unknown | permanently_lost.
  "permanently_lost" = 36.179 linhas em 2026-08-09: sem mediaKey, sem directPath, sem objeto no bucket — irrecuperáveis.
FK: fk_media_message → evo.evolution_messages (NOT VALID — 15.666 orphans existem de mídia sem mensagem pai).
POPULAÇÃO: trigger trg_auto_media_wpp2 (fn_auto_populate_media) insere via zapp.evolution_media (VIEW). ON CONFLICT DO NOTHING com índice único.
ORPHANS: 15.666 linhas em evo.media_orphan_triage sem mensagem correspondente — candidatas a limpeza de storage.
ATENÇÃO: zapp.evolution_media é VIEW sobre esta tabela. DDL sempre em evo.evolution_media.';


--
-- Name: COLUMN evolution_media.id; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON COLUMN zapp.evolution_media.id IS 'PK uuid gerado pelo banco. Diferente do message_id (ID do WhatsApp).';


--
-- Name: COLUMN evolution_media.message_id; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON COLUMN zapp.evolution_media.message_id IS 'ID WhatsApp da mensagem dona deste arquivo. UNIQUE (uq_evolution_media_message_id). FK para evolution_messages (fk_media_message, NOT VALID).';


--
-- Name: COLUMN evolution_media.remote_jid; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON COLUMN zapp.evolution_media.remote_jid IS 'JID do contato que enviou/recebeu a mídia. Mesmo valor de evolution_messages_wpp2.remote_jid para a mesma mensagem. Útil para filtrar mídias por contato sem JOIN em evolution_messages.';


--
-- Name: COLUMN evolution_media.media_type; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON COLUMN zapp.evolution_media.media_type IS 'Tipo simplificado: image | audio | video | document | sticker. Subconjunto do message_type de evolution_messages.';


--
-- Name: COLUMN evolution_media.mime_type; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON COLUMN zapp.evolution_media.mime_type IS 'MIME type completo (ex: "audio/ogg; codecs=opus", "image/jpeg"). NULL quando não informado.';


--
-- Name: COLUMN evolution_media.file_name; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON COLUMN zapp.evolution_media.file_name IS 'Nome original do arquivo. NULL para imagens e áudios gravados in-app.';


--
-- Name: COLUMN evolution_media.file_size; Type: COMMENT; Schema: zapp; Owner: postgres
--

