--
-- Name: evolution_webhook_dlq; Type: TABLE; Schema: zapp; Owner: postgres
--

CREATE TABLE zapp.evolution_webhook_dlq (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    original_event_id uuid,
    event_type text NOT NULL,
    instance_name text NOT NULL,
    remote_jid text,
    payload jsonb,
    error_message text NOT NULL,
    error_stack text,
    retry_count integer DEFAULT 0,
    max_retries integer DEFAULT 3,
    next_retry_at timestamp with time zone,
    status text DEFAULT 'pending'::text NOT NULL,
    resolved_at timestamp with time zone,
    resolved_by text,
    created_at timestamp with time zone DEFAULT now(),
    last_request_id bigint,
    raw_payload text,
    consumer_version text DEFAULT 'consumer-prebuilt:v1'::text,
    queue_name text,
    source_event_id uuid,
    CONSTRAINT evolution_webhook_dlq_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'poison'::text])))
);


ALTER TABLE zapp.evolution_webhook_dlq OWNER TO postgres;

--
-- Name: TABLE evolution_webhook_dlq; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON TABLE zapp.evolution_webhook_dlq IS 'Dead Letter Queue dos eventos do pipeline WhatsApp: eventos que falharam após esgotar retries. Monitorada por crons (fn_detect_ack_loss_gap) e views (v_ack_loss_candidates, v_evolution_dlq_open).';


--
-- Name: COLUMN evolution_webhook_dlq.id; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON COLUMN zapp.evolution_webhook_dlq.id IS 'PK uuid do registro de dead letter.';


--
-- Name: COLUMN evolution_webhook_dlq.original_event_id; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON COLUMN zapp.evolution_webhook_dlq.original_event_id IS 'ID do evento original (evolution_webhook_events_v2.id) que falhou. NULL se o evento nunca entrou na v2.';


--
-- Name: COLUMN evolution_webhook_dlq.event_type; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON COLUMN zapp.evolution_webhook_dlq.event_type IS 'Tipo do evento que falhou (messages.upsert, messages.update, send.message, message.ack...).';


--
-- Name: COLUMN evolution_webhook_dlq.instance_name; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON COLUMN zapp.evolution_webhook_dlq.instance_name IS 'Instância WhatsApp do evento.';


--
-- Name: COLUMN evolution_webhook_dlq.remote_jid; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON COLUMN zapp.evolution_webhook_dlq.remote_jid IS 'JID do contato/grupo envolvido. NULL se não disponível.';


--
-- Name: COLUMN evolution_webhook_dlq.payload; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON COLUMN zapp.evolution_webhook_dlq.payload IS 'jsonb do payload que falhou (pode ser o normalizado ou o envelope, conforme a rota).';


--
-- Name: COLUMN evolution_webhook_dlq.error_message; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON COLUMN zapp.evolution_webhook_dlq.error_message IS 'Mensagem de erro que levou à dead letter.';


--
-- Name: COLUMN evolution_webhook_dlq.error_stack; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON COLUMN zapp.evolution_webhook_dlq.error_stack IS 'Stack trace / detalhe do erro. NULL se não capturado.';


--
-- Name: COLUMN evolution_webhook_dlq.retry_count; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON COLUMN zapp.evolution_webhook_dlq.retry_count IS 'Tentativas já realizadas.';


--
-- Name: COLUMN evolution_webhook_dlq.max_retries; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON COLUMN zapp.evolution_webhook_dlq.max_retries IS 'Limite de tentativas antes de dead letter definitiva.';


--
-- Name: COLUMN evolution_webhook_dlq.next_retry_at; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON COLUMN zapp.evolution_webhook_dlq.next_retry_at IS 'Próximo horário de retry (índice parcial de pending/retrying). NULL = sem retry agendado.';


--
-- Name: COLUMN evolution_webhook_dlq.status; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON COLUMN zapp.evolution_webhook_dlq.status IS 'Estado: pending|retrying|dead_letter|resolved (CHECK). View v_ack_loss_candidates classifica falhas.';


--
-- Name: COLUMN evolution_webhook_dlq.resolved_at; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON COLUMN zapp.evolution_webhook_dlq.resolved_at IS 'Quando foi resolvido/reprocessado com sucesso. NULL = aberto.';


--
-- Name: COLUMN evolution_webhook_dlq.resolved_by; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON COLUMN zapp.evolution_webhook_dlq.resolved_by IS 'Quem resolveu (agente, cron ou sistema).';


--
-- Name: COLUMN evolution_webhook_dlq.created_at; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON COLUMN zapp.evolution_webhook_dlq.created_at IS 'Timestamp de entrada na DLQ.';


--
-- Name: COLUMN evolution_webhook_dlq.last_request_id; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON COLUMN zapp.evolution_webhook_dlq.last_request_id IS 'ID da última requisição pg_net/HTTP relacionada. NULL se não aplicável.';


--
-- Name: COLUMN evolution_webhook_dlq.raw_payload; Type: COMMENT; Schema: zapp; Owner: postgres
--

