--
-- Name: instance_registry; Type: TABLE; Schema: zapp; Owner: postgres
--

CREATE TABLE zapp.instance_registry (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    instance_name character varying(50) NOT NULL,
    display_name character varying(100) NOT NULL,
    phone_number character varying(20),
    department character varying(30) NOT NULL,
    responsible_name character varying(100),
    responsible_email character varying(100),
    is_active boolean DEFAULT true,
    webhook_url text,
    webhook_enabled boolean DEFAULT true,
    auto_reply_enabled boolean DEFAULT false,
    auto_reply_message text,
    business_hours_enabled boolean DEFAULT true,
    max_concurrent_chats integer DEFAULT 50,
    sla_first_response_minutes integer DEFAULT 30,
    sla_resolution_hours integer DEFAULT 24,
    bitrix_integration jsonb DEFAULT '{}'::jsonb,
    n8n_workflows jsonb DEFAULT '[]'::jsonb,
    config jsonb DEFAULT '{}'::jsonb,
    notes text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    slot_name character varying(100),
    operator_name character varying(200),
    operator_email character varying(200),
    operator_since timestamp with time zone DEFAULT now(),
    operator_phone character varying(20),
    usage_type character varying(20) DEFAULT 'shared'::character varying,
    owner_id uuid,
    status text DEFAULT 'inactive'::text,
    connection_status text DEFAULT 'disconnected'::text,
    api_key text,
    api_url text,
    profile_picture text,
    is_master boolean DEFAULT false,
    proxy_host text,
    proxy_port text,
    proxy_user text,
    proxy_pass text,
    settings jsonb DEFAULT '{}'::jsonb,
    last_connected_at timestamp with time zone,
    message_count_sent integer DEFAULT 0,
    message_count_received integer DEFAULT 0,
    error_logs text,
    metadata jsonb DEFAULT '{}'::jsonb,
    CONSTRAINT instance_name_not_empty CHECK (((instance_name)::text ~ '\S'::text)),
    CONSTRAINT instance_registry_connection_status_check CHECK (((connection_status IS NULL) OR (connection_status = ANY (ARRAY['connected'::text, 'disconnected'::text, 'qr_pending'::text, 'error'::text, 'connecting'::text, 'reconnecting'::text, 'degraded'::text, 'logged_out'::text])))),
    CONSTRAINT instance_registry_department_check CHECK (((department)::text = ANY ((ARRAY['vendas'::character varying, 'comercial'::character varying, 'financeiro'::character varying, 'compras'::character varying, 'logistica'::character varying, 'sac'::character varying, 'diretoria'::character varying, 'marketing'::character varying, 'ti'::character varying, 'rh'::character varying, 'producao'::character varying, 'expedicao'::character varying, 'artes'::character varying, 'gravacao'::character varying, 'outros'::character varying])::text[]))),
    CONSTRAINT instance_registry_status_check CHECK ((status = ANY (ARRAY['active'::text, 'inactive'::text, 'connected'::text, 'connecting'::text, 'disconnected'::text, 'qr_pending'::text, 'reconnecting'::text, 'degraded'::text, 'archived'::text, 'not_provisioned'::text, 'logged_out'::text, 'test'::text]))),
    CONSTRAINT instance_registry_usage_type_check CHECK (((usage_type)::text = ANY ((ARRAY['individual'::character varying, 'shared'::character varying])::text[])))
);


