    message_key_id text,
    payload jsonb
)
WITH (autovacuum_vacuum_scale_factor='0', autovacuum_vacuum_threshold='50000', autovacuum_analyze_scale_factor='0', autovacuum_analyze_threshold='30000', autovacuum_vacuum_cost_delay='2');


