--
-- Name: COLUMN webhook_events_processed.id; Type: COMMENT; Schema: zapp; Owner: supabase_admin
--

COMMENT ON COLUMN zapp.webhook_events_processed.id IS 'PK (uuid).';


--
-- Name: COLUMN webhook_events_processed.event_id; Type: COMMENT; Schema: zapp; Owner: supabase_admin
--

