--

CREATE TABLE zapp.evolution_followups (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    contact_id uuid,
    conversation_id uuid,
    deal_id uuid,
    followup_type character varying(50) NOT NULL,
    scheduled_at timestamp with time zone NOT NULL,
    template_id uuid,
    custom_message text,
    status character varying(20) DEFAULT 'scheduled'::character varying,
    sent_at timestamp with time zone,
    response_at timestamp with time zone,
    error_message text,
    attempts integer DEFAULT 0,
    max_attempts integer DEFAULT 3,
    created_by character varying(100),
    instance_name character varying(100) DEFAULT 'wpp2'::character varying,
    metadata jsonb,
    created_at timestamp with time zone DEFAULT now(),
    triggered_at timestamp with time zone,
    CONSTRAINT evolution_followups_status_check CHECK (((status IS NULL) OR ((status)::text = ANY ((ARRAY['scheduled'::character varying, 'pending'::character varying, 'triggered'::character varying, 'sent'::character varying, 'delivered'::character varying, 'completed'::character varying, 'cancelled'::character varying, 'failed'::character varying])::text[]))))
)
WITH (autovacuum_vacuum_scale_factor='0.05', autovacuum_vacuum_threshold='50');


