-- Name: evolution_message_queue; Type: TABLE; Schema: zapp; Owner: postgres
--

CREATE TABLE zapp.evolution_message_queue (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    contact_id uuid,
    remote_jid character varying(50) NOT NULL,
    message_type character varying(30) DEFAULT 'text'::character varying,
    content text,
    media_url text,
    media_filename character varying(255),
    template_id uuid,
    template_vars jsonb DEFAULT '{}'::jsonb,
    scheduled_at timestamp with time zone DEFAULT now(),
    priority integer DEFAULT 5,
    status character varying(20) DEFAULT 'pending'::character varying,
    attempts integer DEFAULT 0,
    max_attempts integer DEFAULT 3,
    sent_at timestamp with time zone,
    delivered_at timestamp with time zone,
    read_at timestamp with time zone,
    error_message text,
    whatsapp_message_id character varying(100),
    source character varying(50) DEFAULT 'manual'::character varying,
    source_id uuid,
    instance_name character varying(100) DEFAULT 'wpp2'::character varying,
    created_by character varying(100),
    metadata jsonb,
    created_at timestamp with time zone DEFAULT now(),
    CONSTRAINT evolution_message_queue_status_check CHECK (((status IS NULL) OR ((status)::text = ANY (ARRAY['pending'::text, 'processing'::text, 'sent'::text, 'delivered'::text, 'failed'::text, 'cancelled'::text]))))
);


ALTER TABLE zapp.evolution_message_queue OWNER TO postgres;

