--
-- Name: evolution_messages_wpp2_archive; Type: TABLE; Schema: zapp; Owner: postgres
--

CREATE TABLE zapp.evolution_messages_wpp2_archive (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    message_id text,
    remote_jid text NOT NULL,
    from_me boolean DEFAULT false,
    message_type character varying(50) DEFAULT 'unknown'::character varying NOT NULL,
    content text,
    media_url text,
    media_mimetype text,
    quoted_message_id text,
    is_starred boolean DEFAULT false,
    is_important boolean DEFAULT false,
    category text,
    sentiment text,
    tags text[],
    notes text,
    follow_up_at timestamp with time zone,
    follow_up_done boolean DEFAULT false,
    payload jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    contact_id uuid,
    conversation_id uuid,
    direction character varying(10) DEFAULT 'inbound'::character varying,
    status character varying(20) DEFAULT 'delivered'::character varying,
    status_at timestamp with time zone DEFAULT now(),
    caption text,
    media_filename character varying(255),
    media_size integer,
    sent_by_bot boolean DEFAULT false,
    template_name character varying(100),
    instance_name character varying(100) NOT NULL,
    push_name text,
    media_type text,
    raw_data jsonb,
    deleted_at timestamp with time zone,
    edited_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now(),
    media_meta jsonb,
    audio_meme_id uuid,
    sticker_id uuid,
    link_preview jsonb,
    is_read boolean DEFAULT false NOT NULL,
    reply_to_id uuid,
    media_bucket text,
    media_path text,
    media_sha256 text,
    media_status text,
    transcription_status text,
    transcription text,
    CONSTRAINT evolution_messages_status_check CHECK (((status IS NULL) OR ((status)::text = ANY (ARRAY['received'::text, 'sent'::text, 'delivered'::text, 'read'::text, 'deleted'::text, 'pending'::text, 'played'::text, 'failed'::text])))),
    CONSTRAINT evolution_messages_wpp2_archive_direction_check CHECK (((direction IS NULL) OR ((direction)::text = ANY (ARRAY['inbound'::text, 'outbound'::text]))))
);


ALTER TABLE zapp.evolution_messages_wpp2_archive OWNER TO postgres;

--
-- Name: TABLE evolution_messages_wpp2_archive; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON TABLE zapp.evolution_messages_wpp2_archive IS 'Arquivo frio de mensagens wpp2 com mais de 12 meses. Criado 2026-07-03. Fonte: fn_archive_old_wpp2_messages.';


