-- Name: evolution_retry_metrics; Type: TABLE; Schema: zapp; Owner: supabase_admin
--

CREATE TABLE zapp.evolution_retry_metrics (
    action text NOT NULL,
    attempt_count integer NOT NULL,
    created_at timestamp with time zone DEFAULT now(),
    final_http_status numeric,
    final_status text NOT NULL,
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    idempotency_key text,
    instance_name text,
    method text NOT NULL,
    retry_reasons jsonb DEFAULT '{}'::jsonb NOT NULL,
    total_duration_ms numeric
);


ALTER TABLE zapp.evolution_retry_metrics OWNER TO supabase_admin;

--
-- Name: TABLE evolution_retry_metrics; Type: COMMENT; Schema: zapp; Owner: supabase_admin
--

COMMENT ON TABLE zapp.evolution_retry_metrics IS 'Métricas de requisições com retry para a Evolution API e edge functions. Gerado pelo consumer.py e N8N.
CARDINALIDADE: ~3.321 linhas | 560 kB.
PROPÓSITO: diagnosticar endpoints instáveis que requerem múltiplas tentativas. Subsídio para alertas de degradação.
CAMPOS CHAVE: action (endpoint chamado), attempt_count (tentativas), final_status (success/failed), total_duration_ms.
ANÁLISE: SELECT action, avg(attempt_count), avg(total_duration_ms), count(*) FROM evo.evolution_retry_metrics GROUP BY 1 ORDER BY 2 DESC.';


--
-- Name: COLUMN evolution_retry_metrics.action; Type: COMMENT; Schema: zapp; Owner: supabase_admin
--

COMMENT ON COLUMN zapp.evolution_retry_metrics.action IS 'Endpoint ou ação que foi chamada com retry. Ex: "evolution-webhook", "fn_send_message", "n8n_webhook_call".';


--
-- Name: COLUMN evolution_retry_metrics.attempt_count; Type: COMMENT; Schema: zapp; Owner: supabase_admin
--

COMMENT ON COLUMN zapp.evolution_retry_metrics.attempt_count IS 'Número de tentativas feitas (inclui a primeira). 1 = sucesso de primeira. > 1 = houve retry.';


--
-- Name: COLUMN evolution_retry_metrics.created_at; Type: COMMENT; Schema: zapp; Owner: supabase_admin
--

COMMENT ON COLUMN zapp.evolution_retry_metrics.created_at IS 'Timestamp do início da primeira tentativa.';


--
-- Name: COLUMN evolution_retry_metrics.final_http_status; Type: COMMENT; Schema: zapp; Owner: supabase_admin
--

COMMENT ON COLUMN zapp.evolution_retry_metrics.final_http_status IS 'HTTP status code da última tentativa (numeric). Ex: 200, 422, 502, 504.';


--
-- Name: COLUMN evolution_retry_metrics.final_status; Type: COMMENT; Schema: zapp; Owner: supabase_admin
--

COMMENT ON COLUMN zapp.evolution_retry_metrics.final_status IS 'Resultado final: success | failed | timeout | circuit_breaker_open.';


--
-- Name: COLUMN evolution_retry_metrics.id; Type: COMMENT; Schema: zapp; Owner: supabase_admin
--

COMMENT ON COLUMN zapp.evolution_retry_metrics.id IS 'PK uuid.';


--
-- Name: COLUMN evolution_retry_metrics.idempotency_key; Type: COMMENT; Schema: zapp; Owner: supabase_admin
--

COMMENT ON COLUMN zapp.evolution_retry_metrics.idempotency_key IS 'Chave de idempotência da requisição. Garante que o retry não duplica efeitos colaterais.';


--
-- Name: COLUMN evolution_retry_metrics.instance_name; Type: COMMENT; Schema: zapp; Owner: supabase_admin
--

COMMENT ON COLUMN zapp.evolution_retry_metrics.instance_name IS 'Instância WhatsApp relacionada. Sempre "wpp2".';


--
-- Name: COLUMN evolution_retry_metrics.method; Type: COMMENT; Schema: zapp; Owner: supabase_admin
--

COMMENT ON COLUMN zapp.evolution_retry_metrics.method IS 'Método HTTP ou tipo de operação: POST | GET | PUT | edge_function | rpc.';


--
-- Name: COLUMN evolution_retry_metrics.retry_reasons; Type: COMMENT; Schema: zapp; Owner: supabase_admin
--

COMMENT ON COLUMN zapp.evolution_retry_metrics.retry_reasons IS 'jsonb com motivos de cada retry. Schema: [{"attempt":int,"reason":str,"status":int,"delay_ms":int}].';


--
-- Name: COLUMN evolution_retry_metrics.total_duration_ms; Type: COMMENT; Schema: zapp; Owner: supabase_admin
--

COMMENT ON COLUMN zapp.evolution_retry_metrics.total_duration_ms IS 'Duração total em ms incluindo todas as tentativas e backoffs.';


