CREATE TABLE zapp.evolution_scheduled_messages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    contact_id uuid,
    scheduled_at timestamp with time zone NOT NULL,
    sent_at timestamp with time zone,
    template_id uuid,
    content text NOT NULL,
    media_url text,
    status character varying(20) DEFAULT 'pending'::character varying,
    error_message text,
    created_by character varying(100),
    instance_name character varying(100) DEFAULT 'wpp2'::character varying,
    created_at timestamp with time zone DEFAULT now(),
    CONSTRAINT evolution_scheduled_messages_status_check CHECK (((status IS NULL) OR ((status)::text = ANY (ARRAY['pending'::text, 'sending'::text, 'sent'::text, 'failed'::text, 'cancelled'::text, 'expired'::text]))))
);


