--
-- Name: mv_conversations_summary; Type: MATERIALIZED VIEW; Schema: zapp; Owner: postgres
--

CREATE MATERIALIZED VIEW zapp.mv_conversations_summary AS
 SELECT date(c.created_at) AS dia,
    c.status,
    c.instance_name,
    count(*) AS total_conversas,
    count(DISTINCT c.contact_id) AS contatos_unicos
   FROM evo.evolution_conversations c
  GROUP BY (date(c.created_at)), c.status, c.instance_name
  WITH NO DATA;


ALTER TABLE zapp.mv_conversations_summary OWNER TO postgres;

--
-- Name: mv_instance_metrics; Type: MATERIALIZED VIEW; Schema: zapp; Owner: postgres
--

CREATE MATERIALIZED VIEW zapp.mv_instance_metrics AS
 SELECT evolution_messages.instance_name,
    count(*) AS total_messages,
    count(*) FILTER (WHERE (evolution_messages.created_at > (now() - '24:00:00'::interval))) AS msgs_24h,
    count(*) FILTER (WHERE (evolution_messages.created_at > (now() - '7 days'::interval))) AS msgs_7d,
    count(*) FILTER (WHERE (evolution_messages.from_me = true)) AS sent,
    count(*) FILTER (WHERE (evolution_messages.from_me = false)) AS received,
    count(DISTINCT evolution_messages.remote_jid) AS unique_contacts,
    count(DISTINCT evolution_messages.remote_jid) FILTER (WHERE (evolution_messages.created_at > (now() - '24:00:00'::interval))) AS active_contacts_24h,
    max(evolution_messages.created_at) AS last_message_at,
    min(evolution_messages.created_at) AS first_message_at
   FROM evo.evolution_messages
  GROUP BY evolution_messages.instance_name
  WITH NO DATA;


ALTER TABLE zapp.mv_instance_metrics OWNER TO postgres;

