--
-- Name: provider_message_log; Type: TABLE; Schema: zapp; Owner: supabase_admin
--

CREATE TABLE zapp.provider_message_log (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    provider text NOT NULL,
    instance_name text,
    direction text NOT NULL,
    remote_jid text,
    message_id text,
    status text,
    http_status integer,
    request_body jsonb,
    response_body jsonb,
    duration_ms integer,
    error_message text,
    created_at timestamp with time zone DEFAULT now(),
    delivered_at timestamp with time zone,
    delivery_status text DEFAULT 'received'::text NOT NULL,
    error_code text,
    external_contact_id uuid,
    external_message_id text,
    idempotency_key text NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    payload jsonb NOT NULL,
    payload_hash text NOT NULL,
    persisted_at timestamp with time zone,
    received_at timestamp with time zone DEFAULT now() NOT NULL,
    routed_at timestamp with time zone,
    thread_id uuid,
    trace_id text,
    CONSTRAINT provider_message_log_delivery_status_check CHECK ((delivery_status = ANY (ARRAY['pending'::text, 'received'::text, 'persisted'::text, 'routed'::text, 'sent'::text, 'delivered'::text, 'read'::text, 'failed'::text, 'error'::text]))),
    CONSTRAINT provider_message_log_direction_check CHECK ((direction = ANY (ARRAY['inbound'::text, 'outbound'::text]))),
    CONSTRAINT provider_message_log_status_check CHECK (((status IS NULL) OR (status = ANY (ARRAY['received'::text, 'persisted'::text, 'routed'::text, 'sent'::text, 'delivered'::text, 'read'::text, 'failed'::text]))))
);


ALTER TABLE zapp.provider_message_log OWNER TO supabase_admin;

