CREATE VIEW zapp.audit_log WITH (security_invoker='on') AS
 SELECT evolution_audit_log.id,
    evolution_audit_log.action,
    evolution_audit_log.created_at AS changed_at,
    evolution_audit_log.performed_by AS changed_by,
    evolution_audit_log.old_values,
    evolution_audit_log.new_values,
    NULL::text AS reason,
    evolution_audit_log.entity_id AS contact_id
   FROM zapp.evolution_audit_log
  WHERE ((evolution_audit_log.entity_type)::text = ANY ((ARRAY['contact'::character varying, 'contacts'::character varying, 'evolution_contacts'::character varying])::text[]));


