-- Name: auto_export_jobs; Type: TABLE; Schema: zapp; Owner: postgres
--

CREATE TABLE zapp.auto_export_jobs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    source_table text NOT NULL,
    format text DEFAULT 'csv'::text NOT NULL,
    filters jsonb DEFAULT '{}'::jsonb NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    file_path text,
    row_count integer DEFAULT 0 NOT NULL,
    last_run_at timestamp with time zone,
    last_error text,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT auto_export_jobs_format_check CHECK ((format = ANY (ARRAY['csv'::text, 'json'::text]))),
    CONSTRAINT auto_export_jobs_name_check CHECK (((length(name) >= 1) AND (length(name) <= 120))),
    CONSTRAINT auto_export_jobs_row_count_check CHECK ((row_count >= 0)),
    CONSTRAINT auto_export_jobs_source_table_check CHECK ((source_table = ANY (ARRAY['contacts'::text, 'messages'::text, 'conversations'::text, 'campaigns'::text, 'scheduled_messages'::text]))),
    CONSTRAINT auto_export_jobs_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'processing'::text, 'completed'::text, 'failed'::text])))
);

ALTER TABLE ONLY zapp.auto_export_jobs REPLICA IDENTITY FULL;


ALTER TABLE zapp.auto_export_jobs OWNER TO postgres;

