CREATE TABLE zapp.emails (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    message_id text,
    thread_id text,
    direction text DEFAULT 'inbound'::text NOT NULL,
    provider text DEFAULT 'resend'::text NOT NULL,
    from_email text NOT NULL,
    from_name text,
    to_emails text[] DEFAULT '{}'::text[] NOT NULL,
    cc_emails text[] DEFAULT '{}'::text[] NOT NULL,
    subject text,
    text_body text,
    html_body text,
    attachments jsonb DEFAULT '[]'::jsonb NOT NULL,
    status text DEFAULT 'received'::text NOT NULL,
    error_message text,
    user_id uuid,
    raw_payload jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT emails_direction_check CHECK ((direction = ANY (ARRAY['inbound'::text, 'outbound'::text]))),
    CONSTRAINT emails_provider_check CHECK ((provider = ANY (ARRAY['resend'::text, 'gmail'::text]))),
    CONSTRAINT emails_status_check CHECK ((status = ANY (ARRAY['received'::text, 'sent'::text, 'failed'::text, 'read'::text])))
);

