--
-- Name: evo_reconcile_contact_snapshot; Type: TABLE; Schema: zapp; Owner: postgres
--

CREATE TABLE zapp.evo_reconcile_contact_snapshot (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    captured_at timestamp with time zone DEFAULT now() NOT NULL,
    instance_name text NOT NULL,
    src_contacts integer NOT NULL,
    mir_contacts integer NOT NULL,
    delta_abs integer GENERATED ALWAYS AS ((mir_contacts - src_contacts)) STORED,
    status text DEFAULT 'ok'::text,
    notes text,
    delta_pct numeric GENERATED ALWAYS AS (
CASE
    WHEN (src_contacts > 0) THEN round(((100.0 * (abs((mir_contacts - src_contacts)))::numeric) / (src_contacts)::numeric), 2)
    ELSE NULL::numeric
END) STORED,
    CONSTRAINT evo_reconcile_contact_snapshot_status_check CHECK ((status = ANY (ARRAY['ok'::text, 'warn'::text, 'alert'::text, 'healthy'::text, 'degraded_sender'::text, 'degraded'::text, 'unknown'::text])))
);

