--

COMMENT ON COLUMN zapp.evo_reconcile_contact_snapshot.delta_pct IS 'Delta medido (absoluto/percentual).';


--
-- Name: evo_contact_delta; Type: VIEW; Schema: zapp; Owner: postgres
--

CREATE VIEW zapp.evo_contact_delta WITH (security_invoker='true') AS
 SELECT ec.instance_name,
    count(*) AS mirror_total,
    count(*) FILTER (WHERE (ec.deleted_at IS NULL)) AS mirror_active,
    count(*) FILTER (WHERE (ec.full_name IS NOT NULL)) AS enriched_nome,
    count(*) FILTER (WHERE (ec.email IS NOT NULL)) AS enriched_email,
    count(*) FILTER (WHERE (ec.created_at >= (now() - '7 days'::interval))) AS novos_7d,
    count(*) FILTER (WHERE (ec.created_at >= (now() - '30 days'::interval))) AS novos_30d,
    round(((100.0 * (count(*) FILTER (WHERE (ec.full_name IS NOT NULL)))::numeric) / (NULLIF(count(*), 0))::numeric), 1) AS enrichment_pct,
    min(ec.created_at) AS oldest,
    max(ec.updated_at) AS newest_activity,
    snap.src_contacts AS src_last,
    snap.mir_contacts AS mir_last,
    snap.delta_pct AS delta_pct_last,
    snap.captured_at AS snap_at
   FROM (evo.evolution_contacts ec
     LEFT JOIN LATERAL ( SELECT s.src_contacts,
            s.mir_contacts,
            s.delta_pct,
            s.captured_at
           FROM zapp.evo_reconcile_contact_snapshot s
          WHERE (s.instance_name = (ec.instance_name)::text)
          ORDER BY s.captured_at DESC
         LIMIT 1) snap ON (true))
  GROUP BY ec.instance_name, snap.src_contacts, snap.mir_contacts, snap.delta_pct, snap.captured_at;


ALTER TABLE zapp.evo_contact_delta OWNER TO postgres;

