-- Name: favorite_messages; Type: TABLE; Schema: zapp; Owner: postgres
--

CREATE TABLE zapp.favorite_messages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    message_id uuid NOT NULL,
    user_id uuid NOT NULL,
    contact_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

ALTER TABLE ONLY zapp.favorite_messages REPLICA IDENTITY FULL;


ALTER TABLE zapp.favorite_messages OWNER TO postgres;

--
-- Name: TABLE favorite_messages; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON TABLE zapp.favorite_messages IS 'Módulo inativo/vazio até 2026-08 (sprawl F-009); ver DICIONARIO';


--
-- Name: finetune_jobs; Type: TABLE; Schema: zapp; Owner: postgres
--

CREATE TABLE zapp.finetune_jobs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workspace_id uuid,
    agent_id uuid,
    model_name text NOT NULL,
    dataset_path text,
    config jsonb DEFAULT '{}'::jsonb,
    status text DEFAULT 'pending'::text,
    progress numeric(5,2) DEFAULT 0,
    result jsonb DEFAULT '{}'::jsonb,
    error text,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now(),
    CONSTRAINT finetune_jobs_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'running'::text, 'completed'::text, 'failed'::text, 'cancelled'::text])))
);


ALTER TABLE zapp.finetune_jobs OWNER TO postgres;

