-- Name: TABLE finetune_jobs; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON TABLE zapp.finetune_jobs IS 'Módulo inativo/vazio até 2026-08 (sprawl F-009); ver DICIONARIO';


--
-- Name: fn_health_score_cache; Type: TABLE; Schema: zapp; Owner: postgres
--

CREATE TABLE zapp.fn_health_score_cache (
    id integer NOT NULL,
    result jsonb NOT NULL,
    computed_at timestamp with time zone DEFAULT now() NOT NULL,
    compute_ms integer,
    call_count integer DEFAULT 0 NOT NULL
)
WITH (autovacuum_vacuum_threshold='2', autovacuum_vacuum_scale_factor='0.05', autovacuum_analyze_threshold='2', autovacuum_analyze_scale_factor='0.05', autovacuum_vacuum_cost_delay='1');


ALTER TABLE zapp.fn_health_score_cache OWNER TO postgres;

--
-- Name: TABLE fn_health_score_cache; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON TABLE zapp.fn_health_score_cache IS 'Cache da fn_system_health_score(). TTL configuravel (default 5min). Evita 20+ queries sequenciais a cada chamada de monitoramento. Impacto: 1060ms -> <5ms em cache hits.';


--
-- Name: COLUMN fn_health_score_cache.id; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON COLUMN zapp.fn_health_score_cache.id IS 'PK (integer).';


--
-- Name: COLUMN fn_health_score_cache.result; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON COLUMN zapp.fn_health_score_cache.result IS 'Resultado da operacao.';


--
