   FROM evo.evolution_contacts
  WHERE (evolution_contacts.deleted_at IS NULL);


ALTER TABLE zapp.v_contacts_with_legacy OWNER TO postgres;

--
-- Name: v_cookie_health; Type: VIEW; Schema: zapp; Owner: postgres
--

CREATE VIEW zapp.v_cookie_health WITH (security_invoker='on') AS
 SELECT c.servico,
    c.is_healthy,
    c.health_status,
    c.last_health_check_at,
    c.health_error,
    c.expires_at,
    p.http_status AS last_probe_http,
    p.probe_ms AS last_probe_ms,
    p.response_preview AS last_probe_preview,
    (EXTRACT(epoch FROM (now() - c.last_health_check_at)) / (60)::numeric) AS mins_since_probe,
        CASE
            WHEN (c.last_health_check_at < (now() - '00:35:00'::interval)) THEN true
            ELSE false
        END AS probe_stale
   FROM (zapp.cookies_config c
     LEFT JOIN LATERAL ( SELECT cookie_probe_log.http_status,
            cookie_probe_log.probe_ms,
            cookie_probe_log.response_preview
           FROM zapp.cookie_probe_log
          WHERE (cookie_probe_log.servico = c.servico)
          ORDER BY cookie_probe_log.probed_at DESC
         LIMIT 1) p ON (true))
  ORDER BY c.servico;


ALTER TABLE zapp.v_cookie_health OWNER TO postgres;

--
-- Name: v_cron_status; Type: VIEW; Schema: zapp; Owner: postgres
--

CREATE VIEW zapp.v_cron_status WITH (security_invoker='on') AS
 SELECT evolution_settings.key AS job_name,
    evolution_settings.value AS schedule,
    evolution_settings.description,
        CASE
            WHEN (evolution_settings.key = 'cron_process_queue'::text) THEN ( SELECT count(*) AS count
               FROM zapp.evolution_message_queue
              WHERE ((evolution_message_queue.status)::text = 'pending'::text))
            WHEN (evolution_settings.key = 'cron_check_tasks'::text) THEN ( SELECT count(*) AS count
               FROM zapp.evolution_tasks
              WHERE (((evolution_tasks.status)::text = 'pending'::text) AND (evolution_tasks.due_date < CURRENT_DATE)))
            ELSE (0)::bigint
        END AS items_pending,
    evolution_settings.updated_at AS last_config_update
   FROM zapp.evolution_settings
  WHERE (evolution_settings.key ~~ 'cron_%'::text);


ALTER TABLE zapp.v_cron_status OWNER TO postgres;

--
-- Name: v_daily_sales_summary; Type: VIEW; Schema: zapp; Owner: postgres
--

CREATE VIEW zapp.v_daily_sales_summary WITH (security_invoker='on') AS
 SELECT date(evolution_deals.created_at) AS date,
    count(*) AS new_deals,
    sum(evolution_deals.value) AS total_value,
    sum(
        CASE
            WHEN ((evolution_deals.stage)::text = 'pago'::text) THEN evolution_deals.value
            ELSE (0)::numeric
        END) AS closed_value,
    sum(
        CASE
            WHEN ((evolution_deals.stage)::text = 'perdido'::text) THEN evolution_deals.value
            ELSE (0)::numeric
        END) AS lost_value,
    count(
        CASE
            WHEN ((evolution_deals.stage)::text = 'pago'::text) THEN 1
            ELSE NULL::integer
        END) AS won_count,
    count(
        CASE
            WHEN ((evolution_deals.stage)::text = 'perdido'::text) THEN 1
            ELSE NULL::integer
        END) AS lost_count
   FROM zapp.evolution_deals
  WHERE (evolution_deals.created_at >= (now() - '30 days'::interval))
  GROUP BY (date(evolution_deals.created_at))
  ORDER BY (date(evolution_deals.created_at)) DESC;


ALTER TABLE zapp.v_daily_sales_summary OWNER TO postgres;

