--
-- Name: v_dr_runbook; Type: VIEW; Schema: zapp; Owner: postgres
--

CREATE VIEW zapp.v_dr_runbook WITH (security_invoker='on') AS
 SELECT t.step_number,
    t.category,
    t.title,
    t.description,
    t.command_hint,
    t.estimated_minutes,
    t.severity,
    t.is_automated,
    t.created_at
   FROM ( VALUES (1,'database'::text,'Verificar saúde do banco'::text,'Checar conexões, dead tuples e locks ativos'::text,'SELECT * FROM public.fn_system_health_score()'::text,2,'critical'::text,true,now()), (2,'api'::text,'Verificar Evolution API'::text,'Confirmar que a instância wpp2 está conectada e respondendo'::text,'GET /instance/connectionState/wpp2'::text,3,'critical'::text,false,now()), (3,'pipeline'::text,'Checar pipeline de webhooks'::text,'Confirmar que eventos estão fluindo via RabbitMQ → Supabase'::text,'SELECT * FROM public.v_webhook_health'::text,2,'high'::text,true,now()), (4,'storage'::text,'Verificar R2 Cloudflare'::text,'Testar upload de arquivo de teste no bucket zapp-whatsapp-media'::text,'aws s3 ls s3://zapp-whatsapp-media --endpoint...'::text,5,'high'::text,false,now()), (5,'alerts'::text,'Verificar canais de alerta'::text,'Confirmar que canais WhatsApp/Discord/Email respondem'::text,'SELECT * FROM public.fn_test_alert_channel(1)'::text,3,'medium'::text,true,now()), (6,'vacuum'::text,'Manutenção do banco'::text,'Rodar VACUUM ANALYZE nas tabelas críticas se dead_pct > 10%'::text,'VACUUM ANALYZE public.webhook_events_processed'::text,5,'medium'::text,false,now()), (7,'cron'::text,'Verificar cron jobs'::text,'Confirmar que todos os jobs estão ativos e sem timeout recente'::text,'SELECT * FROM cron.job WHERE active = true'::text,2,'medium'::text,true,now()), (8,'app'::text,'Verificar Zapp Web'::text,'Confirmar que todos os endpoints de health respondem 200'::text,'curl https://zapp.promobrindes.com.br/health'::text,1,'low'::text,false,now())) t(step_number, category, title, description, command_hint, estimated_minutes, severity, is_automated, created_at);


ALTER TABLE zapp.v_dr_runbook OWNER TO postgres;

