--
-- Name: v_evolution_dlq_open; Type: VIEW; Schema: zapp; Owner: postgres
--

CREATE VIEW zapp.v_evolution_dlq_open WITH (security_invoker='on') AS
 SELECT evolution_webhook_dlq.id,
    evolution_webhook_dlq.created_at,
    evolution_webhook_dlq.event_type,
    evolution_webhook_dlq.instance_name,
    evolution_webhook_dlq.remote_jid,
    evolution_webhook_dlq.status,
    evolution_webhook_dlq.retry_count,
    evolution_webhook_dlq.max_retries,
    evolution_webhook_dlq.next_retry_at,
    "left"(evolution_webhook_dlq.error_message, 300) AS error_message_preview,
        CASE
            WHEN (evolution_webhook_dlq.retry_count >= COALESCE(evolution_webhook_dlq.max_retries, 10)) THEN true
            ELSE false
        END AS exhausted,
    (EXTRACT(epoch FROM (now() - evolution_webhook_dlq.created_at)))::integer AS age_seconds
   FROM zapp.evolution_webhook_dlq
  WHERE (evolution_webhook_dlq.status <> 'resolved'::text)
  ORDER BY evolution_webhook_dlq.created_at DESC;


ALTER TABLE zapp.v_evolution_dlq_open OWNER TO postgres;

--
-- Name: v_evolution_pipeline_dashboard; Type: VIEW; Schema: zapp; Owner: supabase_admin
--

CREATE VIEW zapp.v_evolution_pipeline_dashboard WITH (security_invoker='on') AS
 SELECT now() AS checked_at,
    ( SELECT count(*) AS count
           FROM evo.active_messages
          WHERE (active_messages.created_at > (now() - '00:05:00'::interval))) AS msgs_5min,
    ( SELECT count(*) AS count
           FROM evo.active_messages
          WHERE (active_messages.created_at > (now() - '01:00:00'::interval))) AS msgs_1h,
    ( SELECT count(*) AS count
           FROM evo.active_messages
          WHERE (active_messages.created_at > (now() - '24:00:00'::interval))) AS msgs_24h,
    ( SELECT max(active_messages.created_at) AS max
           FROM evo.active_messages) AS last_message_at,
    ( SELECT count(*) AS count
           FROM zapp.webhook_audit_log
          WHERE ((webhook_audit_log.status = 'processed'::text) AND (webhook_audit_log.created_at > (now() - '00:05:00'::interval)))) AS audit_processed_5min,
    ( SELECT count(*) AS count
           FROM zapp.webhook_audit_log
          WHERE ((webhook_audit_log.status = 'rejected'::text) AND (webhook_audit_log.created_at > (now() - '00:05:00'::interval)))) AS audit_rejected_5min,
    ( SELECT count(*) AS count
           FROM zapp.webhook_audit_log
          WHERE (webhook_audit_log.created_at > (now() - '24:00:00'::interval))) AS audit_total_24h,
    ( SELECT round(avg(webhook_audit_log.duration_ms), 1) AS round
           FROM zapp.webhook_audit_log
          WHERE ((webhook_audit_log.status = 'processed'::text) AND (webhook_audit_log.created_at > (now() - '01:00:00'::interval)))) AS avg_duration_ms_1h,
    ( SELECT count(*) AS count
           FROM zapp.evolution_alerts
          WHERE ((evolution_alerts.acknowledged = false) AND (evolution_alerts.created_at > (now() - '24:00:00'::interval)))) AS open_alerts_24h,
    pg_size_pretty(pg_database_size('postgres'::name)) AS db_size,
    ( SELECT count(*) AS count
           FROM evo.active_messages) AS total_messages_ever;


ALTER TABLE zapp.v_evolution_pipeline_dashboard OWNER TO supabase_admin;

--
-- Name: v_evolution_source_tables_summary; Type: VIEW; Schema: zapp; Owner: postgres
--

CREATE VIEW zapp.v_evolution_source_tables_summary WITH (security_invoker='on') AS
 SELECT evolution_source_schema_map.table_name,
    max(evolution_source_schema_map.row_count_est) AS rows,
    count(*) AS num_columns,
    count(*) FILTER (WHERE (evolution_source_schema_map.data_type = 'jsonb'::text)) AS jsonb_cols,
    count(*) FILTER (WHERE (evolution_source_schema_map.data_type ~~ '%timestamp%'::text)) AS timestamp_cols,
        CASE
            WHEN (max(evolution_source_schema_map.row_count_est) >= 100000) THEN 'critical'::text
            WHEN (max(evolution_source_schema_map.row_count_est) >= 1000) THEN 'active'::text
            WHEN (max(evolution_source_schema_map.row_count_est) >= 1) THEN 'populated'::text
            ELSE 'empty'::text
        END AS status,
    max(evolution_source_schema_map.discovered_at) AS last_discovered
   FROM zapp.evolution_source_schema_map
  GROUP BY evolution_source_schema_map.table_name
  ORDER BY (max(evolution_source_schema_map.row_count_est)) DESC;


ALTER TABLE zapp.v_evolution_source_tables_summary OWNER TO postgres;

