--
-- Name: v_integration_dashboard; Type: VIEW; Schema: zapp; Owner: postgres
--

CREATE VIEW zapp.v_integration_dashboard WITH (security_invoker='on') AS
 SELECT ir.id,
    ir.name,
    ir.type,
    ir.provider,
    ir.status,
    ir.health_status,
    ir.endpoint_url,
    ir.last_health_check,
    (EXTRACT(epoch FROM (now() - ir.last_health_check)) / (3600)::numeric) AS hours_since_check,
    ir.config,
    ir.metadata,
        CASE
            WHEN (ir.health_status = 'healthy'::text) THEN 'ok'::text
            WHEN (ir.health_status = ANY (ARRAY['warning'::text, 'degraded'::text])) THEN 'warn'::text
            ELSE 'error'::text
        END AS status_emoji,
    ir.created_at,
    ir.updated_at
   FROM zapp.integration_registry ir
  ORDER BY
        CASE ir.type
            WHEN 'backend'::text THEN 1
            WHEN 'frontend'::text THEN 2
            WHEN 'ai'::text THEN 3
            ELSE 10
        END, ir.name;


ALTER TABLE zapp.v_integration_dashboard OWNER TO postgres;

--
-- Name: v_lead_status_coverage; Type: VIEW; Schema: zapp; Owner: postgres
--

CREATE VIEW zapp.v_lead_status_coverage WITH (security_invoker='on') AS
 WITH permitted AS (
         SELECT unnest(ARRAY['novo'::text, 'qualificado'::text, 'negociando'::text, 'cliente'::text, 'perdido'::text, 'inativo'::text, 'lead'::text, 'prospect'::text, 'contacted'::text, 'converted'::text, 'churned'::text, 'hot'::text, 'cold'::text, 'quente'::text, 'frio'::text, 'pendente'::text]) AS status
        ), used AS (
         SELECT evolution_contacts.lead_status AS status,
            count(*) AS qtd
           FROM evo.evolution_contacts
          WHERE (evolution_contacts.deleted_at IS NULL)
          GROUP BY evolution_contacts.lead_status
        )
 SELECT COALESCE(p.status, (u.status)::text) AS status,
    (p.status IS NOT NULL) AS permitido_no_constraint,
    COALESCE(u.qtd, (0)::bigint) AS qtd_contatos,
        CASE
            WHEN (p.status IS NULL) THEN 'USADO_SEM_PERMISSAO'::text
            WHEN (u.status IS NULL) THEN 'PERMITIDO_SEM_USO'::text
            ELSE 'OK'::text
        END AS status_visual
   FROM (permitted p
     FULL JOIN used u ON ((p.status = (u.status)::text)))
  ORDER BY
        CASE
            WHEN (p.status IS NULL) THEN 1
            WHEN (u.status IS NULL) THEN 3
            ELSE 2
        END, u.qtd DESC NULLS LAST;


ALTER TABLE zapp.v_lead_status_coverage OWNER TO postgres;

--
-- Name: v_legacy_stages; Type: VIEW; Schema: zapp; Owner: postgres
--

CREATE VIEW zapp.v_legacy_stages WITH (security_invoker='on') AS
 SELECT evolution_stage_mapping.stage_key,
    evolution_stage_mapping.label_name,
    evolution_stage_mapping.label_color,
    evolution_stage_mapping.stage_order,
    evolution_stage_mapping.auto_transition_after_hours,
    evolution_stage_mapping.next_stage
   FROM zapp.evolution_stage_mapping
  WHERE (evolution_stage_mapping.stage_key ~~ 'legacy_%'::text)
  ORDER BY evolution_stage_mapping.stage_order;


ALTER TABLE zapp.v_legacy_stages OWNER TO postgres;

--
-- Name: v_legacy_vs_evolution_comparison; Type: VIEW; Schema: zapp; Owner: postgres
--

CREATE VIEW zapp.v_legacy_vs_evolution_comparison WITH (security_invoker='on') AS
 SELECT s.entidade,
    s.qtd_legacy,
    s.qtd_evolution,
    s.qtd_migrados AS migrados,
    s.qtd_novos_pos_migracao AS novos_pos_migracao,
    s.taxa_migracao_pct AS pct_migrado,
        CASE
            WHEN (s.taxa_migracao_pct >= 99.9) THEN 'EXCELENTE'::text
            WHEN (s.taxa_migracao_pct >= (95)::numeric) THEN 'OK'::text
            WHEN (s.taxa_migracao_pct >= (80)::numeric) THEN 'ATENCAO'::text
            ELSE 'DIVERGENCIA'::text
        END AS status_visual,
    s.snapshot_at AS dados_em,
    'snapshot_congelado'::text AS origem
   FROM archive.migration_snapshot_d30 s
  WHERE (s.snapshot_at = ( SELECT max(s2.snapshot_at) AS max
           FROM archive.migration_snapshot_d30 s2
          WHERE (s2.entidade = s.entidade)));


ALTER TABLE zapp.v_legacy_vs_evolution_comparison OWNER TO postgres;

--
-- Name: v_link_analytics; Type: VIEW; Schema: zapp; Owner: supabase_admin
--

CREATE VIEW zapp.v_link_analytics WITH (security_invoker='on') AS
 SELECT (evolution_messages.link_preview ->> 'url'::text) AS url,
    (evolution_messages.link_preview ->> 'title'::text) AS title,
    (evolution_messages.link_preview ->> 'description'::text) AS description,
    (evolution_messages.link_preview ->> 'previewType'::text) AS preview_type,
    ((evolution_messages.link_preview ->> 'hasThumbnail'::text))::boolean AS has_thumbnail,
    evolution_messages.instance_name,
    evolution_messages.from_me,
    count(*) AS times_shared,
    min(evolution_messages.created_at) AS first_shared,
    max(evolution_messages.created_at) AS last_shared
   FROM evo.evolution_messages
  WHERE (evolution_messages.link_preview IS NOT NULL)
  GROUP BY (evolution_messages.link_preview ->> 'url'::text), (evolution_messages.link_preview ->> 'title'::text), (evolution_messages.link_preview ->> 'description'::text), (evolution_messages.link_preview ->> 'previewType'::text), ((evolution_messages.link_preview ->> 'hasThumbnail'::text))::boolean, evolution_messages.instance_name, evolution_messages.from_me
  ORDER BY (count(*)) DESC;


ALTER TABLE zapp.v_link_analytics OWNER TO supabase_admin;

--
-- Name: v_media_orphan_stats; Type: VIEW; Schema: zapp; Owner: postgres
--

CREATE VIEW zapp.v_media_orphan_stats WITH (security_invoker='true') AS
 WITH uuid_orphans AS (
         SELECT (date_trunc('week'::text, evolution_media.created_at))::date AS semana,
            evolution_media.media_type,
            count(*) AS qtd,
            count(*) FILTER (WHERE (NOT (EXISTS ( SELECT 1
                   FROM zapp.evolution_messages m
                  WHERE (m.message_id = evolution_media.message_id))))) AS sem_mensagem_pai
           FROM zapp.evolution_media
          WHERE (evolution_media.message_id ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'::text)
          GROUP BY ((date_trunc('week'::text, evolution_media.created_at))::date), evolution_media.media_type
        ), geral AS (
         SELECT count(*) AS total_media,
            count(*) FILTER (WHERE (evolution_media.message_id ~ '^[0-9a-f]{8}-[0-9a-f]{4}-'::text)) AS uuid_format_total,
            count(*) FILTER (WHERE (evolution_media.message_id ~ '^[0-9A-F3][0-9A-F]'::text)) AS whatsapp_hex_total,
            count(*) FILTER (WHERE (evolution_media.media_status = 'ready'::text)) AS ready,
            count(*) FILTER (WHERE (evolution_media.media_status = 'expired'::text)) AS expired,
            count(*) FILTER (WHERE (evolution_media.media_status = 'permanently_lost'::text)) AS permanently_lost,
            count(*) FILTER (WHERE (evolution_media.created_at >= (now() - '7 days'::interval))) AS criados_7d,
            count(*) FILTER (WHERE ((evolution_media.created_at >= (now() - '7 days'::interval)) AND (evolution_media.message_id ~ '^[0-9a-f]{8}-[0-9a-f]{4}-'::text))) AS uuid_orphans_7d,
            (min(evolution_media.created_at))::date AS mais_antigo,
            (max(evolution_media.created_at))::date AS mais_recente
           FROM zapp.evolution_media
        ), fila AS (
         SELECT count(*) AS total_fila,
            count(*) FILTER (WHERE (media_download_queue.status = 'pending'::text)) AS pending,
            count(*) FILTER (WHERE (media_download_queue.status = 'processing'::text)) AS processing,
            count(*) FILTER (WHERE (media_download_queue.status = 'done'::text)) AS done,
            count(*) FILTER (WHERE (media_download_queue.status = 'failed'::text)) AS failed,
            (max(media_download_queue.processed_at))::timestamp(0) without time zone AS ultimo_processamento
           FROM evo.media_download_queue
        )
 SELECT g.total_media,
    g.uuid_format_total AS uuid_orphans_total,
    g.whatsapp_hex_total,
    round(((100.0 * (g.uuid_format_total)::numeric) / (NULLIF(g.total_media, 0))::numeric), 1) AS pct_uuid_orphans,
    g.ready,
    g.expired,
    g.permanently_lost,
    g.criados_7d,
    g.uuid_orphans_7d,
    round(((100.0 * (g.uuid_orphans_7d)::numeric) / (NULLIF(g.criados_7d, 0))::numeric), 1) AS pct_uuid_7d,
    g.mais_antigo,
    g.mais_recente,
    f.total_fila,
    f.pending,
    f.processing,
    f.done,
    f.failed,
    f.ultimo_processamento
   FROM (geral g
     CROSS JOIN fila f);


ALTER TABLE zapp.v_media_orphan_stats OWNER TO postgres;

--
-- Name: v_media_pipeline_health; Type: VIEW; Schema: zapp; Owner: postgres
--

CREATE VIEW zapp.v_media_pipeline_health WITH (security_invoker='true') AS
 SELECT ( SELECT count(*) AS count
           FROM evo.media_download_queue
          WHERE (media_download_queue.status = 'pending'::text)) AS queue_pending,
    ( SELECT count(*) AS count
           FROM evo.media_download_queue
          WHERE (media_download_queue.status = 'done'::text)) AS queue_done,
    ( SELECT count(*) AS count
           FROM evo.media_download_queue
          WHERE (media_download_queue.status = 'failed'::text)) AS queue_failed,
    ( SELECT count(*) AS count
           FROM evo.media_download_queue
          WHERE ((media_download_queue.media_key IS NULL) AND (media_download_queue.status = 'pending'::text))) AS queue_broken_no_key,
    ( SELECT count(*) AS count
           FROM public.evolution_messages_wpp2
          WHERE (evolution_messages_wpp2.media_meta IS NOT NULL)) AS msgs_with_media_meta,
    pg_size_pretty(pg_database_size(current_database())) AS db_size,
    ( SELECT round(((sum(pg_statio_user_tables.heap_blks_hit) * 100.0) / NULLIF((sum(pg_statio_user_tables.heap_blks_hit) + sum(pg_statio_user_tables.heap_blks_read)), (0)::numeric)), 1) AS round
           FROM pg_statio_user_tables) AS cache_hit_pct;


ALTER TABLE zapp.v_media_pipeline_health OWNER TO postgres;

--
-- Name: v_media_security_dashboard; Type: VIEW; Schema: zapp; Owner: postgres
--

CREATE VIEW zapp.v_media_security_dashboard WITH (security_invoker='true') AS
 SELECT ( SELECT count(*) AS count
           FROM evo.media_scan_log
          WHERE ((media_scan_log.scan_result)::text = 'clean'::text)) AS scans_clean,
    ( SELECT count(*) AS count
           FROM evo.media_scan_log
          WHERE ((media_scan_log.scan_result)::text = 'blocked'::text)) AS scans_blocked,
    ( SELECT count(*) AS count
           FROM evo.media_scan_log
          WHERE ((media_scan_log.scan_result)::text = 'warning'::text)) AS scans_warning,
    ( SELECT count(*) AS count
           FROM evo.media_quarantine
          WHERE (NOT media_quarantine.released)) AS quarantine_pending,
    ( SELECT count(*) AS count
           FROM evo.media_quarantine
          WHERE media_quarantine.released) AS quarantine_released,
    ( SELECT count(*) AS count
           FROM evo.media_quarantine
          WHERE media_quarantine.reviewed) AS quarantine_reviewed,
    ( SELECT count(*) AS count
           FROM evo.media_security_config
          WHERE media_security_config.is_active) AS rules_active,
    ( SELECT count(*) AS count
           FROM evo.media_security_config
          WHERE (((media_security_config.rule_type)::text = 'blocked_mimetype'::text) AND media_security_config.is_active)) AS blocked_mimetypes,
    ( SELECT count(*) AS count
           FROM evo.media_security_config
          WHERE (((media_security_config.rule_type)::text = 'blocked_extension'::text) AND media_security_config.is_active)) AS blocked_extensions,
    ( SELECT count(*) AS count
           FROM evo.media_download_queue
          WHERE ((media_download_queue.scan_status)::text = 'pending_scan'::text)) AS queue_pending_scan,
    ( SELECT count(*) AS count
           FROM evo.media_download_queue
          WHERE ((media_download_queue.scan_status)::text = 'clean'::text)) AS queue_scanned_clean,
    ( SELECT count(*) AS count
           FROM evo.media_download_queue
          WHERE ((media_download_queue.scan_status)::text = 'blocked'::text)) AS queue_scanned_blocked;


ALTER TABLE zapp.v_media_security_dashboard OWNER TO postgres;

--
-- Name: v_migration_reconciliation; Type: VIEW; Schema: zapp; Owner: postgres
--

CREATE VIEW zapp.v_migration_reconciliation WITH (security_invoker='on') AS
 SELECT s.entidade,
    s.qtd_legacy AS legacy_total,
    s.qtd_evolution AS evolution_total,
    s.qtd_migrados AS from_legacy,
    s.qtd_novos_pos_migracao AS native_or_live,
        CASE
            WHEN (s.qtd_migrados >= s.qtd_legacy) THEN 'OK'::text
            WHEN ((s.qtd_migrados)::numeric >= ((s.qtd_legacy)::numeric * 0.95)) THEN 'OK_95PCT'::text
            ELSE 'DIVERGENCIA'::text
        END AS status_reconciliacao,
    s.taxa_migracao_pct,
    s.snapshot_at AS snapshot_em
   FROM archive.migration_snapshot_d30 s
  WHERE (s.snapshot_at = ( SELECT max(s2.snapshot_at) AS max
           FROM archive.migration_snapshot_d30 s2
          WHERE (s2.entidade = s.entidade)));


ALTER TABLE zapp.v_migration_reconciliation OWNER TO postgres;

--
-- Name: v_mirror_backfill_progress; Type: VIEW; Schema: zapp; Owner: postgres
--

CREATE VIEW zapp.v_mirror_backfill_progress WITH (security_invoker='on') AS
 WITH stats AS (
         SELECT evolution_mirror_batches.run_id,
            count(*) AS total_batches,
            count(*) FILTER (WHERE (evolution_mirror_batches.consumed_status = 'consumed'::text)) AS consumed,
            count(*) FILTER (WHERE (evolution_mirror_batches.consumed_status = 'consuming'::text)) AS consuming,
            count(*) FILTER (WHERE ((evolution_mirror_batches.consumed_status = 'pending'::text) OR (evolution_mirror_batches.consumed_status IS NULL))) AS pending,
            count(*) FILTER (WHERE (evolution_mirror_batches.consumed_status = 'failed'::text)) AS failed,
            sum(evolution_mirror_batches.row_count) AS total_rows,
            sum(((evolution_mirror_batches.metrics ->> 'inserted'::text))::integer) FILTER (WHERE (evolution_mirror_batches.consumed_status = 'consumed'::text)) AS rows_inserted,
            sum(((evolution_mirror_batches.metrics ->> 'skipped'::text))::integer) FILTER (WHERE (evolution_mirror_batches.consumed_status = 'consumed'::text)) AS rows_skipped,
            sum(((evolution_mirror_batches.metrics ->> 'errored'::text))::integer) FILTER (WHERE (evolution_mirror_batches.consumed_status = 'consumed'::text)) AS rows_errored,
            avg(((evolution_mirror_batches.metrics ->> 'duration_ms'::text))::integer) FILTER (WHERE (evolution_mirror_batches.consumed_status = 'consumed'::text)) AS avg_duration_ms,
            min(evolution_mirror_batches.created_at) AS started_at,
            max(evolution_mirror_batches.consumed_at) FILTER (WHERE (evolution_mirror_batches.consumed_status = 'consumed'::text)) AS last_consumed_at
           FROM zapp.evolution_mirror_batches
          GROUP BY evolution_mirror_batches.run_id
        )
 SELECT stats.run_id,
    stats.total_batches,
    stats.consumed,
    stats.consuming,
    stats.pending,
    stats.failed,
    round(((100.0 * (stats.consumed)::numeric) / (NULLIF(stats.total_batches, 0))::numeric), 1) AS progress_pct,
    stats.total_rows,
    stats.rows_inserted,
    stats.rows_skipped,
    stats.rows_errored,
    round(stats.avg_duration_ms) AS avg_chunk_ms,
    stats.started_at,
    stats.last_consumed_at,
        CASE
            WHEN ((stats.pending = 0) AND (stats.consuming = 0)) THEN 'COMPLETE'::text
            ELSE 'running'::text
        END AS eta
   FROM stats
  ORDER BY stats.started_at DESC;


ALTER TABLE zapp.v_mirror_backfill_progress OWNER TO postgres;

--
-- Name: v_model_catalog; Type: VIEW; Schema: zapp; Owner: postgres
--

CREATE VIEW zapp.v_model_catalog WITH (security_invoker='on') AS
 SELECT model_pricing_v2.model,
    model_pricing_v2.provider,
    model_pricing_v2.tier,
    model_pricing_v2.capabilities,
    model_pricing_v2.context_window,
    model_pricing_v2.input_cost_per_1m,
    model_pricing_v2.output_cost_per_1m,
    model_pricing_v2.active_params,
    model_pricing_v2.total_params,
        CASE
            WHEN (model_pricing_v2.input_cost_per_1m <= 0.02) THEN 'free_tier'::text
            WHEN (model_pricing_v2.input_cost_per_1m <= 0.10) THEN 'budget'::text
            WHEN (model_pricing_v2.input_cost_per_1m <= 1.00) THEN 'standard'::text
            ELSE 'premium'::text
        END AS cost_tier
   FROM ai.model_pricing_v2
  ORDER BY model_pricing_v2.input_cost_per_1m;


ALTER TABLE zapp.v_model_catalog OWNER TO postgres;

--
-- Name: v_monthly_comparison; Type: VIEW; Schema: zapp; Owner: postgres
--

CREATE VIEW zapp.v_monthly_comparison WITH (security_invoker='on') AS
 SELECT (date_trunc('month'::text, (evolution_daily_metrics.metric_date)::timestamp with time zone))::date AS month,
    sum(evolution_daily_metrics.new_contacts) AS new_contacts,
    sum(evolution_daily_metrics.messages_received) AS messages_received,
    sum(evolution_daily_metrics.messages_sent) AS messages_sent,
    sum(evolution_daily_metrics.deals_created) AS deals_created,
    sum(evolution_daily_metrics.deals_won) AS deals_won,
    sum(evolution_daily_metrics.deals_lost) AS deals_lost,
    sum(evolution_daily_metrics.revenue) AS revenue,
        CASE
            WHEN ((sum(evolution_daily_metrics.deals_won) + sum(evolution_daily_metrics.deals_lost)) > 0) THEN round((((sum(evolution_daily_metrics.deals_won))::numeric / ((sum(evolution_daily_metrics.deals_won) + sum(evolution_daily_metrics.deals_lost)))::numeric) * (100)::numeric), 2)
            ELSE (0)::numeric
        END AS win_rate,
    round((sum(evolution_daily_metrics.revenue) / (NULLIF(sum(evolution_daily_metrics.deals_won), 0))::numeric), 2) AS avg_deal_value
   FROM zapp.evolution_daily_metrics
  WHERE (evolution_daily_metrics.metric_date >= (date_trunc('month'::text, (CURRENT_DATE)::timestamp with time zone) - '3 mons'::interval))
  GROUP BY (date_trunc('month'::text, (evolution_daily_metrics.metric_date)::timestamp with time zone))
  ORDER BY ((date_trunc('month'::text, (evolution_daily_metrics.metric_date)::timestamp with time zone))::date) DESC;


ALTER TABLE zapp.v_monthly_comparison OWNER TO postgres;

