-- Name: v_pending_conversations; Type: VIEW; Schema: zapp; Owner: postgres
--

CREATE VIEW zapp.v_pending_conversations WITH (security_invoker='on') AS
 SELECT c.id,
    c.contact_id,
    c.remote_jid,
    c.status,
    c.assigned_to,
    c.department,
    c.subject,
    c.priority,
    c.labels,
    c.message_count,
    c.first_message_at,
    c.last_message_at,
    c.last_inbound_at,
    c.last_outbound_at,
    c.first_response_at,
    c.first_response_seconds,
    c.resolution_at,
    c.resolution_seconds,
    c.is_bot_active,
    c.bot_session_id,
    c.satisfaction_score,
    c.satisfaction_comment,
    c.instance_name,
    c.metadata,
    c.created_at,
    c.updated_at,
    c.last_message_content,
    c.last_message_type,
    c.unread_count,
    ct.full_name AS contact_name,
    ct.phone_number
   FROM (evo.evolution_conversations c
     LEFT JOIN evo.evolution_contacts ct ON ((c.contact_id = ct.id)))
  WHERE (((c.status)::text = ANY (ARRAY[('aberta'::character varying)::text, ('open'::character varying)::text, ('active'::character varying)::text])) AND (c.assigned_to IS NULL));


