--
-- Name: v_pending_notifications; Type: VIEW; Schema: zapp; Owner: postgres
--

CREATE VIEW zapp.v_pending_notifications WITH (security_invoker='on') AS
 SELECT nl.id,
    nl.channel,
    nl.message,
    nl.created_at,
    nc.webhook_url,
    nc.api_token,
    nc.chat_id,
    ea.severity,
    ea.alert_type
   FROM ((zapp.evolution_notification_log nl
     JOIN zapp.evolution_notification_config nc ON ((nl.channel = nc.channel)))
     LEFT JOIN zapp.evolution_alerts ea ON ((nl.alert_id = ea.id)))
  WHERE (nl.status = 'pending'::text)
  ORDER BY nl.created_at;


