-- Name: v_pending_transfers; Type: VIEW; Schema: zapp; Owner: supabase_admin
--

CREATE VIEW zapp.v_pending_transfers WITH (security_invoker='on') AS
 SELECT conversation_transfers.target_instance,
    count(*) AS pending,
    count(*) FILTER (WHERE (conversation_transfers.priority = 4)) AS urgente,
    count(*) FILTER (WHERE (conversation_transfers.priority = 3)) AS alta,
    count(*) FILTER (WHERE (conversation_transfers.expires_at < now())) AS sla_estourado,
    min(conversation_transfers.created_at) AS mais_antiga
   FROM zapp.conversation_transfers
  WHERE (conversation_transfers.status = 'pending'::text)
  GROUP BY conversation_transfers.target_instance
  ORDER BY (count(*) FILTER (WHERE (conversation_transfers.priority = 4))) DESC, (count(*)) DESC;


ALTER TABLE zapp.v_pending_transfers OWNER TO supabase_admin;

--
-- Name: v_perf_dashboard; Type: VIEW; Schema: zapp; Owner: postgres
--

CREATE VIEW zapp.v_perf_dashboard WITH (security_invoker='true') AS
 WITH slow_queries AS (
         SELECT "left"(pg_stat_statements.query, 100) AS query_preview,
            pg_stat_statements.calls,
            round((pg_stat_statements.mean_exec_time)::numeric, 0) AS mean_ms,
            round((pg_stat_statements.max_exec_time)::numeric, 0) AS max_ms,
            round(((pg_stat_statements.total_exec_time)::numeric / 1000.0), 1) AS total_sec,
                CASE
                    WHEN (pg_stat_statements.mean_exec_time > (10000)::double precision) THEN 'CRITICAL'::text
                    WHEN (pg_stat_statements.mean_exec_time > (3000)::double precision) THEN 'SLOW'::text
                    WHEN (pg_stat_statements.mean_exec_time > (500)::double precision) THEN 'WARN'::text
                    ELSE 'OK'::text
                END AS severity
           FROM extensions.pg_stat_statements
          WHERE ((pg_stat_statements.mean_exec_time > (500)::double precision) AND (pg_stat_statements.calls > 2))
          ORDER BY pg_stat_statements.total_exec_time DESC
         LIMIT 15
        ), rls_status AS (
         SELECT pg_policies.policyname,
            pg_policies.cmd,
                CASE
                    WHEN ((COALESCE(pg_policies.qual, pg_policies.with_check) ~~* '%( SELECT auth.uid()%'::text) OR (COALESCE(pg_policies.qual, pg_policies.with_check) ~~* '%(SELECT auth.uid()%'::text) OR (COALESCE(pg_policies.qual, pg_policies.with_check) ~~* '%( SELECT current_user_is_privileged()%'::text) OR (COALESCE(pg_policies.qual, pg_policies.with_check) ~~* '%( SELECT zapp.current_user_is_privileged()%'::text)) THEN 'InitPlan OK ✓'::text
                    WHEN ((COALESCE(pg_policies.qual, pg_policies.with_check) ~~* '%auth.uid()%'::text) OR (COALESCE(pg_policies.qual, pg_policies.with_check) ~~* '%current_user_is_privileged()%'::text)) THEN 'PerRow SLOW ✗'::text
                    ELSE 'N/A'::text
                END AS initplan_status
           FROM pg_policies
          WHERE ((pg_policies.schemaname = 'evo'::name) AND (pg_policies.tablename = 'evolution_messages'::name))
        ), index_usage AS (
         SELECT s.indexrelname,
            s.idx_scan
           FROM pg_stat_user_indexes s
          WHERE (s.indexrelname = ANY (ARRAY['idx_evo_contacts_jid_instance_assigned'::name, 'idx_ec_phone_norm_batch'::name, 'idx_wpp2_status_coalesce_created'::name, 'idx_profiles_user_id_role'::name]))
        )
 SELECT now() AS checked_at,
    ( SELECT count(*) AS count
           FROM slow_queries
          WHERE (slow_queries.severity = ANY (ARRAY['CRITICAL'::text, 'SLOW'::text]))) AS critical_slow_queries,
    ( SELECT COALESCE(max(slow_queries.mean_ms), (0)::numeric) AS "coalesce"
           FROM slow_queries
          WHERE (slow_queries.severity = 'CRITICAL'::text)) AS worst_mean_ms,
    ( SELECT count(*) AS count
           FROM rls_status
          WHERE (rls_status.initplan_status = 'InitPlan OK ✓'::text)) AS rls_initplan_ok_count,
    ( SELECT count(*) AS count
           FROM rls_status
          WHERE (rls_status.initplan_status = 'PerRow SLOW ✗'::text)) AS rls_per_row_count,
    ( SELECT string_agg((((rls_status.policyname)::text || '='::text) || rls_status.initplan_status), ' | '::text ORDER BY rls_status.policyname) AS string_agg
           FROM rls_status) AS rls_detail,
    ( SELECT job.schedule
           FROM cron.job
          WHERE (job.jobname = 'autofix-security-invoker'::text)) AS autofix_schedule,
    ( SELECT count(*) AS count
           FROM pg_stat_activity
          WHERE (pg_stat_activity.state = 'active'::text)) AS active_connections,
    ( SELECT count(*) AS count
           FROM pg_stat_activity
          WHERE (pg_stat_activity.state = 'idle in transaction'::text)) AS idle_in_txn,
    ( SELECT string_agg(((((index_usage.indexrelname)::text || '('::text) || index_usage.idx_scan) || ')'::text), ', '::text) AS string_agg
           FROM index_usage) AS key_index_scans;


ALTER TABLE zapp.v_perf_dashboard OWNER TO postgres;

--
-- Name: VIEW v_perf_dashboard; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON VIEW zapp.v_perf_dashboard IS 'Performance dashboard v1 — Agent 9 MONITORING-SETUP 2026-08-05. Consulta tempo real: queries lentas, status RLS InitPlan, uso de índices, conexões ativas.';


