COMMENT ON VIEW zapp.v_vault_health IS 'Onda 9.1 — atalho de leitura: top 20 últimas leituras do healthcheck.';


--
-- Name: v_weekly_metrics; Type: VIEW; Schema: zapp; Owner: postgres
--

CREATE VIEW zapp.v_weekly_metrics WITH (security_invoker='on') AS
 SELECT evolution_daily_metrics.metric_date,
    evolution_daily_metrics.new_contacts,
    (evolution_daily_metrics.messages_received + evolution_daily_metrics.messages_sent) AS total_messages,
    evolution_daily_metrics.deals_created,
    evolution_daily_metrics.deals_won,
    evolution_daily_metrics.revenue,
        CASE
            WHEN ((evolution_daily_metrics.deals_won + evolution_daily_metrics.deals_lost) > 0) THEN round((((evolution_daily_metrics.deals_won)::numeric / ((evolution_daily_metrics.deals_won + evolution_daily_metrics.deals_lost))::numeric) * (100)::numeric), 2)
            ELSE (0)::numeric
        END AS win_rate
   FROM zapp.evolution_daily_metrics
  WHERE (evolution_daily_metrics.metric_date >= (CURRENT_DATE - 7))
  ORDER BY evolution_daily_metrics.metric_date DESC;


ALTER TABLE zapp.v_weekly_metrics OWNER TO postgres;

--
-- Name: v_whatsapp_status_feed; Type: VIEW; Schema: zapp; Owner: supabase_admin
--

CREATE VIEW zapp.v_whatsapp_status_feed WITH (security_invoker='on') AS
 SELECT s.id,
    s.instance_name,
    s.participant_jid,
    COALESCE(s.participant_name, c.push_name, (split_part((s.participant_jid)::text, '@'::text, 1))::character varying) AS display_name,
    c.first_name,
    c.last_name,
    c.lead_status,
    s.message_type,
    s.content,
    s.media_url,
    s.media_mimetype,
    s.posted_at,
    s.expires_at,
    s.viewed_by_us,
    s.viewed_at,
    ( SELECT count(*) AS count
           FROM zapp.evolution_status_reactions r
          WHERE (r.status_id = s.id)) AS reaction_count,
    ( SELECT r.reaction_emoji
           FROM zapp.evolution_status_reactions r
          WHERE (r.status_id = s.id)
          ORDER BY r.reacted_at DESC
         LIMIT 1) AS last_reaction,
    (s.expires_at > now()) AS is_active
   FROM (zapp.evolution_whatsapp_status s
     LEFT JOIN evo.evolution_contacts c ON ((s.contact_id = c.id)))
  ORDER BY s.posted_at DESC;


ALTER TABLE zapp.v_whatsapp_status_feed OWNER TO supabase_admin;

