--
-- Name: voip_profile_credentials; Type: TABLE; Schema: zapp; Owner: postgres
--

CREATE TABLE zapp.voip_profile_credentials (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    profile_id uuid NOT NULL,
    sip_user text NOT NULL,
    sip_password text NOT NULL,
    sip_server text,
    ws_port integer DEFAULT 8089 NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT voip_profile_credentials_sip_password_check CHECK (((char_length(sip_password) >= 1) AND (char_length(sip_password) <= 256))),
    CONSTRAINT voip_profile_credentials_sip_server_check CHECK (((sip_server IS NULL) OR ((char_length(sip_server) >= 1) AND (char_length(sip_server) <= 255)))),
    CONSTRAINT voip_profile_credentials_sip_user_check CHECK (((char_length(sip_user) >= 1) AND (char_length(sip_user) <= 128))),
    CONSTRAINT voip_profile_credentials_ws_port_check CHECK (((ws_port >= 1) AND (ws_port <= 65535)))
);

ALTER TABLE ONLY zapp.voip_profile_credentials REPLICA IDENTITY FULL;


ALTER TABLE zapp.voip_profile_credentials OWNER TO postgres;

--
-- Name: TABLE voip_profile_credentials; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON TABLE zapp.voip_profile_credentials IS 'Credenciais SIP por perfil (VoIP). Leitura SOMENTE via edge function zapp-get-sip-credentials (service_role) — sem GRANT para PostgREST.';


--
-- Name: vw_contact_labels; Type: VIEW; Schema: zapp; Owner: postgres
--

CREATE VIEW zapp.vw_contact_labels WITH (security_invoker='on') AS
 SELECT la.remote_jid,
    ct.full_name AS contact_name,
    ct.phone_number,
    array_agg(l.name) FILTER (WHERE la.is_active) AS active_labels,
    count(*) FILTER (WHERE la.is_active) AS label_count
   FROM ((zapp.evolution_label_associations la
     JOIN zapp.evolution_labels l ON ((la.label_id = l.id)))
     LEFT JOIN evo.evolution_contacts ct ON ((la.contact_id = ct.id)))
  WHERE (la.is_active = true)
  GROUP BY la.remote_jid, ct.full_name, ct.phone_number;


ALTER TABLE zapp.vw_contact_labels OWNER TO postgres;

--
-- Name: vw_dlq_pending; Type: VIEW; Schema: zapp; Owner: postgres
--

CREATE VIEW zapp.vw_dlq_pending WITH (security_invoker='on') AS
 SELECT evolution_webhook_dlq.id,
    evolution_webhook_dlq.event_type,
    evolution_webhook_dlq.instance_name,
    evolution_webhook_dlq.remote_jid,
    evolution_webhook_dlq.error_message,
    evolution_webhook_dlq.retry_count,
    evolution_webhook_dlq.max_retries,
    evolution_webhook_dlq.next_retry_at,
    evolution_webhook_dlq.status,
    evolution_webhook_dlq.created_at,
        CASE
            WHEN (evolution_webhook_dlq.retry_count >= evolution_webhook_dlq.max_retries) THEN 'Excedeu tentativas'::text
            WHEN (evolution_webhook_dlq.next_retry_at <= now()) THEN 'Pronto para retry'::text
            ELSE 'Aguardando'::text
        END AS retry_status
   FROM zapp.evolution_webhook_dlq
  WHERE (evolution_webhook_dlq.status = ANY (ARRAY['pending'::text, 'retrying'::text]))
  ORDER BY evolution_webhook_dlq.created_at DESC;


ALTER TABLE zapp.vw_dlq_pending OWNER TO postgres;

