--
-- Name: vw_media_health_dashboard; Type: VIEW; Schema: zapp; Owner: postgres
--

CREATE VIEW zapp.vw_media_health_dashboard WITH (security_invoker='on') AS
 WITH stats AS (
         SELECT evolution_messages.message_type,
            count(*) AS total,
            count(*) FILTER (WHERE ((evolution_messages.media_url IS NOT NULL) AND (evolution_messages.media_url <> ''::text))) AS with_url,
            count(*) FILTER (WHERE ((evolution_messages.media_mimetype IS NOT NULL) AND (evolution_messages.media_mimetype <> ''::text))) AS with_mime,
            count(*) FILTER (WHERE (evolution_messages.created_at >= (now() - '24:00:00'::interval))) AS last_24h,
            count(*) FILTER (WHERE ((evolution_messages.created_at >= (now() - '24:00:00'::interval)) AND (evolution_messages.media_url IS NOT NULL) AND (evolution_messages.media_url <> ''::text))) AS last_24h_with_url
           FROM evo.evolution_messages
          WHERE (((evolution_messages.message_type)::text = ANY ((ARRAY['image'::character varying, 'video'::character varying, 'audio'::character varying, 'ptt'::character varying, 'document'::character varying, 'sticker'::character varying])::text[])) AND (evolution_messages.deleted_at IS NULL))
          GROUP BY evolution_messages.message_type
        )
 SELECT stats.message_type,
    stats.total,
    stats.with_url,
    round(((100.0 * (stats.with_url)::numeric) / (NULLIF(stats.total, 0))::numeric), 1) AS pct_with_url,
    stats.with_mime,
    stats.last_24h,
    stats.last_24h_with_url,
    round(((100.0 * (stats.last_24h_with_url)::numeric) / (NULLIF(stats.last_24h, 0))::numeric), 1) AS pct_24h_with_url,
        CASE
            WHEN (round(((100.0 * (stats.with_url)::numeric) / (NULLIF(stats.total, 0))::numeric), 1) >= (95)::numeric) THEN 'healthy'::text
            WHEN (round(((100.0 * (stats.with_url)::numeric) / (NULLIF(stats.total, 0))::numeric), 1) >= (50)::numeric) THEN 'degraded'::text
            ELSE 'critical'::text
        END AS health_status
   FROM stats
  ORDER BY stats.total DESC;


ALTER TABLE zapp.vw_media_health_dashboard OWNER TO postgres;

--
-- Name: VIEW vw_media_health_dashboard; Type: COMMENT; Schema: zapp; Owner: postgres
--

COMMENT ON VIEW zapp.vw_media_health_dashboard IS 'Dashboard de saúde do pipeline de mídia por tipo';


--
-- Name: vw_media_pipeline_status; Type: VIEW; Schema: zapp; Owner: postgres
--

CREATE VIEW zapp.vw_media_pipeline_status WITH (security_invoker='true') AS
 WITH queue_stats AS (
         SELECT media_download_queue.status,
            count(*) AS total,
            count(*) FILTER (WHERE (media_download_queue.priority = 10)) AS priority_high,
            count(*) FILTER (WHERE (media_download_queue.priority = 5)) AS priority_medium,
            count(*) FILTER (WHERE (media_download_queue.priority = 1)) AS priority_low
           FROM evo.media_download_queue
          GROUP BY media_download_queue.status
        ), msg_stats AS (
         SELECT count(*) AS total_media_msgs,
            count(*) FILTER (WHERE ((evolution_messages.media_url IS NOT NULL) AND (evolution_messages.media_url <> ''::text))) AS with_url,
            count(*) FILTER (WHERE ((evolution_messages.media_url IS NULL) OR (evolution_messages.media_url = ''::text))) AS without_url,
            count(*) FILTER (WHERE (evolution_messages.media_url ~~ 'https://s3.atomicabr%'::text)) AS s3_public,
            count(*) FILTER (WHERE (evolution_messages.media_url ~~ 'https://allrjhk%'::text)) AS supabase_cloud,
            count(*) FILTER (WHERE (evolution_messages.media_url ~~ 'http://minio%'::text)) AS minio_internal
           FROM evo.evolution_messages
          WHERE (((evolution_messages.message_type)::text = ANY (ARRAY['image'::text, 'video'::text, 'audio'::text, 'ptt'::text, 'document'::text, 'sticker'::text])) AND (evolution_messages.deleted_at IS NULL))
        )
 SELECT ms.total_media_msgs,
    ms.with_url,
    ms.without_url,
    round(((100.0 * (ms.with_url)::numeric) / (NULLIF(ms.total_media_msgs, 0))::numeric), 1) AS pct_with_url,
    ms.s3_public,
    ms.supabase_cloud,
    ms.minio_internal,
    COALESCE(( SELECT queue_stats.total
           FROM queue_stats
          WHERE (queue_stats.status = 'pending'::text)), (0)::bigint) AS queue_pending,
    COALESCE(( SELECT queue_stats.total
           FROM queue_stats
          WHERE (queue_stats.status = 'processing'::text)), (0)::bigint) AS queue_processing,
    COALESCE(( SELECT queue_stats.total
           FROM queue_stats
          WHERE (queue_stats.status = 'done'::text)), (0)::bigint) AS queue_done,
    COALESCE(( SELECT queue_stats.total
           FROM queue_stats
          WHERE (queue_stats.status = 'failed'::text)), (0)::bigint) AS queue_failed,
        CASE
            WHEN (ms.minio_internal > 0) THEN 'HAS_INTERNAL_URLS'::text
            WHEN (COALESCE(( SELECT queue_stats.total
               FROM queue_stats
              WHERE (queue_stats.status = 'pending'::text)), (0)::bigint) > 100) THEN 'QUEUE_BACKLOG'::text
            WHEN (round(((100.0 * (ms.with_url)::numeric) / (NULLIF(ms.total_media_msgs, 0))::numeric), 1) >= (90)::numeric) THEN 'HEALTHY'::text
            WHEN (round(((100.0 * (ms.with_url)::numeric) / (NULLIF(ms.total_media_msgs, 0))::numeric), 1) >= (50)::numeric) THEN 'DEGRADED'::text
            ELSE 'CRITICAL'::text
        END AS overall_status
   FROM msg_stats ms;


ALTER TABLE zapp.vw_media_pipeline_status OWNER TO postgres;

--
-- Name: vw_minio_decommission_check; Type: VIEW; Schema: zapp; Owner: postgres
--

CREATE VIEW zapp.vw_minio_decommission_check WITH (security_invoker='on') AS
 SELECT ( SELECT count(*) AS count
           FROM evo.evolution_messages
          WHERE ((evolution_messages.media_url ~~ 'http://minio%'::text) AND (evolution_messages.deleted_at IS NULL))) AS urls_minio_interno,
    ( SELECT count(*) AS count
           FROM evo.evolution_messages
          WHERE ((evolution_messages.media_url ~~ 'https://s3.atomicabr%'::text) AND (evolution_messages.deleted_at IS NULL))) AS urls_s3_atomicabr,
    ( SELECT count(*) AS count
           FROM evo.evolution_messages
          WHERE ((evolution_messages.media_url ~~ 'https://zapp-media-proxy%'::text) AND (evolution_messages.created_at > (now() - '24:00:00'::interval)) AND (evolution_messages.deleted_at IS NULL))) AS r2_novas_24h,
    'https://zapp-media-proxy.adm01.workers.dev/health'::text AS worker_health_url,
        CASE
            WHEN ((( SELECT count(*) AS count
               FROM evo.evolution_messages
              WHERE ((evolution_messages.media_url ~~ 'http://minio%'::text) AND (evolution_messages.deleted_at IS NULL))) = 0) AND (( SELECT count(*) AS count
               FROM evo.evolution_messages
              WHERE ((evolution_messages.media_url ~~ 'https://s3.atomicabr%'::text) AND (evolution_messages.deleted_at IS NULL))) = 0)) THEN 'SAFE_TO_DECOMMISSION'::text
            ELSE 'NOT_READY'::text
        END AS status;


ALTER TABLE zapp.vw_minio_decommission_check OWNER TO postgres;

--
-- Name: vw_missed_calls_pending; Type: VIEW; Schema: zapp; Owner: postgres
--

CREATE VIEW zapp.vw_missed_calls_pending WITH (security_invoker='on') AS
 SELECT c.id,
    c.call_id,
    c.remote_jid,
    c.call_type,
    c.created_at,
    c.missed_callback_sent,
    ct.full_name AS contact_name,
    ct.phone_number,
    (EXTRACT(epoch FROM (now() - c.created_at)) / (60)::numeric) AS minutes_since_call
   FROM (zapp.evolution_calls c
     LEFT JOIN evo.evolution_contacts ct ON ((c.contact_id = ct.id)))
  WHERE ((c.call_status = 'missed'::text) AND (c.missed_callback_sent = false) AND (c.created_at > (now() - '24:00:00'::interval)))
  ORDER BY c.created_at DESC;


ALTER TABLE zapp.vw_missed_calls_pending OWNER TO postgres;

--
-- Name: vw_pendentes_atual; Type: VIEW; Schema: zapp; Owner: supabase_admin
--

CREATE VIEW zapp.vw_pendentes_atual WITH (security_invoker='on') AS
