--
-- Name: v_popular_tags _RETURN; Type: RULE; Schema: zapp; Owner: postgres
--

CREATE OR REPLACE VIEW zapp.v_popular_tags WITH (security_invoker='on') AS
 SELECT t.id,
    t.name,
    t.color,
    t.category,
    t.use_count,
    count(ta.id) AS current_assignments
   FROM (zapp.evolution_tags t
     LEFT JOIN zapp.evolution_tag_assignments ta ON ((t.id = ta.tag_id)))
  GROUP BY t.id
  ORDER BY t.use_count DESC, (count(ta.id)) DESC
 LIMIT 50;


